    pg.wait_for_timeout(700)
    l3 = pg.evaluate(LN)
    ok("圖例點一個族群 → 真的多一條線、也多一個端點標籤", l3["n"] == 2 and l3["nEnd"] == 2 and l3["pickOn"] is None, l3)
    click(pg, '#seasonPick button[data-v="top"]', 700)
    # 近 3 年勝率只有四種值 → 圖旁要講出來
