    pg.set_viewport_size({"width": 1440, "height": 1000})

    # ---------------------------------------------------------------- ③ 公告／新聞合併成一張
    nc = _stock_with_all_news() or code
    j = pg.evaluate(f"() => fetch('data/stock/{nc}.json').then(r => r.json()).catch(() => null)") or {}
