    wait_until(pg, "() => /\\d/.test((document.querySelector(\"#m3Grid .m3-card[data-id='TSE'] .m3-px\") || {}).textContent || '')", 8000)
    TSE = "#m3Grid .m3-card[data-id='TSE'] .m3-px"
