# ===================================================================== 時鐘 v2（設計系統 v2 第 5 批）
# 規格：docs/design_system_v2.md §3.2。每一條都量**畫上去的**狀態（ECharts 的 option、canvas 像素、DOM），
# 不是「元素存在」。
CLK_STATE = r"""(cid) => { const el = document.getElementById(cid);
  const c = el && window.echarts && echarts.getInstanceByDom(el); if (!c) return null;
  const o = c.getOption(); const ss = o.series || [];
  const lines = ss.filter(s => s.type === 'line');
  const vis = lines.filter(s => ((s.lineStyle || {}).opacity == null ? 1 : s.lineStyle.opacity) > 0 && (s.data || []).length);
  const sym = (s, k) => (s.data || []).filter(d => d && !Array.isArray(d) && d.symbol === k).length;
  const sc = ss.filter(s => s.type === 'scatter')[0] || { data: [] };
  const ring = ss.find(s => s.type === 'custom' && s.name === '象限底色');
  const thin = ss.find(s => s.type === 'custom' && s.name === '細線');
  const moved = ss.find(s => s.type === 'custom' && s.name === '換段色環');
  const g0 = vis.map(s => s.lineStyle.color).find(x => x && typeof x === 'object');
  return { n: sc.data.length, lines: lines.length, vis: vis.length, visGids: vis.map(s => s.gid),
    /* 2026-09-25（每個點都有腳印）：看得到的每一條各自的不透明度 —— 1＝焦點（實、亮），< 1＝退到背景的非焦點 */
    visOp: vis.map(s => (s.lineStyle || {}).opacity == null ? 1 : s.lineStyle.opacity),
    solid: vis.filter(s => ((s.lineStyle || {}).opacity == null ? 1 : s.lineStyle.opacity) >= 1).length,
    solidGids: vis.filter(s => ((s.lineStyle || {}).opacity == null ? 1 : s.lineStyle.opacity) >= 1).map(s => s.gid),
    arrows: vis.reduce((a, s) => a + sym(s, 'triangle'), 0), marks: vis.reduce((a, s) => a + sym(s, 'circle'), 0),
    grad: g0 ? g0.colorStops.map(x => x.color) : null,
    /* 2026-09-24 腳印：每條看得到的軌跡上，path:// 符號（腳印）的數量、左右腳、轉向、由舊到新的透明度 */
    feet: vis.map(s => (s.data || []).filter(d => d && !Array.isArray(d) && String(d.symbol || '').startsWith('path://'))
      .map(d => ({ f: d.foot, rot: d.symbolRotate, sz: d.symbolSize,
                   a: +((String((d.itemStyle || {}).color || '').match(/,([\d.]+)\)$/) || [])[1] || 1) }))),
    lineW: Math.max(0, ...lines.map(s => ((s.lineStyle || {}).width) || 0)),
    lineA: Math.max(0, ...vis.map(s => +((String((s.lineStyle || {}).color || '').match(/,([\d.]+)\)$/) || [])[1] || 1))),
    ringN: ring ? (ring.data || []).length : -1, movedN: moved ? (moved.data || []).length : -1,
    thinN: thin ? (thin.data || []).length : -1,
    splitArea: ((o.angleAxis[0] || {}).splitArea || {}).show,
    angSplit: ((o.angleAxis[0] || {}).splitLine || {}).show, radSplit: ((o.radiusAxis[0] || {}).splitLine || {}).show,
    glow: sc.data.filter(d => ((d.itemStyle || {}).shadowBlur || 0) > 0).length,
    glowMax: Math.max(0, ...sc.data.map(d => ((d.itemStyle || {}).shadowBlur || 0))),
    ringW: Math.max(0, ...sc.data.map(d => ((d.itemStyle || {}).borderWidth || 0))),
    ringCol: [...new Set(sc.data.map(d => String((d.itemStyle || {}).borderColor || '')))],
    lblFs: ((sc.label || {}).fontSize) || 0,
    focusBold: sc.data.filter(d => (d.label || {}).fontWeight === 700).length,
    fr: (window.App && window.App._rotFrame) || null, anim: o.animation }; }"""

# 三圈底色：沿著每個象限的角度，在三圈的中線上取樣 canvas 像素，量「跟卡片底色差多少」（越外圈越濃）
# ★ 2026-09-26 晚（退回有腳印版）改前→改後：
#   改前：直接在 #rotClock 的畫布上取樣。
#   改後：跟 CLK_SMOOTH 一樣，另開一張只留「象限底色」series 的隔離畫布取樣，量完就丟。
#   理由：腳印與軌跡畫回來之後，族群名字膠囊（深色底）的位置跟著換，改善／領先兩個象限的「中圈」
#     剛好壓了好幾顆膠囊，第 20 百分位被拉到接近卡片底色（實測深色 leading 中圈 66 → 13）。
#     origin/main（沒有腳印）這條在深色主題也已經是紅的（中圈 32），同樣是膠囊壓在取樣線上 ——
#     這條要驗的是「背景由內到外有層次」，量背景本身才對；點、腳印、膠囊的長相由 ①② 另外驗。
CLK_RINGS = r"""(cid) => { const el0 = document.getElementById(cid); const c0 = el0 && echarts.getInstanceByDom(el0); if (!c0) return null;
  const o = c0.getOption(); const bgS = o.series.filter(s => s.name === '象限底色'); if (bgS.length !== 1) return null;
  const W = el0.clientWidth, H = el0.clientHeight, R = 0.84 * Math.min(W, H) / 2, cx = W / 2, cy = H / 2;
  const el = document.createElement('div'); el.style.cssText = `position:fixed;left:0;top:0;width:${W}px;height:${H}px;z-index:-1;pointer-events:none`;
  document.body.appendChild(el);
  const c1 = echarts.init(el, null, { devicePixelRatio: window.devicePixelRatio });
  c1.setOption(Object.assign({}, o, { series: bgS, animation: false, tooltip: [], graphic: [] }));
  const cv = el.querySelector('canvas');
  const g = cv.getContext('2d'); const k = cv.width / el.clientWidth;
  const axisMax = 1.25 * 1.18 * 1.06, mids = [0.3125, 0.9375, (1.25 + axisMax) / 2];
  const bg = getComputedStyle(document.documentElement).getPropertyValue('--panel').trim();
  const hx = bg.replace('#', ''); const B = [0, 2, 4].map(i => parseInt(hx.slice(i, i + 2), 16));
  // 取第 20 百分位（不是中位數）：盤上的點與軌跡是飽和色，會把取樣往上拉；最淡的那幾格才是底色本身
  const med = (a) => { const s = a.slice().sort((x, y) => x - y); return Math.round(s[Math.floor(s.length * 0.2)]); };
  const out = {};
  [['leading', 0], ['improving', 90], ['lagging', 180], ['weakening', 270]].forEach(([q, a0]) => {
    out[q] = mids.map(m => { const r = m / axisMax * R, ds = [];
      for (let a = a0 + 8; a <= a0 + 82; a += 4) { const t = a * Math.PI / 180;
        const x = Math.round((cx + Math.cos(t) * r) * k), y = Math.round((cy - Math.sin(t) * r) * k);
        const p = g.getImageData(x, y, 1, 1).data, al = p[3] / 255;
        /* 圖表的 canvas 底是透明的：getImageData 拿到的是「沒乘過 alpha 的色」，要自己疊在卡片底色上才是眼睛看到的 */
        ds.push([0, 1, 2].reduce((s2, i) => s2 + Math.abs(p[i] * al + B[i] * (1 - al) - B[i]), 0)); }
      return med(ds); }); });
  c1.dispose(); el.remove();
  return out; }"""


# 漸層結構：讀「象限底色」那一塊的 renderItem 畫出來的東西 —— 用 ECharts 內部的圖元樹找 sector 的 style.fill
CLK_GRAD = r"""(cid) => { const el = document.getElementById(cid); const c = el && echarts.getInstanceByDom(el); if (!c) return null;
  const zr = c.getZr(); const cells = []; const thin = { w: [], a: [] };
  const alpha = (col) => { const m = String(col).match(/rgba?\(([^)]+)\)/); if (!m) return 1; const p = m[1].split(',').map(Number); return p.length > 3 ? p[3] : 1; };
  zr.storage.getDisplayList(true).forEach(e => {
    const f = e.style && e.style.fill;
    if (e.type === 'sector' && f && typeof f === 'object' && f.colorStops && e.shape && e.shape.r0 === 0) {
      const a = f.colorStops.map(x => alpha(x.color));
      cells.push({ radial: f.type === 'radial', stops: f.colorStops.length, rising: a.every((v, i) => i === 0 || v > a[i - 1]), a });
    }
    if ((e.type === 'circle' || e.type === 'line') && e.style && e.style.stroke && e.style.fill === 'none' && e.z === 1) {
      thin.w.push(e.style.lineWidth); thin.a.push(alpha(e.style.stroke)); }
  });
  return { n: cells.length, cells, thin: thin.w.length ? thin : null }; }"""

# 平順：沿著「轉弱」象限的半徑從圓心取到盤緣，量每一點跟卡片底色的差距；相鄰兩點差距不能突然跳（硬邊台階會跳）
# ★ 2026-09-25（clock-mobile-reds）：改成量「只畫象限底色那一個 series」的隔離畫布，不再量實際盤面。
#   改前：直接在 #rotClock 的畫布上取樣（5 條半徑取中位數）。
#   改後：用同一份 option、同樣大小，另開一個只留「象限底色」series 的圖取樣，量完就丟。
#   理由：同一天稍早改成「每個族群都有淡腳印」之後，轉弱象限圓心附近壓了點與非焦點腳印，
#   5 條半徑有 3 條以上同時踩到 → 中位數也被拉走（實測第 2 點 61→100、盤緣第 21 點 94→159，maxStep 39～88）。
#   換成 15 條半徑取中位數也還有 19～25 的跳動，所以取樣避開擋不乾淨。
#   隔離畫布量到的深／淺主題 maxStep 只有 5／4，也就是**背景本身沒有硬邊**，紅的是點與腳印壓在取樣線上。
#   這條斷言要驗的是「背景是漸層不是台階」，所以量背景本身才對；點與腳印的長相由 ①②④ 另外驗。
CLK_SMOOTH = r"""(cid) => { const el0 = document.getElementById(cid); const c0 = el0 && echarts.getInstanceByDom(el0); if (!c0) return null;
  const W = el0.clientWidth, H = el0.clientHeight, R = 0.84 * Math.min(W, H) / 2, cx = W / 2, cy = H / 2;
  const o = c0.getOption(); const bgS = o.series.filter(s => s.name === '象限底色'); if (bgS.length !== 1) return null;
  const el = document.createElement('div'); el.style.cssText = `position:fixed;left:0;top:0;width:${W}px;height:${H}px;z-index:-1;pointer-events:none`;
  document.body.appendChild(el);
  const c1 = echarts.init(el, null, { devicePixelRatio: window.devicePixelRatio });
  c1.setOption(Object.assign({}, o, { series: bgS, animation: false, tooltip: [], graphic: [] }));
  const cv = el.querySelector('canvas');
  const g = cv.getContext('2d'); const k = cv.width / el.clientWidth;
  const bg = getComputedStyle(document.documentElement).getPropertyValue('--panel').trim().replace('#', '');
  const B = [0, 2, 4].map(i => parseInt(bg.slice(i, i + 2), 16));
  const best = [];
  // 取「轉弱」象限（右下，平常點最少）的五條半徑（避開雷達刻度的 300°／330° 放射線），每一點取中位數（避開點、腳印、名字的描邊）
  // 從 3/25 開始：圓心附近常常壓著一兩顆點（跟大盤差不多的族群），那不是底色
  for (let i = 3; i <= 24; i++) { const r = R * (i / 25) * 0.97; const vs = [];
    [280, 292, 315, 338, 350].forEach(a => { const t = a * Math.PI / 180;
      const x = Math.round((cx + Math.cos(t) * r) * k), y = Math.round((cy - Math.sin(t) * r) * k);
      const p = g.getImageData(x, y, 1, 1).data, al = p[3] / 255;
      const d = [0, 1, 2].reduce((s2, j) => s2 + Math.abs(p[j] * al + B[j] * (1 - al) - B[j]), 0);
      vs.push(d); });
    vs.sort((x, y) => x - y); best.push(Math.round(vs[2])); }
  c1.dispose(); el.remove();
  const steps = best.slice(1).map((v, i) => Math.abs(v - best[i]));
  return { vals: best, maxStep: Math.max(...steps), span: best[best.length - 1] - best[0], isolated: true }; }"""


def _clk_rings_ok(r):
    """四個象限裡至少三個：內圈 < 中圈 < 外帶（跟卡片底色的差距，越外越大）。"""
    if not r:
        return False
    good = sum(1 for v in r.values() if v[0] < v[1] < v[2])
    return good >= 3


def t_clock_v2(pg, b, base):
    for th in ("dark", "light"):
        pg.set_viewport_size({"width": 1440, "height": 950})
        pg.goto("about:blank")
        pg.goto(f"{base}#flow", wait_until="networkidle")
        pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); localStorage.removeItem('tw.rot.tmode'); } catch (e) {} }", th)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
        scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(600)
        s = pg.evaluate(CLK_STATE, "rotClock")
        if not ok(f"[{th}] 讀得到輪動時鐘的狀態", bool(s) and s["n"] > 6 and s["fr"], s and {k: s[k] for k in ("n", "lines")}):
            continue
        fr = s["fr"]
        # ① 焦點族群：預設模式 focus，最多 6 個，只有焦點畫軌跡
        ok(f"[{th}] ① 軌跡預設是「焦點」模式", fr.get("tmode") == "focus", fr.get("tmode"))
        ok(f"[{th}] ① 焦點族群 1～6 個（佔比前 3 ＋ 最近換段）", 1 <= len(fr.get("focus") or []) <= 6, fr.get("focus"))
        # ★ 2026-09-25（Andy：「為何不是每個點都有軌跡」）：
        #   改前：看得到的軌跡 ≤ 6 條、只有焦點族群有（非焦點 opacity 0）
        #   改後：每一條都看得到；**實、亮（opacity 1）的**仍然 ≤ 6 條而且只有焦點，其餘退到背景（opacity < 1）
        ok(f"[{th}] ① 實、亮的軌跡（opacity 1）≤ 6 條、而且只有焦點族群有",
           0 < s["solid"] <= 6 and set(s["solidGids"]) <= set(fr["focus"]), {"實": s["solid"], "焦點": fr["focus"]})
        ok(f"[{th}] ① 非焦點族群也有軌跡（看得到的 ＝ 全部族群；非焦點的 opacity 介於 0.3～0.4）",
           s["vis"] == s["n"] and all(0.3 <= o <= 0.4 for o, g in zip(s["visOp"], s["visGids"]) if g not in fr["focus"]),
           {"看得到": s["vis"], "族群": s["n"], "不透明度": s["visOp"]})
        ok(f"[{th}] ① 每個族群仍然各有一條 line series", s["lines"] == s["n"], s)
        ok(f"[{th}] ① 焦點族群的名字是粗體（其餘一般字重）", 0 < s["focusBold"] < s["n"], s["focusBold"])
        ok(f"[{th}] ① 族群名稱字級 ≥ 12px", s["lblFs"] >= 12, s["lblFs"])
        # ② ★ 2026-09-24（Andy：「軌跡線 改成小小的腳印」）：
        #   改前：一條漸強的線（.15 → .90）＋ 最新一段三角箭頭 ＋ 每 5 天一顆小點
        #   改後：線不畫（寬 0），改成一串左右交錯、腳尖朝前進方向、越舊越淡的小腳印
        # 2026-09-25：腳印的逐項長相只量焦點那幾條（非焦點的腳印刻意縮小、變疏，另外在「足跡輪盤全部腳印」段驗）
        #   改前：feet＝看得到的全部（那時看得到＝焦點）→ 改後：feet＝opacity 1 的那幾條
        feet = [f for f, o in zip(s["feet"], s["visOp"]) if f and o >= 1]
        allf = [x for f in feet for x in f]
        # ★ 2026-09-24 晚（Andy 參考檔）：桌機在腳印底下留一條極淡的細線（1.2px、25%），把一步一步串成一條路。
        #   改前（同一天稍早）：寬 0 → 改後（桌機）：≤ 1.2px、α ≤ .3；手機仍然是 0（這一段跑在 1440）
        ok(f"[{th}] ② 腳印底下只有一條極淡的細線（≤ 1.2px、透明度 ≤ .3；主角是腳印）",
           0 < s["lineW"] <= 1.2 and s["lineA"] <= .3, [s["lineW"], s["lineA"]])
        ok(f"[{th}] ② 看得到的每一條軌跡都畫出了腳印（每條 ≥ 2 個）",
           len(feet) == s["solid"] and all(len(f) >= 2 for f in feet), [len(f) for f in s["feet"]])
        ok(f"[{th}] ② 左右腳交錯（相鄰兩個腳印一左一右）",
           all(all(f[i]["f"] != f[i + 1]["f"] for i in range(len(f) - 1)) for f in feet), [[x["f"] for x in f][:6] for f in feet][:2])
        ok(f"[{th}] ② 腳尖朝前進方向（每個腳印都有依路徑轉向，不是全部同一個角度）",
           len({round(x["rot"] or 0) for x in allf}) >= 3, sorted({round(x["rot"] or 0) for x in allf})[:8])
        ok(f"[{th}] ② 越舊越淡、越新越清楚（每一條最舊的比最新的淡）",
           all(f[0]["a"] < f[-1]["a"] for f in feet if len(f) >= 2), [(f[0]["a"], f[-1]["a"]) for f in feet][:3])
        ok(f"[{th}] ② 腳印的框約 10～14px、越新越大（參考檔：前掌＋腳跟兩個橢圓，腳本身約 8～11px）",
           all(isinstance(x["sz"], list) and max(x["sz"]) <= 14 and min(x["sz"]) >= 6 for x in allf), allf[:2])
        ok(f"[{th}] ② 舊的「三角箭頭」「每 5 天小點」都不在了（改成腳印，不是疊在一起）", s["arrows"] == 0 and s["marks"] == 0,
           {"箭頭": s["arrows"], "小點": s["marks"]})
        # ③ 象限底色三圈（像素量：越外圈跟卡片底差越多）
        # ★ 2026-09-24（Andy：「輪動時鐘分層需要漸層 並且需搭配細線描繪」）：12 塊硬邊扇形 → 4 塊徑向漸層＋細線
        ok(f"[{th}] ③ 象限底色改成 4 塊（每個象限一塊漸層，splitArea 關掉）", s["ringN"] == 4 and s["splitArea"] is False, s)
        ok(f"[{th}] ③ 分界線與兩圈虛線改由「細線」series 畫（兩個軸自己的 splitLine 關掉，不會畫兩次）",
           s["thinN"] == 1 and s["angSplit"] is False and s["radSplit"] is False, s)
        grad = pg.evaluate(CLK_GRAD, "rotClock")
        ok(f"[{th}] ③ 底色真的是徑向漸層（每一塊的填色是 radial、4 個色標、由內到外越來越濃）",
           bool(grad) and grad["n"] == 4 and all(g["radial"] and g["stops"] == 4 and g["rising"] for g in grad["cells"]), grad)
        # ★ 2026-09-24 晚：盤緣 72 刻裡每 30° 的主刻是 1.5px（參考檔），其餘 1px。改前：全部 1px、≤ .45 → 改後：≤ 1.5px、≤ .5
        ok(f"[{th}] ③ 細線真的是細的（刻度與虛線 ≤ 1.5px、低對比 ≤ .5）",
           bool(grad) and grad["thin"] and all(w <= 1.5 for w in grad["thin"]["w"]) and max(grad["thin"]["a"]) <= .5, grad and grad["thin"])
        rg = pg.evaluate(CLK_RINGS, "rotClock")
        ok(f"[{th}] ③ 由內到外真的有層次：至少三個象限「內 < 中 < 外」（跟卡片底色的差距，canvas 取樣）", _clk_rings_ok(rg), rg)
        smooth = pg.evaluate(CLK_SMOOTH, "rotClock")
        # 改前：在實際盤面取樣 → 改後：在「只畫象限底色」的隔離畫布取樣（理由見 CLK_SMOOTH 上方註解）
        ok(f"[{th}] ③ 是平順過渡不是台階：只畫底色的隔離畫布沿半徑取樣 22 點，相鄰兩點的差距都 ≤ 12（三圈硬邊版在交界處會一次跳 20～30）",
           bool(smooth) and smooth["maxStep"] <= 12 and smooth["span"] >= 12, smooth)
        # ④ 換段色環取代發光
        # ★ 2026-09-24 晚（Andy 參考檔「點＝發光核心＋1px 白外圈」）：
        #   改前：一顆都不准發光（v2 第 5 批把「剛換段」的 14px 光暈換成色環）
        #   改後（桌機）：**每一顆**都有同樣 6px 的微光（不再拿光暈標「換段」—— 換段仍然是色環），外圈 1px 近白
        ok(f"[{th}] ④ 每一顆點都是同樣的微光（shadowBlur ≤ 6，不是舊的 14px 大光暈；換段不靠發光）",
           s["glow"] == s["n"] and s["glowMax"] <= 6, [s["glow"], s["n"], s["glowMax"]])
        ok(f"[{th}] ④ 點的外圈是 1px 近白細邊", s["ringW"] == 1 and all("255,255,255" in c for c in s["ringCol"]), [s["ringW"], s["ringCol"]])
        ok(f"[{th}] ④ 換段色環的數量＝畫面上剛換段的族群數", s["movedN"] == fr.get("rings"), {"色環": s["movedN"], "換段": fr.get("rings")})
        # ⑤ 象限卡的「本週新進」
        nw = pg.evaluate("""() => [...document.querySelectorAll('#rotClock .rotquads .rq')].map(q => ({
            k: q.dataset.k, n: parseInt(((q.querySelector('em')||{}).textContent||'0'), 10),
            nw: q.querySelector('i.nw') ? q.querySelector('i.nw').textContent : '' }))""")
        ok(f"[{th}] ⑤ 象限卡的「+N 本週新進」格式正確、而且不超過那一段的族群數",
           all((not x["nw"]) or (x["nw"].startswith("+") and 0 < int(x["nw"][1:]) <= x["n"]) for x in nw), nw)
        if th == "dark":
            # ⑥ ★ 2026-09-24（Andy：「把顯示軌跡 旁邊的 焦點 全部拿掉，沒必要」）：
            #   改前：「焦點｜全部」兩顆鈕（全部＝16 條軌跡）→ 改後：只剩「顯示腳印」勾選框，預設只畫焦點的腳印
            tools = pg.evaluate("""() => ({ tmode: document.querySelectorAll('#rotTools .rot-tmode, #rotTools [data-m]').length,
                label: [...document.querySelectorAll('#rotTools label')].map(l => l.textContent.trim()),
                long: /已經走過|大圈＝你選的那一天/.test(document.getElementById('rotTools').textContent) })""")
            ok("⑥ 「焦點｜全部」那組鈕真的不在了", tools["tmode"] == 0, tools)
            ok("⑥ 勾選框改名「顯示腳印」（原「顯示軌跡」）", "顯示腳印" in tools["label"] and "顯示軌跡" not in tools["label"], tools["label"])
            ok("⑥ 旁邊那一長句補充說明拿掉了（讀法在「怎麼看 ?」裡）", not tools["long"], tools)
            # 「顯示腳印」真的關得掉、開得回來
            pg.eval_on_selector("#rotTools input.rot-trail", "e => e.click()"); pg.wait_for_timeout(900)
            s2 = pg.evaluate(CLK_STATE, "rotClock")
            ok("⑥ 關掉「顯示腳印」→ 一個腳印都不剩", s2 and sum(len(f) for f in s2["feet"]) == 0, s2 and [len(f) for f in s2["feet"]])
            pg.eval_on_selector("#rotTools input.rot-trail", "e => e.click()"); pg.wait_for_timeout(1200)
            s3 = pg.evaluate(CLK_STATE, "rotClock")
            # 改前：再打開只回來焦點那幾條（vis ≤ 6）→ 改後（2026-09-25）：全部回來，實的仍 ≤ 6
            ok("⑥ 再打開 → 腳印回來（每個族群都有、實的仍只有焦點 ≤ 6）",
               s3 and s3["vis"] == s3["n"] and 0 < s3["solid"] <= 6 and sum(len(f) for f in s3["feet"]) > 0, s3 and [s3["vis"], s3["solid"]])
            # ⑦ 滑到一顆**非焦點**的點 → 它的軌跡出現、其他壓暗；滑開 → 還原
            tgt = pg.evaluate("""() => { const el = document.getElementById('rotClock'); const c = echarts.getInstanceByDom(el);
                const o = c.getOption(); const si = o.series.findIndex(s => s.type === 'scatter');
                const f = new Set((window.App._rotFrame || {}).focus || []);
                const d = o.series[si].data.find(x => x.row && !f.has(x.row.gid)); if (!d) return null;
                const p = c.convertToPixel({ seriesIndex: si }, d.value); const r = el.getBoundingClientRect();
                return { gid: d.row.gid, x: r.left + p[0], y: r.top + p[1] }; }""")
            if ok("⑦ 找得到一顆非焦點的點（下一條要滑過去）", bool(tgt), tgt):
                pg.mouse.move(tgt["x"], tgt["y"]); pg.wait_for_timeout(700)
                hv = pg.evaluate("""(gid) => { const c = echarts.getInstanceByDom(document.getElementById('rotClock'));
                    const ls = c.getOption().series.filter(s => s.type === 'line');
                    const me = ls.find(s => s.gid === gid); const others = ls.filter(s => s.gid !== gid);
                    return { me: me ? me.lineStyle.opacity : null, maxOther: Math.max(0, ...others.map(s => s.lineStyle.opacity)) }; }""", tgt["gid"])
                # 改前「它的軌跡出現」→ 改後（2026-09-25）「它的軌跡提亮」：本來就在（淡），滑到才拉到 1
                ok("⑦ 滑到非焦點的點：它的軌跡提亮（opacity 1）、其他軌跡壓到 ≤ 0.12", hv["me"] == 1 and hv["maxOther"] <= 0.12, hv)
                pg.mouse.move(5, 5); pg.wait_for_timeout(700)
                s4 = pg.evaluate(CLK_STATE, "rotClock")
                # 改前：滑開 → 非焦點又看不見（vis ≤ 6）→ 改後：滑開 → 非焦點退回淡（實的 ≤ 6、全部仍看得到）
                ok("⑦ 滑開之後還原（實的只剩焦點 ≤ 6，非焦點退回淡腳印）", s4 and 0 < s4["solid"] <= 6 and s4["vis"] == s4["n"],
                   s4 and [s4["solid"], s4["vis"]])
            # ⑧ 編號模式的判準跟容器寬度一致（1440 不是編號模式）
            ok("⑧ 1440px 的卡片不是編號模式（容器 ≥ 560px）", (s["fr"] or {}).get("num") is False, s["fr"].get("num"))
    pg.evaluate("() => { try { localStorage.setItem('tw.theme','dark'); localStorage.removeItem('tw.rot.tmode'); } catch (e) {} }")

    # ⑨ 手機 390px
    # ★ 2026-09-25（clock-mobile-reds）改前→改後：
    #   改前：量桌機那張 `#rotClock` 的「編號模式」（編號框、圖下方 `.rotnums` 清單、點清單單獨亮一顆）。
    #   改後：量 390 真正看得到的那張 —— mobile3.js 的手機雷達 `#mRadarFlow`，驗它的等價功能
    #         「名字不擠」＋「名字一個都沒少（點了就看得到）」＋「點清單 → 圖上圈起那一顆」。
    #   理由：≤640 時 body.m3on、卡片掛 .m3host，`#rotClock` 是 display:none（量到 W=0），
    #         編號模式與 `.rotnums` 清單根本沒有畫出來，使用者看到的是手機雷達。
    #         手機雷達不用編號，改成「只替佔比前 5 名＋選取那一顆掛名字膠囊，其他點一下就出現」，
    #         目的一樣：名字不擠成一直排、每個族群都找得到名字。
    #   桌機那套編號模式的判準（容器 < 560 才進）仍由 ⑧ 驗 1440 不進編號模式；
    #   560 以下、640 以上這段寬度目前沒有段落驗（寫在回報裡）。
    m = b.new_page(viewport={"width": 390, "height": 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
    m.on("pageerror", lambda e: fails.append(f"時鐘v2 手機 pageerror: {e}"))
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    m.goto(f"{base}#flow", wait_until="networkidle"); m.wait_for_timeout(2600)
    MR9 = """() => { const host = document.getElementById('mRadarFlow'), svg = host && host.querySelector('svg'); if (!svg) return null;
        const S = +svg.getAttribute('width'), br = svg.getBoundingClientRect(), k = br.width / S;
        const dots = [...host.querySelectorAll('g[data-g]')].map(g => { const c = g.querySelector('circle[stroke="#fff"]');
          return { gid: g.dataset.g, x: +c.getAttribute('cx'), y: +c.getAttribute('cy'), r: +c.getAttribute('r'),
                   ring: +c.getAttribute('stroke-width') > 2 };});
        const caps = [...host.querySelectorAll('g[pointer-events=none]')].map(g => { const r = g.querySelector('rect'), t = g.querySelector('text');
          return { x: +r.getAttribute('x'), y: +r.getAttribute('y'), w: +r.getAttribute('width'), h: +r.getAttribute('height'),
                   t: t.textContent, fs: parseFloat(getComputedStyle(t).fontSize) * k }; });
        let hit = null, out = null;
        caps.forEach((a, i) => { if (a.x < 0 || a.y < 0 || a.x + a.w > S || a.y + a.h > S) out = out || a.t;
          caps.slice(i + 1).forEach(q => { if (a.x < q.x + q.w && q.x < a.x + a.w && a.y < q.y + q.h && q.y < a.y + a.h) hit = hit || [a.t, q.t]; }); });
        const f = document.querySelector('#flowRotCard .mfocus');
        const clk = document.getElementById('rotClock').getBoundingClientRect();
        return { S, k, left: br.left, top: br.top, dots, caps, hit, out, clockW: clk.width,
                 focus: f && f.dataset.focus, focusName: f ? (f.querySelector('.nm') || f).textContent.trim() : '',
                 ringOn: dots.filter(d => d.ring).map(d => d.gid) }; }"""
    st = m.evaluate(MR9)
    if ok("⑨ [390px] 手機雷達接手：桌機那張 #rotClock 藏起來（寬 0）、#mRadarFlow 畫得出 16 顆點",
           bool(st) and st["clockW"] == 0 and len(st["dots"]) == 16, st and {"clockW": st["clockW"], "dots": len(st["dots"])}):
        ok("⑨ [390px] 名字不擠：盤上只掛 1～6 個名字膠囊、每個 ≤ 7 字（超過截成 6 字＋…），不會擠成一直排",
           1 <= len(st["caps"]) <= 6 and all(len(c["t"]) <= 7 for c in st["caps"]), [c["t"] for c in st["caps"]])
        ok("⑨ [390px] 名字膠囊兩兩不重疊、全在盤面內", st["hit"] is None and st["out"] is None, {"撞": st["hit"], "出界": st["out"]})
        ok("⑨ [390px] 名字膠囊的字 ≥ 12px（實際畫出來的大小）", min(c["fs"] for c in st["caps"]) >= 12, [round(c["fs"], 1) for c in st["caps"]])
        # 名字一個都沒少：挑一顆「沒掛名字」的點（DOM 依佔比排序，第 6 顆以後沒膠囊），挑離別顆最遠的那顆，真的用手指點
        cand = st["dots"][5:]
        def _gap(d):
            return min(math.hypot(d["x"] - o["x"], d["y"] - o["y"]) - o["r"] - d["r"] for o in st["dots"] if o is not d)
        tgt = max(cand, key=_gap) if cand else None
        if ok("⑨ [390px] 找得到一顆沒掛名字的點", bool(tgt) and tgt["gid"] != st["focus"], tgt):
            m.touchscreen.tap(st["left"] + tgt["x"] * st["k"], st["top"] + tgt["y"] * st["k"]); m.wait_for_timeout(600)
            s1 = m.evaluate(MR9)
            nm = s1["focusName"][:6]
            ok("⑨ [390px] 點一顆沒掛名字的點 → 焦點條換成它、盤上圈起它、它的名字膠囊出現（名字沒少，只是收起來）",
               s1["focus"] == tgt["gid"] and s1["ringOn"] == [tgt["gid"]] and any(c["t"].startswith(nm) for c in s1["caps"]),
               {"點的": tgt["gid"], "焦點": s1["focus"], "圈": s1["ringOn"], "膠囊": [c["t"] for c in s1["caps"]], "焦點名": s1["focusName"]})
            # 等價於「點清單第一列 → 圖上只亮那一顆」：點排行第 1 列 → 盤上只圈那一顆（有圈的只有 1 顆）
            g1 = m.evaluate("() => (document.querySelector('#mRank li') || {}).dataset.g")
            m.tap('#mRank li:nth-child(1)'); m.wait_for_timeout(500)
            s2 = m.evaluate(MR9)
            ok("⑨ [390px] 點排行第 1 列 → 盤上改圈那一顆（只有 1 顆有圈）、焦點條跟著換回來",
               bool(g1) and s2["ringOn"] == [g1] and s2["focus"] == g1, {"排行第1": g1, "圈": s2["ringOn"], "焦點": s2["focus"]})
        fsz = m.evaluate("""() => Math.min(...[...document.querySelectorAll('#mRank li .n, #mRank li .v, #flowRotCard .mfocus .nm')]
            .map(e => parseFloat(getComputedStyle(e).fontSize)))""")
        ok("⑨ [390px] 排行與焦點條的字都 ≥ 12px", fsz >= 12, fsz)
    m.close()

    # ⑩ 使用者要求減少動態：時鐘的補間整個關掉
    ctx = b.new_context(viewport={"width": 1440, "height": 950}, reduced_motion="reduce")
    rp = ctx.new_page()
    rp.goto(f"{base}#flow", wait_until="networkidle"); rp.wait_for_timeout(2600)
    rs2 = rp.evaluate(CLK_STATE, "rotClock")
    ok("⑩ prefers-reduced-motion：時鐘的動畫關掉（播放變成一天一跳）", bool(rs2) and rs2["anim"] is False, rs2 and rs2["anim"])
    ctx.close()


# ===================================================================== 資金去向 v2（設計系統 v2 第 5 批）
OVF_STATE = r"""() => { const el = document.getElementById('ovFlow'); const c = el && echarts.getInstanceByDom(el); if (!c) return null;
  const o = c.getOption(); const s = o.series[0]; const root = s.data[0]; const chains = root.children || [];
  const rgb = (x) => String(x || '').replace(/\s/g, '').replace(/^rgba\((\d+),(\d+),(\d+),[\d.]+\)$/, '$1,$2,$3');
  const alpha = (x) => { const m = String(x || '').match(/,([\d.]+)\)$/); return m ? +m[1] : null; };
  const d = c.getModel().getSeriesByIndex(0).getData(); let outR = 0;
  for (let i = 0; i < d.count(); i++) { const g = d.getItemGraphicEl(i); if (!g) continue;
    const h = (g.getTextContent && g.getTextContent()) ? g : (g.childAt ? g.childAt(0) : null);
    const t = h && h.getTextContent && h.getTextContent(); if (!t || t.ignore) continue;
    const r = t.getBoundingRect().clone(); r.applyTransform(t.getComputedTransform()); outR = Math.max(outR, r.x + r.width); }
  return { anim: o.animation, W: el.clientWidth, outR,
    chains: chains.map(ch => ({ sym: ch.symbol, size: ch.symbolSize, line: ch.lineStyle.color, a: alpha(ch.lineStyle.color),
      kidsSame: (ch.children || []).every(k => rgb(k.lineStyle.color) === rgb(ch.lineStyle.color)),
      lbl: (ch.label || {}).formatter, first: ((ch.children || [])[0] || {}).label.formatter,
      rest: (ch.children || []).slice(1).map(k => (k.label || {}).formatter) })) }; }"""


def t_flow_v2(pg, base):
    # ★ 2026-09-26 改前→改後：總覽那張的 v2 第 5 批斷言（ECharts：線色 alpha .38／.30、產業鏈直條 roundRect、rich 標籤 cn／gb／gn）
    #   → 桌機改成 flowtopo 緊湊光纖版（Andy 09-26），改驗新畫布：線色＝產業鏈色、圓點、膠囊標籤「名稱 佔比%」、不出畫布。
    #   OVF_STATE 留著（手機 ≤ 820 仍是 ECharts 樹，手機段落用得到）。
    for th in ("dark", "light"):
        pg.set_viewport_size({"width": 1440, "height": 950})
        pg.goto("about:blank")
        pg.goto(f"{base}#overview", wait_until="networkidle")
        pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); } catch (e) {} }", th)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
        scroll_to(pg, "ovFlow"); pg.wait_for_timeout(900)
        t = pg.evaluate(OVFX)
        if not ok(f"[{th}] 總覽的資金去向畫得出來（光纖緊湊版）", bool(t) and t["layout"] == "mini", t and t.get("layout")):
            continue
        L1 = [n for n in t["nodes"] if n["lv"] == 1]; L2 = [n for n in t["nodes"] if n["lv"] == 2]
        dot = {n["key"]: n["dot"] for n in t["nodes"]}
        ok(f"[{th}] ① 族群跟所屬產業鏈同一個色、不同產業鏈不同色",
           all(n["dot"] == dot.get(n["parent"]) for n in L2) and len({n["dot"] for n in L1}) >= min(3, len(L1)), [n["dot"] for n in L1])
        ok(f"[{th}] ② 產業鏈節點是圓點（改前直條）", all(n["shape"] == "circle" for n in L1), [(n["shape"], n["hh"]) for n in L1])
        ok(f"[{th}] ③ 每個標籤都以「數字%」結尾（百分比一個都沒被截掉）",
           all(re.search(r"\d%$", n["text"]) for n in L1 + L2), [n["text"] for n in L1 + L2 if not re.search(r"\d%$", n["text"])][:4])
        ok(f"[{th}] ③ 標籤沒有超出畫布右緣", all(n["lab"]["x"] + n["lab"]["w"] <= t["W"] + 0.5 for n in t["nodes"] if n["lab"]),
           {"寬": t["W"], "最右": max(n["lab"]["x"] + n["lab"]["w"] for n in t["nodes"] if n["lab"])})

    # 資金流向頁那張：鏈色線條、直條節點、小圓點不壓字（小圓點本身保留）
    pg.evaluate("() => { try { localStorage.setItem('tw.theme','dark'); } catch (e) {} }")
    pg.goto(f"{base}#flow", wait_until="networkidle"); pg.wait_for_timeout(3000)
    # ★ 2026-09-24：這裡驗的是經典版（ECharts 樹＋小圓點）；桌機預設的拓撲版由「資金去向拓撲」驗
    sk_classic(pg, True)
    scroll_to(pg, "sankey"); pg.wait_for_timeout(1500)
    sk = pg.evaluate(r"""() => { const c = echarts.getInstanceByDom(document.getElementById('sankey')); if (!c) return null;
        const root = c.getOption().series[0].data[0];
        const rgb = (x) => String(x || '').replace(/\s/g, '').replace(/^rgba\((\d+),(\d+),(\d+),[\d.]+\)$/, '$1,$2,$3');
        return (root.children || []).map(ch => ({ sym: ch.symbol, size: ch.symbolSize,
          same: (ch.children || []).every(g => rgb(g.lineStyle.color) === rgb(ch.lineStyle.color)),
          lbl: (ch.label || {}).formatter })); }""")
    if ok("讀得到資金流向頁的資金去向", bool(sk), sk):
        ok("① 族群那一層的線改用所屬產業鏈的色（跟鏈那條線同一個色相）", all(c["same"] for c in sk), [c["same"] for c in sk])
        ok("② 產業鏈節點是直立細長條（圓角矩形、寬 4）",
           all(c["sym"] == "roundRect" and c["size"][0] == 4 for c in sk), [(c["sym"], c["size"]) for c in sk])
        ok("③ 產業鏈名字用 13px 粗體（rich cn）、百分比仍在", all(c["lbl"].startswith("{cn|") and "%" in c["lbl"] for c in sk),
           [c["lbl"] for c in sk][:3])
    # ⑥ 小圓點不壓字：連續取樣 1.2 秒，每一顆畫出來的點都不在任何標籤外框（含 3px 描邊）裡
    bad, tot = 0, 0
    lbs = pg.evaluate("() => window.App.sankeyLabels()") or []
    for _ in range(8):
        dots = pg.evaluate("() => window.App.sankeyDots()") or []
        tot += len(dots)
        for x, y, _l in dots:
            if any(r["x"] - 3 < x < r["x"] + r["w"] + 3 and r["y"] - 3 < y < r["y"] + r["h"] + 3 for r in lbs):
                bad += 1
        pg.wait_for_timeout(150)
    ok("⑥ 讀得到標籤外框（小圓點要避開的地方）", len(lbs) > 10, len(lbs))
    ok("⑥ 小圓點還在跑（09-20／21 要的傳輸效果保留）", tot > 50 and pg.evaluate("() => window.App.sankeyFxRunning()"), tot)
    ok("⑥ 取樣 8 次、每一顆畫出來的點都不在標籤上（點不壓字）", bad == 0, f"{bad} / {tot} 顆壓在字上")
    sk_classic(pg, False)


# ===================================================================== 點了才出現的資訊：點外面就關、Esc 也關（2026-09-24）
# Andy：「不需要"收起"選項，點擊背景即可消除（每個點擊資訊都確保是這樣功能）」。
# 做法是全站一份登記表（app.js 的 dismissable）。這一段逐項**用真滑鼠**（手機用真的觸控 tap）驗三件事：
#   ① 點面板裡面 → 不會關　② 點面板外面 → 真的關　③ 按 Esc → 真的關
# 「外面」一律挑一個沒有功能的地方點（卡片標題的字），不然量到的可能是「點到別的按鈕」而不是「點背景」。
def _dz_vis(pg, sel):
    return pg.evaluate("""(s) => { const e = document.querySelector(s);
        return !!e && !e.hidden && e.getClientRects().length > 0 && getComputedStyle(e).display !== 'none'; }""", sel)


def _dz_click_el(pg, sel, fx=0.5, fy=0.5):
    """真滑鼠點某個元素的相對位置（先把它捲進畫面中段）。回傳有沒有點到。
    ⚠ 不用 scrollIntoView：時鐘外面包著一層可以捲的 .zpane（滾輪放大），scrollIntoView 會去捲那一層，
      象限卡跟著盤面一起被捲到框外（實測 y = -9），真人根本點不到那裡。一律捲**視窗**。"""
    for _ in range(2):
        pg.evaluate("""(s) => { const e = document.querySelector(s); if (!e) return; const r = e.getBoundingClientRect();
            if (r.top < 90 || r.bottom > innerHeight - 20) window.scrollBy({ top: r.top - innerHeight / 2, behavior: 'instant' }); }""", sel)
        pg.wait_for_timeout(300)
    r = pg.evaluate("""(s) => { const e = document.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect();
        return { x: r.left, y: r.top, w: r.width, h: r.height }; }""", sel)
    if not r or r["w"] <= 0:
        return False
    pg.mouse.click(r["x"] + r["w"] * fx, r["y"] + r["h"] * fy)
    return True


# ★ 2026-09-27（dismiss-fix）改前 → 改後：「外面」改前是點 outside_sel 寬度 20% 的位置 → 改後是點它**第一段沒有功能的字**的中間。
#   根因（桌機 1440 #flow 象限面板／下鑽面板那 3 條紅燈）：`#flowSankeyCard h3` 旁邊的副標 `#sankeySub` 變長之後，
#   h3 寬 470px，20% ＝ 94px 正好落在標題旁的「?」鈕上（81～103px）。「?」刻意不算點外面（dismissable 的 ignore 有 .howbtn：
#   按別張卡的說明不該順手收掉面板），而且它會打開跳出式說明 #howPop —— 說明開著時 Esc 只關說明（DECISIONS #258 ⑥），
#   所以接下來的 Esc 也關不掉面板。**網站沒壞**：實測點真正的背景（標題文字）與沒有說明浮層時按 Esc，兩個面板都會關。
#   這條註解最上面就寫了「外面一律挑一個沒有功能的地方點（卡片標題的字）」—— 改成量字的位置才真的做到，
#   並且先斷言「那一點真的是沒有功能的字」，下次版面再變也不會默默點到按鈕上。
#   例外只有一個：受測的面板本身是跳出式說明（在 #howPop 裡）時，蓋在整頁上的 #howBack 就是它的「背景」，點到它才是對的。
_DZ_TXT = """([s, ps]) => { const e = [...document.querySelectorAll(s)].find(x => x.getClientRects().length > 0); if (!e) return null;
    const pe = ps && document.querySelector(ps), inPop = !!(pe && pe.closest('#howPop'));
    const bad = 'button,a,input,select,textarea,label,[role="button"],.howbtn';
    const w = document.createTreeWalker(e, NodeFilter.SHOW_TEXT,
      { acceptNode: n => n.textContent.trim() && !n.parentElement.closest(bad) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP });
    const n = w.nextNode(); if (!n) return null;
    const rg = document.createRange(); rg.selectNodeContents(n); const r = rg.getBoundingClientRect();
    if (r.top < 90 || r.bottom > innerHeight - 90) window.scrollBy({ top: r.top - innerHeight / 2, behavior: 'instant' });
    const r2 = rg.getBoundingClientRect();
    const x = r2.left + Math.min(r2.width / 2, 24), y = r2.top + r2.height / 2, hit = document.elementFromPoint(x, y);
    return { x, y, txt: n.textContent.trim().slice(0, 12),
             plain: !!hit && ((e.contains(hit) && !hit.closest(bad)) || (inPop && hit.id === 'howBack')),
             hit: hit ? hit.tagName + (hit.id ? '#' + hit.id : '') + (hit.className && hit.className.baseVal === undefined ? '.' + hit.className : '') : null }; }"""


def _dz_out_pt(pg, sel, panel=None):
    """outside_sel 裡第一段「沒有功能的字」的螢幕座標（先捲進畫面）。回傳 None＝找不到。"""
    pt = pg.evaluate(_DZ_TXT, [sel, panel])
    if pt:
        pg.wait_for_timeout(250)
        pt = pg.evaluate(_DZ_TXT, [sel, panel])       # 捲完再量一次（這一頁是 scroll-behavior:smooth）
    return pt


def _dz_rect(pg, sel):
    return pg.evaluate("(s) => { const e = document.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; }", sel)


def _dz_three(pg, tag, panel, open_fn, inside_sel, outside_sel, wait=700):
    """一個面板的三件事。open_fn() 要把面板打開並回傳 True。"""
    if not ok(f"[{tag}] 打得開（後面三條的前提）", open_fn() and _dz_vis(pg, panel), panel):
        return
    ok(f"[{tag}] 面板裡沒有「收起 ✕」按鈕", pg.evaluate(
        "(s) => { const e = document.querySelector(s); return !!e && !e.querySelector('[data-x]') && !/收起 ✕/.test(e.textContent); }", panel))
    _dz_click_el(pg, inside_sel, 0.5, 0.5); pg.wait_for_timeout(wait)
    ok(f"[{tag}] ① 點面板裡面 → 不會關", _dz_vis(pg, panel))
    pt = _dz_out_pt(pg, outside_sel, panel)
    if not ok(f"[{tag}] 「外面」那一點是沒有功能的字（{outside_sel}），不是按鈕或連結（前提）", bool(pt) and pt["plain"], pt):
        return
    c0 = _dz_rect(pg, panel)
    pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(wait)
    ok(f"[{tag}] ② 點面板外面（{outside_sel} 的「{pt['txt']}」）→ 真的關了", not _dz_vis(pg, panel))
    # 關掉之後原本面板那塊不能留下一層看不見的東西擋住底下（頁面其他地方要還能點）
    if c0:
        ok(f"[{tag}] 關掉之後原本面板的位置不會擋住底下的東西", pg.evaluate(
            "([s, x, y]) => { const h = document.elementFromPoint(x, y), p = document.querySelector(s); return !h || !p || !p.contains(h); }",
            [panel, c0["x"], c0["y"]]), c0)
    if not ok(f"[{tag}] 再打開一次（驗 Esc 的前提）", open_fn() and _dz_vis(pg, panel), panel):
        return
    pg.keyboard.press("Escape"); pg.wait_for_timeout(wait)
    ok(f"[{tag}] ③ 按 Esc → 真的關了", not _dz_vis(pg, panel))


def t_dismiss(pg, b, base, code):
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.goto(f"{base}#flow", wait_until="networkidle"); pg.wait_for_timeout(2800)
    scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(400)

    # ---- 1. 輪動時鐘的象限展開面板
    def open_stage():
        k = pg.evaluate("""() => { const q = [...document.querySelectorAll('#rotClock .rotquads .rq')]
            .find(x => parseInt(((x.querySelector('em')||{}).textContent||'0'), 10) > 0); return q ? q.dataset.k : ''; }""")
        if not k:
            return False
        if not _dz_vis(pg, "#stagePanel"):
            _dz_click_el(pg, f'#rotClock .rotquads .rq[data-k="{k}"]'); pg.wait_for_timeout(900)
        return True
    _dz_three(pg, "象限展開面板", "#stagePanel", open_stage, "#stagePanel .ph", "#flowSankeyCard h3")
    # 點另一顆象限卡＝換一段（不是「點外面」）
    if open_stage():
        k0 = pg.evaluate("() => document.getElementById('stagePanel').dataset.k")
        k1 = pg.evaluate("""(k0) => { const q = [...document.querySelectorAll('#rotClock .rotquads .rq')]
            .find(x => x.dataset.k !== k0 && parseInt(((x.querySelector('em')||{}).textContent||'0'), 10) > 0); return q ? q.dataset.k : ''; }""", k0)
        if k1:
            _dz_click_el(pg, f'#rotClock .rotquads .rq[data-k="{k1}"]'); pg.wait_for_timeout(900)
            ok("[象限展開面板] 點另一顆象限卡＝換一段（面板還開著、換成那一段），不會被當成點外面",
               _dz_vis(pg, "#stagePanel") and pg.evaluate("() => document.getElementById('stagePanel').dataset.k") == k1,
               [k0, k1, pg.evaluate("() => document.getElementById('stagePanel').dataset.k")])
        pg.keyboard.press("Escape"); pg.wait_for_timeout(500)

    # ---- 2. 下鑽面板（點排行長條 → #rankPanel）
    def open_rank():
        if _dz_vis(pg, "#rankPanel"):
            return True
        pt = pg.evaluate("""() => { const el = document.getElementById('rankFlow'); const c = echarts.getInstanceByDom(el); if (!c) return null;
            const d = c.getOption().series[0].data; let bi = 0; d.forEach((x, k) => { if (Math.abs(x.value) > Math.abs(d[bi].value)) bi = k; });
            const p0 = c.convertToPixel({ seriesIndex: 0 }, [0, bi]), p1 = c.convertToPixel({ seriesIndex: 0 }, [d[bi].value, bi]);
            { const rr = el.getBoundingClientRect(); window.scrollBy({ top: rr.top - innerHeight / 2 + rr.height / 2, behavior: 'instant' }); } const r = el.getBoundingClientRect();
            return { x: r.left + (p0[0] + p1[0]) / 2, y: r.top + p0[1] }; }""")
        if not pt:
            return False
        pg.wait_for_timeout(300)
        pt = pg.evaluate("""() => { const el = document.getElementById('rankFlow'); const c = echarts.getInstanceByDom(el);
            const d = c.getOption().series[0].data; let bi = 0; d.forEach((x, k) => { if (Math.abs(x.value) > Math.abs(d[bi].value)) bi = k; });
            const p0 = c.convertToPixel({ seriesIndex: 0 }, [0, bi]), p1 = c.convertToPixel({ seriesIndex: 0 }, [d[bi].value, bi]);
            const r = el.getBoundingClientRect(); return { x: r.left + (p0[0] + p1[0]) / 2, y: r.top + p0[1] }; }""")
        pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(1300)
        return True
    _dz_three(pg, "下鑽成分股面板", "#rankPanel", open_rank, "#rankPanel .note", "#flowSankeyCard h3")
    # ★ 2026-09-27：兩塊面板關掉之後，頁面其他地方要還能正常點 —— 真的按一顆別的按鈕，驗它真的有反應
    #   （按資金去向的「?」→ 跳出式說明打開 → Esc 關），不是只驗「元素還在」。
    ok("[資金流向] 象限／下鑽面板都關掉了（下一條的前提）", not _dz_vis(pg, "#stagePanel") and not _dz_vis(pg, "#rankPanel"))
    _dz_click_el(pg, '#flowSankeyCard .howbtn[data-how="sankey"]'); pg.wait_for_timeout(700)
    ok("[資金流向] 面板關掉之後，別的按鈕照樣點得動（資金去向「?」→ 說明真的跳出來）", _dz_vis(pg, "#howPop"))
    pg.keyboard.press("Escape"); pg.wait_for_timeout(500)
    ok("[資金流向] 說明按 Esc 關掉，面板也沒有被誤開", not _dz_vis(pg, "#howPop") and not _dz_vis(pg, "#stagePanel") and not _dz_vis(pg, "#rankPanel"))

    # ---- 3. 「怎麼看 ?」說明
    def open_how():
        if not _dz_vis(pg, "#how-rot"):
            _dz_click_el(pg, '#v-flow .howbtn[data-how="rot"]'); pg.wait_for_timeout(500)
        return True
    _dz_three(pg, "怎麼看說明", "#how-rot", open_how, "#how-rot", "#flowSankeyCard h3")
    ok("[怎麼看說明] 按鈕不再寫「收起說明」", "收起" not in pg.evaluate(
        "() => document.querySelector('#v-flow .howbtn[data-how=\"rot\"]').textContent"))

    # ---- 4. 資金集中度：點某一天 → 側欄
    def open_conc():
        if _dz_vis(pg, "#concSide"):
            return True
        pg.evaluate("() => { const r = document.getElementById('conc').getBoundingClientRect(); window.scrollBy({ top: r.top - innerHeight / 2 + r.height / 2, behavior: 'instant' }); }")
        pg.wait_for_timeout(500)
        r = pg.evaluate("() => { const r = document.getElementById('conc').getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height }; }")
        pg.mouse.click(r["x"] + r["w"] * 0.6, r["y"] + r["h"] * 0.45); pg.wait_for_timeout(1200)
        return True
    _dz_three(pg, "資金集中度側欄", "#concSide", open_conc, "#concSide .hh", "#flowInstCard h3")

    # ---- 5. 放大罩：點遮罩背景關、Esc 關、點罩裡的圖不關
    # ★ 2026-09-26 改前→改後：改前用資金流向頁足跡輪盤的「放大」開罩 → 改後那顆拿掉（Andy「放大功能取消」），
    #   放大罩本身（openZoom）沒動，改用總覽資金熱力圖的「放大 ⤢」（#heatZoom）開同一個罩來驗。
    ok("[放大罩] 資金流向頁沒有足跡輪盤的「放大」了", pg.evaluate("() => !document.getElementById('rotZoomBtn')"))
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2600)
    _dz_click_el(pg, "#heatZoom"); pg.wait_for_timeout(2200)
    if ok("[放大罩] 打得開", _dz_vis(pg, "#zoomOv")):
        _dz_click_el(pg, "#zoomTitle"); pg.wait_for_timeout(500)
        ok("[放大罩] 點罩裡面（標題）不會關", _dz_vis(pg, "#zoomOv"))
        pg.mouse.click(4, 470); pg.wait_for_timeout(700)
        ok("[放大罩] 點遮罩背景真的關了", not _dz_vis(pg, "#zoomOv"))
        _dz_click_el(pg, "#heatZoom"); pg.wait_for_timeout(2000)
        pg.keyboard.press("Escape"); pg.wait_for_timeout(700)
        ok("[放大罩] 按 Esc 真的關了", not _dz_vis(pg, "#zoomOv"))

    # ---- 6. 總覽熱力圖的成分股面板
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2600)

    def open_heat():
        if _dz_vis(pg, "#heatPanel"):
            return True
        pg.evaluate("() => { const el = document.getElementById('heat'); { const rr = el.getBoundingClientRect(); window.scrollBy({ top: rr.top - innerHeight / 2 + rr.height / 2, behavior: 'instant' }); } }"); pg.wait_for_timeout(300)
        r = pg.evaluate("() => { const r = document.getElementById('heat').getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height }; }")
        for fx, fy in ((0.2, 0.35), (0.45, 0.5), (0.72, 0.4), (0.3, 0.68)):
            pg.mouse.click(r["x"] + r["w"] * fx, r["y"] + r["h"] * fy); pg.wait_for_timeout(900)
            if _dz_vis(pg, "#heatPanel"):
                return True
        return False
    _dz_three(pg, "熱力圖成分股面板", "#heatPanel", open_heat, "#heatPanel .hh", "#ovHeatCard h3")

    # ---- 7. 市場明細：漲跌分佈點一段 → 清單
    pg.goto(f"{base}#market", wait_until="networkidle"); pg.wait_for_timeout(2600)

    def open_dist():
        if _dz_vis(pg, "#distPick"):
            return True
        pt = pg.evaluate("""() => { const el = document.getElementById('chgDist'); const c = el && echarts.getInstanceByDom(el); if (!c) return null;
            { const rr = el.getBoundingClientRect(); window.scrollBy({ top: rr.top - innerHeight / 2 + rr.height / 2, behavior: 'instant' }); } const d = c.getOption().series[0].data; let bi = 0;
            d.forEach((x, k) => { if ((x.value || 0) > (d[bi].value || 0)) bi = k; });
            const p = c.convertToPixel({ seriesIndex: 0 }, [bi, (d[bi].value || 0) / 2]); const r = el.getBoundingClientRect();
            return { x: r.left + p[0], y: r.top + p[1] }; }""")
        if not pt:
            return False
        pg.wait_for_timeout(300)
        pt = pg.evaluate("""() => { const el = document.getElementById('chgDist'); const c = echarts.getInstanceByDom(el);
            const d = c.getOption().series[0].data; let bi = 0; d.forEach((x, k) => { if ((x.value || 0) > (d[bi].value || 0)) bi = k; });
            const p = c.convertToPixel({ seriesIndex: 0 }, [bi, (d[bi].value || 0) / 2]); const r = el.getBoundingClientRect();
            return { x: r.left + p[0], y: r.top + p[1] }; }""")
        pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(900)
        return True
    _dz_three(pg, "漲跌分佈清單", "#distPick", open_dist, "#distPick .hh", "#mktTitle")

    # ---- 8. 題材剖析圖（熱力圖分頁）：點題材 → 就地展開；點外面 → 網址回 #heatmap/theme
    pg.goto(f"{base}#heatmap/theme", wait_until="networkidle"); pg.wait_for_timeout(2600)
    opened = False
    for fx, fy in ((0.2, 0.3), (0.5, 0.5), (0.75, 0.35)):
        pg.evaluate("() => { const el = document.getElementById('themeMap'); { const rr = el.getBoundingClientRect(); window.scrollBy({ top: rr.top - innerHeight / 2 + rr.height / 2, behavior: 'instant' }); } }"); pg.wait_for_timeout(300)
        r = pg.evaluate("() => { const r = document.getElementById('themeMap').getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height }; }")
        pg.mouse.click(r["x"] + r["w"] * fx, r["y"] + r["h"] * fy); pg.wait_for_timeout(1500)
        if pg.evaluate("() => location.hash.startsWith('#heatmap/theme/') && !!document.getElementById('themeDiagram')"):
            opened = True
            break
    if ok("[題材剖析圖] 點題材方塊就地展開（前提）", opened, pg.evaluate("location.hash")):
        ok("[題材剖析圖] 沒有「收起 ✕」", pg.evaluate("() => !document.getElementById('themeClose')"))
        _dz_click_el(pg, "#themeDetail h3", 0.2, 0.5); pg.wait_for_timeout(900)
        ok("[題材剖析圖] ① 點剖析圖卡片裡面 → 不會收", pg.evaluate("() => location.hash.startsWith('#heatmap/theme/')"))
        _dz_click_el(pg, "#indHeat h3", 0.1, 0.5); pg.wait_for_timeout(1400)
        ok("[題材剖析圖] ② 點卡片外面 → 收回去（網址回到 #heatmap/theme、剖析圖不見）",
           pg.evaluate("() => location.hash === '#heatmap/theme' && !document.getElementById('themeDiagram')"),
           pg.evaluate("location.hash"))

    # ---- 9. 產業鏈剖析圖的零件小卡：Esc 收（圖上點背景收是既有的「點背景恢復」段落在驗）
    pg.goto(f"{base}#industry/ai_server/dg/ic_substrate", wait_until="networkidle"); pg.wait_for_timeout(2800)
    got = pg.evaluate("""() => { const ns = [...document.querySelectorAll('#prodDiagram [data-seg]')].filter(x => x.dataset.part && !x.classList.contains('lrow'));
        const n = ns[0]; if (!n) return false; n.dispatchEvent(new MouseEvent('click', { bubbles: true })); return true; }""")
    pg.wait_for_timeout(900)
    if ok("[零件小卡] 點零件小卡出現（前提）", got and _dz_vis(pg, "#partCard")):
        ok("[零件小卡] 沒有「✕」", pg.evaluate("() => !document.getElementById('pcClose')"))
        pg.keyboard.press("Escape"); pg.wait_for_timeout(700)
        ok("[零件小卡] 按 Esc 真的收掉", not _dz_vis(pg, "#partCard"))

    # ---- 10. 個股頁的指標下拉：Esc 關（點外面關是既有的「設定面板」段落在驗）
    # ★ 2026-09-26 改前：`#cfgBtn`（⚙ 設定）→ 改後：`#indBtn`（指標 ▾）
    pg.goto(f"{base}#stock/{code}", wait_until="networkidle"); pg.wait_for_timeout(2600)
    if ok("[指標下拉] 按鈕在", bool(pg.query_selector("#indBtn"))):
        _dz_click_el(pg, "#indBtn"); pg.wait_for_timeout(600)
        if ok("[指標下拉] 打得開", _dz_vis(pg, "#cfgPop")):
            pg.keyboard.press("Escape"); pg.wait_for_timeout(500)
            ok("[指標下拉] 按 Esc 真的關了", not _dz_vis(pg, "#cfgPop"))

    # ---- 11. 搜尋建議：Esc 關
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(1800)
    q = pg.query_selector("#q")
    if q and q.is_visible():
        pg.click("#q"); pg.keyboard.type("23"); pg.wait_for_timeout(500)
        sg_on = pg.evaluate("() => { const s = document.querySelector('.search .sg, #sg, .sugg'); return !!s && s.style.display !== 'none' && s.getClientRects().length > 0; }")
        if sg_on:
            pg.keyboard.press("Escape"); pg.wait_for_timeout(400)
            ok("[搜尋建議] 按 Esc 真的收掉", not pg.evaluate("() => { const s = document.querySelector('.search .sg, #sg, .sugg'); return !!s && s.style.display !== 'none' && s.getClientRects().length > 0; }"))
        pg.fill("#q", "")

    # ---- 12. 手機 390：真的用觸控 tap（不是滑鼠）
    m = b.new_page(viewport={"width": 390, "height": 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    m.goto(f"{base}#flow", wait_until="networkidle"); m.wait_for_timeout(2600)

    def tap(sel, fx=0.5, fy=0.5):
        for _ in range(2):
            m.evaluate("""(s) => { const e = document.querySelector(s); if (!e) return; const r = e.getBoundingClientRect();
                if (r.top < 90 || r.bottom > innerHeight - 90) window.scrollBy({ top: r.top - innerHeight / 2, behavior: 'instant' }); }""", sel)
            m.wait_for_timeout(300)
        r = m.evaluate("(s) => { const e = document.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height }; }", sel)
        if r and r["w"] > 0:
            m.touchscreen.tap(r["x"] + r["w"] * fx, r["y"] + r["h"] * fy)
        m.wait_for_timeout(800)
    # ★ 2026-09-27（dismiss-fix）改前 → 改後：
    #   改前：直接找 `#rotClock .rq`，找不到就 `if k:` 整段**默默跳過**。
    #   改後：先按卡片最下面的「完整版 ›」，再用觸控把象限面板與下鑽面板各驗一輪（點裡面不關、點外面關、Esc 關、關完別處還點得動）；
    #         找不到象限卡就是紅燈，不再默默跳過。
    #   理由：≤640px 手機 v3（mobile3.js）預設把桌機那張輪盤藏成 0×0，`#rotClock .rq` 永遠找不到 —— 改前這段手機驗收
    #         從 2026-09-24 起一條都沒跑過，卻是綠的。手機使用者要碰到這兩塊面板，唯一的入口就是「完整版 ›」。
    #   「外面」一樣挑沒有功能的字（`_dz_out_pt`），不再點寬度 15% 的位置：手機上那一格的 h3 是藏起來的手機版標題，
    #   改前那一點量到的是 (0, 0) —— 點到的是最上面的工具列，綠燈是碰巧。
    def tap_pt(pt):
        m.touchscreen.tap(pt["x"], pt["y"]); m.wait_for_timeout(800)
    fb_ok = m.evaluate("() => { const b = document.querySelector('#flowRotCard > .mfullbtn'); return !!b && b.getClientRects().length > 0; }")
    if ok("[手機 390] 資金輪動卡有「完整版 ›」（手機上要碰到象限面板的唯一入口）", fb_ok):
        tap("#flowRotCard > .mfullbtn"); m.wait_for_timeout(1500)
        ok("[手機 390] 觸控按「完整版 ›」→ 卡片真的切成完整版", m.evaluate("() => document.getElementById('flowRotCard').classList.contains('mfull')"))
    m.evaluate("() => { const e = document.getElementById('rotClockWrap'); if (e) { const r = e.getBoundingClientRect(); window.scrollBy({ top: r.top - 100, behavior: 'instant' }); } }")
    m.wait_for_timeout(900)
    k = m.evaluate("""() => { const q = [...document.querySelectorAll('#rotClock .rotquads .rq')]
        .find(x => x.getClientRects().length > 0 && parseInt(((x.querySelector('em')||{}).textContent||'0'), 10) > 0); return q ? q.dataset.k : ''; }""")
    if ok("[手機 390] 完整版裡找得到有族群的象限卡（前提，不再默默跳過）", bool(k), k):
        def m_open_stage():
            if not _dz_vis(m, "#stagePanel"):
                tap(f'#rotClock .rotquads .rq[data-k="{k}"]')
            return _dz_vis(m, "#stagePanel")
        if ok("[手機 390] 觸控點象限卡，面板打開", m_open_stage()):
            tap("#stagePanel .ph")
            ok("[手機 390] 觸控點面板裡面 → 不會關", _dz_vis(m, "#stagePanel"))
            pt = _dz_out_pt(m, "#flowRotCard h3")
            if ok("[手機 390] 「外面」那一點是看得到、沒有功能的字（前提）", bool(pt) and pt["plain"], pt):
                tap_pt(pt)
                ok("[手機 390] 觸控點面板外面 → 真的關了", not _dz_vis(m, "#stagePanel"))
            if ok("[手機 390] 象限面板再打開一次（驗 Esc 的前提）", m_open_stage()):
                m.keyboard.press("Escape"); m.wait_for_timeout(600)
                ok("[手機 390] 象限面板按 Esc 關（外接鍵盤）", not _dz_vis(m, "#stagePanel"))
        # 下鑽面板：從象限面板點一個族群 → 同一個位置換成成分股（#rankPanel）
        def m_open_rank():
            if _dz_vis(m, "#rankPanel"):
                return True
            if m_open_stage():
                tap("#stagePanel li[data-gid]")
            return _dz_vis(m, "#rankPanel")
        if ok("[手機 390] 觸控點象限面板裡的族群 → 下鑽成分股面板打開", m_open_rank()):
            ok("[手機 390] 側欄同時只開一塊（下鑽打開、象限面板收起）", not _dz_vis(m, "#stagePanel"))
            inner = "#rankPanel .note" if m.query_selector("#rankPanel .note") else "#rankPanel"
            tap(inner, 0.5, 0.2)
            ok("[手機 390] 觸控點下鑽面板裡面 → 不會關", _dz_vis(m, "#rankPanel"))
            pt = _dz_out_pt(m, "#flowRotCard h3")
            if ok("[手機 390] 「外面」那一點是看得到、沒有功能的字（下鑽，前提）", bool(pt) and pt["plain"], pt):
                tap_pt(pt)
                ok("[手機 390] 觸控點下鑽面板外面 → 真的關了", not _dz_vis(m, "#rankPanel"))
            if ok("[手機 390] 下鑽面板再打開一次（驗 Esc 的前提）", m_open_rank()):
                m.keyboard.press("Escape"); m.wait_for_timeout(600)
                ok("[手機 390] 下鑽面板按 Esc 關（外接鍵盤）", not _dz_vis(m, "#rankPanel"))
        # 關完之後別的地方照樣點得動：再點一次象限卡，面板真的重新打開（不是被卡住的殘影）
        ok("[手機 390] 兩塊面板都關掉之後，再點象限卡照樣打得開", m_open_stage())
        m.keyboard.press("Escape"); m.wait_for_timeout(400)
    if m.query_selector("#moreBtn") and m.evaluate("() => getComputedStyle(document.getElementById('moreBtn')).display !== 'none'"):
        m.evaluate("() => window.scrollTo(0, 0)"); m.wait_for_timeout(200)
        tap("#moreBtn")
        if ok("[手機 390] 「⋯ 更多工具」打得開", _dz_vis(m, "#morePop")):
            m.keyboard.press("Escape"); m.wait_for_timeout(400)
            ok("[手機 390] 「⋯ 更多工具」按 Esc 關（外接鍵盤）", not _dz_vis(m, "#morePop"))
    m.close()


# ===================================================================== 全站圖表圓滑化（2026-09-24）
# Andy：「所有的長條圖 圓餅圖 等圖表都顯得太過銳利，需要圓滑化」。
# 量的是 getOption() 裡**真的上了**的樣式（不是 CSS、不是我心裡想的）：
#   長條每一根都有圓角、而且圓在「長出去的那一端」（正值／負值、橫的／直的各自對）；堆疊只圓最外面那一段；
#   圓餅有扇區圓角＋間隙；儀表圓頭；折線圓頭圓角、**但不准變 smooth**（週期統計今天剛改成直線段）。
SOFT_SCAN = r"""() => { const out = { bar: [], pie: [], gauge: [], line: [], stack: [] };
  /* ★ 2026-09-24 晚：改成掃**畫面上每一個 ECharts 實例**（DOM 上的 _echarts_instance_），不只 App.charts ——
     產業地圖、個股各分頁的圖是用元素建的，不一定登記在 App.charts 裡，只掃登記的會漏掉（CEO：全站逐張列）。*/
  const insts = [...document.querySelectorAll('[_echarts_instance_]')].map(el => [el.id || ((el.closest('[id]') || {}).id) || '?', echarts.getInstanceByDom(el)]);
  insts.forEach(([id, c]) => { if (!c || c.isDisposed()) return;
    const el = c.getDom(); if (!el || !el.getClientRects().length || el.clientWidth < 2) return;
    const o = c.getOption(); const ss = o.series || [];
    if (ss.some(s => s.type === 'candlestick')) return;
    const yCat = (s) => { const y = (o.yAxis || [])[s.yAxisIndex || 0]; return !!(y && y.type === 'category'); };
    const val = (d) => { const v = d && typeof d === 'object' && !Array.isArray(d) ? d.value : d; const n = Array.isArray(v) ? v[v.length - 1] : v; return n == null || n === '-' ? null : +n; };
    const rad = (s, d) => (d && typeof d === 'object' && d.itemStyle && d.itemStyle.borderRadius != null) ? d.itemStyle.borderRadius : (s.itemStyle || {}).borderRadius;
    const stacks = {};
    ss.forEach((s, si) => {
      if (s.type === 'bar') {
        if (s.stack != null) { (stacks[s.stack] = stacks[s.stack] || []).push(s); return; }
        const h = yCat(s); let n = 0, bad = [], lbad = [], thick = [];
        const sd = c.getModel().getSeriesByIndex(si).getData();
        const lab = s.label || {};
        (s.data || []).forEach((d, k) => { const v = val(d); if (v == null || !isFinite(v) || v === 0) return; n++;
          const r = rad(s, d); const rr = Array.isArray(r) ? r : [r, r, r, r];
          // 膠囊：畫出來的厚度的一半就是半圓；四個角的圓角都要 ≥ 厚度一半（zrender 會縮回剛好半圓）
          const L = sd.getItemLayout(k) || {}; const t = Math.abs(h ? L.height : L.width) || 0; thick.push(Math.round(t));
          // 2026-09-24 Andy：「圓弧化太嚴重」改回小圓角 → 改前「四角 ≥ 厚度一半（膠囊）」→ 改後「最大圓角 1～4px」
          const mx = Math.max(...rr.map(x => +x || 0)); if (!(t > 0 && mx >= 1 && mx <= 4)) bad.push({ k, v, r, t });
          // 數值標籤在末端外側：正值右／上、負值左／下（有開標籤、而且不是寫在長條裡面的）
          const il = (d && typeof d === 'object' && d.label) || {};
          const show = il.show != null ? il.show : lab.show;
          const pos = il.position || lab.position;
          if (show && !/inside/.test(String(pos || ''))) {
            const want = h ? (v < 0 ? 'left' : 'right') : (v < 0 ? 'bottom' : 'top');
            const fs = il.fontSize || lab.fontSize || 12;
            if (pos !== want || fs < 12) lbad.push({ k, v, pos, want, fs });
          } });
        const d0 = (s.data || []).find(x => x != null);
        out.bar.push({ id, si, n, bad: bad.slice(0, 3), nbad: bad.length, lbad: lbad.slice(0, 3), nlbad: lbad.length,
          lbl: !!lab.show, thick: thick.length ? [Math.min(...thick), Math.max(...thick)] : null,
          r0: JSON.stringify(rad(s, d0)), pos0: ((d0 && d0.label) || {}).position || lab.position || null, h: yCat(s) });
      } else if (s.type === 'pie') {
        out.pie.push({ id, r: (s.itemStyle || {}).borderRadius, pad: s.padAngle, n: (s.data || []).length });
      } else if (s.type === 'gauge') {
        out.gauge.push({ id, axis: (s.axisLine || {}).roundCap, prog: s.progress && s.progress.show ? s.progress.roundCap : 'n/a' });
      } else if (s.type === 'line') {
        out.line.push({ id, name: s.name || '', cap: (s.lineStyle || {}).cap, join: (s.lineStyle || {}).join, smooth: s.smooth });
      }
    });
    Object.keys(stacks).forEach(sk => { const arr = stacks[sk]; const n = Math.max(...arr.map(s => (s.data || []).length));
      for (let k = 0; k < n; k++) { let pos = -1, neg = -1;
        arr.forEach((s, i) => { const v = val((s.data || [])[k]); if (v > 0) pos = i; else if (v < 0) neg = i; });
        arr.forEach((s, i) => { const v = val((s.data || [])[k]); if (!v) return; const r = rad(s, (s.data || [])[k]);
          const has = Array.isArray(r) ? r.some(x => x > 0) : r > 0;
          out.stack.push({ id, k, i, outer: i === pos || i === neg, has }); }); } });
  });
  return out; }"""


def t_soften(pg, base):
    pg.set_viewport_size({"width": 1440, "height": 950})
    seen = {"bar": 0, "pie": 0, "gauge": 0, "line": 0, "stack": 0}
    listing = []                       # 逐張列：哪一頁、哪張圖、讀 getOption 的結果（寫進備註，回報要逐張列）
    # ★ 2026-09-24 晚（Andy：「整個網頁，都需要改成我要求長條圖風格 圓餅圖風格」）：個股各分頁（營收／獲利／除權息／籌碼／基本資料）也掃
    for rt in ("overview", "flow", "industry", "market", "season", "industry/semiconductor",
               "stock/2330|revenue", "stock/2330|profit", "stock/2330|dividend", "stock/2330|chips", "stock/2330|basics"):
        rt, _, tab = rt.partition("|")
        pg.goto("about:blank"); pg.goto(f"{base}#{rt}", wait_until="networkidle"); pg.wait_for_timeout(2600)
        if tab:
            pg.evaluate("(t) => { const b = document.querySelector('#stockTabs button[data-t=\"' + t + '\"]'); if (b) b.click(); }", tab)
            pg.wait_for_timeout(1800)
            rt = rt + "/" + tab
        # 往下捲一輪，讓懶載入的圖都畫出來
        pg.evaluate("async () => { for (let y = 0; y < document.body.scrollHeight; y += 700) { window.scrollTo(0, y); await new Promise(r => setTimeout(r, 120)); } window.scrollTo(0, 0); }")
        pg.wait_for_timeout(900)
        s = pg.evaluate(SOFT_SCAN)
        for k in seen:
            seen[k] += len(s[k])
        for x in s["bar"]:
            listing.append(f"#{rt} {x['id']}（{'橫' if x['h'] else '直'}）圓角 {x['r0']}、標籤 {x['pos0'] or ('無' if not x['lbl'] else '預設')}、厚 {x['thick']}")
        for sk in sorted({x["id"] for x in s["stack"]}):
            listing.append(f"#{rt} {sk}（堆疊）只圓最外段 {sum(1 for x in s['stack'] if x['id'] == sk and x['outer'] and x['has'])} 格")
        for x in s["pie"]:
            listing.append(f"#{rt} {x['id']}（圓餅）圓角 {x['r']}、縫 {x['pad']}")
        badbar = [x for x in s["bar"] if x["nbad"]]
        ok(f"[圓滑化 #{rt}] 每一根長條都是小圓角（1～4px，不是膠囊；{len(s['bar'])} 個 series）", not badbar, badbar[:3])
        lb = [x for x in s["bar"] if x["nlbad"]]
        ok(f"[圓滑化 #{rt}] 長條的數值標籤都在末端外側（正值右／上、負值左／下），字 ≥ 12px", not lb, lb[:3])
        thick = [x for x in s["bar"] if x["thick"] and x["thick"][1] > 18.5]
        ok(f"[圓滑化 #{rt}] 非堆疊長條的厚度 ≤ 18px（參考圖是細長條，不是一塊磚）", not thick, thick[:3])
        ok(f"[圓滑化 #{rt}] 圓餅有扇區圓角＋間隙（只有一塊的那種是甜甜圈內側的細軌道，沒有角可圓）", all(x["n"] <= 1 or ((x["r"] or 0) > 0 and (x["pad"] or 0) > 0) for x in s["pie"]), s["pie"])
        ok(f"[圓滑化 #{rt}] 儀表是圓頭", all(x["axis"] is True and x["prog"] in (True, "n/a") for x in s["gauge"]), s["gauge"])
        ok(f"[圓滑化 #{rt}] 折線的端點與轉折是圓的（cap／join = round）",
           all(x["cap"] == "round" and x["join"] == "round" for x in s["line"]), [x for x in s["line"] if x["cap"] != "round"][:3])
        st_bad = [x for x in s["stack"] if x["outer"] != x["has"]]
        ok(f"[圓滑化 #{rt}] 堆疊長條只圓最外面那一段（中間那幾段不圓，不會變成一串珠子）", not st_bad, st_bad[:4])
        if rt == "season":
            # 週期統計：今天剛因為「平滑曲線畫出假波浪」改成直線段 —— 圓滑化不准把 smooth 打開
            pg.evaluate("() => { const b = [...document.querySelectorAll('#v-season button')].find(x => /曲線/.test(x.textContent)); if (b) b.click(); }")
            pg.wait_for_timeout(1500)
            s2 = pg.evaluate(SOFT_SCAN)
            ok("[圓滑化 #season] 曲線圖的線仍然是直線段（smooth 沒被打開）", all(not x["smooth"] for x in s2["line"]) and len(s2["line"]) > 0,
               [(x["name"], x["smooth"]) for x in s2["line"]][:4])
    # ★ 2026-09-25：總覽改版後全站已經沒有儀表圖（gauge）—— 沒有就不判紅（沒有東西可以圓滑化，不是空掃）；
    #   其餘四種仍然必須各至少掃到一個，才證明這一段真的走過整站。
    ok("[圓滑化] 全站真的掃到了長條、圓餅、折線、堆疊各至少一個（不是空掃；儀表圖全站已沒有，不判）",
       all(v > 0 for k, v in seen.items() if k != "gauge"), seen)
    notes.append("圖表圓滑化逐張（讀 getOption）：\n      " + "\n      ".join(listing))

    # ---- 甜甜圈（Andy 參考圖一）：產業地圖「成交值占比」
    DONUT = """() => { const el = document.getElementById('gpPie'); const c = el && echarts.getInstanceByDom(el); if (!c) return null;
        const o = c.getOption(); const s0 = o.series[0]; const tr = o.series[1];
        const lg = document.getElementById('gpLegend'); const lr = lg ? lg.getBoundingClientRect() : null; const pr = el.getBoundingClientRect();
        const cols = lg ? getComputedStyle(lg).gridTemplateColumns.split(' ').filter(Boolean).length : 0;
        const rows = lg ? [...lg.querySelectorAll('.lg')].map(b => { const r = b.getBoundingClientRect(); return { x: Math.round(r.left), fs: parseFloat(getComputedStyle(b).fontSize) }; }) : [];
        return { radius: s0.radius, pad: s0.padAngle, br: (s0.itemStyle || {}).borderRadius, label: (s0.label || {}).show, line: (s0.labelLine || {}).show,
                 scale: ((s0.emphasis || {}).scaleSize), track: tr ? { r: tr.radius, silent: tr.silent } : null,
                 titles: (o.title || []).map(t => ({ text: t.text, fs: (t.textStyle || {}).fontSize })),
                 legendBelow: !!lr && lr.top >= pr.bottom - 1, cols, xs: [...new Set(rows.map(r => r.x))].length, minFs: Math.min(...rows.map(r => r.fs)),
                 n: (s0.data || []).length, nLegend: rows.length }; }"""
    for th in ("dark", "light"):
        pg.set_viewport_size({"width": 1440, "height": 950})
        pg.goto(f"{base}#industry", wait_until="networkidle")
        pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); } catch (e) {} }", th)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
        d = pg.evaluate(DONUT)
        if not ok(f"[甜甜圈 {th}] 讀得到產業地圖的成交值占比", bool(d), d):
            continue
        ok(f"[甜甜圈 {th}] 粗環：內 58%、外 78%", d["radius"] == ["58%", "78%"], d["radius"])
        ok(f"[甜甜圈 {th}] 扇區圓角、縫只有 1～2°（不是大縫）", (d["br"] or 0) > 0 and 0 < (d["pad"] or 0) <= 2, [d["br"], d["pad"]])
        ok(f"[甜甜圈 {th}] 環內側有一圈細軌道（不能點）", bool(d["track"]) and d["track"]["silent"] is True, d["track"])
        ok(f"[甜甜圈 {th}] 不再用引線把標籤拉到圓外", d["label"] is False and d["line"] is False, [d["label"], d["line"]])
        ok(f"[甜甜圈 {th}] 中心兩行字：小字標題（12～13px）＋大數字（32～36px）",
           len(d["titles"]) == 2 and 12 <= d["titles"][0]["fs"] <= 13 and 32 <= d["titles"][1]["fs"] <= 36 and "%" in d["titles"][1]["text"], d["titles"])
        ok(f"[甜甜圈 {th}] 圖例在圖下方、兩欄、每一塊一列、字 ≥ 12px",
           d["legendBelow"] and d["cols"] == 2 and d["xs"] == 2 and d["nLegend"] == d["n"] and d["minFs"] >= 12, d)
        ok(f"[甜甜圈 {th}] 滑到扇區會外擴（≤ 4px）", 0 < (d["scale"] or 0) <= 4, d["scale"])
        if th == "dark":
            # 真滑鼠滑到第一塊扇區 → 中心換成那一塊的名字；滑開 → 回到「前五大」
            pt = pg.evaluate("""() => { const el = document.getElementById('gpPie'); el.scrollIntoView({ block: 'center', behavior: 'instant' });
                const c = echarts.getInstanceByDom(el); const L = c.getModel().getSeriesByIndex(0).getData().getItemLayout(0);
                const a = (L.startAngle + L.endAngle) / 2, rr = (L.r0 + L.r) / 2; const r = el.getBoundingClientRect();
                return { x: r.left + L.cx + Math.cos(a) * rr, y: r.top + L.cy + Math.sin(a) * rr,
                         name: c.getOption().series[0].data[0].name }; }""")
            pg.mouse.move(pt["x"], pt["y"]); pg.wait_for_timeout(700)
            t1 = pg.evaluate("() => echarts.getInstanceByDom(document.getElementById('gpPie')).getOption().title.map(t => t.text)")
            ok("[甜甜圈] 滑到扇區 → 中心換成那一塊的名字與百分比", t1[0] == pt["name"] and "%" in t1[1], [t1, pt["name"]])
            ok("[甜甜圈] 滑到扇區 → 下方圖例那一列一起亮", pg.evaluate("(n) => { const b = document.querySelector('#gpLegend .lg.on'); return !!b && b.dataset.n === n; }", pt["name"]))
            pg.mouse.move(5, 5); pg.wait_for_timeout(700)
            t2 = pg.evaluate("() => echarts.getInstanceByDom(document.getElementById('gpPie')).getOption().title.map(t => t.text)")
            ok("[甜甜圈] 滑開 → 中心回到「前五大」", t2[0] == "前五大", t2)
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'dark'); } catch (e) {} }")
    # 390：兩張卡上下疊、圖例仍然兩欄、沒有橫向捲軸
    pg.set_viewport_size({"width": 390, "height": 844})
    pg.goto(f"{base}#industry", wait_until="networkidle"); pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2600)
    d = pg.evaluate(DONUT)
    if ok("[甜甜圈 390] 讀得到", bool(d), d):
        ok("[甜甜圈 390] 圖例在圖下方、兩欄、字 ≥ 12px", d["legendBelow"] and d["cols"] == 2 and d["minFs"] >= 12, d)
        ok("[甜甜圈 390] 沒有橫向捲軸", pg.evaluate("() => document.documentElement.scrollWidth <= innerWidth + 1"))
    # 同一頁左邊的「族群漲跌幅」長條：負值標籤寫在左端外側之後，要有自己的位置，不准壓到族群名。
    # 改前（main 3748ade，390px 量到 6 對）：「HBM 高頻寬記憶體」×「-3.3%」、「矽光子與 CPO」×「-3.1%」
    #   —— 負號被名字蓋掉，看起來像正的；x 軸五個刻度擠成一串（4 對）。改後：0 對。
    ovl = pg.evaluate("""() => { const c = echarts.getInstanceByDom(document.getElementById('gpBar')); if (!c) return null;
        const bx = c.getZr().storage.getDisplayList(true).filter(e => e.style && e.style.text).map(e => {
            const r = e.getBoundingRect().clone(); if (e.transform) r.applyTransform(e.transform); return { t: String(e.style.text), r }; });
        const out = [];
        for (let i = 0; i < bx.length; i++) for (let j = i + 1; j < bx.length; j++) { const a = bx[i].r, b = bx[j].r;
            if (a.x < b.x + b.width - 1 && b.x < a.x + a.width - 1 && a.y < b.y + b.height - 1 && b.y < a.y + a.height - 1) out.push([bx[i].t, bx[j].t]); }
        return { n: bx.length, out }; }""")
    ok("[漲跌長條 390] 族群名、數值標籤、刻度字彼此都不重疊（負值的數字不會壓到名字）",
       bool(ovl) and ovl["n"] > 10 and not ovl["out"], ovl)
    pg.set_viewport_size({"width": 1440, "height": 950})


# ===================================================================== 輪動時鐘：水滴＋水波（2026-09-24）
# Andy：「幫我將輪動時鐘結合水滴這概念，我當他移動會有水波文，試試看這特效」。
def _rip(pg, cid="rotClock"):
    return pg.evaluate("(id) => window.App.rotRipple(id)", cid)


def _rot_px(pg):
    """每一顆族群點現在在畫布上的像素位置（ripple 應該冒在「出發的地方」）。"""
    return pg.evaluate("""() => { const el = document.getElementById('rotClock'); const c = echarts.getInstanceByDom(el);
        const o = c.getOption(); const si = o.series.findIndex(s => s.type === 'scatter');
        return o.series[si].data.map(d => { const p = c.convertToPixel({ seriesIndex: si }, d.value); return { gid: d.row.gid, x: p[0], y: p[1] }; }); }""")


def t_ripple(pg, b, base):
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.goto(f"{base}#flow", wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.removeItem('tw.rot.ripple'); } catch (e) {} }")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
    scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(500)
    r0 = _rip(pg)
    ok("① 預設是開的，而且工具列有「水波」勾選框（打勾）",
       r0["on"] and pg.evaluate("() => { const x = document.querySelector('#rotTools input.rot-ripple'); return !!x && x.checked; }"), r0)
    ok("① 靜止的時候一圈都沒有（一進頁面不會冒）", r0["alive"] == 0, r0)
    # 點真的挪位置：把「看哪一天」拉到 10 天前
    before = _rot_px(pg)
    rot_seek(pg, 10, 180)
    r1 = _rip(pg)
    ok("② 點移動了 → 真的冒出水波（活著的圈 > 0、疊層 canvas 在）", r1["alive"] > 0 and r1["canvas"], r1)
    # 每一圈都冒在某一顆點「出發的位置」上（2px 內）
    far = [p for p in r1["pts"] if min(((p["x"] - q["x"]) ** 2 + (p["y"] - q["y"]) ** 2) ** .5 for q in before) > 2]
    ok("② 每一圈都冒在點出發的位置（2px 內），不是亂冒", r1["pts"] and not far, far[:3])
    ok("② 同時最多 48 圈（不會把畫面洗成一片）", r1["alive"] <= 48, r1["alive"])
    pg.wait_for_timeout(3000)
    r2 = _rip(pg)
    ok("③ 靜止 3 秒之後一圈都不剩（不會一直冒、不閃爍）", r2["alive"] == 0, r2)
    pg.wait_for_timeout(1000)
    ok("③ 靜止期間沒有再冒新的（累計次數沒變）", _rip(pg)["spawned"] == r2["spawned"], [_rip(pg)["spawned"], r2["spawned"]])
    # 播放一步：量幀率（這個容器沒有 GPU，數字偏保守）
    pg.evaluate("() => { const b = [...document.querySelectorAll('#rotBack button')].find(x => /▶/.test(x.textContent)); if (b) b.click(); }")
    fr = pg.evaluate("""() => new Promise(res => { let n = 0; const t0 = performance.now(); let last = t0, mx = 0;
        const f = (t) => { n++; mx = Math.max(mx, t - last); last = t; if (t - t0 < 2000) requestAnimationFrame(f); else res({ fps: +(n / ((t - t0) / 1000)).toFixed(1), maxGap: Math.round(mx) }); };
        requestAnimationFrame(f); })""")
    r3 = _rip(pg)
    pg.evaluate("() => { const b = [...document.querySelectorAll('#rotBack button')].find(x => /❚|⏸|暫停/.test(x.textContent)); if (b) b.click(); }")
    ok("④ 播放時每一步都會冒水波", r3["spawned"] > r2["spawned"], [r2["spawned"], r3["spawned"]])
    ok(f"④ 播放＋水波時畫面不卡：2 秒平均 ≥ 20 fps、最長一幀 ≤ 250ms（量到 {fr['fps']} fps、最長 {fr['maxGap']}ms）",
       fr["fps"] >= 20 and fr["maxGap"] <= 250, fr)
    pg.wait_for_timeout(2500)
    rot_seek(pg, 0, 1500)
    pg.wait_for_timeout(1500)
    # ⑤ 關掉：真的點勾選框
    pg.click("#rotTools input.rot-ripple"); pg.wait_for_timeout(300)
    ls = pg.evaluate("() => { try { return localStorage.getItem('tw.rot.ripple'); } catch (e) { return null; } }")
    ok("⑤ 關掉之後記在這台瀏覽器（tw.rot.ripple = '0'）", ls == "0", ls)
    s0 = _rip(pg)["spawned"]
    rot_seek(pg, 8, 200)
    r4 = _rip(pg)
    ok("⑤ 關掉之後點照樣會動，但一圈水波都不冒", r4["alive"] == 0 and r4["spawned"] == s0 and not r4["on"], r4)
    pg.click("#rotTools input.rot-ripple"); pg.wait_for_timeout(300)
    ok("⑤ 再打開 → 記回 '1'", pg.evaluate("() => localStorage.getItem('tw.rot.ripple')") == "1")
    rot_seek(pg, 0, 1500)
    # ⑥ 點的長相。★ 2026-09-24 晚（Andy 參考檔「點＝發光核心＋1px 白外圈」，桌機）：
    #   改前：水滴（帶高光的徑向漸層）→ 改後（桌機）：實心核心 ＋ 6px 同色微光 ＋ 1px 近白外圈；手機仍是水滴（下面 390 那段驗）
    drop = pg.evaluate("""() => { const c = echarts.getInstanceByDom(document.getElementById('rotClock'));
        const sc = c.getOption().series.find(s => s.type === 'scatter');
        return { solid: sc.data.filter(d => typeof d.itemStyle.color === 'string').length, all: sc.data.length,
                 glow: sc.data.filter(d => (d.itemStyle.shadowBlur || 0) > 0 && d.itemStyle.shadowBlur <= 6).length,
                 ring: sc.data.filter(d => d.itemStyle.borderWidth === 1 && /255,255,255/.test(d.itemStyle.borderColor)).length }; }""")
    ok("⑥ [桌機] 每一顆點都是發光核心＋1px 白外圈", drop["solid"] == drop["all"] == drop["glow"] == drop["ring"] and drop["all"] > 0, drop)
    m = b.new_page(viewport={"width": 390, "height": 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    m.goto(f"{base}#flow", wait_until="networkidle"); m.wait_for_timeout(2600)
    drop2 = m.evaluate("""() => { const c = echarts.getInstanceByDom(document.getElementById('rotClock'));
        const sc = c.getOption().series.find(s => s.type === 'scatter');
        return { radial: sc.data.filter(d => d.itemStyle.color && d.itemStyle.color.type === 'radial').length, all: sc.data.length }; }""")
    ok("⑥ [手機 390] 點仍然是上一版的水滴（Andy：手機先暫停，這一批不動手機）", drop2["radial"] == drop2["all"] > 0, drop2)
    m.close()
    # ⑦ 總覽的小時鐘：一律不冒（總覽 Andy 不要動畫）
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2400)
    mini = _rip(pg, "rotClockMini")
    ok("⑦ 總覽的小時鐘沒有水波疊層（總覽不加動畫）", not mini["canvas"] and mini["spawned"] == 0, mini)
    # ⑧ 系統開了「減少動態效果」：一圈都不冒
    ctx = b.new_context(viewport={"width": 1440, "height": 950}, reduced_motion="reduce")
    rp = ctx.new_page()
    rp.goto(f"{base}#flow", wait_until="networkidle"); rp.wait_for_timeout(2600)
    rot_seek(rp, 10, 300)
    rr = _rip(rp)
    ok("⑧ 減少動態效果：點移動了也一圈都不冒", rr["alive"] == 0 and rr["spawned"] == 0, rr)
    ctx.close()
    pg.set_viewport_size({"width": 1500, "height": 1000})



# ★ 2026-09-26（Andy：卡片名稱「足跡輪盤」要改名 —— 腳印已拿掉，名字對不上內容；CEO 定名「資金輪盤」）：
#   全站使用者看得到的地方都不准再出現「足跡輪盤」：可見文字（innerText）、aria-label／title、「?」說明的內文，
#   桌機 1440 與手機 390 各掃一次（手機的雷達是 mobile3.js 另一份，aria-label 與載入中字樣是它自己寫的）。
#   說明內文要**真的按開**才會填進去（HOW 是點了才 innerHTML），所以總覽按 rotm、資金流向按 rot，讀跳出來的氣泡。
OLD_WHEEL = "足跡輪盤"
OLD_WHEEL_JS = """(old) => { const hit = [];
  const t = document.body.innerText || ''; if (t.includes(old)) hit.push('innerText: ' + t.split('\\n').filter(l => l.includes(old)).slice(0, 3).join(' | '));
  document.querySelectorAll('[aria-label],[title]').forEach(e => {
    ['aria-label', 'title'].forEach(a => { const v = e.getAttribute(a) || ''; if (v.includes(old)) hit.push(a + ': ' + (e.id || e.className) + ' → ' + v); }); });
  const tt = document.title || ''; if (tt.includes(old)) hit.push('document.title: ' + tt);
  return hit; }"""
def no_old_wheel_name(pg, base):
    vp = pg.viewport_size
    hits = []
    try:
        for w, h in ((1440, 950), (390, 844)):
            pg.set_viewport_size({"width": w, "height": h})
            for r, how in (("overview", "rotm"), ("flow", "rot"), ("industry", None), ("themes", None),
                           ("season", None), ("market/updown", None), ("heatmap", None)):
                pg.goto(f"{base}#{r}", wait_until="networkidle"); pg.wait_for_timeout(1600)
                if how:
                    # 說明氣泡：按開 → 讀 → 按 Esc 關；按不到（手機那顆在別的分段）就略過，不當成通過
                    btn = pg.locator(f'.howbtn[data-how="{how}"]:visible').first
                    if btn.count():
                        btn.click(); pg.wait_for_timeout(400)
                        box = pg.evaluate(f"() => ((document.getElementById('howPop')||{{}}).innerText || '') + ' ' + ((document.getElementById('how-{how}')||{{}}).innerText || '')")  # 氣泡標題＋內文
                        if OLD_WHEEL in box: hits.append(f"[{w}] #{r} 「?」{how}：{box[:80]}")
                        pg.keyboard.press("Escape"); pg.wait_for_timeout(200)
                hits += [f"[{w}] #{r} {x}" for x in pg.evaluate(OLD_WHEEL_JS, OLD_WHEEL)]
            # 反面也要驗：新名字真的上去了（不是整個標題被拿掉才「找不到舊名字」）
            pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(1600)
            nw = pg.evaluate("""() => ({ h3: ((document.querySelector('#ovRotHead h3') || {}).childNodes || [{}])[0].textContent || '',
                aria: (document.querySelector('#ovRotHead .howbtn') || {getAttribute: () => ''}).getAttribute('aria-label') || '',
                m: (document.querySelector('#mRadarOv svg') || {getAttribute: () => null}).getAttribute('aria-label') })""")
            ok(f"[{w}] 總覽右欄卡片標題＝「資金輪盤」、「?」的 aria-label＝「資金輪盤怎麼看」",
               nw["h3"].strip() == "資金輪盤" and nw["aria"] == "資金輪盤怎麼看", nw)
            if w <= 640:
                ok(f"[{w}] 手機雷達的 aria-label＝「資金輪盤」", nw["m"] == "資金輪盤", nw)
    finally:
        if vp: pg.set_viewport_size(vp)
    ok("★ 全站可見文字（含 aria-label／title／「?」說明）不再出現「足跡輪盤」（2026-09-26 改名資金輪盤）", not hits, hits[:6])

# ===================================================================== 足跡輪盤（2026-09-24）
# Andy：「輪動時鐘 改成 足跡輪盤，要有點像是雷達的樣貌，並且軌跡線 改成小小的腳印…圓圈幫我再縮小／
#        時間軸拉Bar 只需要留一個…把顯示軌跡 旁邊的 焦點 全部拿掉…」。
# 腳印的長相、焦點鈕不在了在「時鐘v2」段；即時的短狀態字在「輪動時鐘即時」段；排行副標在「資金輪動合併」段。
# 這一段驗：改名、雷達刻度、圓點縮小（量重疊對數）、拉Bar 改天數 → 腳印段數真的變。
FP_OVERLAP = """() => { const el = document.getElementById('rotClock'); const c = echarts.getInstanceByDom(el); const o = c.getOption();
  const si = o.series.findIndex(s => s.type === 'scatter'); const d = o.series[si].data;
  const pts = d.map(x => { const p = c.convertToPixel({ seriesIndex: si }, x.value); return { x: p[0], y: p[1], r: x.row.sz / 2, sz: x.row.sz }; });
  let n = 0; for (let i = 0; i < pts.length; i++) for (let j = i + 1; j < pts.length; j++)
    if (Math.hypot(pts[i].x - pts[j].x, pts[i].y - pts[j].y) < pts[i].r + pts[j].r) n++;
  return { dots: pts.length, pairs: n, minSz: Math.min(...pts.map(p => p.sz)), maxSz: Math.max(...pts.map(p => p.sz)) }; }"""
FP_FEET = """() => { const c = echarts.getInstanceByDom(document.getElementById('rotClock'));
  return c.getOption().series.filter(s => s.type === 'line' && ((s.lineStyle || {}).opacity || 0) > 0)
    .reduce((a, s) => a + (s.data || []).filter(d => d && !Array.isArray(d) && String(d.symbol || '').startsWith('path://')).length, 0); }"""


def t_footprint(pg, b, base):
    pg.set_viewport_size({"width": 1440, "height": 950})
    reset_rot(pg, base, 2600)
    scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(500)
    # ① 改名
    nm = pg.evaluate("""() => ({ h4: (document.querySelector('#flowRotCard h4.subh')||{}).textContent || '',
        page: document.getElementById('v-flow').innerText })""")
    # ★ 2026-09-26 改前→改後：改前「改名『足跡輪盤』」→ 改後「資金輪盤」（Andy：腳印已拿掉，名字對不上內容；CEO 定名）
    ok("① 卡片裡那張圖改名「資金輪盤」", nm["h4"].startswith("資金輪盤"), nm["h4"])
    no_old_wheel_name(pg, base)
    # 上面那支會把頁面帶去七個分頁、切 390 再切回來；後面②③量的是資金流向頁 1440 的盤面，所以回到跟開頭同一個狀態
    #（不重置的話 ③ 會在錯的版面上量到 109 對重疊 —— 那是量測假象，不是畫面）
    pg.set_viewport_size({"width": 1440, "height": 950})
    reset_rot(pg, base, 2600)
    scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(500)
    ok("① 資金流向頁上看不到「輪動時鐘」四個字了", "輪動時鐘" not in nm["page"], [ln for ln in nm["page"].splitlines() if "輪動時鐘" in ln][:3])
    # ★ 2026-09-26 改前→改後：改前「放大視窗的標題也是足跡輪盤」→ 改後放大鈕與放大視窗拿掉（Andy「放大功能取消」）
    ok("① 足跡輪盤沒有放大鈕了（2026-09-26 拿掉）", pg.evaluate("() => !document.getElementById('rotZoomBtn')"))
    # ② 雷達盤面（★ 2026-09-24 晚改成 Andy 參考檔的盤面，桌機）：
    #   改前：距離環 3 ＋ 兩圈虛線 ＋ 盤緣 ＝ 6 圈；放射狀細線 8 ＋ 每 10° 刻度 36 ＋ 十字 2；圓心小點 1
    #   改後：三圈虛線（一半／最大偏離／盤緣）；十字 2 ＋ 盤緣 72 刻（30° 主刻 12 條 1.5px）；沒有圓心小點
    #   盤面本身仍然是靜態的 —— 會轉的掃描光束畫在另一張疊層 canvas（「掃描光束」段驗它），不進 ECharts。
    rad = pg.evaluate("""() => { const c = echarts.getInstanceByDom(document.getElementById('rotClock'));
        const els = c.getZr().storage.getDisplayList(true).filter(e => e.z === 1);
        const cir = els.filter(e => e.type === 'circle' && e.style && e.style.fill === 'none');
        const ln = els.filter(e => e.type === 'line');
        return { circles: cir.length, dashed: cir.filter(e => e.style.lineDash && e.style.lineDash.length).length,
                 lines: ln.length, major: ln.filter(e => e.style.lineWidth === 1.5).length,
                 dot: els.filter(e => e.type === 'circle' && e.style && e.style.fill && e.style.fill !== 'none').length,
                 anim: els.some(e => e.animators && e.animators.length) }; }""")
    ok("② 三圈同心虛線（今天最大偏離的一半／最大偏離／盤緣）", rad["circles"] == 3 and rad["dashed"] == 3, rad)
    ok("② 十字軸 ＋ 盤緣 72 刻羅盤刻度（= 74 條；30° 主刻 12 條較粗）", rad["lines"] == 74 and rad["major"] == 12, rad)
    ok("② 參考檔沒有的圓心小點拿掉了", rad["dot"] == 0, rad)
    ok("② 盤面刻度本身是靜態的（會轉的只有疊層上的掃描光束）", not rad["anim"], rad)
    # ③ 圓點縮小：6～14px；重疊對數（圓心距離 < 兩個半徑相加）
    ov = pg.evaluate(FP_OVERLAP)
    ok("③ 族群圓點縮成 6～14px（改前 9～26px）", ov["minSz"] >= 6 and ov["maxSz"] <= 14, ov)
    ok("③ [1440] 預設 16 個族群的圓點重疊 ≤ 5 對（改前 8 對）", ov["pairs"] <= 5, ov)
    # ④ 拉Bar 改天數 → 腳印段數真的變、排行標題日期真的變
    rot_span(pg, 5, 1300)
    f5, s5 = pg.evaluate(FP_FEET), text(pg, "#rankSub")
    rot_span(pg, 25, 1300)
    f25, s25 = pg.evaluate(FP_FEET), text(pg, "#rankSub")
    ok("④ 拉Bar 從 5 天前拉到 25 天前，腳印真的變多（走的路變長）", f25 > f5 > 0, [f5, f25])
    changed("④ 同一個動作，排行標題的起始日真的跟著變", s5, s25)
    ok("④ 讀數寫「25 天前」", (text(pg, "#rotBack .val") or "").startswith("25 天前"), text(pg, "#rotBack .val"))
    rot_span(pg, 20, 900)
    # ⑤ 手機 390：圓點重疊也要少（改前 14 對）、沒有橫向捲軸、拉Bar 讀數 ≥ 12px
    m = b.new_page(viewport={"width": 390, "height": 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    m.goto(f"{base}#flow", wait_until="networkidle"); m.wait_for_timeout(2600)
    # ★ 2026-09-25（stale-reds）改前→改後：
    #   改前：在 390 量 `#rotClock`（桌機那張 ECharts）的重疊 → 量到 105～109 對。
    #   改後：量使用者在 390 真正看到的那張 —— mobile3.js 的 `#mRadarFlow`（SVG 雷達）。
    #   理由：≤640 時 body.m3on、卡片掛 .m3host，桌機那張 `#rotClock` 是 display:none（0×0），
    #   convertToPixel 在 0×0 的圖上把 16 顆點全算到同一小塊，105 對是量測假象，不是畫面。
    #   但換量真正看得到的雷達之後，它**真的**擠：16 顆有 15 對重疊（尺度用全部 ~50 族群算、盤上只畫 16 顆，
    #   全被壓在圓心附近）→ 真 bug，已修 mobile3.js（尺度改用盤上那 16 顆，跟桌機 scope 同一條）。
    hid = m.evaluate("() => { const r = document.getElementById('rotClock').getBoundingClientRect(); return { m3on: document.body.classList.contains('m3on'), w: r.width, h: r.height }; }")
    ok("⑤ [390] 手機版掛上了、桌機那張 #rotClock 藏起來（所以重疊要量手機雷達）", hid["m3on"] and hid["w"] == 0, hid)
    MR_OVERLAP = """() => { const cs = [...document.querySelectorAll('#mRadarFlow g[data-g] circle[stroke="#fff"]')]
        .map(c => ({ g: c.parentNode.dataset.g, x: +c.getAttribute('cx'), y: +c.getAttribute('cy'), r: +c.getAttribute('r') }));
      let n = 0; for (let i = 0; i < cs.length; i++) for (let j = i + 1; j < cs.length; j++)
        if (Math.hypot(cs[i].x - cs[j].x, cs[i].y - cs[j].y) < cs[i].r + cs[j].r) n++;
      const svg = document.querySelector('#mRadarFlow svg'), S = svg ? +svg.getAttribute('width') : 0;
      const far = cs.length ? Math.max(...cs.map(c => Math.hypot(c.x - S / 2, c.y - S / 2))) / (S / 2 - 30) : 0;
      const lbl = [...document.querySelectorAll('#mRadarFlow svg g[pointer-events=none] rect')].map(r => ({ x: +r.getAttribute('x'), y: +r.getAttribute('y'), w: +r.getAttribute('width'), h: +r.getAttribute('height') }));
      return { dots: cs.length, pairs: n, far: +far.toFixed(2), lbl, pos: Object.fromEntries(cs.map(c => [c.g, [Math.round(c.x), Math.round(c.y)]])) }; }"""
    ov2 = m.evaluate(MR_OVERLAP)
    ok("⑤ [390] 手機雷達 16 顆族群圓點重疊 ≤ 8 對（改前 15 對）", ov2["dots"] == 16 and ov2["pairs"] <= 8, {k: ov2[k] for k in ("dots", "pairs", "far")})
    ok("⑤ [390] 盤上最遠那顆點離圓心 ≥ 盤半徑 60%（改前全擠在圓心 30% 內）", ov2["far"] >= 0.6, ov2["far"])
    # 名字膠囊要貼著自己的點：每一個膠囊最近邊到某一顆點中心 ≤ 16px（改前會被往下推到 40px 以上）
    near = m.evaluate("""() => { const cs = [...document.querySelectorAll('#mRadarFlow g[data-g] circle[stroke="#fff"]')].map(c => ({ x: +c.getAttribute('cx'), y: +c.getAttribute('cy'), r: +c.getAttribute('r') }));
      return [...document.querySelectorAll('#mRadarFlow svg g[pointer-events=none] rect')].map(r => { const x = +r.getAttribute('x'), y = +r.getAttribute('y'), w = +r.getAttribute('width'), h = +r.getAttribute('height');
        return Math.round(Math.min(...cs.map(c => Math.hypot(Math.max(x - c.x, 0, c.x - x - w), Math.max(y - c.y, 0, c.y - y - h)) - c.r))); }); }""")
    ok("⑤ [390] 手機雷達的名字膠囊都貼著點（膠囊邊到點邊 ≤ 12px）", len(near) >= 3 and max(near) <= 12, near)
    # 真的點一個角落徽章：只剩那一段的點，而且留下來的點位置一個像素都不動（尺不跟著篩選換）
    q = m.evaluate("() => { const b = [...document.querySelectorAll('#mRadarFlow .mqb')].find(x => +x.querySelector('b').textContent > 0 && x.dataset.quad === 'improving'); if (b) b.click(); return b ? b.dataset.quad : null; }")
    m.wait_for_timeout(500)
    ov3 = m.evaluate(MR_OVERLAP)
    same = [g for g, p in ov3["pos"].items() if ov2["pos"].get(g) == p]
    # （改前：點一下角落整個盤面從 340px 縮成 290px、每顆點都跳位置 —— 輪盤大小每次重畫都重量，已修 mobile3.js）
    ok("⑤ [390] 點「改善」角落：盤上點變少，且留下的點位置不動（尺度、盤面大小都沒跟著篩選換）",
       q == "improving" and 0 < ov3["dots"] < ov2["dots"] and len(same) == ov3["dots"], [q, ov2["dots"], ov3["dots"], len(same)])
    m.evaluate("() => { const b = document.querySelector('#mRadarFlow .mqb[data-quad=improving]'); if (b) b.click(); }")
    m.wait_for_timeout(400)
    st = m.evaluate("""() => ({ side: document.documentElement.scrollWidth > innerWidth + 1,
        fs: parseFloat(getComputedStyle(document.querySelector('#rotBack .val')).fontSize) })""")
    ok("⑤ [390] 沒有橫向捲軸、拉Bar 讀數 ≥ 12px", not st["side"] and st["fs"] >= 12, st)
    m.close()
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 足跡輪盤：掃描光束＋聲納（2026-09-24 晚，桌機）
# Andy 的參考檔「原站風格雷達 × 淡淡掃描特效」；CEO：照做但做成「掃描 開／關」、減少動態效果時關、手機這一批不動。
# 這一段真的操作：勾掉／勾回「掃描」、看疊層真的在轉（幀數增加、角度在變）、掃到點真的冒聲納、
# 捲離畫面就停、減少動態效果不轉、手機與總覽小時鐘不轉，最後量播放＋掃描同時跑的幀率。
def _scan(pg, cid="rotClock"):
    return pg.evaluate("(id) => window.App.rotScan(id)", cid)


def t_scan(pg, b, base):
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.goto(f"{base}#flow", wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.removeItem('tw.rot.scan'); } catch (e) {} }")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
    scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(600)
    s0 = _scan(pg)
    ok("① 工具列有「掃描」勾選框，預設打開", pg.evaluate("() => { const x = document.querySelector('#rotTools input.rot-scan'); return !!x && x.checked; }"))
    ok("① 預設就在轉（疊層 canvas 存在、迴圈在跑）", s0["on"] and s0["running"] and s0["canvas"], s0)
    pg.wait_for_timeout(700)
    s1 = _scan(pg)
    ok("① 真的在轉：0.7 秒內幀數增加、角度變了", s1["frames"] > s0["frames"] + 10 and s1["ang"] != s0["ang"], [s0, s1])
    # 光束真的畫在盤內。
    # ★ 2026-09-24 效能：光束改成「圓形遮罩裡一片轉動的錐形漸層」（DOM ＋ 合成器動畫，以前是每幀整張重畫 canvas），
    #   所以改驗那個元素：真的有錐形漸層、圓形遮罩、圓心對齊盤心、半徑不超過盤、動畫真的在跑。
    #   舊的斷言（canvas 像素都在盤內）驗的是同一件事 ——「光束看得到，而且不會畫出盤外」。
    px = pg.evaluate("""() => { const el = document.getElementById('rotClock'); const bm = el.querySelector(':scope > .rotbeam');
        if (!bm) return { beam: false };
        const r = bm.getBoundingClientRect(), e = el.getBoundingClientRect();
        const W = el.clientWidth, H = el.clientHeight, cx = W / 2, cy = H / 2;
        // 盤的半徑讀 polar 真正的半徑（2026-09-24 夜起桌機是 min/2 − 14px，不再是 84%）
        const c0 = echarts.getInstanceByDom(el), R = c0.getModel().getComponent('polar').coordinateSystem.getRadiusAxis().getExtent()[1];
        const bx = r.left - e.left - el.clientLeft + r.width / 2, by = r.top - e.top - el.clientTop + r.height / 2;
        const rotor = bm.querySelector('.rotor'), cs = getComputedStyle(bm);
        const an = rotor && rotor.getAnimations ? rotor.getAnimations() : [];
        return { beam: true, grad: !!rotor && /conic-gradient/.test(getComputedStyle(rotor).backgroundImage),
          clip: cs.borderRadius === '50%' && cs.overflow === 'hidden', off: +Math.hypot(bx - cx, by - cy).toFixed(1),
          rr: +(r.width / 2).toFixed(1), R: +R.toFixed(1), running: an.some(a => a.playState === 'running'),
          ray: !!bm.querySelector('.ray') && bm.querySelector('.ray').getBoundingClientRect().width > 10 }; }""")
    ok("① 光束真的畫出來了，而且只在盤內（錐形漸層＋射線、圓形遮罩、圓心對齊盤心、半徑不超過盤、正在轉）",
       px.get("beam") and px["grad"] and px["ray"] and px["clip"] and px["off"] < 2 and px["rr"] <= px["R"] + 0.5 and px["running"], px)
    # ② 聲納：一圈約 5.8 秒，最多等 6.5 秒一定掃過至少一顆點
    got = wait_until(pg, "() => (window.App.rotScan('rotClock').pings || 0) > 0", 6500)
    ok("② 掃描線掃到族群點時冒出聲納環", bool(got), _scan(pg))
    # ③ 關掉：寫進 localStorage、迴圈停、疊層清空
    pg.click("#rotTools input.rot-scan"); pg.wait_for_timeout(400)
    s2 = _scan(pg)
    ok("③ 勾掉「掃描」→ 記在這台瀏覽器（tw.rot.scan = '0'）", pg.evaluate("() => localStorage.getItem('tw.rot.scan')") == "0")
    f0 = s2["frames"]; pg.wait_for_timeout(600); s3 = _scan(pg)
    ok("③ 勾掉之後真的停了（0.6 秒內一幀都沒有再轉）", not s3["on"] and s3["frames"] == f0, [s2, s3])
    blank = pg.evaluate("""() => { const cv = document.querySelector('#rotClock > canvas.rotripple'); if (!cv) return true;
        const d = cv.getContext('2d').getImageData(0, 0, cv.width, cv.height).data; for (let i = 3; i < d.length; i += 16) if (d[i]) return false; return true; }""")
    beam_left = pg.evaluate("() => document.querySelectorAll('#rotClock > .rotbeam, #rotClock > .rotping').length")
    ok("③ 疊層清乾淨了（沒有殘留一道停住的光束）", blank and beam_left == 0, {"canvas 乾淨": blank, "殘留光束／聲納元素": beam_left})
    pg.click("#rotTools input.rot-scan"); pg.wait_for_timeout(500)
    ok("③ 勾回來 → 記回 '1'、又開始轉", pg.evaluate("() => localStorage.getItem('tw.rot.scan')") == "1" and _scan(pg)["running"])
    # ④ 捲離畫面就停（不在畫面上不吃 CPU）
    pg.evaluate("() => window.scrollTo({ top: document.documentElement.scrollHeight, behavior: 'instant' })"); pg.wait_for_timeout(700)
    a1 = _scan(pg)["frames"]; pg.wait_for_timeout(500); a2 = _scan(pg)["frames"]
    ok("④ 捲到看不到輪盤 → 掃描停下來（0.5 秒內幀數不再增加）", a2 == a1, [a1, a2])
    scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(700)
    ok("④ 捲回來 → 又接著轉", _scan(pg)["frames"] > a2)
    # ⑤ 播放＋掃描＋水波同時跑的幀率（參考檔要求 60FPS；容器是軟體繪圖，門檻放在平均 ≥ 30、最長一幀 ≤ 200ms）
    pg.evaluate("() => { const b = document.querySelector('#rotBack .pb.play'); b && b.click(); }")
    fr = pg.evaluate("""() => new Promise(res => { let n = 0; const t0 = performance.now(); const gaps = []; let last = t0;
        const f = (t) => { n++; gaps.push(t - last); last = t; if (t - t0 < 2000) requestAnimationFrame(f); else res({ fps: +(n * 1000 / (t - t0)).toFixed(1), maxGap: Math.round(Math.max(...gaps)) }); };
        requestAnimationFrame(f); })""")
    pg.evaluate("() => { const b = document.querySelector('#rotBack .pb.play'); b && b.click(); }")
    notes.append(f"掃描＋播放＋水波同時跑：{fr['fps']} fps、最長一幀 {fr['maxGap']}ms（容器是軟體繪圖，實機會更高）")
    ok("⑤ 播放＋掃描＋水波同時跑不卡（2 秒平均 ≥ 30 fps、最長一幀 ≤ 200ms）", fr["fps"] >= 30 and fr["maxGap"] <= 200, fr)
    rot_seek(pg, 0, 900)
    # ⑥ 放大視窗裡的輪盤也在轉；關掉放大視窗，卡片那張照轉
    # ★ 2026-09-26 改前→改後：改前「放大視窗的輪盤也在掃描」→ 改後放大視窗拿掉（Andy「放大功能取消」），只剩卡片那張
    ok("⑥ 沒有放大視窗了（2026-09-26 拿掉）；卡片那張照轉", pg.evaluate("() => !document.getElementById('rotZoomBtn')") and _scan(pg)["on"])
    # ⑦ 總覽小時鐘不掃（總覽 Andy 不要動畫）
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2400)
    mini = _scan(pg, "rotClockMini")
    ok("⑦ 總覽的小時鐘不掃描、沒有疊層", not mini["on"] and not mini["canvas"], mini)
    # ⑧ 減少動態效果：不轉、勾選框照樣在（使用者看得到它為什麼沒轉）
    ctx = b.new_context(viewport={"width": 1440, "height": 950}, reduced_motion="reduce")
    rp = ctx.new_page()
    rp.goto(f"{base}#flow", wait_until="networkidle"); rp.wait_for_timeout(2600)
    rr = rp.evaluate("() => window.App.rotScan('rotClock')")
    ok("⑧ 系統開了「減少動態效果」→ 掃描不轉", not rr["on"] and rr["frames"] == 0, rr)
    ctx.close()
    # ⑨ 手機 390：這一批不動手機 —— 不掃、沒有「掃描」勾選框、盤面仍是上一版（6 圈細圓）
    m = b.new_page(viewport={"width": 390, "height": 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    m.goto(f"{base}#flow", wait_until="networkidle"); m.wait_for_timeout(2600)
    ms = m.evaluate("() => window.App.rotScan('rotClock')")
    lbl = m.evaluate("() => { const l = document.querySelector('#rotTools .rot-scanlbl'); return !!l && l.getClientRects().length > 0; }")
    circ = m.evaluate("""() => { const c = echarts.getInstanceByDom(document.getElementById('rotClock'));
        return c.getZr().storage.getDisplayList(true).filter(e => e.z === 1 && e.type === 'circle' && e.style && e.style.fill === 'none').length; }""")
    ok("⑨ [390] 手機不掃描、看不到「掃描」勾選框", not ms["on"] and not lbl, [ms, lbl])
    ok("⑨ [390] 手機的盤面仍是上一版（距離環 3 ＋ 兩圈虛線 ＋ 盤緣 ＝ 6 圈）", circ == 6, circ)
    m.close()
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 足跡輪盤：既有功能逐項（2026-09-24 晚）
# CEO 更正：「參考檔只取視覺風格，既有功能一個都不准掉」。這一段把清單上每一項都真的操作一次，
# 驗「畫面真的因此改變了」—— 各功能自己的細節在它原本的段落（資金流向、批次2、輪動象限面板…）。
def t_rot_keep(pg, b, base):
    pg.set_viewport_size({"width": 1440, "height": 950})
    reset_rot(pg, base, 2600)
    scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(500)
    npts = lambda: len(pg.evaluate("() => (window.App._rotPts || [])"))
    n0 = npts()
    # 1 產業鏈／族群篩選（兩層下拉）
    chain = pg.evaluate(f"""() => {{ const o = [...document.querySelectorAll('{ROT_DD} .rotdd[data-dd="chain"] .ddopt[data-c]')].find(x => x.dataset.c);
        return o ? o.dataset.c : null; }}""")
    hit = _rot_pick_chain(pg, chain) if chain else False
    n1 = npts()
    ok("1 產業鏈篩選：挑一條鏈之後盤上的點數真的變了", hit and n1 != n0, {"鏈": chain, "前": n0, "後": n1})
    _rot_pick_chain(pg, "")
    gs = rot_dd_groups(pg)
    if gs:
        rot_dd_toggle(pg, gs[0])
        ok("1 族群篩選：勾一個族群 → 盤上只剩它", npts() == 1, npts())
        rot_dd_clear(pg)
    reset_rot(pg, base, 2400); scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(400)
    # 2 只看前 10 大
    cb = pg.query_selector("#flowRotFilter input.rot-top10")
    if ok("2 「只看前 10 大」勾選框還在", bool(cb)):
        # 勾完篩選列會重畫（元素換新），所以每次都重新找一次再點
        pg.click("#flowRotFilter input.rot-top10"); pg.wait_for_timeout(1400)
        ok("2 勾「只看前 10 大」→ 盤上剩 10 顆", npts() == 10, npts())
        pg.click("#flowRotFilter input.rot-top10"); pg.wait_for_timeout(1200)
    # 3 時間軸（N 天前）＋ 播放
    rot_span(pg, 8, 1200); sub8 = text(pg, "#rankSub")
    rot_span(pg, 20, 1200); sub20 = text(pg, "#rankSub")
    changed("3 拉「N 天前」→ 排行日期範圍真的變了", sub8, sub20)
    f0 = pg.evaluate("() => window.App.rotFrameNow()")
    pg.evaluate("() => { const b = document.querySelector('#rotBack .pb.play'); b && b.click(); }"); pg.wait_for_timeout(1300)
    f1 = pg.evaluate("() => window.App.rotFrameNow()")
    pg.evaluate("() => { const b = document.querySelector('#rotBack .pb.play'); b && b.click(); }")
    ok("3 按 ▶ → 真的在回放（看的那一天變了）", f1 != f0, [f0, f1])
    rot_seek(pg, 0, 900)
    # 4 即時模式與狀態字（假報價，同「輪動時鐘即時」段）
    pg.evaluate(_RLV_STUB, None)
    pg.evaluate("() => document.getElementById('rotLiveBtn').click()"); pg.wait_for_timeout(1800)
    ok("4 按「即時」→ 卡片標題旁出現短狀態字", pg.evaluate("() => { const t = document.getElementById('rotLiveTag'); return !!t && !t.hidden; }"))
    pg.evaluate("() => document.getElementById('rotLiveBtn').click()"); pg.wait_for_timeout(900)
    ok("4 再按一次 → 退回盤後、狀態字收掉", pg.evaluate("() => !window.App.rotLive().on && document.getElementById('rotLiveTag').hidden"))
    pg.goto("about:blank"); reset_rot(pg, base, 2400); scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(400)
    # 5 顯示腳印開關
    feet = lambda: sum(len(f) for f in (pg.evaluate(CLK_STATE, "rotClock") or {"feet": []})["feet"])
    k0 = feet(); pg.click("#rotTools input.rot-trail"); pg.wait_for_timeout(900); k1 = feet()
    pg.click("#rotTools input.rot-trail"); pg.wait_for_timeout(900)
    ok("5 「顯示腳印」關掉 → 腳印歸零；打開 → 回來", k0 > 0 and k1 == 0 and feet() > 0, [k0, k1])
    # 6 點族群 → 成分股面板；點外面收掉
    pt = pg.evaluate("""() => { const el = document.getElementById('rotClock'); const c = echarts.getInstanceByDom(el);
        const o = c.getOption(); const si = o.series.findIndex(s => s.type === 'scatter'); const d = o.series[si].data[0];
        const p = c.convertToPixel({ seriesIndex: si }, d.value); const r = el.getBoundingClientRect();
        return { x: r.left + p[0], y: r.top + p[1], name: d.row.name }; }""")
    pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(1500)
    ok("6 點盤上的族群點 → 成分股面板打開", pg.evaluate("() => !document.getElementById('rankPanel').hidden"), pt["name"])
    pg.mouse.click(700, 140); pg.wait_for_timeout(700)
    ok("6 點外面 → 面板收掉（點背景關閉）", pg.evaluate("() => document.getElementById('rankPanel').hidden"))
    # 7 點象限徽章 → 展開面板；Esc 收掉
    pg.eval_on_selector("#rotClock .rotquads .rq[data-k=leading]", "b => b.click()"); pg.wait_for_timeout(900)
    ok("7 點「領先」徽章 → 右邊展開那一段的族群表", pg.evaluate("() => !document.getElementById('stagePanel').hidden"))
    pg.keyboard.press("Escape"); pg.wait_for_timeout(600)
    ok("7 按 Esc → 收掉", pg.evaluate("() => document.getElementById('stagePanel').hidden"))
    # 8 放大視窗
    # ★ 2026-09-26 改前→改後：改前「按放大 → 放大視窗裡有一張足跡輪盤」→ 改後 Andy「放大功能取消」，驗它真的不在
    ok("8 「放大」鈕已拿掉（2026-09-26），不是既有功能了", pg.evaluate("() => !document.getElementById('rotZoomBtn')"))
    # 9 右側排行連動：點排行長條 → 盤上只亮那一個（其他壓暗）。座標算法同「批次2」的 rank_spot（先捲到圖上、點長條末端內側）
    scroll_to(pg, "rankFlow")
    bar = pg.evaluate("""() => { const el = document.getElementById('rankFlow'); const c = echarts.getInstanceByDom(el);
        const d = c.getOption().series[0].data; const i = d.length - 1; const v = typeof d[i] === 'object' ? d[i].value : d[i];
        const p = c.convertToPixel({ seriesIndex: 0 }, [v, i]); const r = el.getBoundingClientRect();
        return { x: r.left + p[0] - (v >= 0 ? 4 : -4), y: r.top + p[1] }; }""")
    op0 = pg.evaluate("() => echarts.getInstanceByDom(document.getElementById('rotClock')).getOption().series.find(s => s.type === 'scatter').data.map(d => d.itemStyle.opacity)")
    pg.mouse.click(bar["x"], bar["y"]); pg.wait_for_timeout(1200)
    op1 = pg.evaluate("() => echarts.getInstanceByDom(document.getElementById('rotClock')).getOption().series.find(s => s.type === 'scatter').data.map(d => d.itemStyle.opacity)")
    note = pg.evaluate("() => (document.getElementById('rankPanel')||{}).innerText || ''")
    ok("9 點右邊排行的長條 → 成分股在原地展開", pg.evaluate("() => !document.getElementById('rankPanel').hidden"))
    # 排行依「佔比變化」排、盤上只畫佔比前 16 —— 點到的族群不一定在盤上（同批次2 的兩種正確行為）
    if "不在左邊資金輪盤" in note:   # ★ 2026-09-26 改前→改後：「不在左邊足跡輪盤」→「不在左邊資金輪盤」
        ok("9 點到盤上沒有的族群 → 盤不准整張灰掉，面板明講原因", max(x if x is not None else 1 for x in op1) > .9, op1[:6])
    else:
        ok("9 點右邊排行的長條 → 盤上只亮那一個、其他壓暗（連動）",
           min(x if x is not None else 1 for x in op1) < .3 and max(x if x is not None else 1 for x in op1) > .9, [op0[:6], op1[:6]])
    pg.mouse.click(700, 140); pg.wait_for_timeout(800)
    # 10 滑過提示 ＋ 焦點高亮
    pg.mouse.move(pt["x"], pt["y"]); pg.wait_for_timeout(700)
    tip = pg.evaluate("() => { const t = [...document.querySelectorAll('div')].find(d => /相對大盤強弱/.test(d.textContent) && d.offsetParent && getComputedStyle(d).position === 'absolute'); return t ? t.textContent.slice(0, 40) : ''; }")
    ok("10 滑到族群點 → 跳出提示框（名字＋強弱＋動能）", pt["name"] in tip, tip)
    pg.mouse.move(5, 5); pg.wait_for_timeout(400)
    # 11 水波／掃描開關都在
    ok("11 工具列：顯示腳印、水波、掃描三個勾選框都在",
       pg.evaluate("() => ['rot-trail','rot-ripple','rot-scan'].every(c => !!document.querySelector('#rotTools input.' + c))"))
    pg.set_viewport_size({"width": 1500, "height": 1000})



# ===================================================================== 足跡輪盤：每一個族群點都有腳印（2026-09-25）
# Andy 截圖問「為何不是每個點都有軌跡」。改法：焦點族群照舊（實、亮），非焦點的腳印退到背景
# （整條 opacity .35、腳印 ×0.78、間距 ×2），滑到／點到那一顆點就換成焦點樣式；「顯示腳印」照舊關全部。
# 這一段真的操作：對盤上**每一顆**族群點找它的腳印序列、滑過一顆非焦點點看它提亮、勾掉「顯示腳印」看全部歸零、
# 按 ▶ 看非焦點的腳印也跟著補間走（沿用 rotTween 只搬位置），並量回放幀率寫進 notes。
ALLTR = r"""(cid) => { const el = document.getElementById(cid); const c = el && window.echarts && echarts.getInstanceByDom(el);
  if (!c) return null;
  const o = c.getOption(); const ss = o.series || [];
  const sc = ss.find(s => s.type === 'scatter' && s.name === '族群'); if (!sc) return null;
  const alpha = (col) => { const m = String(col || '').match(/,([\d.]+)\)$/); return m ? +m[1] : 1; };
  const focus = new Set(((window.App && window.App._rotFrame) || {}).focus || []);
  const rows = sc.data.map(d => {
    const gid = d.row.gid; const li = ss.findIndex(s => s.type === 'line' && s.gid === gid); const ln = ss[li];
    if (!ln) return { gid, name: d.row.name, line: false };
    const op = (ln.lineStyle || {}).opacity == null ? 1 : ln.lineStyle.opacity;
    const feet = (ln.data || []).filter(x => x && !Array.isArray(x) && String(x.symbol || '').startsWith('path://'));
    // 軌跡在畫面上的長度（px）：太短的族群（幾乎沒動）本來就放不下腳印，要分得出「沒畫」跟「沒得畫」
    const px = (ln.data || []).map(x => c.convertToPixel({ seriesIndex: li }, Array.isArray(x) ? x : x.value)).filter(Boolean);
    let len = 0; for (let i = 1; i < px.length; i++) len += Math.hypot(px[i][0] - px[i - 1][0], px[i][1] - px[i - 1][1]);
    return { gid, name: d.row.name, line: true, focus: focus.has(gid), op, n: feet.length, len: Math.round(len),
      sz: Math.max(0, ...feet.map(x => Math.max(...[].concat(x.symbolSize || 0)))),
      a: Math.max(0, ...feet.map(x => alpha((x.itemStyle || {}).color))) };
  });
  return { rows, dots: sc.data.length }; }"""


# ===================================================================== 足跡輪盤只留圓圈（2026-09-26；當晚改驗「有腳印」）
# ★ 2026-09-26 晚改前→改後（Andy：「先退回到有腳印那版本」）：
#   改前：這一段驗「足跡輪盤只需要留下圓圈即可」—— 乾淨開頁「顯示腳印」不勾、盤上 0 個腳印、手機雷達 0 個腳印。
#   改後：退回 09-25 晚的樣子 —— 乾淨開頁**預設勾選**、每顆點身後有軌跡＋腳印、總覽小輪盤有焦點腳印、手機雷達有腳印；
#     勾掉記成 tw.rot.feet='0'，重新整理之後仍然尊重（桌機卡片、總覽小輪盤、手機雷達三張都不畫）；勾回來記 '1'。
#   段落名稱不改（CEO 的段落清單與歷史紀錄都用這個名字），內容改驗新行為。
# ⚠ 這一段刻意用 Browser._tw_raw_new_page（原版）開乾淨頁面 —— 量的是「完全沒動過設定的人」看到什麼。
#   （改前其他段落都被 FEET_PRESET 預寫成「勾過腳印」；預設改回開之後那條預寫已經拿掉，這裡仍用原版以免將來又加回預寫。）
# 真的操作：乾淨開頁 → 量腳印與軌跡都在、圓點照畫 → 按 ▶ 回放量點的逐幀位置（平滑、腳印跟著）
#   → 總覽小輪盤有焦點腳印 → 勾掉「顯示腳印」看腳印歸零、記進 localStorage → 重新整理還是關的 → 總覽也只剩圓圈
#   → 手機雷達：沒有值時畫腳印、'0' 時不畫 → 勾回來記 '1' → 手機「?」點開量沒有附註段（附註拿掉那部分保留）。
# 手機：這一頁看得到的每一顆「?」的 key（去重）
MOB_HOWKEYS = r"""() => [...new Set([...document.querySelectorAll('.howbtn[data-how]')]
  .filter(b => b.getClientRects().length && b.offsetParent).map(b => b.dataset.how))]"""
MOB_HOWCLICK = r"""(k) => { const b = [...document.querySelectorAll('.howbtn[data-how="' + k + '"]')].find(x => x.getClientRects().length && x.offsetParent);
  if (!b) return false; b.scrollIntoView({block: 'center', behavior: 'instant'}); b.click(); return true; }"""
# 手機雷達：圓點數與腳印數（mobile3.js 的小腳印是 g.mrfoot，每個由前掌＋腳跟兩個 ellipse 組成）
MOB_RADAR_FEET = r"""(box) => { const s = document.querySelector(box + ' svg'); if (!s) return null;
  return { dots: s.querySelectorAll('g[data-g]').length, feet: s.querySelectorAll('g.mrfoot').length }; }"""


def t_rot_dots_only(pg, b, base):
    raw = getattr(type(b), "_tw_raw_new_page", None)

    def fresh(w, h, mobile=False):
        kw = dict(viewport={"width": w, "height": h})
        if mobile:
            kw.update(device_scale_factor=2, is_mobile=True, has_touch=True)
        p = raw(b, **kw) if raw else b.new_page(**kw)
        p.add_init_script(CONSENT_PRESET)          # 只預寫同意條款與導覽（不寫 tw.rot.feet）
        p.on("pageerror", lambda e: fails.append(f"足跡輪盤只留圓圈 pageerror: {e}"))
        return p

    feet_n = lambda st: sum(len(f) for f in (st or {}).get("feet") or [])
    chk_js = "() => { const c = document.querySelector('#rotTools input.rot-trail'); return c ? c.checked : null; }"
    d = fresh(1440, 950)
    try:
        d.goto(f"{base}#flow", wait_until="networkidle"); d.wait_for_timeout(2800)
        scroll_to(d, "rotClockWrap"); d.wait_for_timeout(700)
        ok("乾淨的瀏覽器沒有 tw.rot.feet（量的是真正的預設）",
           d.evaluate("() => { try { return localStorage.getItem('tw.rot.feet'); } catch (e) { return 'ERR'; } }") is None)
        chk = d.evaluate(chk_js)
        # 改前（09-26 稍早）：開關預設不勾 → 改後（09-26 晚，Andy 要求退回）：預設勾選
        ok("★「顯示腳印」開關回來了，而且預設**勾選**", chk is True, chk)
        st = d.evaluate(CLK_STATE, "rotClock")
        ok("★ 預設盤上有腳印、也有看得到的軌跡線（改前：0 個腳印）", bool(st) and st["vis"] > 0 and feet_n(st) > 0,
           st and {"看得到的軌跡": st["vis"], "腳印": feet_n(st)})
        ok("族群點（圓圈）照舊畫（> 6 顆）", bool(st) and st["n"] > 6, st and st["n"])
        ok("象限底色、刻度照舊", bool(st) and st["ringN"] > 0 and st["thinN"] > 0, st and [st["ringN"], st["thinN"]])
        ok("回報給驗收的狀態也是「腳印開」（_rotFrame.trail true、走過 > 0 天）",
           bool(st) and st["fr"] and st["fr"]["trail"] is True and st["fr"].get("trailDays", 0) > 0, st and st["fr"])
        # 回放／補間：點平滑滑過去，腳印一路都在
        r = d.evaluate(TW_SAMPLE, [12, 900])
        out = r["out"]
        if ok("回放到 12 天前量得到點的逐幀位置", len(out) >= 3 and r["a"], {"n": len(out)}):
            A, B = r["a"], out[-1]
            D = ((B["x"] - A["x"]) ** 2 + (B["y"] - A["y"]) ** 2) ** 0.5
            mids = [q for q in out if 0.03 * D < ((q["x"] - A["x"]) ** 2 + (q["y"] - A["y"]) ** 2) ** 0.5 < 0.97 * D]
            ok("★ 回放：點平滑滑過去（補間中出現 ≥ 1 個中間位置）", D >= 3 and len(mids) >= 1,
               {"距離": round(D, 1), "中間幀": len(mids)})
            dist = [((q["x"] - B["x"]) ** 2 + (q["y"] - B["y"]) ** 2) ** 0.5 for q in out]
            ok("回放：位置一路往終點走（沒有往回跳）",
               not [i for i in range(1, len(dist)) if dist[i] > dist[i - 1] + 0.5])
        d.evaluate("() => window.App.rotReplay(0)"); d.wait_for_timeout(900)
        st = d.evaluate(CLK_STATE, "rotClock")
        ok("回放結束後腳印仍在", feet_n(st) > 0 and st["vis"] > 0, st and [st["vis"], feet_n(st)])
        # 總覽小輪盤：預設也有腳印（09-25 的行為：只畫焦點族群的）
        d.evaluate("() => { location.hash = '#overview'; }"); d.wait_for_timeout(2800)
        scroll_to(d, "rotClockMini"); d.wait_for_timeout(600)
        ms = d.evaluate(CLK_STATE, "rotClockMini")
        # ★ 2026-10-03 改前→改後（過時斷言，DECISIONS #274／#310）：
        #   改前：「總覽小輪盤預設也畫腳印（焦點族群）」—— 那是 09-26 晚的行為。
        #   改後：09-28 Andy「首頁 -> 資金輪盤不需要標示軌跡，只要標示點即可」，app.js 對 rotClockMini 一律傳 trail:false
        #     （#274），總覽這張不管開關怎麼設都只有點。所以這裡改驗「有點、0 腳印、0 條看得到的軌跡」。
        ok("★ 總覽小輪盤只有點、沒有腳印與軌跡（#274：首頁輪盤只標點）", bool(ms) and ms["n"] > 0 and feet_n(ms) == 0 and ms["vis"] == 0,
           ms and [ms["n"], feet_n(ms), ms["vis"]])
        # 勾掉「顯示腳印」→ 卡片只剩圓圈、記成 '0'
        d.evaluate("() => { location.hash = '#flow'; }"); d.wait_for_timeout(2000)
        scroll_to(d, "rotClockWrap"); d.wait_for_timeout(500)
        ok("沒有足跡輪盤的放大鈕（2026-09-26 拿掉，這次不退）", d.evaluate("() => !document.getElementById('rotZoomBtn')"))
        d.eval_on_selector("#rotTools input.rot-trail", "e => e.click()"); d.wait_for_timeout(1200)
        st = d.evaluate(CLK_STATE, "rotClock")
        ok("★ 勾掉「顯示腳印」→ 卡片只剩圓圈（0 腳印、0 條看得到的軌跡）", feet_n(st) == 0 and st["vis"] == 0 and st["n"] > 6,
           st and [st["vis"], feet_n(st), st["n"]])
        ok("勾掉之後記成 '0'", d.evaluate("() => localStorage.getItem('tw.rot.feet')") == "0")
        # 同一次瀏覽換頁：總覽小輪盤也只剩圓圈
        d.evaluate("() => { location.hash = '#overview'; }"); d.wait_for_timeout(2800)
        scroll_to(d, "rotClockMini"); d.wait_for_timeout(600)
        ms = d.evaluate(CLK_STATE, "rotClockMini")
        ok("關著時總覽小輪盤也只剩圓圈（兩張一致）", bool(ms) and ms["n"] > 0 and feet_n(ms) == 0 and ms["vis"] == 0,
           ms and [ms["vis"], feet_n(ms)])
        # ★ 2026-10-03 改前→改後（#307「重新整理＝圖表設定回預設」）：
        #   改前：重新整理之後 '0' 仍然被尊重。改後：重新整理 → tw.rot.feet 被清掉、回到預設「勾選、有腳印」。
        #   （這一頁的開機腳本是 CONSENT_PRESET，含驗收後門，所以要用 real_reload 才是正式站的重新整理）
        d.evaluate("() => { location.hash = '#flow'; }"); d.wait_for_timeout(1500)
        real_reload(d, wait_ms=2600)
        scroll_to(d, "rotClockWrap"); d.wait_for_timeout(600)
        st = d.evaluate(CLK_STATE, "rotClock")
        ok("★ 重新整理之後回到預設：勾選框打勾、有腳印、tw.rot.feet 被清掉（#307）",
           d.evaluate(chk_js) is True and feet_n(st) > 0 and d.evaluate("() => localStorage.getItem('tw.rot.feet')") is None,
           st and [d.evaluate(chk_js), feet_n(st)])
        # 再勾掉一次，下面「勾回來」照舊從關的狀態開始
        d.eval_on_selector("#rotTools input.rot-trail", "e => e.click()"); d.wait_for_timeout(1200)
        # 勾回來 → 記 '1'、腳印回來；回總覽也跟上
        d.evaluate("() => { location.hash = '#flow'; }"); d.wait_for_timeout(2000)
        scroll_to(d, "rotClockWrap"); d.wait_for_timeout(500)
        d.eval_on_selector("#rotTools input.rot-trail", "e => e.click()"); d.wait_for_timeout(1200)
        st = d.evaluate(CLK_STATE, "rotClock")
        ok("勾回來 → 腳印與軌跡回來、記成 '1'",
           feet_n(st) > 0 and st["vis"] > 0 and d.evaluate("() => localStorage.getItem('tw.rot.feet')") == "1",
           st and [st["vis"], feet_n(st)])
        d.evaluate("() => { location.hash = '#overview'; }"); d.wait_for_timeout(2800)
        scroll_to(d, "rotClockMini"); d.wait_for_timeout(600)
        ms = d.evaluate(CLK_STATE, "rotClockMini")
        # （改前驗「勾回來之後小輪盤的腳印也回來」；#274 起總覽這張不跟資金流向頁的開關走 —— 勾回來仍然只有點）
        ok("勾回來之後回到總覽，小輪盤照舊只有點（不跟資金流向頁的開關走，#274）", bool(ms) and ms["n"] > 0 and feet_n(ms) == 0,
           ms and [ms["n"], feet_n(ms)])
    finally:
        d.close()
    # 手機 390：沒有值 → 兩張雷達都畫腳印；'0'（桌機勾掉過）→ 不畫；「?」點開沒有附註段
    m = fresh(390, 844, mobile=True)
    try:
        # ★ 2026-10-03（過時斷言，#274）：總覽那張雷達 mobile3.js 傳 feet:false（首頁輪盤只標點），只有資金流向那張畫腳印。
        for route, box, want_feet in (("flow", "#mRadarFlow", True), ("overview", "#mRadarOv", False)):
            m.goto(f"{base}#{route}", wait_until="networkidle"); m.wait_for_timeout(2600)
            r = m.evaluate(MOB_RADAR_FEET, box)
            if want_feet:
                ok(f"★ 手機 {route} 雷達：圓點照畫、佔比前 3 名身後有小腳印（改前：0 個）",
                   bool(r) and r["dots"] > 3 and r["feet"] > 0, r)
            else:
                ok(f"★ 手機 {route} 雷達：圓點照畫、沒有腳印（#274：首頁輪盤只標點）",
                   bool(r) and r["dots"] > 3 and r["feet"] == 0, r)
        m.evaluate("() => localStorage.setItem('tw.rot.feet', '0')")
        m.goto(f"{base}#flow", wait_until="networkidle"); m.reload(wait_until="networkidle"); m.wait_for_timeout(2600)
        r = m.evaluate(MOB_RADAR_FEET, "#mRadarFlow")
        ok("手機雷達尊重桌機勾掉的偏好（tw.rot.feet='0' → 0 個腳印、圓點照畫）", bool(r) and r["dots"] > 3 and r["feet"] == 0, r)
        m.evaluate("() => localStorage.removeItem('tw.rot.feet')")
        # 手機：總覽與資金流向看得到的每一顆「?」都真的按開，量沒有附註段（手機一律是跳出式，點背景／Esc 關）
        for route in ("overview", "flow"):
            m.goto(f"{base}#{route}", wait_until="networkidle"); m.wait_for_timeout(2400)
            keys = m.evaluate(MOB_HOWKEYS) or []
            ok(f"手機 {route} 找得到「?」", len(keys) >= 1, keys)
            for k in keys:
                if not m.evaluate(MOB_HOWCLICK, k):
                    continue
                m.wait_for_timeout(450)
                hs = m.evaluate(COPY_HOWBOX, k)
                ok(f"★ 手機 {route}「?」（{k}）跳出來只有標題＋條列、沒有附註段",
                   bool(hs) and hs["open"] and hs["fine"] == 0 and not hs["tail"], hs)
                m.keyboard.press("Escape"); m.wait_for_timeout(300)
    finally:
        m.close()


def t_rot_all_trails(pg, b, base):
    for th in ("dark", "light"):
        pg.set_viewport_size({"width": 1440, "height": 950})
        pg.goto(f"{base}#flow", wait_until="networkidle")
        pg.evaluate("(t) => { try { localStorage.setItem('tw.theme', t); localStorage.removeItem('tw.rot.filter');"
                    " localStorage.removeItem('tw.rot.back3'); localStorage.removeItem('tw.rot.days'); } catch (e) {} }", th)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(2800)
        scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(700)
        st = pg.evaluate(ALLTR, "rotClock")
        if not ok(f"[{th}] 讀得到盤上每一顆族群點與它的腳印", bool(st) and st["dots"] > 6, st and st["dots"]):
            continue
        rows = st["rows"]
        foc = [r for r in rows if r.get("focus")]
        rest = [r for r in rows if r.get("line") and not r.get("focus")]
        # ① 每一顆族群點都有自己的腳印序列（改前：只有焦點 ≤ 6 顆有）
        nofeet = [r for r in rows if not (r.get("line") and r["op"] > 0 and (r["n"] >= 1 or r["len"] < 12))]
        ok(f"[{th}] ① 盤上每一顆族群點都有對應的腳印序列（看得到、至少 1 個腳印；軌跡 < 12px 的幾乎沒動，不算）",
           not nofeet and len(rows) == st["dots"], {"缺": [(r["name"], r.get("n"), r.get("len")) for r in nofeet], "點數": st["dots"]})
        ok(f"[{th}] ① 真的有非焦點族群被畫出來（非焦點 {len(rest)} 條、其中有腳印的 ≥ 一半）",
           len(rest) >= 1 and sum(1 for r in rest if r["n"] >= 1) * 2 >= len(rest), [(r["name"], r["n"]) for r in rest])
        # ② 非焦點比焦點淡、小
        if ok(f"[{th}] ② 焦點與非焦點都有（才比得出淡與實）", bool(foc) and bool(rest), [len(foc), len(rest)]):
            ok(f"[{th}] ② 焦點整條 opacity 1、非焦點 0.3～0.4",
               all(r["op"] == 1 for r in foc) and all(0.3 <= r["op"] <= 0.4 for r in rest),
               {"焦點": [r["op"] for r in foc], "非焦點": sorted({r["op"] for r in rest})})
            fa = max((r["op"] * r["a"] for r in foc if r["n"]), default=0)
            ra = max((r["op"] * r["a"] for r in rest if r["n"]), default=0)
            ok(f"[{th}] ② 非焦點腳印實際不透明度 < 焦點（整條 × 腳印自己的，最亮那一個比）", 0 < ra < fa,
               {"非焦點": round(ra, 3), "焦點": round(fa, 3)})
            fs = max((r["sz"] for r in foc if r["n"]), default=0)
            rs = max((r["sz"] for r in rest if r["n"]), default=0)
            ok(f"[{th}] ② 非焦點腳印比焦點小（最大那一個比）", 0 < rs < fs, {"非焦點": rs, "焦點": fs})
        if th != "dark":
            continue
        # ③ 滑過一顆非焦點的點 → 它的腳印提亮到焦點樣式（opacity 1、原尺寸、原密度），其他壓暗；滑開還原
        cand = sorted([r for r in rest if r["n"] >= 1], key=lambda r: -r["len"])
        tgt = None
        for r in cand:
            tgt = pg.evaluate("""(gid) => { const el = document.getElementById('rotClock'); const c = echarts.getInstanceByDom(el);
                const o = c.getOption(); const si = o.series.findIndex(s => s.type === 'scatter' && s.name === '族群');
                const d = o.series[si].data.find(x => x.row && x.row.gid === gid); if (!d) return null;
                const p = c.convertToPixel({ seriesIndex: si }, d.value); const rc = el.getBoundingClientRect();
                return { gid, x: rc.left + p[0], y: rc.top + p[1] }; }""", r["gid"])
            if tgt:
                # 目標點上不能剛好疊著別的點（命中測試取最近的那一顆）
                pg.mouse.move(tgt["x"], tgt["y"]); pg.wait_for_timeout(800)
                if pg.evaluate("() => document.getElementById('rotClock')._hovGid") == r["gid"]:
                    break
            tgt = None
        if ok("③ 找得到一顆可以滑到的非焦點點（有腳印）", bool(tgt), [r["name"] for r in cand][:5]):
            r0 = next(r for r in rows if r["gid"] == tgt["gid"])
            h = pg.evaluate(ALLTR, "rotClock")
            me = next(r for r in h["rows"] if r["gid"] == tgt["gid"])
            others = [r for r in h["rows"] if r["gid"] != tgt["gid"] and r.get("line")]
            ok("③ 滑過非焦點的點 → 它的腳印提亮（opacity 從 0.3～0.4 變 1）", r0["op"] < 1 and me["op"] == 1, [r0["op"], me["op"]])
            ok("③ 滑過之後它的腳印換成焦點尺寸與密度（變大、不變少）", me["sz"] > r0["sz"] and me["n"] >= r0["n"],
               {"前": [r0["sz"], r0["n"]], "後": [me["sz"], me["n"]]})
            ok("③ 其他族群的腳印壓到 ≤ 0.12（包括焦點）", max(r["op"] for r in others) <= 0.12, max(r["op"] for r in others))
            pg.mouse.move(5, 5); pg.wait_for_timeout(800)
            h2 = pg.evaluate(ALLTR, "rotClock")
            me2 = next(r for r in h2["rows"] if r["gid"] == tgt["gid"])
            ok("③ 滑開 → 它退回淡、小（opacity、尺寸、個數都回到滑過前）",
               me2["op"] == r0["op"] and me2["sz"] == r0["sz"] and me2["n"] == r0["n"],
               {"前": [r0["op"], r0["sz"], r0["n"]], "滑開": [me2["op"], me2["sz"], me2["n"]]})
            ok("③ 滑開 → 焦點的腳印也回到 1", all(r["op"] == 1 for r in h2["rows"] if r.get("focus")),
               [r["op"] for r in h2["rows"] if r.get("focus")])
        # ④ 關掉「顯示腳印」→ 全部歸零（焦點與非焦點都是）；打開 → 全部回來
        pg.eval_on_selector("#rotTools input.rot-trail", "e => e.click()"); pg.wait_for_timeout(1000)
        off = pg.evaluate(ALLTR, "rotClock")
        ok("④ 勾掉「顯示腳印」→ 每一條的 opacity 都是 0、一個腳印都不剩",
           bool(off) and all(r["op"] == 0 and r["n"] == 0 for r in off["rows"] if r.get("line")),
           off and [(r["name"], r["op"], r["n"]) for r in off["rows"] if r.get("op") or r.get("n")][:5])
        pg.eval_on_selector("#rotTools input.rot-trail", "e => e.click()"); pg.wait_for_timeout(1200)
        on = pg.evaluate(ALLTR, "rotClock")
        ok("④ 勾回來 → 非焦點的淡腳印也回來",
           bool(on) and sum(1 for r in on["rows"] if r.get("line") and 0 < r["op"] < 1 and r["n"]) >= 1,
           on and [(r["name"], r["op"], r["n"]) for r in on["rows"]][:6])
        # ⑤ 回放：非焦點的腳印也跟著補間走（rotTween 只搬位置，不是每一步重建）＋ 量幀率
        pl = pg.evaluate("""async () => {
          const el = document.getElementById('rotClock'); const c = echarts.getInstanceByDom(el);
          const f = new Set((window.App._rotFrame || {}).focus || []);
          const pick = () => { for (const s of c.getModel().getSeries().filter(s => s.subType === 'line')) {
              const o = s.option; if (!o || f.has(o.gid) || !(o.lineStyle && o.lineStyle.opacity > 0 && o.lineStyle.opacity < 1)) continue;
              const d = s.getData(); for (let i = d.count() - 1; i >= 0; i--) { const raw = d.getRawDataItem(i);
                if (raw && raw.foot) { const g = d.getItemGraphicEl(i); if (g) return [Math.round(g.x * 10) / 10, Math.round(g.y * 10) / 10]; } } }
            return null; };
          window.App.rotReplay(12); await new Promise(r => setTimeout(r, 900));
          const st0 = window.App.rotTween();
          const btn = document.querySelector('#rotBack .pb.play'); btn.click();
          const ps = []; let n = 0; const gaps = []; const t0 = performance.now(); let last = t0;
          await new Promise(res => { const g = (t) => { n++; gaps.push(t - last); last = t; const p = pick(); if (p) ps.push(p.join(','));
            if (t - t0 < 2500) requestAnimationFrame(g); else res(); }; requestAnimationFrame(g); });
          btn.click();
          const st1 = window.App.rotTween();
          return { uniq: new Set(ps).size, n: ps.length, fps: +(n * 1000 / (performance.now() - t0)).toFixed(1), maxGap: Math.round(Math.max(...gaps)),
            tweens: st1.tweens - st0.tweens, paintMs: st1.last && st1.last.paintMs }; }""")
        notes.append(f"足跡輪盤全部腳印：回放 2.5 秒 {pl['fps']} fps、最長一幀 {pl['maxGap']}ms、補間 {pl['tweens']} 次、"
                     f"每幀搬圖元 {pl['paintMs']}ms（容器軟體繪圖）")
        ok("⑤ 回放中非焦點的腳印也跟著補間走（同一個腳印在 2.5 秒裡出現 ≥ 5 個不同位置）", pl["uniq"] >= 5, pl)
        ok("⑤ 回放真的走補間（rotTween 次數增加），不是每一步整張重建", pl["tweens"] >= 2, pl)
        pg.evaluate("() => window.App.rotReplay(0)"); pg.wait_for_timeout(600)
        # ⑥ 總覽小時鐘（compact）不跟：仍然只有焦點的腳印，沒有淡的
        pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2600)
        mini = pg.evaluate("""() => { const el = document.getElementById('rotClockMini'); const c = el && echarts.getInstanceByDom(el);
            if (!c) return null; return c.getOption().series.filter(s => s.type === 'line').map(s => (s.lineStyle || {}).opacity); }""")
        if mini is not None:
            ok("⑥ 總覽小時鐘不畫淡腳印（每一條不是 0 就是 1）", all(o in (0, 1) for o in mini), mini)
        else:
            notes.append("足跡輪盤全部腳印 ⑥：總覽頁沒有小時鐘（rotClockMini），略過")
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 載入效能（2026-09-24）
# Andy：「我開啟網頁現在都會卡頓一陣子，需要修正延遲問題」。
# 修法（見 app.js 的「★ 2026-09-24 效能」註解）：尺寸沒變就不 resize、首屏以下的卡片延後畫、
# 圖表第一次出現不播進場動畫、熱力圖不再被拉長重畫、掃描光束改由合成器轉、看不到的動畫停掉、
# JSON 同時要兩次只抓一次……
# 這一段守的是「修好的不要再慢回去」，所以量的是**使用者感覺得到的兩個數字**：
#   ① 可互動時間：從開始載入，到「連續 3 秒沒有任何 >50ms 的長任務」之前最後一個長任務結束的時刻
#   ② 最長的單一卡住：這段期間最長的那一個長任務（這段時間整頁點不動、捲不動）
# 門檻＝修完之後在這個容器實測中位數 × 1.5（容器 4 核常被別的 agent 吃滿，數字會飄，1.5 倍是留給它的）。
# 另外守三件「接近 0」的事（不受容器忙不忙影響，最穩）：
#   ③ 資金流向捲到看不見輪盤與分流圖 → 主執行緒 5 秒內幾乎不忙（修前 1.4 秒）
#   ④ 從資金流向切到總覽 → 那邊的動畫不再空轉（修前 90ms／5 秒）
#   ⑤ 延後畫的卡片最後都真的畫出來了（功能一個都沒少）
# 2026-09-25 實測（這一段自己的量法，同一台容器、交錯跑）：
#   修前 可互動 4663／6178／4511ms、最長卡住 1124／2299／1249ms
#   修後 可互動 2635／3545／3134／3328／3299／3267／3663ms（中位數 3299）、最長卡住 460／573／307／609／579／461／728ms（中位數 573）
#   ── 2026-09-25 晚 第二輪（perf-2）──
#   修法：畫頁途中的強制排版拿掉（route 首次 scrollTo、產業鏈分頁列、剖析圖 relayout／fitCanvas）、
#   首屏以下的關聯圖與藏著的族群面板延後畫、資金流向輪盤畫完先讓一幀、三張大盤圖第一次分張建、
#   fmt.n 與事件日期不再逐筆新建 Intl 格式器、拓撲版露出不到 10% 就停粒子。
#   合併 main（623b890）之後這一段自己的量法，同一台容器跑六次（三次負載 3～4、三次負載 1～2）：
#     總覽 可互動 2448／1968／2288／1852／2132／1916ms（中位數 2050）、最長卡住 390／318／281／256／286／237ms（中位數 284）
#     資金流向 可互動 1916／1421／1990／1289／1341／1750ms（中位數 1586）、最長卡住 280／215／250／197／232／229ms（中位數 231）
#   同一時段（負載 1～2）的 main 623b890：總覽 1964／1896／2141、最長 287／248／266；資金流向 1362／1301／1306、最長 284／281／305；
#   捲到底 5 秒忙 4588／4446／4203ms（③ 在 main 上是紅的）。
#   門檻＝六次中位數 × 1.5（容器負載 10 以上時牆鐘會被拉長 1.5～2 倍，那時候紅了先看 uptime 再判斷）。
LOADPERF_TTI_MAX = 3100        # ms：總覽 中位數 2050 × 1.5 ≈ 3075
LOADPERF_LONGEST_MAX = 430     # ms：總覽 中位數 284 × 1.5 ≈ 426
LOADPERF_FLOW_TTI_MAX = 2400   # ms：資金流向 中位數 1586 × 1.5 ≈ 2379
LOADPERF_FLOW_LONGEST_MAX = 350  # ms：資金流向 中位數 231 × 1.5 ≈ 347
LOADPERF_IDLE_BUSY_MAX = 150   # ms／5 秒：看不見的動畫該停就停（修前 1442ms，修後實測 1～2ms）

_LT_INIT = """window.__lt = [];
try { new PerformanceObserver(l => l.getEntries().forEach(e => __lt.push([+e.startTime.toFixed(0), +e.duration.toFixed(0)])))
  .observe({type: 'longtask', buffered: true}); } catch (e) {}"""


_LP_ANIM = """() => ({ classic: !!window.App.sankeyFxRunning(),
    topo: !!((window.App.sankeyTopo && window.App.sankeyTopo()) || {}).running,
    scan: !!window.App.rotScan('rotClock').running })"""


def _lp_first_load(b, url, route_block=True):
    """全新的瀏覽環境（沒有快取）開一次網址，回傳 (可互動 ms, 最長長任務 ms, 長任務清單, page, ctx)。"""
    ctx = b.new_context(viewport={"width": 1440, "height": 900}, service_workers="block")
    ctx.add_init_script(_LT_INIT)
    pg = ctx.new_page()
    pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    if route_block:
        pg.route("**/*workers.dev/**", lambda r: r.abort())      # 容器連不到報價代理：直接失敗，不要讓它拖著網路
    pg.goto(url, wait_until="load")
    t0 = time.time()
    while time.time() - t0 < 30:                                  # 等到「連續 3 秒沒有長任務」，最多 30 秒
        pg.wait_for_timeout(250)
        now = pg.evaluate("performance.now()")
        lt = pg.evaluate("window.__lt || []")
        last = max([s0 + d for s0, d in lt] or [0])
        if now - last > 3000 and now > 2500:
            break
    lt = pg.evaluate("window.__lt || []")
    dcl = pg.evaluate("performance.getEntriesByType('navigation')[0].domContentLoadedEventEnd")
    tti = round(max([dcl] + [s0 + d for s0, d in lt]))
    longest = max([d for _s, d in lt] or [0])
    return tti, longest, lt, pg, ctx


def _lp_busy(pg, ms=5000):
    """主執行緒在接下來 ms 毫秒內忙了多久（CDP Performance.TaskDuration 差值）。"""
    cdp = pg.context.new_cdp_session(pg)
    cdp.send("Performance.enable")
    m = lambda: {x["name"]: x["value"] for x in cdp.send("Performance.getMetrics")["metrics"]}
    a = m(); pg.wait_for_timeout(ms); z = m()
    return round((z["TaskDuration"] - a["TaskDuration"]) * 1000)


def t_loadperf(pg, b, base):
    # ---- ①② 首次開總覽（預設首頁）：量兩次取較好的一次（容器忙的時候單次會被別人的 CPU 拖到）
    runs = []
    for _ in range(2):
        tti, longest, lt, p2, c2 = _lp_first_load(b, f"{base}#overview")
        runs.append((tti, longest, len(lt)))
        if _ == 1 or tti <= LOADPERF_TTI_MAX:
            # ⑤ 延後畫的卡片最後都真的畫出來了（沒捲動也會在閒下來時補畫）
            drawn = wait_until(p2, """() => { const has = (id) => { const e = document.getElementById(id);
                return !!(e && window.echarts && echarts.getInstanceByDom(e)); };
              /* 2026-09-26 改前→改後：#ovFlow 桌機改成 flowtopo 畫布 → 「畫出來了」＝ ECharts 實例 或 flowtopo 已經不在延後狀態 */
              const ov = document.getElementById('ovFlow');
              const ovDrawn = has('ovFlow') || !!(ov && window.FlowTopo && window.FlowTopo.has(ov) && !window.FlowTopo.probe(ov).pending);
              return has('heat') && has('rotClockMini') && ovDrawn && has('ovTheme') && has('breadth') && has('trust'); }""", 8000)
            ok("⑤ 首屏以下延後畫的卡片（資金去向、題材熱力圖、漲跌家數分佈、法人四象限）最後都真的畫出來了", bool(drawn))
            c2.close()
            break
        c2.close()
    best = min(runs, key=lambda r: r[0])
    notes.append(f"載入效能：首次開總覽 可互動 {best[0]}ms、最長卡住 {best[1]}ms、長任務 {best[2]} 個（各次：{runs}）")
    ok(f"① 首次開總覽的可互動時間 ≤ {LOADPERF_TTI_MAX}ms（修完實測中位數 × 1.5）", best[0] <= LOADPERF_TTI_MAX, runs)
    ok(f"② 首次開總覽最長的單一卡住 ≤ {LOADPERF_LONGEST_MAX}ms", min(r[1] for r in runs) <= LOADPERF_LONGEST_MAX, runs)

    # ---- ③ 資金流向：捲到看不見輪盤與分流圖 → 動畫停，主執行緒幾乎不忙
    tti_f, longest_f, _lt, p3, c3 = _lp_first_load(b, f"{base}#flow")
    notes.append(f"載入效能：首次開資金流向 可互動 {tti_f}ms、最長卡住 {longest_f}ms")
    ok(f"① 首次開資金流向的可互動時間 ≤ {LOADPERF_FLOW_TTI_MAX}ms（perf-2 修完實測中位數 × 1.5）", tti_f <= LOADPERF_FLOW_TTI_MAX, tti_f)
    ok(f"② 首次開資金流向最長的單一卡住 ≤ {LOADPERF_FLOW_LONGEST_MAX}ms", longest_f <= LOADPERF_FLOW_LONGEST_MAX, longest_f)
    p3.evaluate("() => window.scrollTo({ top: document.documentElement.scrollHeight, behavior: 'instant' })")
    p3.wait_for_timeout(1500)
    busy_bottom = _lp_busy(p3)
    # ★ 2026-09-25（perf-2）：側欄合併後整頁只剩 2349px，捲到底時分流圖上緣還有 9px 在畫面裡 —— 以前拓撲版照跑粒子
    #   （main 上實測 5 秒忙 3.7 秒，這一條在 main 上是紅的）。flowtopo 改成露出 ≥10% 才算看得見。
    ok(f"③ 資金流向捲到看不見輪盤與分流圖 → 主執行緒 5 秒內忙 ≤ {LOADPERF_IDLE_BUSY_MAX}ms（修前 1442ms）",
       busy_bottom <= LOADPERF_IDLE_BUSY_MAX, busy_bottom)
    # 捲回來 → 動畫要接著跑（停是為了省 CPU，不是把功能關掉）
    # ★ 2026-09-25 合併 main：桌機的資金去向預設是拓撲版（site/flowtopo.js，自己有 IntersectionObserver）；
    #   經典版（小圓點）只在手機或切回經典時出現 —— 兩種都認。
    scroll_to(p3, "sankey"); p3.wait_for_timeout(1200)
    run = p3.evaluate(_LP_ANIM)
    ok("③ 捲回資金去向 → 動畫又接著跑（拓撲版粒子或經典版小圓點）", run["topo"] or run["classic"], run)
    # ---- ④ 切到總覽 → 資金流向那邊的動畫不再空轉
    # 總覽第一次打開本來就要畫圖（那是正當的工作，時間長短跟容器忙不忙有關），
    # 所以這裡不量「總覽忙多久」，直接問兩組動畫的迴圈**還在不在跑**——那才是這一條要守的事。
    p3.evaluate("() => { location.hash = '#overview'; }"); p3.wait_for_timeout(2500)
    st = p3.evaluate(_LP_ANIM)
    ok("④ 從資金流向切到總覽 → 資金去向動畫與輪盤掃描的迴圈都停了（修前小圓點一直空轉：90ms／5 秒）",
       not st["topo"] and not st["classic"] and not st["scan"], st)
    busy_ov = _lp_busy(p3)
    notes.append(f"載入效能：資金流向捲到底 5 秒忙 {busy_bottom}ms、切到總覽後 5 秒忙 {busy_ov}ms")
    c3.close()

    # ---- ⑥（R6 附帶）報價抓不到時，仍然會檢查網站有沒有重新部署（「有新資料」鈕與盤後自動重新載入靠它）
    ctx = b.new_context(viewport={"width": 1440, "height": 900}, service_workers="block")
    p4 = ctx.new_page()
    p4.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    p4.route("**/*workers.dev/**", lambda r: r.abort())
    hits = []
    p4.on("request", lambda r: hits.append(r.url) if "meta.json?t=" in r.url else None)
    p4.goto(f"{base}#overview", wait_until="networkidle"); p4.wait_for_timeout(1500)
    n0 = len(hits)
    p4.evaluate("() => window.Live && window.Live.tick(false)")
    wait_until(p4, "() => true", 1500)
    p4.wait_for_timeout(1500)
    ok("⑥ 報價代理連不到時，Live.tick() 仍會去檢查 meta.json（是否重新部署）", len(hits) > n0, {"前": n0, "後": len(hits)})
    ctx.close()


# ============================================================================================
# ★ 2026-09-24 Andy 回報：產業地圖 → AI 伺服器 → 電源，3D 按「收合圖」關掉再打開，
#   模型縮成左上角一小塊、零件卡片堆在左下與右側互相重疊、說明文字疊在圖上。
#   根因（three3d.js onResize 上面有完整說明）：收合＝容器 display:none、寬 0，
#   這段期間一來一次視窗 resize（捲軸消失、半邊視窗、開關事件抽屜），畫布就被重設成 320×340 的下限，
#   展開時沒人再重設。所以驗收**一定要在收合期間動一下視窗寬度**，不然量不到那個 bug
#   （只收再開、中間什麼都沒發生，修之前也是綠的 —— 2026-09-24 實測）。
#   每一項都是「收合前量一次 → 真的按收合 → 動視窗 → 真的按展開 → 再量一次」，比兩次。
# ============================================================================================
FOLD3D_MEAS = """() => {
  const h = document.getElementById('prod3d'); const c = h && h.querySelector('canvas');
  if (!h || !c || h.hidden) return null;
  const R = (e) => { const r = e.getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height, r: r.right, b: r.bottom }; };
  const hit = (a, b) => Math.min(a.r, b.r) - Math.max(a.x, b.x) > 2 && Math.min(a.b, b.b) - Math.max(a.y, b.y) > 2;
  const hr = R(h), cr = R(c);
  const cards = [...h.querySelectorAll('.lbl3d')].filter(e => e.offsetParent && getComputedStyle(e).visibility !== 'hidden').map(R);
  let ov = 0; const ovp = [];
  for (let i = 0; i < cards.length; i++) for (let j = i + 1; j < cards.length; j++) if (hit(cards[i], cards[j])) { ov++; if (ovp.length < 3) ovp.push([i, j]); }
  const outside = cards.filter(a => a.x < hr.x - 2 || a.r > hr.r + 2 || a.y < hr.y - 2 || a.b > hr.b + 2).length;
  const note = document.getElementById('dg3dNote');
  const nr = note && !note.hidden && note.offsetParent ? R(note) : null;
  const bd = window.Rack3D && window.Rack3D.current && window.Rack3D.current.bounds ? window.Rack3D.current.bounds() : null;
  return { hostW: h.clientWidth, hostH: h.clientHeight, cw: Math.round(cr.w), ch: Math.round(cr.h),
    cx: cr.x + cr.w / 2, cy: cr.y + cr.h / 2, n: cards.length, ov, ovp, outside,
    noteOnCanvas: !!(nr && hit(nr, cr)), noteOnCard: !!(nr && cards.some(a => hit(nr, a))),
    below: h.classList.contains('dgstage--below'),
    mcx: bd ? (bd.x0 + bd.x1) / 2 : null, mcy: bd ? (bd.y0 + bd.y1) / 2 : null,
    mw: bd ? bd.x1 - bd.x0 : null, mh: bd ? bd.y1 - bd.y0 : null }; }"""

FOLD2D_MEAS = """() => {
  const w = document.getElementById('prodDiagram'); const s = w && w.querySelector('svg');
  if (!w || !s || w.hidden) return null;
  const R = (e) => { const r = e.getBoundingClientRect(); return { x: r.left, y: r.top, w: r.width, h: r.height, r: r.right, b: r.bottom }; };
  const hit = (a, b) => Math.min(a.r, b.r) - Math.max(a.x, b.x) > 2 && Math.min(a.b, b.b) - Math.max(a.y, b.y) > 2;
  const cards = [...w.querySelectorAll('.dgc')].filter(e => e.offsetParent).map(R);
  let ov = 0; for (let i = 0; i < cards.length; i++) for (let j = i + 1; j < cards.length; j++) if (hit(cards[i], cards[j])) ov++;
  const sr = R(s);
  return { sw: Math.round(sr.w), sh: Math.round(sr.h), n: cards.length, ov,
    leads: w.querySelectorAll('svg.dglead path').length, hostW: w.clientWidth }; }"""


def _fold3d_cycle(pg, width: int, wiggle: bool = True):
    """按收合 → （收合期間動一下視窗寬度）→ 按展開。回傳展開後量到的值。"""
    click(pg, "#dgFold", 700)
    folded = pg.evaluate("() => { const b = document.getElementById('dgBody'); return !!b && getComputedStyle(b).display === 'none'; }")
    ok(f"[{width}] 按「收合圖」→ 圖真的收起來（#dgBody 不顯示）", folded)
    if wiggle == "side":
        # 審查 R3 的重現條件之二：收合期間切換事件欄 —— 容器寬度真的變了（964 ↔ 1322），展開時要照新寬度重排
        pg.evaluate("() => document.getElementById('evToggle').click()"); pg.wait_for_timeout(700)
    elif wiggle:
        # 模擬「收合之後頁面變短、捲軸消失／使用者把視窗拉窄一點」—— 那一次 resize 就是 bug 的觸發點
        pg.set_viewport_size({"width": width - 40, "height": 1000}); pg.wait_for_timeout(400)
        pg.set_viewport_size({"width": width, "height": 1000}); pg.wait_for_timeout(400)
    click(pg, "#dgFold", 400)
    ok(f"[{width}] 再按一次 → 圖真的展開回來", pg.evaluate(
        "() => { const b = document.getElementById('dgBody'); return !!b && getComputedStyle(b).display !== 'none'; }"))


def _fold_meas(pg):
    """量之前先把滑鼠移到角落：滑鼠停在收成一行的卡片上時，那張卡會展開成全文（66 → 100px）
    蓋住下一張 —— 那是既有的 hover 行為，不是這次要驗的跑位（2026-09-24 實測踩到）。"""
    pg.mouse.move(3, 3); pg.wait_for_timeout(350)
    return pg.evaluate(FOLD3D_MEAS)


def t_fold3d(pg, base):
    route = "industry/ai_server/dg/server_psu"
    # 動畫關掉再量：自轉時卡片每 4 幀跟著相機重排，兩次量測之間卡片本來就會換位置，
    # 「收合前 vs 展開後」就變成在比兩個不同的相機角度。收尾時還原使用者原本的設定。
    anim0 = pg.evaluate("() => { try { return localStorage.getItem('tw.dganim'); } catch (e) { return null; } }")
    for width in (1440, 800):
        pg.set_viewport_size({"width": width, "height": 1000})
        pg.goto("about:blank")
        pg.goto(f"{base}#{route}", wait_until="networkidle")
        pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0'); localStorage.setItem('tw.dgOpen', '1');"
                    " localStorage.setItem('tw.dganim', '0'); } catch (e) {} }")
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1800)
        if not pg.evaluate("() => !!(window.Rack3D && window.Rack3D.supported() && window.Rack3D.hasScene('server_psu'))"):
            ok(f"[{width}] 伺服器電源要有 3D 場景（WebGL 可用）", False, "Rack3D 不可用或沒有 server_psu 場景")
            return
        click(pg, "#dg3d button:not(.on)", 400)
        wait_until(pg, "() => !!(window.Rack3D.current && document.querySelector('#prod3d canvas') && document.querySelectorAll('#prod3d .lbl3d').length > 3)", 12000)
        pg.wait_for_timeout(1200)
        scroll_to(pg, "prod3d"); pg.wait_for_timeout(500)
        m0 = _fold_meas(pg)
        if not ok(f"[{width}] 按「3D 立體」→ 3D 真的掛起來", bool(m0 and m0["n"] > 3), m0):
            continue
        # 基準本身要合格，不然後面「跟收合前一樣」沒有意義
        ok(f"[{width}] 收合前：畫布寬＝容器寬", abs(m0["cw"] - m0["hostW"]) <= 2, m0)

        for wiggle in ((False, True, "side") if width >= 1280 else (False, True)):
            tag = {False: "直接收合再展開", True: "收合期間動過視窗寬度", "side": "收合期間切換事件欄"}[wiggle]
            _fold3d_cycle(pg, width, wiggle)
            m1 = wait_until(pg, "() => { const f = " + FOLD3D_MEAS + "; const m = f(); return m && m.cw > 0 ? m : null; }", 4000)
            pg.wait_for_timeout(700)
            scroll_to(pg, "prod3d"); pg.wait_for_timeout(500)
            m1 = _fold_meas(pg)
            if not ok(f"[{width}/{tag}] 展開後 3D 還在", bool(m1), m1):
                continue
            ok(f"[{width}/{tag}] 畫布寬＝容器寬（不是縮在左上角的 320）",
               abs(m1["cw"] - m1["hostW"]) <= 2, f"畫布 {m1['cw']} vs 容器 {m1['hostW']}")
            same_w = abs(m1["hostW"] - m0["hostW"]) <= 2
            if same_w:
                ok(f"[{width}/{tag}] 畫布高＝收合前的高度（{m0['ch']}px）", abs(m1["ch"] - m0["ch"]) <= 2,
                   f"{m0['ch']} → {m1['ch']}")
            else:
                ok(f"[{width}/{tag}] 容器寬度真的變了（{m0['hostW']} → {m1['hostW']}），畫布照新寬度重排、不是 320×340",
                   m1["cw"] > 400 and m1["ch"] > 340, (m1["cw"], m1["ch"]))
            if not m1["below"]:
                ok(f"[{width}/{tag}] 兩欄／右欄模式：畫布高＝容器高", abs(m1["ch"] - m1["hostH"]) <= 4,
                   f"畫布 {m1['ch']} vs 容器 {m1['hostH']}")
            if m1["mcx"] is not None:
                dx = abs(m1["mcx"] - m1["cx"]) / max(1, m1["cw"]); dy = abs(m1["mcy"] - m1["cy"]) / max(1, m1["ch"])
                ok(f"[{width}/{tag}] 模型包圍盒中心接近畫面中心（偏差 ≤ 12%）", dx <= 0.12 and dy <= 0.12,
                   f"dx={dx:.1%} dy={dy:.1%}")
                if same_w:
                    ok(f"[{width}/{tag}] 模型大小跟收合前一樣（沒有縮成一小塊）",
                       m0["mw"] and abs(m1["mw"] - m0["mw"]) / m0["mw"] <= 0.05,
                       f"模型寬 {m0['mw']:.0f} → {m1['mw']:.0f}")
                else:
                    ok(f"[{width}/{tag}] 模型沒有縮成一小塊（寬 ≥ 畫布 25%）", m1["mw"] >= m1["cw"] * 0.25,
                       f"模型寬 {m1['mw']:.0f} ／ 畫布 {m1['cw']}")
            ok(f"[{width}/{tag}] 零件卡片數量不變（{m0['n']}）", m1["n"] == m0["n"], f"{m0['n']} → {m1['n']}")
            ok(f"[{width}/{tag}] 零件卡片彼此不重疊", m1["ov"] == 0, f"重疊 {m1['ov']} 對 {m1['ovp']}")
            ok(f"[{width}/{tag}] 零件卡片都在 3D 框內（沒有堆到框外）", m1["outside"] == 0, f"框外 {m1['outside']} 張")
            ok(f"[{width}/{tag}] 說明文字沒有疊在圖上或卡片上", not m1["noteOnCanvas"] and not m1["noteOnCard"], m1)

        # ---- 2D 模式也走一遍：收合期間動視窗，展開後圖寬、引線、卡片要跟收合前一樣
        click(pg, "#dg3d button:not(.on)", 1200)
        wait_until(pg, "() => { const w = document.getElementById('prodDiagram'); return w && !w.hidden && !!w.querySelector('svg'); }", 4000)
        pg.wait_for_timeout(600)
        d0 = pg.evaluate(FOLD2D_MEAS)
        if ok(f"[{width}] 關掉 3D → 回到 2D 剖析圖", bool(d0 and d0["sw"] > 0), d0):
            _fold3d_cycle(pg, width, True)
            pg.wait_for_timeout(700)
            d1 = pg.evaluate(FOLD2D_MEAS)
            ok(f"[{width}/2D] 展開後圖寬跟收合前一樣", bool(d1) and abs(d1["sw"] - d0["sw"]) <= 2, [d0, d1])
            ok(f"[{width}/2D] 展開後引線條數跟收合前一樣", bool(d1) and d1["leads"] == d0["leads"], [d0, d1])
            ok(f"[{width}/2D] 展開後卡片彼此不重疊", bool(d1) and d1["ov"] == 0, d1)

    # ---- 其他有 3D 的剖析圖分頁：修在共用的 Rack3D.mount，抽兩張不同形狀的場景各驗一次（1440）
    for r2, scene in (("industry/ai_server/dg/ai_server", "ai_server"), ("industry/ai_server/dg/liquid_cooling", "liquid_cooling")):
        pg.set_viewport_size({"width": 1440, "height": 1000})
        pg.goto("about:blank")
        pg.goto(f"{base}#{r2}", wait_until="networkidle"); pg.wait_for_timeout(1600)
        if not pg.evaluate(f"() => !!(window.Rack3D && window.Rack3D.hasScene('{scene}'))"):
            continue
        if not pg.evaluate("() => ((document.getElementById('dg3d')||{}).dataset||{}).mode === '3d'"):
            click(pg, "#dg3d button:not(.on)", 400)
        wait_until(pg, "() => !!(window.Rack3D.current && document.querySelectorAll('#prod3d .lbl3d').length > 3)", 12000)
        pg.wait_for_timeout(1000)
        a = _fold_meas(pg)
        if not ok(f"[{scene}] 3D 掛得起來", bool(a), a):
            continue
        _fold3d_cycle(pg, 1440, True)
        pg.wait_for_timeout(900); scroll_to(pg, "prod3d"); pg.wait_for_timeout(400)
        z = _fold_meas(pg)
        ok(f"[{scene}] 收合（期間動過視窗）再展開：畫布寬高跟收合前一樣",
           bool(z) and abs(z["cw"] - a["cw"]) <= 2 and abs(z["ch"] - a["ch"]) <= 2 and abs(z["cw"] - z["hostW"]) <= 2,
           [a and (a["cw"], a["ch"]), z and (z["cw"], z["ch"], z["hostW"])])
        ok(f"[{scene}] 展開後卡片不重疊、不在框外", bool(z) and z["ov"] == 0 and z["outside"] == 0,
           f"收合前 重疊 {a['ov']} 框外 {a['outside']}；展開後 {z}")

    # 收尾：事件欄切回預設（開），不要把 3D 開關、收合狀態、動畫偏好留給下一段
    pg.evaluate("() => { try { localStorage.setItem('tw.side', '1'); } catch (e) {} }")
    pg.evaluate("(a) => { try { localStorage.setItem('tw.dg3d', '0'); localStorage.setItem('tw.dgOpen', '1');"
                " if (a == null) localStorage.removeItem('tw.dganim'); else localStorage.setItem('tw.dganim', a); } catch (e) {} }", anim0)
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ============================================================================================
# ★ 2026-09-24 Andy：「產業地圖內的 2D／3D 剖析圖（例：半導體 → 矽晶圓），左右兩側資訊卡很多，
#   一路往下超出範圍、整張拉得很長。改成：資訊卡環繞示意圖、限制在示意圖同高的範圍內；
#   放不下的收成可點開的下拉字卡（預設只顯示編號＋標題，點了才展開說明）。
#   圖上零件用編號標示，點編號就跳出該零件說明（點背景關閉）。」
#   修之前量到的（1440、事件抽屜開）：矽晶圓卡片欄 1669px／畫布 457px，13 張全部超出。
#   這一段每張圖都量「卡片欄高 ≤ 畫布高 ＋ 40」，而且真的點編號、真的點背景。
# ============================================================================================
DGFIT_MEAS = """() => { const w = document.getElementById('prodDiagram'); const c = w && w.querySelector('.dgcanvas');
  if (!w || w.hidden || !c) return null;
  const cr = c.getBoundingClientRect(); const k = w.querySelector('.dgcards'); if (!k) return null;
  const three = getComputedStyle(k).display === 'contents';
  const boxes = three ? [...w.querySelectorAll('.dgcol')] : [k];
  const kr = k.getBoundingClientRect();
  const vis = [...w.querySelectorAll('.dgc')].filter(e => e.offsetParent);
  return { three, beside: three || kr.left >= cr.right - 2, ch: Math.round(cr.height),
    boxH: boxes.map(b => Math.round(b.getBoundingClientRect().height)), lbl: w.dataset.dglbl || '',
    fold: w.classList.contains('dgfold'), n: vis.length,
    descShown: vis.filter(e => [...e.querySelectorAll('.bd i')].some(i => i.offsetParent)).length,
    pop: (() => { const p = w.querySelector('.dgpop'); return p && !p.hidden ? { t: p.innerText.slice(0, 40), r: p.getBoundingClientRect().toJSON() } : null; })() }; }"""

# 挑一個「真的點得到」的編號：捲進畫面（instant —— 全站 scroll-behavior:smooth，平滑捲動時量到的是捲之前的座標）
# 之後用 elementFromPoint 確認圓心那一點打到的就是它自己
# （有些圖兩個編號靠得很近、或上面疊著章節列，直接點第一個會點到別人 —— 那是量測選錯點，不是功能壞）。
DGFIT_ANC = """() => { const all = [...document.querySelectorAll('#prodDiagram g.anc')].filter(g => g.querySelector('.anchor.no') && g.getBoundingClientRect().width);
  let a = null, r = null;
  for (const g of all) { g.scrollIntoView({ block: 'center', behavior: 'instant' }); const q = g.querySelector('.anchor').getBoundingClientRect();
    const e = document.elementFromPoint(q.left + q.width / 2, q.top + q.height / 2);
    if (e && g.contains(e)) { a = g; r = q; break; } }
  if (!a) return null; const id = a.dataset.for;
  const card = document.querySelector(`#prodDiagram .dgc[data-anc="${id}"]`);
  return { x: r.left + r.width / 2, y: r.top + r.height / 2, no: (a.querySelector('.non') || {}).textContent || '',
           title: card ? (card.querySelector('.bd b') || {}).textContent || '' : '' }; }"""


def _dgfit_bg_point(pg):
    """剖析圖上真正的「背景」：畫布框裡、不是零件／錨點／卡片的一點（用 elementFromPoint 找）。"""
    return pg.evaluate("""() => { const c = document.querySelector('#prodDiagram .dgcanvas'); if (!c) return null;
      const r = c.getBoundingClientRect();
      for (const [fx, fy] of [[.03,.03],[.97,.03],[.03,.97],[.5,.02],[.97,.97],[.02,.5]]) {
        const x = r.left + r.width * fx, y = r.top + r.height * fy; const e = document.elementFromPoint(x, y);
        if (e && c.contains(e) && !e.closest('[data-seg],[data-part],.anc,[data-fold],a,.dgpop')) return { x, y }; }
      return null; }""")


DGSTK_2D = """() => [...document.querySelectorAll('#prodDiagram .dgc')].filter(c => c.dataset.seg || c.dataset.part).map(c => ({
  part: c.dataset.part || '', box: !!c.querySelector('.dgchips'),
  codes: [...c.querySelectorAll('.dgchips a.dgchip')].map(a => a.dataset.code),
  hrefOk: [...c.querySelectorAll('.dgchips a.dgchip')].every(a => a.getAttribute('href') === '#stock/' + a.dataset.code && /\\d/.test(a.title)),
  none: !!c.querySelector('.dgchips s') && /台股無直接對應/.test(c.querySelector('.dgchips').textContent) }))"""
DGSTK_3D = """() => Object.fromEntries([...document.querySelectorAll('#prod3d .lbl3d')].filter(d => d.dataset.dgpart).map(d => [d.dataset.dgpart,
  [...d.querySelectorAll('a.chip3d')].map(a => (a.getAttribute('href') || '').replace('#stock/', ''))]))"""


def _dgstk_click(pg, sel_js, want_hash_prefix="#stock/"):
    """找一顆可點的股票標籤 → 滑過去等版面停（收合卡片滑過會展開、3D 卡片每幾幀重排）→
    點之前再確認游標底下真的是那一顆 → 點 → 輪詢網址。最多試 4 次。回傳 (code, hash)。"""
    code, h = None, None
    for _ in range(4):
        r = pg.evaluate("() => { for (const a of " + sel_js + ") { const b = a.getBoundingClientRect(); if (!b.width) continue; const x = b.x + b.width / 2, y = b.y + b.height / 2; if (document.elementFromPoint(x, y) === a) return {x, y, code: (a.getAttribute('href') || '').replace('#stock/', '')}; } return null; }")
        if not r:
            pg.wait_for_timeout(400); continue
        pg.mouse.move(r["x"], r["y"]); pg.wait_for_timeout(600)
        r2 = pg.evaluate("() => { const e = document.elementFromPoint(%s, %s); const a = e && e.closest('a.chip3d,a.dgchip'); return a ? (a.getAttribute('href') || '').replace('#stock/', '') : null; }" % (r["x"], r["y"]))
        if not r2:
            continue
        code = r2
        pg.mouse.click(r["x"], r["y"])
        h = wait_until(pg, "() => location.hash.startsWith('%s') ? location.hash : null" % want_hash_prefix, 3000)
        if h:
            return code, h
    return code, pg.evaluate("() => location.hash")


def t_dgstock(pg, base):
    """剖析圖股票可點：2D 卡片有台股標籤、與 3D 同零件名單一致、點了真的進 #stock/代號、上一頁回得來。"""
    pg.set_viewport_size({"width": 1440, "height": 1000})
    anim0 = pg.evaluate("() => { try { return localStorage.getItem('tw.dganim'); } catch (e) { return null; } }")
    picks = [("semiconductor", "foundry"), ("semiconductor", "silicon_wafer"), ("ai_server", "pcb_rigid"), ("ai_server", "server_psu")]
    for ch, dg in picks:
        route = f"#industry/{ch}/dg/{dg}"
        pg.goto(f"{base}{route}", wait_until="networkidle"); pg.reload(wait_until="networkidle")
        pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0'); localStorage.setItem('tw.dgOpen', '1'); localStorage.setItem('tw.dganim', '0'); } catch (e) {} }")
        pg.reload(wait_until="networkidle")
        wait_until(pg, "() => document.querySelectorAll('#prodDiagram .dgc .dgchips').length > 0", 8000)
        pg.wait_for_timeout(600)
        c2 = pg.evaluate(DGSTK_2D)
        ok(f"{dg}：2D 每張零件卡都掛了股票列（有標籤或「台股無直接對應」）", bool(c2) and all(c["box"] and (c["codes"] or c["none"]) for c in c2),
           [c for c in c2 if not (c["box"] and (c["codes"] or c["none"]))][:3])
        ok(f"{dg}：2D 至少一張卡有台股標籤，且連結＝#stock/代號、滑過有代號＋名稱", any(c["codes"] for c in c2) and all(c["hrefOk"] for c in c2), c2[:2])
        # 真的點：先選起有股票的那張卡（收合模式下選起來才展開），再用滑鼠點它的第一個股票標籤
        tgt = next((c for c in c2 if c["codes"]), None)
        if not tgt:
            continue
        idx = [c["part"] for c in c2].index(tgt["part"])
        pg.evaluate(f"() => {{ const c = [...document.querySelectorAll('#prodDiagram .dgc')].filter(c => c.dataset.seg || c.dataset.part)[{idx}]; if (!c.classList.contains('sel-part')) c.click(); c.scrollIntoView({{block: 'center'}}); }}")
        pg.wait_for_timeout(500)
        r = pg.evaluate(f"() => {{ const c = [...document.querySelectorAll('#prodDiagram .dgc')].filter(c => c.dataset.seg || c.dataset.part)[{idx}]; const a = c.querySelector('a.dgchip'); const b = a && a.getBoundingClientRect(); return b && b.width ? {{x: b.x + b.width / 2, y: b.y + b.height / 2, code: a.dataset.code, sel: c.classList.contains('sel-part')}} : null; }}")
        if ok(f"{dg}：選起卡片後股票標籤看得見", bool(r), r):
            pg.mouse.click(r["x"], r["y"]); pg.wait_for_timeout(1200)
            h = pg.evaluate("() => location.hash")
            ok(f"{dg}：點 2D 股票標籤 → 進個股頁 #stock/{r['code']}", h == f"#stock/{r['code']}", h)
            pg.go_back(); pg.wait_for_timeout(1500)
            h2 = pg.evaluate("() => location.hash")
            ok(f"{dg}：按上一頁 → 回到剖析圖", h2 == route and pg.evaluate("() => !!document.querySelector('#prodDiagram .dgc')"), h2)
        # 點圖上編號跳出的說明小卡也要有可點的股票
        pg.goto(f"{base}{route}", wait_until="networkidle"); pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1500)
        pr = pg.evaluate("""() => { const cs = [...document.querySelectorAll('#prodDiagram .dgc')].filter(c => c.querySelector('a.dgchip') && c.dataset.anc);
          for (const c of cs) { const a = document.querySelector(`#prodDiagram g.anc[data-for="${c.dataset.anc}"] .anchor`) || document.querySelector(`#prodDiagram g.anc[data-for="${c.dataset.anc}"]`);
            if (!a) continue; a.scrollIntoView({block: 'center'}); const b = a.getBoundingClientRect(); if (b.width) return {x: b.x + b.width / 2, y: b.y + b.height / 2}; } return null; }""")
        if pr:
            pg.mouse.click(pr["x"], pr["y"]); pg.wait_for_timeout(700)
            q = pg.evaluate("() => !!document.querySelector('.dgpop:not([hidden]) a.dgchip')")
            if ok(f"{dg}：點編號跳出的說明小卡裡有股票標籤", q, q):
                code, h = _dgstk_click(pg, "document.querySelectorAll('.dgpop:not([hidden]) a.dgchip')")
                ok(f"{dg}：點說明小卡的股票 → 進 #stock/{code}", bool(code) and h == f"#stock/{code}", h)
        # 3D：同一零件名單要一致、點 3D 標籤也要進個股頁，而且不會先被當成選零件
        pg.goto(f"{base}{route}", wait_until="networkidle"); pg.reload(wait_until="networkidle"); pg.wait_for_timeout(1200)
        if not pg.evaluate(f"() => !!(window.Rack3D && window.Rack3D.supported() && window.Rack3D.hasScene('{dg}'))"):
            ok(f"{dg}：沒有 3D 場景，只驗 2D", True, "")
            continue
        click(pg, "#dg3d button:not(.on)", 400)
        wait_until(pg, "() => document.querySelectorAll('#prod3d .lbl3d a.chip3d').length > 0", 12000)
        pg.wait_for_timeout(1200)
        c3 = pg.evaluate(DGSTK_3D)
        m2 = {c["part"]: c["codes"] for c in c2 if c["part"]}
        common = [k for k in m2 if k in c3]
        diff = [(k, m2[k], c3[k]) for k in common if m2[k] != c3[k]]
        ok(f"{dg}：2D 與 3D 同一零件的股票名單一致（對得上的 {len(common)} 個零件）", not diff, diff[:3])
        code, h = _dgstk_click(pg, "document.querySelectorAll('#prod3d .lbl3d:not(.hid) a.chip3d')")
        if ok(f"{dg}：點 3D 股票標籤 → 進 #stock/{code}", bool(code) and h == f"#stock/{code}", h):
            pg.go_back()
            h2 = wait_until(pg, "() => location.hash === '%s' ? location.hash : null" % route, 4000)
            ok(f"{dg}：3D 點股票後按上一頁回到剖析圖", h2 == route, pg.evaluate("() => location.hash"))
        pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0'); } catch (e) {} }")
    pg.evaluate(f"() => {{ try {{ const v = {anim0!r}; if (v == null) localStorage.removeItem('tw.dganim'); else localStorage.setItem('tw.dganim', v); }} catch (e) {{}} }}".replace("None", "null"))


def t_dgfit(pg, base):
    pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0'); localStorage.setItem('tw.dgOpen', '1'); } catch (e) {} }")
    side0 = pg.evaluate("() => { try { return localStorage.getItem('tw.side'); } catch (e) { return null; } }")
    ids = pg.evaluate("""() => { const S = window.DiagramSlots; if (!S) return []; const out = [];
      ['semiconductor', 'ai_server'].forEach(ch => { if (S.chainDefault(ch)) out.push([ch, ch]); S.groupsOf(ch).forEach(g => out.push([ch, g])); });
      return out; }""")
    ok("半導體與 AI 伺服器鏈列得出剖析圖", len(ids) >= 10, ids)
    # 兩種版面各跑一輪：事件抽屜開（兩欄：卡片全在右欄）／關（三欄：左右夾著畫布）
    for side, label in (("1", "抽屜開・兩欄"), ("0", "抽屜關・三欄")):
        pg.set_viewport_size({"width": 1440, "height": 1000})
        pg.evaluate(f"() => {{ try {{ localStorage.setItem('tw.side', '{side}'); }} catch (e) {{}} }}")
        clicked = 0
        for ch, dg in ids:
            pg.goto("about:blank")
            pg.goto(f"{base}#industry/{ch}/dg/{dg}", wait_until="networkidle")
            m = wait_until(pg, "() => { const f = " + DGFIT_MEAS + "; const m = f(); return m && m.ch > 0 ? m : null; }", 6000)
            pg.wait_for_timeout(500)
            m = pg.evaluate(DGFIT_MEAS)
            if not m:
                continue                                    # 不是 v2 版面（沒有外掛卡片）的圖不在這一條的範圍
            if m["beside"]:
                ok(f"[{label}] {dg}：卡片欄高 ≤ 畫布高 ＋ 40px", max(m["boxH"]) <= m["ch"] + 40,
                   f"卡片欄 {m['boxH']} ／ 畫布 {m['ch']}")
                if m["fold"]:
                    ok(f"[{label}] {dg}：收合模式下卡片只留編號＋標題（沒有一張展開說明）", m["descShown"] == 0,
                       f"展開說明的 {m['descShown']} 張")
            # 每一條鏈只挑前三張做完整的點擊（其餘只量高度），控制時間
            if clicked >= 3:
                continue
            # 先等版面停下來（載入後 300ms 還有一次補排），量完座標**立刻**點 —— 量和點之間隔著一次重排，
            # 點到的就是隔壁那個編號（2026-09-24 寬能隙實測：01 在 300ms 內往上移了 72px，點到 02）
            pg.wait_for_timeout(700)
            a = pg.evaluate(DGFIT_ANC)
            if not a:
                continue
            clicked += 1
            pg.mouse.click(a["x"], a["y"]); pg.wait_for_timeout(700)
            m1 = pg.evaluate(DGFIT_MEAS)
            ok(f"[{label}] {dg}：點圖上的編號 {a['no']} → 跳出那個零件的說明小卡",
               bool(m1 and m1["pop"]) and a["title"][:6] in (m1["pop"] or {}).get("t", ""),
               [a, m1 and m1["pop"]])
            if m1 and m1["fold"]:
                ok(f"[{label}] {dg}：被點的那張卡片展開說明（其餘維持收合）", m1["descShown"] == 1, m1["descShown"])
            if m1 and m1["beside"]:
                ok(f"[{label}] {dg}：展開之後卡片欄仍然 ≤ 畫布高 ＋ 40px（多的在欄內捲）",
                   max(m1["boxH"]) <= m1["ch"] + 40, f"{m1['boxH']} ／ {m1['ch']}")
            bg = _dgfit_bg_point(pg)
            if ok(f"[{label}] {dg}：找得到畫布背景可以點", bool(bg), bg):
                pg.mouse.click(bg["x"], bg["y"]); pg.wait_for_timeout(700)
                m2 = pg.evaluate(DGFIT_MEAS)
                ok(f"[{label}] {dg}：點背景 → 說明小卡關掉", bool(m2) and not m2["pop"], m2 and m2["pop"])
                if m2 and m2["fold"]:
                    ok(f"[{label}] {dg}：點背景 → 卡片收回只剩編號＋標題", m2["descShown"] == 0, m2["descShown"])
        ok(f"[{label}] 至少真的點過一張圖的編號", clicked >= 1, clicked)

    # Esc 也關得掉、同一個編號再點一次＝收起（選取保留）
    pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor/dg/silicon_wafer", wait_until="networkidle"); pg.wait_for_timeout(1500)
    a = pg.evaluate(DGFIT_ANC)
    if ok("矽晶圓：找得到編號", bool(a), a):
        pg.mouse.click(a["x"], a["y"]); pg.wait_for_timeout(600)
        pg.keyboard.press("Escape"); pg.wait_for_timeout(400)
        ok("按 Esc → 說明小卡關掉", not (pg.evaluate(DGFIT_MEAS) or {}).get("pop"))
        a = pg.evaluate(DGFIT_ANC)
        pg.mouse.click(a["x"], a["y"]); pg.wait_for_timeout(600)
        a = pg.evaluate(DGFIT_ANC)
        pg.mouse.click(a["x"], a["y"]); pg.wait_for_timeout(600)
        st = pg.evaluate("() => ({ pop: !document.querySelector('#prodDiagram .dgpop') || document.querySelector('#prodDiagram .dgpop').hidden, sel: document.querySelectorAll('#prodDiagram .dgc.sel-part').length })")
        ok("同一個編號再點一次 → 小卡收起、零件仍然選著", st["pop"] and st["sel"] == 1, st)
    # 審查 R3：傳產鏈預設的輕油裂解廠一打開整張被壓暗（族群環節跟圖上的 data-seg 對不上）
    pg.goto("about:blank"); pg.goto(f"{base}#industry/traditional", wait_until="networkidle"); pg.wait_for_timeout(1800)
    pd = pg.evaluate("() => ({ dg: (document.getElementById('prodDiagram')||{dataset:{}}).dataset.dgid,"
                     " dim: document.querySelectorAll('#prodDiagram .dim').length, seg: document.querySelectorAll('#prodDiagram [data-seg]').length })")
    if pd.get("seg"):
        ok("傳產鏈一打開：剖析圖沒有被整張壓暗（沒選任何零件時 .dim＝0）", pd["dim"] == 0, pd)
    pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor/dg/silicon_wafer", wait_until="networkidle"); pg.wait_for_timeout(1500)
    # 手機版要用的「只留編號」資料結構：data-dglbl="num" 時卡片欄藏起來、點編號照樣有說明
    pg.evaluate("() => { const w = document.getElementById('prodDiagram'); w.dataset.dglbl = 'num'; window.dispatchEvent(new Event('resize')); }")
    pg.wait_for_timeout(500)
    a = pg.evaluate(DGFIT_ANC)
    hid = pg.evaluate("() => { const k = document.querySelector('#prodDiagram .dgcards'); return !!k && !k.offsetParent; }")
    ok("data-dglbl=num：卡片欄整個藏起來（只留圖上的編號）", hid)
    if a:
        pg.mouse.click(a["x"], a["y"]); pg.wait_for_timeout(600)
        ok("data-dglbl=num：點編號照樣跳出說明小卡", bool((pg.evaluate(DGFIT_MEAS) or {}).get("pop")))

    # ---- 3D：卡片不准再掉到畫布底下那一排（兩欄模式要塞在畫布同高裡，塞不下收成「編號＋標題」）
    pg.evaluate("() => { try { localStorage.setItem('tw.side', '1'); localStorage.setItem('tw.dg3d', '1'); localStorage.setItem('tw.dganim', '0'); } catch (e) {} }")
    for ch, dg in ids:
        has = pg.evaluate(f"() => {{ const S = window.DiagramSlots; const s = S && S.scene('{dg}'); return !!(s && window.Rack3D && window.Rack3D.supported() && window.Rack3D.hasScene(s)); }}")
        if not has:
            continue
        pg.goto("about:blank"); pg.goto(f"{base}#industry/{ch}/dg/{dg}", wait_until="networkidle")
        wait_until(pg, "() => document.querySelectorAll('#prod3d .lbl3d').length > 2", 15000); pg.wait_for_timeout(1400)
        pg.mouse.move(3, 3); pg.wait_for_timeout(300)
        st = pg.evaluate("""() => { const h = document.getElementById('prod3d'); const c = h && h.querySelector('canvas'); if (!c) return null;
          const cr = c.getBoundingClientRect(); const cards = [...h.querySelectorAll('.lbl3d')].filter(e => e.offsetParent && !e.classList.contains('hid'));
          return { mode: ['lr','r','below'].find(m => h.classList.contains('dgstage--' + m)), ch: Math.round(cr.height), hostH: h.clientHeight,
            below: cards.filter(e => e.classList.contains('below')).length,
            bottom: Math.round(Math.max(...cards.map(e => e.getBoundingClientRect().bottom)) - cr.top) }; }""")
        if not st or st["mode"] == "below":
            continue
        ok(f"[3D] {dg}：卡片都在畫布兩側（沒有掉到底下那一排）", st["below"] == 0 and st["hostH"] <= st["ch"] + 40, st)
    pg.evaluate("(s) => { try { localStorage.setItem('tw.dg3d', '0'); localStorage.removeItem('tw.dganim');"
                " if (s == null) localStorage.removeItem('tw.side'); else localStorage.setItem('tw.side', s); } catch (e) {} }", side0)
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ============================================================================================
# ★ 2026-09-25 Andy 回報（產業地圖 → 半導體 → 矽晶圓，3D）：「點擊後不會收回」——
#   左欄 01／06／02／03、右欄 05 同時展開說明全文＋台股，越點越多張。
#   根因：3D 卡片的收合階數 0 ＝ 全開（一欄塞得下就整欄全開，跟點了哪一張無關）；
#   2D 收合模式的公式／警語說明卡各自 toggle .open，點背景／Esc 收不掉。
#   規則（兩種圖一樣）：同一時間最多一張展開說明（被選的那張，或滑過的那張）；
#   再點同一張 → 0；點背景／Esc → 0；點圖上零件後再點背景 → 0。
#   「展開」＝那張卡片的說明全文（3D 的 <i>／2D 的 .bd i）真的顯示在畫面上 —— 量畫面，不是量 class。
#   ⚠ 一律 --workers 1（3D、滑鼠位置、動畫都會互相干擾）。
# ============================================================================================
DGC_3D = """() => { const h = document.getElementById('prod3d'); if (!h) return null;
  const cards = [...h.querySelectorAll('.lbl3d')].filter(e => e.offsetParent && !e.classList.contains('hid'));
  const no = (e) => (e.querySelector('em.no3d') || {}).textContent || '';
  const shown = (e) => { const i = e.querySelector('i'); return !!i && getComputedStyle(i).display !== 'none' && i.getBoundingClientRect().height > 0; };
  return { n: cards.length, mode: ['lr', 'r', 'below'].find(m => h.classList.contains('dgstage--' + m)) || '',
    exp: cards.filter(shown).map(no), sel: cards.filter(e => e.classList.contains('sel-part')).map(no), nos: cards.map(no) }; }"""
DGC_2D = """() => { const w = document.getElementById('prodDiagram'); if (!w || w.hidden) return null;
  const cards = [...w.querySelectorAll('.dgc')].filter(e => e.offsetParent);
  const no = (e) => (e.querySelector('.no') || {}).textContent || ('note' + [...e.parentNode.children].indexOf(e) + (e.classList.contains('warn') ? 'w' : ''));
  const shown = (e) => [...e.querySelectorAll('.bd i')].some(i => i.offsetParent && i.getBoundingClientRect().height > 0);
  const pop = w.querySelector('.dgpop');
  return { n: cards.length, fold: w.classList.contains('dgfold'),
    exp: cards.filter(shown).map(no), sel: cards.filter(e => e.classList.contains('sel-part')).map(no),
    nos: cards.filter(e => e.dataset.seg || e.dataset.part).map(no), notes: cards.filter(e => !e.dataset.seg && !e.dataset.part).map(no),
    pop: !!(pop && !pop.hidden) }; }"""
# 找某一張卡片的「標題」那一點（避開台股標籤 —— 點到標籤會進個股頁），捲進畫面後**立刻**回座標
DGC_PT = """([mode, no]) => { const all = mode === '3d' ? [...document.querySelectorAll('#prod3d .lbl3d')] : [...document.querySelectorAll('#prodDiagram .dgc')];
  const nf = mode === '3d' ? (e) => (e.querySelector('em.no3d') || {}).textContent || ''
    : (e) => (e.querySelector('.no') || {}).textContent || ('note' + [...e.parentNode.children].indexOf(e) + (e.classList.contains('warn') ? 'w' : ''));
  const e = all.find(x => nf(x) === no && x.offsetParent); if (!e) return null;
  e.scrollIntoView({ block: 'center', behavior: 'instant' });
  const t = e.querySelector('b') || e; const r = t.getBoundingClientRect();
  const x = Math.min(r.right - 4, r.left + 34), y = r.top + Math.min(9, r.height / 2);
  const hit = document.elementFromPoint(x, y);
  return hit && e.contains(hit) && !hit.closest('a') ? { x, y } : null; }"""
# 3D 畫布上的「背景」：畫布頂端正中間那一條（模型一律置中、兩側是卡片欄）
DGC_BG3D = """() => { const c = document.querySelector('#prod3d canvas'); if (!c) return null;
  c.scrollIntoView({ block: 'center', behavior: 'instant' }); const r = c.getBoundingClientRect();
  for (const [fx, fy] of [[.5, .02], [.45, .03], [.55, .03], [.5, .98]]) { const x = r.left + r.width * fx, y = r.top + r.height * fy;
    if (document.elementFromPoint(x, y) === c) return { x, y }; } return null; }"""


def _dgc_meas(pg, mode):
    return pg.evaluate(DGC_3D if mode == "3d" else DGC_2D)


def _dgc_click_card(pg, mode, no):
    """點某一張卡片的標題；最多試 3 次（3D 卡片每幾幀會重排，量和點之間可能換了位置）。
    點完把滑鼠移開（滑過會展開，要量的是「點擊之後」的狀態），回傳量測結果。"""
    m = None
    for _ in range(3):
        pt = pg.evaluate(DGC_PT, [mode, no])
        if not pt:
            pg.wait_for_timeout(300); continue
        pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(650)
        pg.mouse.move(3, 3); pg.wait_for_timeout(450)
        return _dgc_meas(pg, mode)
    return m


def _dgc_bg(pg, mode):
    pt = pg.evaluate(DGC_BG3D) if mode == "3d" else _dgfit_bg_point(pg)
    if not pt:
        return None
    pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(650)
    pg.mouse.move(3, 3); pg.wait_for_timeout(450)
    return _dgc_meas(pg, mode)


def t_dgcollapse(pg, base):
    keep = pg.evaluate("() => { try { return ['tw.side','tw.dg3d','tw.dganim','tw.dgOpen'].map(k => localStorage.getItem(k)); } catch (e) { return [null,null,null,null]; } }")
    pg.set_viewport_size({"width": 1440, "height": 1000})
    for route, name in (("industry/semiconductor/dg/silicon_wafer", "矽晶圓"), ("industry/ai_server/dg/pcb_rigid", "PCB硬板")):
        for mode in ("3d", "2d"):
            tag = f"[{name}/{mode.upper()}]"
            pg.evaluate("(m) => { try { localStorage.setItem('tw.side', '0'); localStorage.setItem('tw.dgOpen', '1');"
                        " localStorage.setItem('tw.dganim', '0'); localStorage.setItem('tw.dg3d', m === '3d' ? '1' : '0'); } catch (e) {} }", mode)
            pg.goto("about:blank"); pg.goto(f"{base}#{route}", wait_until="networkidle")
            if mode == "3d":
                if not wait_until(pg, "() => document.querySelectorAll('#prod3d .lbl3d').length > 2", 15000):
                    ok(f"{tag} 3D 掛得起來", False, "15 秒內沒有卡片"); continue
            else:
                wait_until(pg, "() => { const w = document.getElementById('prodDiagram'); return w && !w.hidden && !!w.querySelector('.dgc'); }", 8000)
            pg.wait_for_timeout(1400)
            pg.mouse.move(3, 3); pg.wait_for_timeout(500)
            m0 = _dgc_meas(pg, mode)
            if not ok(f"{tag} 量得到卡片", bool(m0 and m0["n"] >= 4), m0):
                continue
            if mode == "3d" and m0["mode"] == "below":
                ok(f"{tag} 1440 寬應該是欄位模式（lr／r），不是底下那一排", False, m0); continue
            if mode == "2d" and not m0["fold"]:
                ok(f"{tag} 1440／抽屜關：卡片塞不下，應該進收合模式（.dgfold）", False, m0); continue
            ok(f"{tag} 一進來：沒有任何一張卡片展開說明", len(m0["exp"]) == 0, m0["exp"])
            nos = sorted(m0["nos"])[:3]
            # ① 依序點三張：任何時刻展開數 ≤ 1，而且展開的就是剛剛點的那一張
            last = None
            for no in nos:
                m = _dgc_click_card(pg, mode, no)
                ok(f"{tag} 點 {no}：只有它展開（展開數 ≤ 1、選取＝{no}）",
                   bool(m) and len(m["exp"]) <= 1 and m["sel"] == [no] and m["exp"] == [no], m and {"exp": m["exp"], "sel": m["sel"]})
                last = no
            # ② 再點同一張 → 收回、取消選取
            m = _dgc_click_card(pg, mode, last)
            ok(f"{tag} 再點同一張 {last} → 收回（展開 0、選取 0）", bool(m) and not m["exp"] and not m["sel"],
               m and {"exp": m["exp"], "sel": m["sel"]})
            # ③ 點一張 → 點背景 → 0
            _dgc_click_card(pg, mode, nos[0])
            m = _dgc_bg(pg, mode)
            ok(f"{tag} 點 {nos[0]} 再點背景 → 全部收回", bool(m) and not m["exp"] and not m["sel"], m and {"exp": m["exp"], "sel": m["sel"]})
            # ④ 點一張 → 按 Esc → 0
            _dgc_click_card(pg, mode, nos[1])
            pg.keyboard.press("Escape"); pg.wait_for_timeout(600)
            m = _dgc_meas(pg, mode)
            ok(f"{tag} 點 {nos[1]} 再按 Esc → 全部收回", bool(m) and not m["exp"] and not m["sel"], m and {"exp": m["exp"], "sel": m["sel"]})
            # ⑤ 點圖上的零件（3D：模型本身；2D：圖上的編號）→ 展開 ≤ 1 → 點背景 → 0
            if mode == "3d":
                pt = pg.evaluate("""() => { const v = window.Rack3D && window.Rack3D.current; if (!v) return null;
                  document.querySelector('#prod3d canvas').scrollIntoView({ block: 'center', behavior: 'instant' });
                  for (const s of v.segs()) { const p = v.screen(s); if (p && p.front) return p; } return null; }""")
            else:
                pt = pg.evaluate(DGFIT_ANC)
            if ok(f"{tag} 找得到圖上的零件可以點", bool(pt), pt):
                pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(700)
                pg.mouse.move(3, 3); pg.wait_for_timeout(450)
                m = _dgc_meas(pg, mode)
                ok(f"{tag} 點圖上零件：選起來、展開數 ≤ 1", bool(m) and len(m["sel"]) >= 1 and len(m["exp"]) <= 1,
                   m and {"exp": m["exp"], "sel": m["sel"]})
                m = _dgc_bg(pg, mode)
                ok(f"{tag} 點圖上零件後再點背景 → 全部收回", bool(m) and not m["exp"] and not m["sel"] and not m.get("pop"),
                   m and {"exp": m["exp"], "sel": m["sel"], "pop": m.get("pop")})
            # ⑥ 滑過展開、滑出收回（3D 收成一行的卡片靠 :hover 看說明）
            if mode == "3d":
                bg = pg.evaluate(DGC_BG3D)                    # 先進容器（爆炸圖展開、卡片重排完）再找卡片，不然滑進去那一刻卡片會跑掉
                if bg:
                    pg.mouse.move(bg["x"], bg["y"]); pg.wait_for_timeout(600)
                mh, pt = None, None
                for _ in range(3):                            # 捲動／爆炸圖重排會讓卡片離開游標底下：重新找點再滑一次
                    pt = pg.evaluate(DGC_PT, ["3d", nos[2]])
                    if not pt:
                        pg.wait_for_timeout(300); continue
                    pg.mouse.move(pt["x"], pt["y"]); pg.wait_for_timeout(400)
                    mh = _dgc_meas(pg, mode)
                    if mh and nos[2] in mh["exp"]:
                        break
                if pt:
                    pg.mouse.move(3, 3); pg.wait_for_timeout(450)
                    mo = _dgc_meas(pg, mode)
                    ok(f"{tag} 滑過 {nos[2]} → 只有它展開；滑出 → 收回",
                       bool(mh and mo) and mh["exp"] == [nos[2]] and not mo["exp"], [mh and mh["exp"], mo and mo["exp"]])
            # ⑦ 2D 的公式／警語說明卡（沒有零件身分、點它自己開合）：一次只開一張，點背景／Esc 收回
            if mode == "2d" and len(m0["notes"]) >= 2:
                a, b2 = m0["notes"][0], m0["notes"][1]
                m = _dgc_click_card(pg, mode, a)
                ok(f"{tag} 點說明卡 {a} → 只有它展開", bool(m) and m["exp"] == [a], m and m["exp"])
                m = _dgc_click_card(pg, mode, b2)
                ok(f"{tag} 再點說明卡 {b2} → 前一張收回、只剩它", bool(m) and m["exp"] == [b2], m and m["exp"])
                m = _dgc_click_card(pg, mode, nos[0])
                ok(f"{tag} 說明卡開著時點零件卡 {nos[0]} → 說明卡收回、只剩零件卡", bool(m) and m["exp"] == [nos[0]], m and m["exp"])
                _dgc_click_card(pg, mode, a)
                m = _dgc_bg(pg, mode)
                ok(f"{tag} 說明卡開著時點背景 → 收回", bool(m) and not m["exp"], m and m["exp"])
                _dgc_click_card(pg, mode, b2)
                pg.keyboard.press("Escape"); pg.wait_for_timeout(500)
                m = _dgc_meas(pg, mode)
                ok(f"{tag} 說明卡開著時按 Esc → 收回", bool(m) and not m["exp"], m and m["exp"])

    # ⑧ 動畫開著（自轉＋爆炸圖展開，投影點每幀在動 —— 修之前就是這時候一欄從塞不下變塞得下、冒出整欄全開）：
    #    選一張卡片之後，游標停在畫布上（爆炸圖展開）連續取樣 3 秒，每一次展開數都 ≤ 1
    pg.evaluate("() => { try { localStorage.setItem('tw.side', '0'); localStorage.setItem('tw.dg3d', '1'); localStorage.setItem('tw.dganim', '1'); } catch (e) {} }")
    pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor/dg/silicon_wafer", wait_until="networkidle")
    if wait_until(pg, "() => document.querySelectorAll('#prod3d .lbl3d').length > 2", 15000):
        pg.wait_for_timeout(1400)
        m0 = _dgc_meas(pg, "3d")
        no = sorted(m0["nos"])[0] if m0 and m0["nos"] else None
        if no:
            _dgc_click_card(pg, "3d", no)
            bg = pg.evaluate(DGC_BG3D)
            if bg:
                pg.mouse.move(bg["x"], bg["y"])
            worst = []
            for _ in range(8):
                pg.wait_for_timeout(400)
                m = _dgc_meas(pg, "3d")
                if m and len(m["exp"]) > len(worst):
                    worst = m["exp"]
            ok("[矽晶圓/3D 動畫開] 自轉＋爆炸圖展開 3 秒內，任何時刻展開數 ≤ 1", len(worst) <= 1, worst)
    pg.mouse.move(3, 3)
    pg.evaluate("(k) => { try { ['tw.side','tw.dg3d','tw.dganim','tw.dgOpen'].forEach((n, i) => { if (k[i] == null) localStorage.removeItem(n); else localStorage.setItem(n, k[i]); }); } catch (e) {} }", keep)
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 資金去向・拓撲版（site/flowtopo.js）
# ★ 2026-09-24（Andy：卡片 1700px 要一直捲、左欄一排散點、照參考檔的微光拓撲重畫）。
#   桌機（> 820px）預設畫拓撲版；手機維持經典版（ECharts 樹）。這一段**真的用滑鼠點畫布上的節點**
#   （座標從 App.sankeyTopo() 探針讀，那是畫布上實際畫出去的位置），每一步都驗「畫面真的變了」。
#   經典版那一套（ECharts 內部結構、小圓點）仍由「資金流向／新-資金流向／資金去向v2／桑基展開與即時」驗，
#   那幾段開頭會先切到經典版（sk_classic）。
TOPO = "() => window.App && window.App.sankeyTopo ? window.App.sankeyTopo() : null"
TOPO_CARD_MAX = 760           # 1440 寬整張卡的高度上限（Andy：一屏看得完）


def sk_classic(pg, on: bool = True):
    """切資金去向的樣式（經典版＝ECharts 樹／經典光纖＝flowtopo.js 經典版面），並等它真的換過去。
    ★ 2026-09-25 改前→改後：
      · localStorage key：tw.sankey.style → tw.sankey.mode（三選一換了新 key，舊 key 不再被讀）
      · on=False 切回的：'topo'（當時的桌機預設）→ 'fx'（經典光纖，現在的桌機預設）
    ★ 2026-09-26（晚）改前→改後（Andy：「只留下經典光纖版本」，使用者已經沒有切換鈕）：
      · 不再寫 tw.sankey.mode（app.js 已經不讀它）；只走驗收用的內部切換 App.sankeyStyle('classic'|'fx')，
        重新整理就回到經典光纖。ECharts 樹仍是手機（≤ 820）的畫法，這幾段在桌機寬度量它的內部結構。"""
    pg.evaluate("(s) => { if (window.App && window.App.sankeyStyle) window.App.sankeyStyle(s); }",
                "classic" if on else "fx")
    if on:
        wait_until(pg, "() => !document.getElementById('sankey') || !!(window.echarts && "
                       "echarts.getInstanceByDom(document.getElementById('sankey')))", 5000)
    pg.wait_for_timeout(700)


def _topo_card_h(pg) -> int:
    return pg.evaluate("() => Math.round(document.getElementById('flowSankeyCard').getBoundingClientRect().height)")


def _topo_node(pg, key: str):
    """把畫布上的某個節點捲到視窗正中間，回傳它（含螢幕座標 cx／cy）；找不到回 None。
    ★ 2026-09-25 加的：經典光纖整張圖 928px 高，比 950px 的視窗扣掉固定頂欄還高，
      「捲到卡片中央」之後最上面幾個族群會躲在頂欄底下 —— 滑鼠點下去點到的是頂欄。
      改成以**那個節點**為準置中（instant，不吃全站的 smooth scroll）。"""
    scroll_to(pg, "sankey")
    t = pg.evaluate(TOPO)
    n = [x for x in (t or {}).get("nodes", []) if x["key"] == key]
    if not n:
        return None
    ih = pg.evaluate("() => innerHeight")
    if not (120 < n[0]["cy"] < ih - 40):
        pg.evaluate("(dy) => window.scrollBy({top: dy, behavior: 'instant'})", n[0]["cy"] - ih / 2)
        pg.wait_for_timeout(350)
        n = [x for x in pg.evaluate(TOPO)["nodes"] if x["key"] == key]
    return n[0] if n else None


def _topo_click(pg, key: str) -> bool:
    """用滑鼠點畫布上的某個節點（key：root / c:<鏈> / g:<族群> / l:<族群>:<代號>）。
    改前：捲到卡片中央就點；改後：先把那個節點捲到視窗中央（_topo_node），拓撲版（矮）行為不變。"""
    n = _topo_node(pg, key)
    if not n:
        return False
    pg.mouse.click(n["cx"], n["cy"])
    pg.wait_for_timeout(900)
    return True


def _topo_left_pixels(pg) -> int:
    """粒子層（.ftfx）在根節點左邊那一條有幾個不透明像素 —— 「左欄一排散點」直接量畫面。"""
    return pg.evaluate("""() => { const t = window.App.sankeyTopo(); const c = document.querySelector('#sankey canvas.ftfx');
        if (!t || !c) return -1; const dpr = t.dpr, w = Math.max(1, Math.floor((t.rootX - 10) * dpr));
        const d = c.getContext('2d').getImageData(0, 0, w, c.height).data; let n = 0;
        for (let i = 3; i < d.length; i += 4) if (d[i] > 24) n++; return n; }""")


def t_flowtopo(pg, base):
    """★ 2026-09-26（晚）改前→改後（Andy：「將資金去向只留下經典光纖版本」）：
    改前：這一段整段驗拓撲版本身（先把 tw.sankey.mode 設成 'topo' 再量卡片高度、左欄散點、粒子、點族群長成分股…）。
    改後：拓撲版已經沒有入口（三選一分段鈕拿掉、tw.sankey.mode 不再讀），這一段改驗「切不到拓撲」：
      ① 沒有版面分段鈕（#sankeyStyleSeg／.skseg 都不在），拉Bar 那一列只剩日期、回放、即時
      ② localStorage 裡舊的 tw.sankey.mode＝'topo'／'classic'（之前切過的人）→ 一律畫經典光纖
      ③ 驗收用的內部切換傳 'topo' 也只會回到經典光纖（'topo' 不再是合法值）"""
    pg.set_viewport_size({"width": 1440, "height": 950})
    for old in ("topo", "classic"):
        pg.goto(f"{base}#overview", wait_until="networkidle")
        pg.evaluate("(v) => { try { localStorage.setItem('tw.sankey.mode', v); localStorage.removeItem('tw.sankey.day'); } catch (e) {} }", old)
        pg.reload(wait_until="networkidle"); pg.goto(f"{base}#flow", wait_until="networkidle")
        wait_until(pg, "() => window.App && window.App.sankeyTopoOn && window.App.sankeyTopoOn()", 8000)
        scroll_to(pg, "sankey"); pg.wait_for_timeout(1200)
        t = pg.evaluate(TOPO)
        ok(f"② 舊設定 tw.sankey.mode＝'{old}' 被忽略：畫的是經典光纖（flowtopo 經典版面，不是拓撲、不是 ECharts）",
           bool(t) and t["layout"] == "classic" and not pg.evaluate(
               "() => !!(window.echarts && echarts.getInstanceByDom(document.getElementById('sankey')))"), t and t.get("layout"))
    ok("① 沒有版面分段鈕（經典光纖／拓撲／經典 那一組整個拿掉）", pg.evaluate(
        "() => !document.getElementById('sankeyStyleSeg') && !document.querySelector('#flowSankeyCard .skseg, #flowSankeyCard [data-sk-style]')"))
    ok("① 拉Bar 那一列只剩日期拉Bar、回放、即時（沒有任何版面鈕）", pg.evaluate(
        "() => { const b = document.getElementById('sankeyDays'); return !!b && !!b.querySelector('#sankeyLiveBtn') && !b.querySelector('[data-sk-style]'); }"))
    got = pg.evaluate("() => window.App.sankeyStyle('topo')")
    pg.wait_for_timeout(900)
    t = pg.evaluate(TOPO)
    ok("③ 內部切換傳 'topo' 也只回到經典光纖（拓撲版沒有入口）", got == "fx" and bool(t) and t["layout"] == "classic", {"回": got, "layout": t and t.get("layout")})
    pg.evaluate("() => { try { localStorage.removeItem('tw.sankey.mode'); } catch (e) {} }")


def _topo_contrast(t, tag, motion=True, fx=False):
    """粗細、快慢、明暗三個維度的對比（Andy 2026-09-25：「粗細、快慢、明暗變化加強點，看不出差異」）。
    量的是探針回報的每條活著的線：線寬 w、粒子速度 v（px/秒）、不透明度係數 al、實際發車率 er。
    改前實測（1440 深色）：線寬 1.43～2.87（2 倍）、速度 141～177（1.3 倍），沒有明暗係數。"""
    lk = [x for x in (t or {}).get("links", []) if not x["dead"]]
    if not ok(f"{tag} 量得到活著的連線", len(lk) >= 5, len(lk)):
        return
    ws, als = [x["w"] for x in lk], [x["al"] for x in lk]
    if fx:
        # ★ 2026-09-26（第二版）經典光纖 改前→改後：weight 1～13px、×6 → 黃金標準的 0.8～3.8、×4.5 以上
        #   （最粗 13px 的外暈 ×2.4＝31px 就是 Andy 說的「霧」；參考稿主幹 3.8、毛細 0.8）
        ok(f"{tag} 粗細：最粗 weight ≥ 最細 ×4.5，且落在 0.8～3.8（黃金標準尺度）",
           max(ws) >= min(ws) * 4.5 and max(ws) <= 3.81 and min(ws) >= 0.79, {"min": min(ws), "max": max(ws)})
    else:
        ok(f"{tag} 粗細：最粗線寬 ≥ 最細 ×6，且落在 1～14px", max(ws) >= min(ws) * 6 and max(ws) <= 14 and min(ws) >= 1,
           {"min": min(ws), "max": max(ws)})
    ok(f"{tag} 明暗：最小線不透明度 ≤ 最大 ×0.45", min(als) <= max(als) * 0.45, {"min": min(als), "max": max(als)})
    if motion:
        vs = [x["v"] for x in lk if x["v"] > 0]
        ok(f"{tag} 快慢：最大線粒子速度 ≥ 最小 ×4", bool(vs) and max(vs) >= min(vs) * 4,
           vs and {"min": min(vs), "max": max(vs)})
        # 2026-09-26（晚）：代表股預設收起 → 收起的毛細線不發車（er＝0），比「密度」時只算看得見的線
        lkd = [x for x in lk if x.get("shown", 1)] if fx else lk
        big = max(lkd, key=lambda x: x["w"])
        small = min(lkd, key=lambda x: x["w"])
        ok(f"{tag} 密度：最粗線的發車率 ≥ 最細 ×6", big["er"] >= small["er"] * 6, {"粗": big["er"], "細": small["er"]})


def _topo_rank_ok(t, tag):
    """換日依排名換位：同一條鏈裡族群的 y 由上到下＝成交值由大到小（盤後／無資料／0 墊底）。"""
    if not ok(f"{tag}：讀得到拓撲版", bool(t)):
        return
    bad = []
    for c in [n for n in t["nodes"] if n["lv"] == 1]:
        ks = {e["key"].split(">")[1] for e in t["links"] if e["key"].startswith(c["key"] + ">")}
        kids = sorted([n for n in t["nodes"] if n["lv"] == 2 and n["key"] in ks], key=lambda n: n["y"])
        vals = [-1 if (n["stale"] or not (n["value"] or 0) > 0) else n["value"] for n in kids]
        if any(vals[i] < vals[i + 1] for i in range(len(vals) - 1)):
            bad.append((c["name"], [n["name"] for n in kids][:5]))
    ok(f"{tag}：族群在鏈內依成交值由大到小排（依排名換位，改前是位置固定）", not bad, bad[:2])


def _topo_swap_tween(pg, bar):
    """換到排名不同的一天：節點沿垂直方向補間滑過去，中途 y 有中間值、而且單調趨近終點。"""
    samp = pg.evaluate("""(sel) => new Promise(res => {
        const host = document.getElementById('sankey'), inp = document.querySelector(sel);
        const cur = +inp.value, to = cur >= +inp.max ? +inp.min : +inp.max;
        window.FlowTopo.tweenMs(host, 2400);   // 容器 rAF 只有 13～15 FPS：拉長補間才取得到足夠的中途樣本
        const out = []; const t0 = performance.now();
        const grab = () => { const t = window.FlowTopo.probe(host);
          out.push({ t: performance.now() - t0, tw: t.tweening, e: t.twE,
                     ys: Object.fromEntries(t.nodes.filter(n => n.lv === 2).map(n => [n.key, n.y])) }); };
        grab();
        inp.value = to; inp.dispatchEvent(new Event('input', {bubbles: true}));
        inp.dispatchEvent(new Event('change', {bubbles: true}));
        const f = () => { grab(); if (performance.now() - t0 < 3200) requestAnimationFrame(f); else { window.FlowTopo.tweenMs(host, 0); res(out); } };
        requestAnimationFrame(f); })""", bar)
    start, end = samp[0]["ys"], samp[-1]["ys"]
    mv = sorted(((abs(end[k] - start[k]), k) for k in end if k in start), reverse=True)
    if not ok("換日：至少有一個族群因排名改變而換了位置", bool(mv) and mv[0][0] >= 10, mv[:2]):
        return
    k = mv[0][1]
    ys = [s["ys"][k] for s in samp if k in s["ys"]]
    y0, y1 = ys[0], ys[-1]
    mids = [y for y in ys if min(y0, y1) + 1 < y < max(y0, y1) - 1]
    ok("換日：補間中途節點 y 有中間值（不是瞬移）", len(mids) >= 2, {"node": k, "ys": ys[:40:3]})
    sgn = 1 if y1 > y0 else -1
    ok("換日：y 單調趨近終點（不來回晃）", all((ys[i + 1] - ys[i]) * sgn >= -0.6 for i in range(len(ys) - 1)),
       {"node": k, "ys": ys[:40:3]})
    ok("換日：補間會收掉（驗收拉長成 2.4 秒，3.2 秒時已經不在補間；平常 480ms）", not samp[-1]["tw"], samp[-1]["t"])
    ok("換日：百分比同步補間（補間進度走過中間值）", any(0.05 < s["e"] < 0.95 for s in samp),
       [s["e"] for s in samp][:20:2])


def _topo_overlap(t) -> int:
    if not t:
        return -1
    bs = [n["lab"] for n in t["nodes"] if n["lab"] and not n["dim"]]
    k = 0
    for i in range(len(bs)):
        for j in range(i + 1, len(bs)):
            a, b = bs[i], bs[j]
            if a["x"] < b["x"] + b["w"] - 1 and b["x"] < a["x"] + a["w"] - 1 and a["y"] < b["y"] + b["h"] - 1 and b["y"] < a["y"] + a["h"] - 1:
                k += 1
    return k


def t_flowtopo_reduced(b, base):
    """★ 2026-09-26（晚）改前→改後：改前驗「拓撲版在減少動態時只畫靜態」；拓撲版已沒有入口，
    改驗：系統「減少動態效果」＋舊設定 tw.sankey.mode＝'topo' → 仍是經典光纖、只畫靜態、動態鈕停用、
    代表股照樣滑過才顯示（沒有淡入淡出，直接到位）。"""
    ctx = b.new_context(viewport={"width": 1440, "height": 950}, reduced_motion="reduce")
    pg = ctx.new_page()
    pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    pg.goto(f"{base}#flow", wait_until="networkidle")
    pg.evaluate("() => { try { localStorage.setItem('tw.sankey.mode', 'topo'); localStorage.removeItem('tw.flowtopo.motion'); } catch (e) {} }")
    pg.reload(wait_until="networkidle")
    wait_until(pg, "() => window.App && window.App.sankeyTopoOn && window.App.sankeyTopoOn()", 8000)
    pg.wait_for_timeout(1200)
    t = pg.evaluate(TOPO)
    ok("[減少動態] 舊設定 topo 被忽略、畫經典光纖", bool(t) and t["layout"] == "classic", t and t.get("layout"))
    ok("[減少動態] 動畫不跑、沒有粒子", bool(t) and t["reduce"] and not t["running"] and not t["motion"],
       t and {k: t[k] for k in ("reduce", "running", "motion")})
    ok("[減少動態] 動態鈕停用並講明原因", pg.evaluate("() => { const b = document.getElementById('sankeyMotionBtn');"
                                           " return !!b && b.disabled && b.textContent.includes('減少動態'); }"))
    ha = canvas_hash(pg, "#sankey"); pg.wait_for_timeout(900)
    ok("[減少動態] 畫面完全靜止", ha == canvas_hash(pg, "#sankey"))
    if t:
        ok("[減少動態] 代表股預設收起", not [n for n in _fx_lv(t, 3) if n["vis"] > 0.01], [n["name"] for n in _fx_lv(t, 3) if n["vis"] > 0.01][:3])
        g = [n for n in _fx_lv(t, 2) if not n["stale"] and _fx_kids(t, n["key"])][0]
        nd = _topo_node(pg, g["key"])
        if nd:
            pg.mouse.move(nd["cx"], nd["cy"]); pg.wait_for_timeout(250)
            t2 = pg.evaluate(TOPO)
            ok("[減少動態] 滑到族群：那一族的代表股直接顯示（沒有淡入）",
               all(n["vis"] == 1 for n in _fx_kids(t2, g["key"])) and not [n for n in _fx_lv(t2, 3) if n["parent"] != g["key"] and n["vis"] > 0],
               [(n["name"], n["vis"]) for n in _fx_lv(t2, 3) if n["vis"] > 0][:5])
    pg.evaluate("() => { try { localStorage.removeItem('tw.sankey.mode'); } catch (e) {} }")
    ctx.close()


# ===================================================================== 資金去向・經典光纖（flowtopo.js layout:'classic'，桌機預設）
# ★ 2026-09-25 Andy 附兩張圖：圖一經典版（ECharts 樹：台股 → 產業鏈 → 族群 → 代表股三檔，文字標籤、%、▲▼），
#   圖二拓撲版（粗細明顯、發光光纖、粒子很密），原話「維持經典版風格，但傳輸特效需要跟拓撲版一樣」。
#   這一段驗的就是這句話的兩半，每一條都讀畫布探針（畫出去的座標與參數）或真的用滑鼠操作：
#     版面半（照經典版）：四層都在、代表股三檔帶 %、四欄等距、標籤在節點右邊、父節點置中、標籤不疊
#     特效半（照拓撲版）：線寬最粗 ≥ 最細 ×6、粒子速度最大 ≥ 最小 ×4、密度 ×6、明暗、換日依排名補間、動態開關
#   另外驗三種模式都切得過去、看不見時停動畫、首次畫圖時間與回放幀率（寫進 notes）。
# ★ 2026-09-26 Andy：「資金去向維持經典版的樹狀結構，不要像圖三那樣；樹狀改成如圖四那樣結構；幫我參考圖五」
#   Andy 的完整規格：連線「禁止使用生硬直線，必須採用平滑水平切線的三次貝茲」，CP1＝(x0＋dx×0.55, y0)、CP2＝(x0＋dx×0.45, y1)。
#   改前→改後（_fx_bezier／_fx_hits 兩支）：
#     · 線：S 形貝茲 CP 0.45／0.55（從產業鏈直條上依目標 y 扇形排開）→ 規格貝茲 CP 0.55／0.45，一律從父節點圓心那一列出發
#     · 產業鏈節點：直條 → 圓點
#     · 特效：加上碰撞激發（hitFlash）、擴散震波（同時 ≤ 60 圈）、標籤變亮；動態關／減少動態時全部不出現
# ★★ 2026-09-26（第二版）Andy：「參考圖顏色更鮮豔」＋第一版「濁、混亂」四點，附黃金標準 docs/prototypes/flow_perfect_topology.html。
#   改前→改後（_fx_bezier／_fx_crisp／_fx_hits 與版面那幾條）：
#     · 控制點 0.55／0.45 → 0.45／x1−0.45（對稱張力）
#     · 線：外暈 w×3.2、內芯 w×0.9／.32 → 外暈 w×2.4／≤ .09、內芯固定 1.1px／.65（毛細 0.7px／.2、外暈 .04）
#     · 節點：產業鏈 6～12、族群 4～15 → 全部 4.5～7.5；標籤描邊字 → 17px 高圓角膠囊
#     · 版面：四欄等分、葉子等距 16px → 欄位 26%／54%／83%、族群等距槽位 36～42、代表股固定在 83% 那一欄、間距 13
#     · 拿掉「標籤變亮」的第四張畫布；深色畫布底 #050a14
FX_FIRST_DRAW_MAX = 400     # ms：首次畫圖（buildModel→layout→量字→曲線→畫底圖與標籤）。容器實測 80～230ms，拓撲版同條件 77～190ms


def _fx_lv(t, k):
    return [n for n in (t or {}).get("nodes", []) if n["lv"] == k]


def _fx_bezier(t, tag):
    """★ 2026-09-26 Andy 規格：連線禁止生硬直線，一律「平滑水平切線的三次貝茲」，
    產業鏈不要直條（圖三紅框）。
    改前→改後：
      · 控制點：CP1＝x0＋dx×0.45、CP2＝x1−dx×0.45（＝x0＋dx×0.55）→ CP1 0.55、CP2 0.45（第一版）
        → 第二版（黃金標準）CP1＝x0＋dx×0.45、CP2＝x1−dx×0.45（對稱張力）
      · 起點：在產業鏈直條上依目標 y 排開（扇形散出）→ 一律從父節點圓心那一列（y0＝父節點 y）
      · 產業鏈節點：直立細條（hh＝出發線寬加總）→ 圓點
    量的是探針回報的每條線的貝茲 cp＝[x0,y0, c1x,c1y, c2x,c2y, x1,y1]（粒子沿同一條的查表走，offCurve 另外量）。"""
    nodes = {n["key"]: n for n in (t or {}).get("nodes", [])}
    lk = [x for x in (t or {}).get("links", []) if x.get("cp")]
    if not ok(f"{tag} 每條線都讀得到貝茲控制點", bool(lk) and len(lk) == len(t["links"]),
              {"有": len(lk), "全部": len(t["links"])}):
        return
    bad_cp, bad_end = [], []
    for x in lk:
        x0, y0, c1x, c1y, c2x, c2y, x1, y1 = x["cp"]
        dx = x1 - x0
        if dx <= 0 or abs(c1x - (x0 + dx * 0.45)) > 0.05 or abs(c2x - (x1 - dx * 0.45)) > 0.05 \
                or abs(c1y - y0) > 0.05 or abs(c2y - y1) > 0.05:
            bad_cp.append((x["key"], x["cp"]))
        a, b = nodes.get(x["from"]), nodes.get(x["to"])
        if not a or not b or abs(y0 - a["y"]) > 1 or abs(y1 - b["y"]) > 1 \
                or not (a["x"] <= x0 <= a["x"] + a["r"] + 1) or not (b["x"] - b["r"] - 1 <= x1 <= b["x"]):
            bad_end.append((x["key"], x["cp"][:2], x["cp"][6:], a and [a["x"], a["y"], a["r"]], b and [b["x"], b["y"], b["r"]]))
    ok(f"{tag} 四層連線都是黃金標準貝茲：CP1＝(x0＋dx×0.45, y0)、CP2＝(x1−dx×0.45, y1)（對稱張力；第一版 0.55／0.45）",
       not bad_cp, bad_cp[:3])
    ok(f"{tag} 連線從父節點圓心那一列出發、接進子節點（改前在產業鏈直條上依目標 y 排開、扇形散出）",
       not bad_end, bad_end[:3])
    ok(f"{tag} 四層都有連線（根→產業鏈、產業鏈→族群、族群→代表股）", sorted({x["lv"] for x in lk}) == [0, 1, 2],
       sorted({x["lv"] for x in lk}))
    L1 = _fx_lv(t, 1)
    ok(f"{tag} 產業鏈節點是圓、不是直條（改前：直立細條 hh＝出發線寬加總，Andy 圖三紅框）",
       bool(L1) and all(n["shape"] == "circle" and n["hh"] == 0 and 4.5 <= n["r"] <= 7.5 for n in L1),
       [(n["name"], n["shape"], n["hh"], n["r"]) for n in L1][:5])
    ok(f"{tag} 四層節點全部是圓點", all(n["shape"] == "circle" for n in t["nodes"]),
       [n["key"] for n in t["nodes"] if n["shape"] != "circle"][:3])


def _fx_crisp(t, tag, dark=True):
    """★★ 2026-09-26（第二版）Andy「濁、混亂」四點＋黃金標準的數字，全部讀探針回報的「實際畫出去的值」：
      ① 去霧：內芯固定 1.1px、alpha 0.65（毛細 0.7px／0.2）；外暈寬＝weight×2.4、alpha ≤ 0.09（毛細 ≤ 0.04）
      ② 節點 4.5～7.5 的圓點；根／產業鏈／族群的標籤是高 17px 的膠囊，代表股不是膠囊
      ③ 族群等距垂直槽位 36～42px（同一條鏈內相鄰族群的 y 差都一樣）
      ④ 代表股全部對齊在寬度 83% 那一欄；三檔在族群的 y 上下對稱排開
      ⑤ 深色主題畫布底 #050a14（淺色照舊），畫布三張（第一版為標籤變亮加的第四張拿掉）"""
    lk = [x for x in (t or {}).get("links", []) if not x["dead"]]
    trunk = [x for x in lk if x["lv"] < 2]
    cap = [x for x in lk if x["lv"] == 2]
    ok(f"{tag} ① 內芯固定 1.1px、alpha 0.65（主幹與族群段；改前 w×0.9、0.32）",
       bool(trunk) and all(x["inW"] == 1.1 and x["inA"] == 0.65 for x in trunk),
       [(x["key"], x["inW"], x["inA"]) for x in trunk if not (x["inW"] == 1.1 and x["inA"] == 0.65)][:3])
    ok(f"{tag} ① 毛細線（族群 → 代表股）0.7px、alpha 0.2",
       bool(cap) and all(x["inW"] == 0.7 and x["inA"] == 0.2 for x in cap),
       [(x["key"], x["inW"], x["inA"]) for x in cap if not (x["inW"] == 0.7 and x["inA"] == 0.2)][:3])
    ok(f"{tag} ① 外暈寬＝weight×2.4（改前 ×3.2）、alpha ≤ 0.09（毛細 ≤ 0.04）",
       bool(lk) and all(abs(x["outW"] - x["w"] * 2.4) < 0.02 and 0 < x["outA"] <= (0.04 if x["lv"] == 2 else 0.09) + 1e-9 for x in lk),
       [(x["key"], x["w"], x["outW"], x["outA"]) for x in lk
        if not (abs(x["outW"] - x["w"] * 2.4) < 0.02 and 0 < x["outA"] <= (0.04 if x["lv"] == 2 else 0.09) + 1e-9)][:3])
    # 參考稿每幀蓋 rgba(5,10,20,.38) 再重畫 → 看起來的透明度是穩態 a／(1−(1−a)(1−.38))；底圖直接畫這個值
    eq = lambda a: a / (1 - (1 - a) * (1 - 0.38))
    ok(f"{tag} ① 實際畫出的透明度＝參考稿殘影穩態（內芯 .65→{eq(.65):.3f}、毛細 .2→{eq(.2):.3f}、外暈同公式）",
       bool(lk) and all(abs(x["inAEff"] - eq(x["inA"])) < 2e-3 and abs(x["outAEff"] - eq(x["outA"])) < 2e-3 for x in lk),
       [(x["key"], x["inA"], x["inAEff"], x["outA"], x["outAEff"]) for x in lk
        if not (abs(x["inAEff"] - eq(x["inA"])) < 2e-3 and abs(x["outAEff"] - eq(x["outA"])) < 2e-3)][:3])
    L0, L1, L2, L3 = (_fx_lv(t, i) for i in range(4))
    big = L0 + L1 + L2
    ok(f"{tag} ② 根／產業鏈／族群節點半徑 4.5～7.5（改前產業鏈 6～12、族群 4～15、根 13）",
       bool(big) and all(4.5 <= n["r"] <= 7.5 for n in big), [(n["name"], n["r"]) for n in big if not 4.5 <= n["r"] <= 7.5][:4])
    ok(f"{tag} ② 產業鏈與族群的標籤是高 17px 的膠囊（改前是描邊字）",
       all(n["lab"] and n["lab"]["badge"] and n["lab"]["h"] == 17 for n in L1 + L2),
       [(n["name"], n["lab"]) for n in L1 + L2 if not (n["lab"] and n["lab"]["badge"] and n["lab"]["h"] == 17)][:3])
    ok(f"{tag} ② 代表股不是膠囊（小點＋「名稱 佔比%」）", bool(L3) and all(n["lab"] and not n["lab"]["badge"] for n in L3))
    bad_eq, diffs = [], set()
    for c in L1:
        ys = sorted(g["y"] for g in L2 if g["parent"] == c["key"])
        d = [ys[i + 1] - ys[i] for i in range(len(ys) - 1)]
        diffs.update(d)
        if d and max(d) - min(d) > 1.01:
            bad_eq.append((c["name"], d))
    sl = t.get("slot") or 0
    ok(f"{tag} ③ 族群等距垂直槽位：同一條鏈內相鄰族群的 y 差都一樣、槽高 36～42（改前依葉子數排）",
       not bad_eq and 36 <= sl <= 42 and all(abs(x - sl) <= 1.01 for x in diffs), {"slot": sl, "差": sorted(diffs), "不等距": bad_eq[:2]})
    lx = sorted({n["x"] for n in L3})
    # 2026-09-26（晚）改前→改後：固定在 83% → max(83%, 族群膠囊最右緣 ＋ 16)（代表股收起後族群欄往右移，滑過顯示時不能蓋到族群膠囊）
    # ★ 2026-09-28 設計 v4 第二批 2A 改前→改後：max(83%, 族群膠囊最右緣 ＋ 16) → 從右邊往回排：代表股的字右緣離畫布 8px
    #   （01 §4.4「標籤欄寬度＝實際最長標籤、葉節點標籤右側只留 8px」；改前 1440 寬右邊 108px 連滑過都用不到）。
    #   窄到族群欄退到 54% 時照舊接在族群膠囊後面，那時不驗右緣。
    gr = max((n["lab"]["x"] + n["lab"]["w"] for n in L2 if n["lab"]), default=0)
    lr = max((n["lab"]["x"] + n["lab"]["w"] for n in L3 if n["lab"]), default=0)
    gx = min((n["x"] for n in L2), default=0)
    clamped = gx <= t["W"] * 0.54 + 1.5
    ok(f"{tag} ④ 代表股全部對齊同一欄、在所有族群膠囊右緣 16px 之後（滑過顯示時不蓋到族群膠囊）",
       bool(lx) and max(lx) - min(lx) <= 1 and lx[0] >= gr + 15,
       {"x": lx[:4], "族群膠囊最右": round(gr, 1)})
    ok(f"{tag} ④ 右側不留空帶：代表股的字右緣離畫布右緣 ≤ 16px（規格 8px＋最長標籤量測誤差；族群欄退到 54% 時不驗）",
       clamped or 0 <= t["W"] - lr <= 16, {"W": t["W"], "代表股字最右": round(lr, 1), "族群欄": round(gx, 1)})
    ok(f"{tag} ④ 代表股的字不出畫布右緣", all(n["lab"]["x"] + n["lab"]["w"] <= t["W"] + 0.5 for n in L3),
       [n["name"] for n in L3 if n["lab"]["x"] + n["lab"]["w"] > t["W"] + 0.5][:3])
    per = {}
    for n in L3:
        per.setdefault(n["parent"], []).append(n)
    gy = {g["key"]: g["y"] for g in L2}
    bad_c = [k for k, v in per.items() if len(v) >= 2 and abs((min(n["y"] for n in v) + max(n["y"] for n in v)) / 2 - gy.get(k, -99)) > 1.5]
    ok(f"{tag} ④ 代表股以族群的 y 為中心上下排開", not bad_c, bad_c[:3])
    ok(f"{tag} ⑤ 畫布底：深色 #050a14、淺色照舊；畫布三張（改前四張）",
       t.get("canvases") == 3 and (("5, 10, 20" in t.get("stageBg", "") or "#050a14" in t.get("stageBg", "")) if dark else t.get("stageBg", "") == ""),
       {k: t.get(k) for k in ("canvases", "stageBg")})


def _fx_hits(pg, t0, tag):
    """★ 2026-09-26 Andy 圖五＋原型：碰撞激發、擴散震波、震波上限。讀探針的 hitFlash（每個節點 hf）、
    目前的震波圈數、累計起了幾圈（rpMade）與同時最多幾圈（rpPeak）。"""
    scroll_to(pg, "sankey"); pg.wait_for_timeout(400)            # 畫布要在畫面裡動畫才會跑（捲出就停）
    t1 = wait_until(pg, """() => { const t = window.App.sankeyTopo();
        return t && t.running && t.hits > 0 && t.rpMade > 0 && t.nodes.some(n => n.hf > 0) ? t : null; }""", 6000)
    if not ok(f"{tag} 粒子到站會激發終點節點（hitFlash > 0）、也會起震波", bool(t1),
              (pg.evaluate(TOPO) or {}).get("hits")):
        return
    hot = [n for n in t1["nodes"] if n["hf"] > 0]
    ok(f"{tag} 激發中的節點 hitFlash 落在 0～1（疊加有上限）", all(0 < n["hf"] <= 1 for n in hot),
       [(n["name"], n["hf"]) for n in hot][:5])
    ok(f"{tag} 根節點沒有進來的線、不會被激發", all(n["hf"] == 0 for n in t1["nodes"] if n["lv"] == 0))
    ok(f"{tag} 震波同時圈數 ≤ 上限 {t1['rpMax']}", t1["ripples"] <= t1["rpMax"] and t1["rpPeak"] <= t1["rpMax"] and t1["rpMax"] <= 60,
       {k: t1[k] for k in ("ripples", "rpPeak", "rpMax", "rpMade", "hits")})
    # 一口氣灌 800 次到站（略過每節點冷卻）：上限那道閘要擋得住
    bu = pg.evaluate("() => window.FlowTopo.burst(document.getElementById('sankey'), 800)")
    ok(f"{tag} 一口氣 800 次到站：震波仍 ≤ {t1['rpMax']} 圈（上限真的有擋）", bool(bu) and 0 < bu["ripples"] <= t1["rpMax"]
       and bu["peak"] <= t1["rpMax"], bu)
    pg.wait_for_timeout(1500)
    t2 = pg.evaluate(TOPO)
    ok(f"{tag} 震波會自己收掉（1.5 秒後圈數回落到上限的一半以下）", bool(t2) and t2["ripples"] < t1["rpMax"] / 2,
       t2 and t2["ripples"])
    rise, fall = pg.evaluate("() => { const s = getComputedStyle(document.documentElement);"
                             " return [s.getPropertyValue('--rise').trim(), s.getPropertyValue('--fall').trim()]; }")
    dots = {n["dot"] for n in t0["nodes"]}
    ok(f"{tag} 節點色是產業鏈色、不是漲跌紅綠（原型每條線不同色，站上規矩：紅綠只給 ▲▼）",
       rise not in dots and fall not in dots and len(dots) >= 3, sorted(dots))
    # 2026-09-26 第二版 改前→改後：「標籤變亮用的第四張畫布在」→ 拿掉（黃金標準的膠囊字固定色），改驗「沒有 ftglow」
    ok(f"{tag} 第一版的標籤變亮畫布（ftglow）已拿掉", not pg.evaluate("() => !!document.querySelector('#sankey canvas.ftglow')"))
    ok(f"{tag} 代表股（毛細終點）不起漣漪、節點仍會被激發", all(n["hf"] >= 0 for n in t1["nodes"]) and t1["rpMade"] > 0)


def _fx_seg(pg):
    """2026-09-26（晚）：分段鈕已拿掉 —— 這支現在應該永遠回空清單（驗收拿它來證明「沒有」）。"""
    return pg.evaluate("""() => [...document.querySelectorAll('#sankeyStyleSeg [data-sk-style]')]
        .map(b => [b.dataset.skStyle, b.textContent, b.getAttribute('aria-pressed')])""")


def _fx_kids(t, gk):
    return [n for n in (t or {}).get("nodes", []) if n["lv"] == 3 and n["parent"] == gk]


def _fx_leafhover(pg, tag):
    """★ 2026-09-26（晚）Andy：「族群後的個股先隱藏，只有游標移動過去會顯示」。每一步都真的用滑鼠：
      預設 0 個代表股看得見、毛細線沒有粒子 → 滑到族群圓點只出現那一族（其他族 0）→ 移開消失 →
      滑到族群膠囊、滑到那一格槽位最右邊的空白也會出現 → 顯示時不蓋到其他標籤 → 先滑過再點代表股進個股頁。"""
    scroll_to(pg, "sankey"); pg.mouse.move(3, 3); pg.wait_for_timeout(800)
    t = pg.evaluate(TOPO)
    L3 = _fx_lv(t, 3)
    ok(f"{tag} 預設代表股 0 個看得見（模型裡有 {len(L3)} 檔，全部收起）", bool(L3) and not [n for n in L3 if n["vis"] > 0.01],
       [n["name"] for n in L3 if n["vis"] > 0.01][:4])
    ok(f"{tag} 預設毛細線上沒有粒子（收起就不跑）", sum(x["n"] for x in t["links"] if x["lv"] == 2) == 0,
       sum(x["n"] for x in t["links"] if x["lv"] == 2))
    live = [n for n in _fx_lv(t, 2) if not n["stale"] and not n["nodata"] and len(_fx_kids(t, n["key"])) >= 2]
    if not ok(f"{tag} 找得到有代表股的族群", len(live) >= 2, len(live)):
        return
    g, g2 = live[2 % len(live)], live[-1]
    nd = _topo_node(pg, g["key"])
    pg.mouse.move(nd["cx"] - 30, nd["cy"] - 40); pg.wait_for_timeout(150)
    pg.mouse.move(nd["cx"], nd["cy"])
    wait_until(pg, ("() => { const t = window.App.sankeyTopo(); return t && t.leafHot && t.nodes.filter(n => n.lv === 3 && n.parent === t.leafHot).every(n => n.vis > 0.95) ? 1 : 0; }"), 3000)
    t1 = pg.evaluate(TOPO)
    mine = _fx_kids(t1, g["key"])
    other = [n for n in _fx_lv(t1, 3) if n["parent"] != g["key"] and n["vis"] > 0.01]
    ok(f"{tag} 滑到「{g['name']}」圓點：只出現那一族的 {len(mine)} 檔（淡入完成）、其他族 0 檔",
       bool(mine) and all(n["vis"] > 0.95 for n in mine) and not other and t1["leafHot"] == g["key"],
       {"那一族": [(n["name"], n["vis"]) for n in mine], "其他": [n["name"] for n in other][:3]})
    ok(f"{tag} 滑過時那一族的毛細線有粒子在跑", bool(wait_until(pg, """(k) => { const t = window.App.sankeyTopo();
        return t.links.some(x => x.lv === 2 && x.key.startsWith(k + '>') && x.n > 0) ? 1 : 0; }""".replace("(k)", "()").replace("k + '>'", repr(g["key"] + ">")), 3000)))
    vis_labs = [n for n in t1["nodes"] if n["lab"] and (n["lv"] < 3 or n["vis"] > 0.5) and not n["dim"]]
    hit = 0
    for i in range(len(vis_labs)):
        for j in range(i + 1, len(vis_labs)):
            a, bb = vis_labs[i]["lab"], vis_labs[j]["lab"]
            if a["x"] < bb["x"] + bb["w"] - 1 and bb["x"] < a["x"] + a["w"] - 1 and a["y"] < bb["y"] + bb["h"] - 1 and bb["y"] < a["y"] + a["h"] - 1:
                hit += 1
    ok(f"{tag} 顯示出來的代表股不蓋到任何其他標籤", hit == 0, hit)
    pg.mouse.move(5, 5); wait_until(pg, "() => { const t = window.App.sankeyTopo(); return t && !t.nodes.some(n => n.lv === 3 && n.vis > 0.01) ? 1 : 0; }", 3000)
    t2 = pg.evaluate(TOPO)
    ok(f"{tag} 移開：代表股淡出、又是 0 個看得見", not [n for n in _fx_lv(t2, 3) if n["vis"] > 0.01] and t2["leafHot"] is None,
       [(n["name"], n["vis"]) for n in _fx_lv(t2, 3) if n["vis"] > 0.01][:3])
    # 滑到族群膠囊（標籤）也算
    n2 = _topo_node(pg, g2["key"])
    lab = [n for n in pg.evaluate(TOPO)["nodes"] if n["key"] == g2["key"]][0]["lab"]
    bx = pg.evaluate("() => { const r = document.querySelector('#sankey canvas.ftlab').getBoundingClientRect(); return [r.left, r.top]; }")
    pg.mouse.move(bx[0] + lab["x"] + lab["w"] * 0.6, bx[1] + lab["y"] + lab["h"] / 2); wait_until(pg, "() => { const t = window.App.sankeyTopo(); return t && t.leafHot && t.nodes.filter(n => n.lv === 3 && n.parent === t.leafHot).every(n => n.vis > 0.95) ? 1 : 0; }", 3000)
    t3 = pg.evaluate(TOPO)
    ok(f"{tag} 滑到「{g2['name']}」的膠囊：出現那一族的代表股", all(n["vis"] > 0.95 for n in _fx_kids(t3, g2["key"])) and t3["leafHot"] == g2["key"],
       [(n["name"], n["vis"]) for n in _fx_kids(t3, g2["key"])])
    # 那一格槽位最右邊的空白（代表股字的右邊）也算
    pg.mouse.move(5, 5); wait_until(pg, "() => { const t = window.App.sankeyTopo(); return t && !t.nodes.some(n => n.lv === 3 && n.vis > 0.01) ? 1 : 0; }", 3000)
    pg.mouse.move(bx[0] + t3["W"] - 6, n2["cy"] + 4); wait_until(pg, "() => { const t = window.App.sankeyTopo(); return t && t.leafHot && t.nodes.filter(n => n.lv === 3 && n.parent === t.leafHot).every(n => n.vis > 0.95) ? 1 : 0; }", 3000)
    t4 = pg.evaluate(TOPO)
    ok(f"{tag} 滑到那一格槽位最右邊的空白：也出現那一族的代表股", t4["leafHot"] == g2["key"] and all(n["vis"] > 0.95 for n in _fx_kids(t4, g2["key"])),
       t4["leafHot"])
    # 先滑過再點代表股 → 進個股頁
    lf = [n for n in _fx_kids(t4, g2["key"]) if not n["rest"]][0]
    code = lf["key"].split(":")[-1]
    pg.mouse.move(lf["cx"] - 60, lf["cy"], steps=3); pg.mouse.move(lf["cx"], lf["cy"], steps=3); pg.wait_for_timeout(300)
    pg.mouse.click(lf["cx"], lf["cy"]); pg.wait_for_timeout(1200)
    ok(f"{tag} 先滑到族群、再點代表股：進到那一檔的個股頁", pg.evaluate("() => location.hash") == f"#stock/{code}", pg.evaluate("() => location.hash"))
    pg.go_back(wait_until="networkidle"); pg.wait_for_timeout(1500)
    wait_until(pg, "() => window.App.sankeyTopoOn()", 5000)


def t_flowfx(pg, b, base):
    pg.set_viewport_size({"width": 1440, "height": 950})
    pg.goto(f"{base}#overview", wait_until="networkidle")
    # 新使用者：沒有任何版面設定 → 應該落在經典光纖；舊 key 存著 classic 的人也一樣
    # （2026-09-26 晚起 tw.sankey.mode 也不讀了：不管存什麼都是經典光纖）
    pg.evaluate("() => { try { localStorage.removeItem('tw.sankey.mode'); localStorage.setItem('tw.sankey.style', 'classic');"
                " localStorage.removeItem('tw.sankey.day'); localStorage.removeItem('tw.flowtopo.motion');"
                " localStorage.setItem('tw.theme', 'dark'); localStorage.setItem('tw.side', '0'); } catch (e) {} }")
    pg.reload(wait_until="networkidle")
    pg.goto(f"{base}#flow", wait_until="networkidle")
    wait_until(pg, "() => window.App && window.App.sankeyTopoOn && window.App.sankeyTopoOn()", 8000)
    scroll_to(pg, "sankey"); pg.wait_for_timeout(1500)
    t0 = pg.evaluate(TOPO)
    if not ok("[1440] 沒設定過（舊 key 存 classic 也一樣）→ 預設是「經典光纖」：flowtopo 經典版面，不是 ECharts、不是拓撲版",
              bool(t0) and t0.get("layout") == "classic" and pg.evaluate(
                  "() => !echarts.getInstanceByDom(document.getElementById('sankey'))"), t0 and t0.get("layout")):
        return
    # 2026-09-26（晚）改前→改後：改前「版面分段鈕三顆（經典光纖／拓撲／經典），亮的是經典光纖」→ 改後「沒有分段鈕」
    ok("沒有版面分段鈕（Andy：只留下經典光纖）", _fx_seg(pg) == [] and pg.evaluate("() => !document.getElementById('sankeyStyleSeg')"), _fx_seg(pg))
    ok("首次畫圖時間有量到、在上限內", t0.get("firstDrawMs") is not None and t0["firstDrawMs"] < FX_FIRST_DRAW_MAX,
       {k: t0.get(k) for k in ("firstDrawMs", "warmMs")})
    notes.append(f"經典光纖首次畫圖 {t0.get('firstDrawMs')} ms、預熱 {t0.get('warmMs')} ms、粒子 {t0['particles']} 顆、連線 {len(t0['links'])} 條")
    # ---- 版面半：照經典版
    L0, L1, L2, L3 = (_fx_lv(t0, i) for i in range(4))
    ok("四層節點都在（台股 1、產業鏈 ≥3、族群 ≥10、代表股 ≥ 族群數×2）",
       len(L0) == 1 and len(L1) >= 3 and len(L2) >= 10 and len(L3) >= len(L2) * 2, [len(L0), len(L1), len(L2), len(L3)])
    per = {}
    for n in L3:
        per.setdefault(n["parent"], []).append(n)
    live_g = [g for g in L2 if not g["stale"] and not g["nodata"] and (g["value"] or 0) > 0]
    # 2026-09-26（晚）改前→改後：「每個有量的族群底下都常駐代表股」→ 代表股仍在模型裡（每族三檔），但預設收起（滑過才顯示，見 _fx_leafhover）
    ok("每個有量的族群底下都有代表股（模型裡；畫面上預設收起）", all(per.get(g["key"]) for g in live_g),
       [g["name"] for g in live_g if not per.get(g["key"])][:4])
    ok("代表股預設收起（0 個看得見）", not [n for n in L3 if n["vis"] > 0.01], [n["name"] for n in L3 if n["vis"] > 0.01][:4])
    ok("代表股預設最多三檔（和經典版一樣）", bool(per) and max(len(v) for v in per.values()) <= 3,
       {k: len(v) for k, v in list(per.items())[:4]})
    lf_live = [n for n in L3 if not n["stale"] and not n["rest"]]
    ok("代表股標籤有百分比（% 佔族群）", bool(lf_live) and all(re.search(r"\d+(\.\d)?%", n["text"]) for n in lf_live),
       [n["text"] for n in lf_live if "%" not in n["text"]][:4])
    labs12 = [n for n in L1 + L2 if not n["stale"] and not n["nodata"]]
    ok("產業鏈與族群標籤有 % 佔上一層", all("%" in n["text"] for n in labs12), [n["text"] for n in labs12 if "%" not in n["text"]][:3])
    rise, fall = pg.evaluate("() => { const s = getComputedStyle(document.documentElement);"
                             " return [s.getPropertyValue('--rise').trim(), s.getPropertyValue('--fall').trim()]; }")
    ups = [n for n in t0["nodes"] if n["chg"] == "up"]
    dns = [n for n in t0["nodes"] if n["chg"] == "dn"]
    ok("漲跌三角照經典版（▲ 用 --rise、▼ 用 --fall，紅漲綠跌）", len(ups) + len(dns) > 3
       and all(n["chgColor"] == rise for n in ups) and all(n["chgColor"] == fall for n in dns),
       [(n["text"], n["chgColor"]) for n in (ups + dns)][:3])
    xs = [sorted({n["x"] for n in lvl}) for lvl in (L0, L1, L2, L3)]
    one_col = all(len(v) >= 1 and max(v) - min(v) <= 1 for v in xs)
    cx = [v[0] for v in xs]
    gaps = [cx[i + 1] - cx[i] for i in range(3)]
    # 2026-09-26 第二版 改前→改後：四欄等分 → 黃金標準的 26%／54%／83%（根貼左）
    W0 = t0["W"]
    # 2026-09-26（晚）改前→改後：固定 26%／54%／83% → 代表股收起後右欄讓給版面：族群 54%～66%、產業鏈在根與族群的 44% 處、
    #   代表股 ≥ 83%（細節在 _fx_crisp ④）
    # ★ 2026-09-28 設計 v4 第二批 2A 改前→改後：族群 54%～66%、代表股 ≥ 83% → 從右邊往回排（代表股的字右緣離畫布 8px、
    #   族群膠囊右緣＋16＝代表股），族群欄只剩下限 54%；代表股欄在族群欄右邊（細節在 _fx_crisp ④）
    ok("四層各自一欄：根貼左、族群 ≥ 54%、產業鏈在根與族群之間 44% 處、代表股在族群右邊",
       one_col and cx[0] < 40 and W0 * 0.54 - 1.5 <= cx[2] < cx[3]
       and abs(cx[1] - (cx[0] + (cx[2] - cx[0]) * 0.44)) <= 1.5,
       {"x": xs, "欄距": gaps, "W": W0})
    ok("標籤都在節點右邊（經典版 label.position = right）",
       all(n["lab"] and n["lab"]["x"] > n["x"] for n in t0["nodes"]),
       [n["key"] for n in t0["nodes"] if n["lab"] and n["lab"]["x"] <= n["x"]][:3])
    bad_mid = []
    for c in L1:
        ks = [g for g in L2 if g["parent"] == c["key"]]
        if ks and abs(c["y"] - (min(g["y"] for g in ks) + max(g["y"] for g in ks)) / 2) > 1.5:
            bad_mid.append(c["name"])
    ok("產業鏈節點在它第一個與最後一個族群的正中間（經典版 tree 的父節點置中）", not bad_mid, bad_mid)
    lf_step = sorted({round(per[k][i + 1]["y"] - per[k][i]["y"]) for k in per for i in range(len(per[k]) - 1)})
    # 2026-09-26 第二版：間距 16 → 13（黃金標準 9px 配 10px 字；這裡字是 12px 下限，所以 13）
    ok("同一族群的代表股等距排開（間距 ≥ 12px）",
       bool(lf_step) and min(lf_step) >= 12 and max(lf_step) - min(lf_step) <= 1, lf_step)
    ok("標籤沒有互相重疊", _topo_overlap(t0) == 0, _topo_overlap(t0))
    ok("發光 shadowBlur ≤ 6px、畫布字 ≥ 12px", 0 < t0["maxBlur"] <= 6 and (t0["minFont"] or 0) >= 12, [t0["maxBlur"], t0["minFont"]])
    # ---- ★ 2026-09-26 連線改規格貝茲（CP 0.55／0.45）、產業鏈改圓點（圖三不要直條）
    _fx_bezier(t0, "[經典光纖 1440 深色]")
    _fx_crisp(t0, "[經典光纖 1440 深色]")
    # ---- 特效半：照拓撲版
    lk = [x for x in t0["links"] if not x["dead"]]
    ws, vs = [x["w"] for x in lk], [x["v"] for x in lk if x["v"] > 0]
    # 2026-09-26 第二版 改前→改後：1～13px、×6 → 黃金標準 0.8～3.8、×4.5（見 _topo_contrast 的 fx 分支）
    ok("線 weight 最粗 ≥ 最細 ×4.5（依金額平方根，0.8～3.8）", max(ws) >= min(ws) * 4.5 and 0.79 <= min(ws) and max(ws) <= 3.81,
       {"min": min(ws), "max": max(ws)})
    ok("粒子速度最大 ≥ 最小 ×4", bool(vs) and max(vs) >= min(vs) * 4, vs and {"min": min(vs), "max": max(vs)})
    _topo_contrast(t0, "[經典光纖 1440 深色]", fx=True)
    # 2026-09-26（晚）改前→改後：「粒子也走在代表股那一段（> 20 顆）」→ 代表股收起時毛細線不跑粒子（滑過才跑，見 _fx_leafhover）
    ok("代表股收起時，毛細線上沒有粒子（省效能）", sum(x["n"] for x in t0["links"] if x["lv"] == 2) == 0,
       sum(x["n"] for x in t0["links"] if x["lv"] == 2))
    # 根節點照經典版貼著左緣（x≈14、半徑 13），它左邊已經沒有「一條」可以量像素 —— 只用探針量（粒子 x < 根節點 x）
    # 2026-09-26 改前→改後：曲線控制點 0.45／0.55 → 0.55／0.45（探針的 offCurve 量的是同一張查表，斷言不變）
    ok("粒子全部在自己的曲線上、根節點左邊沒有散點", t0["offCurve"] == 0 and t0["leftStray"] == 0,
       {k: t0[k] for k in ("particles", "offCurve", "leftStray", "rootX")})
    # ---- ★ 2026-09-26 碰撞激發＋擴散震波（Andy 圖五＋原型）
    _fx_hits(pg, t0, "[經典光纖 1440 深色]")
    # ---- 換日：拉Bar／－＋／依排名換位的補間
    bar = "#sankeyDays input[type=range]"
    if ok("有「看哪一天」拉Bar", count(pg, bar) == 1):
        sub0 = text(pg, "#sankeySub")
        l3a = [n["text"] for n in _fx_lv(t0, 3)]
        set_range(pg, bar, 0, 1200)
        pg.wait_for_timeout(600)
        t2 = pg.evaluate(TOPO)
        changed("拉到最舊那天：副標日期換了", sub0, text(pg, "#sankeySub"))
        changed("拉到最舊那天：代表股標籤（名單或 %）跟著換", l3a, [n["text"] for n in _fx_lv(t2, 3)])
        ok("拉到最舊那天：仍是經典光纖、四層都在", bool(t2) and t2["layout"] == "classic"
           and len(_fx_lv(t2, 3)) >= len(_fx_lv(t2, 2)) * 2)
        _topo_rank_ok(t2, "經典光纖・拉到最舊那天")
        tb = pg.evaluate(TOPO)
        pg.evaluate("() => [...document.querySelectorAll('#sankeyDays .pb.step')].find(b => b.textContent === '＋').click()")
        pg.wait_for_timeout(900)
        changed("按「＋」：族群數值真的變", [n["text"] for n in _fx_lv(tb, 2)], [n["text"] for n in _fx_lv(pg.evaluate(TOPO), 2)])
        tb = pg.evaluate(TOPO)
        pg.evaluate("() => [...document.querySelectorAll('#sankeyDays .pb.step')].find(b => b.textContent === '−').click()")
        pg.wait_for_timeout(900)
        changed("按「−」：族群數值真的變", [n["text"] for n in _fx_lv(tb, 2)], [n["text"] for n in _fx_lv(pg.evaluate(TOPO), 2)])
        _topo_swap_tween(pg, bar)
        # ▶ 回放：量幀率（回放中每 650ms 換一天、每一幀都在補間＋重畫底圖與標籤，是這張圖最重的狀態）
        set_range(pg, bar, 0, 900)
        scroll_to(pg, "sankey")
        sa = text(pg, "#sankeySub")
        pg.evaluate("() => window.FlowTopo.resetMeter(document.getElementById('sankey'))")
        pg.eval_on_selector("#sankeyDays .pb.play", "b => b.click()")
        pg.wait_for_timeout(2600)
        page_fps = pg.evaluate("""() => new Promise(res => { let n = 0; const t0 = performance.now();
            const f = () => { n++; if (performance.now() - t0 < 1500) requestAnimationFrame(f);
              else res(n / ((performance.now() - t0) / 1000)); }; requestAnimationFrame(f); })""")
        tp2 = pg.evaluate(TOPO)
        changed("按 ▶ 回放：副標日期一天一天走", sa, text(pg, "#sankeySub"))
        ok("回放中仍是經典光纖、動畫迴圈在跑", bool(tp2) and tp2["layout"] == "classic" and tp2["running"], tp2 and tp2.get("running"))
        notes.append(f"經典光纖回放幀率（1440、headless 軟體繪圖）：{tp2['fps']} FPS（同時段整頁 rAF {page_fps:.1f}）、"
                     f"每幀運算 {tp2['avgCostMs']} ms（含補間中重排標籤與重畫底圖）、單次換日重畫 {tp2.get('lastDrawMs')} ms")
        ok("回放中每幀運算 < 12ms（預算 16.7ms）", 0 < tp2["avgCostMs"] < 12, {k: tp2[k] for k in ("fps", "avgCostMs", "frames")})
        ok("回放中迴圈沒有掉幀（≥ 同時段整頁 rAF 的 60%）", tp2["fps"] >= page_fps * 0.6, {"fx": tp2["fps"], "page": round(page_fps, 1)})
        pg.eval_on_selector("#sankeyDays .pb.play", "b => b.click()")
        pg.wait_for_timeout(800)
        set_range(pg, bar, pg.evaluate(f"() => +document.querySelector('{bar}').max"), 1000)
    # ---- 滑過提示
    scroll_to(pg, "sankey")
    t3 = pg.evaluate(TOPO)
    g1 = _topo_node(pg, [n for n in _fx_lv(t3, 2) if not n["stale"] and not n["nodata"]][0]["key"])
    pg.mouse.move(g1["cx"], g1["cy"]); pg.wait_for_timeout(500)
    tip = pg.evaluate("() => { const t = document.querySelector('#sankey .fttip.on'); return t ? t.innerText : ''; }")
    ok("滑過族群：提示框寫著成交值與佔上一層", "成交值" in tip and "佔上一層" in tip, tip[:60])
    ok("滑過族群：路徑以外壓暗（hover 聚焦）", (pg.evaluate(TOPO) or {}).get("hover") == g1["key"])
    lf1 = _topo_node(pg, [n for n in _fx_lv(t3, 3) if not n["stale"] and not n["rest"]][0]["key"])
    pg.mouse.move(lf1["cx"], lf1["cy"]); pg.wait_for_timeout(500)
    tip2 = pg.evaluate("() => { const t = document.querySelector('#sankey .fttip.on'); return t ? t.innerText : ''; }")
    ok("滑過代表股：提示框寫著成交值、提示點一下進個股頁", "成交值" in tip2 and "個股頁" in tip2, tip2[:60])
    pg.mouse.move(5, 5); pg.wait_for_timeout(300)
    # ---- ★ 2026-09-26（晚）代表股預設收起、滑過才顯示（放在換日那幾段之後：它會進個股頁再返回）
    _fx_leafhover(pg, "[經典光纖 1440 深色]")
    # ---- 點族群：展開全部成分股＋面板；點代表股進個股頁；再點收回
    det = pg.evaluate("() => window.App.D.groups_detail || {}")
    cand = [n for n in _fx_lv(t3, 2) if not n["key"].startswith("g:ind_") and not n["stale"]
            and len((det.get(n["key"][2:]) or {}).get("members") or []) >= 5]
    if ok("找得到成分股 ≥ 5 檔的族群來點", bool(cand)):
        gk = cand[0]["key"]
        n_before = len([n for n in _fx_lv(t3, 3) if n["parent"] == gk])
        ok("用滑鼠點族群節點", _topo_click(pg, gk))
        t4 = pg.evaluate(TOPO)
        mine = [n for n in _fx_lv(t4, 3) if n["parent"] == gk]
        ok("點族群：那個族群的成分股從三檔延伸成全部（經典版同一套）", len(mine) > max(3, n_before), f"{n_before} → {len(mine)}")
        # 2026-09-26（晚）改前→改後：「別的族群的代表股仍常駐」→ 別族的代表股仍在（收起），點開的這一族全部成分股常駐顯示
        ok("點族群：族群名前面標 ▾、別的族群的代表股仍在（收起）", any(n["key"] == gk and n["text"].startswith("▾") for n in t4["nodes"])
           and len([n for n in _fx_lv(t4, 3) if n["parent"] != gk]) >= 10)
        pg.mouse.move(5, 5)
        wait_until(pg, "(k) => { const t = window.App.sankeyTopo(); return t && !t.nodes.some(n => n.lv === 3 && n.parent !== k && n.vis > 0.01) ? 1 : 0; }".replace("(k) =>", "() =>").replace("n.parent !== k", "n.parent !== " + repr(gk)), 3000)
        t4b = pg.evaluate(TOPO)
        ok("點開的族群：它的全部成分股常駐顯示（游標移開也不收）", all(n["vis"] > 0.95 for n in _fx_lv(t4b, 3) if n["parent"] == gk)
           and not [n for n in _fx_lv(t4b, 3) if n["parent"] != gk and n["vis"] > 0.01],
           [(n["name"], n["vis"]) for n in _fx_lv(t4b, 3) if n["parent"] == gk][:4])
        ok("點族群：右邊成分股面板打開", pg.evaluate(
            "() => { const b = document.getElementById('sankeyPanel'); return !!b && !b.hidden && b.querySelectorAll('.ms a').length > 0; }"))
        ok("點族群：其餘族群被壓暗", sum(1 for n in _fx_lv(t4, 2) if n["dim"]) >= 5)
        ok("展開後標籤仍不重疊", _topo_overlap(t4) == 0, _topo_overlap(t4))
        lf = [n for n in mine if not n["rest"]][0]
        code = lf["key"].split(":")[-1]
        ok("用滑鼠點代表股節點", _topo_click(pg, lf["key"]))
        ok("點代表股：真的進到那一檔的個股頁", pg.evaluate("() => location.hash") == f"#stock/{code}", pg.evaluate("() => location.hash"))
        pg.go_back(wait_until="networkidle"); pg.wait_for_timeout(1800)
        wait_until(pg, "() => window.App.sankeyTopoOn()", 5000)
        scroll_to(pg, "sankey"); pg.wait_for_timeout(600)
        if len([n for n in _fx_lv(pg.evaluate(TOPO), 3) if n["parent"] == gk]) <= 3:
            _topo_click(pg, gk)
        ok("再點一次同一個族群", _topo_click(pg, gk))
        t5 = pg.evaluate(TOPO)
        ok("再點一次：收回成三檔、面板關掉", len([n for n in _fx_lv(t5, 3) if n["parent"] == gk]) <= 3 and pg.evaluate(
            "() => { const b = document.getElementById('sankeyPanel'); return !b || b.hidden; }"))
    # ---- 點產業鏈 → 壓暗別條；點背景 → 回預設
    t6 = pg.evaluate(TOPO)
    ok("用滑鼠點產業鏈節點", _topo_click(pg, _fx_lv(t6, 1)[0]["key"]))
    t7 = pg.evaluate(TOPO)
    ok("點產業鏈：別條鏈被壓暗、面板打開", sum(1 for n in _fx_lv(t7, 1) if n["dim"]) == len(_fx_lv(t7, 1)) - 1 and pg.evaluate(
        "() => { const b = document.getElementById('sankeyPanel'); return !!b && !b.hidden; }"))
    box = pg.evaluate("() => { const r = document.querySelector('#sankey canvas.ftlab').getBoundingClientRect(); return [r.left, r.bottom]; }")
    pg.mouse.click(box[0] + 6, box[1] - 6); pg.wait_for_timeout(900)
    t8 = pg.evaluate(TOPO)
    ok("點背景：回到預設（沒有節點被壓暗、面板關掉）", not any(n["dim"] for n in t8["nodes"]) and pg.evaluate(
        "() => { const b = document.getElementById('sankeyPanel'); return !b || b.hidden; }"))
    # ---- 即時
    if ok("「即時」鈕在拉Bar 那一列", count(pg, "#sankeyDays #sankeyLiveBtn") == 1):
        pg.eval_on_selector("#sankeyLiveBtn", "b => b.click()")
        wait_until(pg, "() => { const s = window.App.sankeyLive(); return s.on && !s.busy; }", 15000)
        tl = pg.evaluate(TOPO)
        ok("按「即時」：進入即時模式、經典光纖照樣畫得出來", pg.evaluate("() => window.App.sankeyLive().on")
           and bool(tl) and tl["layout"] == "classic")
        pg.eval_on_selector("#sankeyLiveBtn", "b => b.click()"); pg.wait_for_timeout(800)
        ok("再按一次：退出即時", not pg.evaluate("() => window.App.sankeyLive().on"))
    # ---- 動態開關：關掉就完全靜止、記住；開回來
    scroll_to(pg, "sankey"); pg.wait_for_timeout(500)
    ok("動態預設開、迴圈在跑", bool(wait_until(pg, "() => { const t = window.App.sankeyTopo(); return t && t.running ? 1 : 0; }", 5000)))
    pg.eval_on_selector("#sankeyMotionBtn", "b => b.click()"); pg.wait_for_timeout(700)
    tm = pg.evaluate(TOPO)
    ok("按「動態」：動畫停、設定寫進 localStorage", not tm["motion"] and not tm["running"]
       and pg.evaluate("() => localStorage.getItem('tw.flowtopo.motion')") == "0")
    ha = canvas_hash(pg, "#sankey"); pg.wait_for_timeout(900)
    ok("動態關掉之後畫面完全靜止（不閃、不動）", ha == canvas_hash(pg, "#sankey"))
    ok("動態關掉：沒有震波、沒有節點在激發（靜止狀態不閃）", tm["ripples"] == 0 and all(n["hf"] == 0 for n in tm["nodes"]),
       {"震波": tm["ripples"], "激發中": [n["name"] for n in tm["nodes"] if n["hf"]][:3]})
    _topo_contrast(tm, "[經典光纖・動態關]", motion=False, fx=True)
    pg.eval_on_selector("#sankeyMotionBtn", "b => b.click()")
    ok("再按一次：動畫又跑起來", bool(wait_until(pg, "() => { const t = window.App.sankeyTopo(); return t && t.running ? 1 : 0; }", 5000)))
    # ---- 看不見就停：捲出畫面
    # 捲回頁首（instant）：資金去向卡在首屏下方 1000px 以外；往下捲過卡片不一定捲得動（頁尾不夠長）
    pg.evaluate("() => window.scrollTo({top: 0, behavior: 'instant'})")
    ok("捲回頁首時資金去向的畫布真的在視窗外（前提；卡片標題可能剛好露出一行）", pg.evaluate(
        "() => document.querySelector('#sankey .ftstage').getBoundingClientRect().top > innerHeight"))
    stopped = wait_until(pg, "() => { const t = window.App.sankeyTopo(); return t && !t.running ? 1 : 0; }", 4000)
    ok("捲出畫面：動畫迴圈停掉（IntersectionObserver）", bool(stopped), (pg.evaluate(TOPO) or {}).get("running"))
    scroll_to(pg, "sankey")
    ok("捲回來：動畫迴圈接上", bool(wait_until(pg, "() => { const t = window.App.sankeyTopo(); return t && t.running ? 1 : 0; }", 5000)))
    # ---- 2026-09-26（晚）改前→改後：改前在這裡把三種版面（拓撲／經典／經典光纖）逐一點過；改後沒有切換鈕，
    #      改驗「舊設定寫著別的版面也照樣是經典光纖」（拓撲、經典都切不到；細節在「資金去向拓撲」段）
    pg.evaluate("() => { try { localStorage.setItem('tw.sankey.mode', 'classic'); } catch (e) {} }")
    # ---- 重新整理：設定記住
    pg.reload(wait_until="networkidle"); pg.goto(f"{base}#flow", wait_until="networkidle")
    wait_until(pg, "() => window.App.sankeyTopoOn()", 6000); scroll_to(pg, "sankey"); pg.wait_for_timeout(1000)
    ok("重新整理之後仍是經典光纖（舊設定 tw.sankey.mode＝classic 被忽略）", (pg.evaluate(TOPO) or {}).get("layout") == "classic")
    pg.evaluate("() => { try { localStorage.removeItem('tw.sankey.mode'); } catch (e) {} }")
    # ---- 窄一點的桌機（1024）＋手機邊界
    pg.set_viewport_size({"width": 1024, "height": 950}); pg.wait_for_timeout(1600)
    tw = pg.evaluate(TOPO)
    ok("[1024px] 經典光纖：四層都在、標籤不重疊、沒有橫向捲軸", bool(tw) and tw["layout"] == "classic" and len(_fx_lv(tw, 3)) >= 20
       and _topo_overlap(tw) == 0 and pg.evaluate("() => document.documentElement.scrollWidth <= innerWidth + 1"),
       tw and {"overlap": _topo_overlap(tw), "leaves": len(_fx_lv(tw, 3))})
    if tw:
        _fx_bezier(tw, "[1024px]")
        _fx_crisp(tw, "[1024px]")
    # 2026-09-26（晚）改前→改後：「[1024px] 分段鈕沒有被擠出拉Bar 那一列」→ 沒有分段鈕；改驗 1024 的代表股滑過也正常
    if tw:
        _fx_leafhover(pg, "[1024px]")
    pg.set_viewport_size({"width": 800, "height": 950}); pg.wait_for_timeout(1600)
    # 2026-09-26（晚）改前→改後：「分段鈕藏起來」→ 分段鈕根本不存在；手機寬仍是 ECharts 樹（窄畫面的替代畫法，不是可選版本）
    ok("[800px] 手機寬維持經典版（ECharts 樹），沒有分段鈕", not pg.evaluate("() => window.App.sankeyTopoOn()") and pg.evaluate(
        "() => !document.getElementById('sankeyStyleSeg') && !!(window.echarts && echarts.getInstanceByDom(document.getElementById('sankey')))"))
    pg.set_viewport_size({"width": 1440, "height": 950}); pg.wait_for_timeout(1600)
    # ---- 淺色主題
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'light'); } catch (e) {} }")
    pg.reload(wait_until="networkidle"); pg.goto(f"{base}#flow", wait_until="networkidle")
    wait_until(pg, "() => window.App.sankeyTopoOn()", 6000); scroll_to(pg, "sankey"); pg.wait_for_timeout(1200)
    tl = pg.evaluate(TOPO)
    ok("[淺色] 經典光纖畫得出來、是淺色配色、發光 ≤ 6", bool(tl) and tl["layout"] == "classic" and tl["dark"] is False
       and tl["maxBlur"] <= 6, tl and (tl["layout"], tl["dark"]))
    if tl:
        _topo_contrast(tl, "[經典光纖 1440 淺色]", fx=True)
        ok("[淺色] 標籤不重疊", _topo_overlap(tl) == 0, _topo_overlap(tl))
        _fx_bezier(tl, "[淺色]")
        _fx_crisp(tl, "[淺色]", dark=False)
        _fx_hits(pg, tl, "[淺色]")
    pg.evaluate("() => { try { localStorage.setItem('tw.theme', 'dark'); localStorage.removeItem('tw.sankey.style'); } catch (e) {} }")
    # ---- 減少動態效果：經典光纖一樣只畫靜態、換日不補間
    ctx = b.new_context(viewport={"width": 1440, "height": 950}, reduced_motion="reduce")
    p2 = ctx.new_page()
    p2.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    p2.goto(f"{base}#flow", wait_until="networkidle")
    p2.evaluate("() => { try { localStorage.removeItem('tw.sankey.mode'); localStorage.removeItem('tw.flowtopo.motion'); } catch (e) {} }")
    p2.reload(wait_until="networkidle")
    wait_until(p2, "() => window.App && window.App.sankeyTopoOn && window.App.sankeyTopoOn()", 8000)
    p2.wait_for_timeout(1200)
    tr = p2.evaluate(TOPO)
    ok("[減少動態] 經典光纖照樣畫得出來、動畫不跑、動態鈕停用", bool(tr) and tr["layout"] == "classic" and tr["reduce"]
       and not tr["running"] and p2.evaluate("() => document.getElementById('sankeyMotionBtn').disabled"),
       tr and {k: tr[k] for k in ("layout", "reduce", "running")})
    if tr:
        ok("[減少動態] 沒有震波、沒有節點在激發、標籤變亮那層是空的", tr["ripples"] == 0 and all(n["hf"] == 0 for n in tr["nodes"])
           and tr["hits"] == 0, {k: tr[k] for k in ("ripples", "hits")})
        _fx_bezier(tr, "[減少動態]")
    if count(p2, bar) == 1:
        p2.evaluate(f"() => {{ const i = document.querySelector('{bar}'); i.value = 0;"
                    " i.dispatchEvent(new Event('input', {bubbles: true})); i.dispatchEvent(new Event('change', {bubbles: true})); }")
        tr2 = p2.evaluate(TOPO)
        ok("[減少動態] 換日直接到位（沒有補間）", bool(tr2) and not tr2["tweening"])
    ctx.close()


# ===================================================================== 2026-09-26：關聯圖說明卡點背景收回
REL_ST = """() => { const rm = document.getElementById('relMain'), sb = document.getElementById('segBox');
  const lst = [...document.querySelectorAll('#relList .rlseg.on')].filter(x => x.getClientRects().length > 0);
  return { hassel: !!rm && rm.classList.contains('hassel'), on: lst.map(x => x.dataset.seg),
    co: !!document.getElementById('coBox'), coTxt: ((document.getElementById('coBox') || {}).innerText || '').slice(0, 40),
    dim: document.querySelectorAll('.chainmap .co.dim').length, sel: document.querySelectorAll('.chainmap .segtitle.sel').length,
    segBox: sb ? sb.innerText.trim().length : 0, dd: ((document.querySelector('#segDDBtn b') || {}).textContent || '') }; }"""
# 圖上的「空白背景」：SVG 本身（不是節點、標籤、邊線）。從可視範圍裡掃一個 elementFromPoint 正好是 <svg> 的點。
REL_BLANK = """() => { const svg = document.querySelector('#chainMap svg'); if (!svg) return null;
  const r = svg.getBoundingClientRect(), top = Math.max(r.top, 90) + 8, bot = Math.min(r.bottom, innerHeight) - 8;
  for (let y = top; y < bot; y += 11)
    for (let x = Math.max(r.left, 0) + 8; x < Math.min(r.right, innerWidth) - 8; x += 13) {
      const e = document.elementFromPoint(x, y); if (e === svg) return { x, y }; }
  return null; }"""


def _rel_blank_click(pg):
    """捲到關聯圖、找一塊空白、用真滑鼠點下去。找不到空白就回 None（呼叫端自己處理）。"""
    pg.evaluate("() => { const m = document.getElementById('chainMap'); if (m) m.scrollIntoView({ block: 'center', behavior: 'instant' }); }")
    pg.wait_for_timeout(300)
    pt = pg.evaluate(REL_BLANK)
    if pt:
        pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(600)
    return pt


def t_rel_dismiss(pg, base):
    """Andy 2026-09-26：「點擊背景後說明欄會消失」。
    #industry/semiconductor 的供應鏈分層圖，點環節標題或個股標籤之後右側（窄畫面在圖上方）會出現說明卡。
    要驗的是「畫面真的變了」：卡片不見（.hassel 拿掉、.rlseg.on 0、#coBox 不在、#segBox 空）、
    圖上的選取高亮（.co.dim、.segtitle.sel）全部歸零、下拉鈕回到「全部」。
    反過來也要驗：點到節點、標籤、卡片本身**不會**被當成點背景而收掉。"""
    pg.goto(f"{base}#overview", wait_until="domcontentloaded")
    keep = pg.evaluate("() => { try { return ['tw.relOpen','tw.relView','tw.side'].map(k => localStorage.getItem(k)); } catch (e) { return [null,null,null]; } }")
    for width in (1440, 800):
        T = f"[{width}]"
        wide = width > 820
        pg.set_viewport_size({"width": width, "height": 950})
        pg.goto(f"{base}#overview", wait_until="domcontentloaded")
        pg.evaluate("() => { try { localStorage.setItem('tw.relOpen','1'); localStorage.setItem('tw.relView','layer'); localStorage.setItem('tw.side','0'); } catch (e) {} }")
        pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor", wait_until="networkidle")
        pg.evaluate("() => { const r = document.getElementById('relSec'); if (r) r.scrollIntoView({ block: 'start', behavior: 'instant' }); }")
        if not wait_until(pg, "() => document.querySelectorAll('#chainMap .segtitle').length > 3", 10000):
            ok(f"{T} 關聯圖畫得出來", False, "10 秒內沒有環節標題"); continue
        s0 = pg.evaluate(REL_ST)
        ok(f"{T} 一進來沒有任何選取（卡片不在、沒有淡化）", not s0["hassel"] and not s0["co"] and s0["dim"] == 0 and s0["segBox"] == 0, s0)
        # ① 點環節標題 → 卡片出現、圖上有高亮
        click(pg, "#chainMap .segtitle[data-seg='foundry']", 700)
        s1 = pg.evaluate(REL_ST)
        ok(f"{T} 點「晶圓代工」標題：說明卡出現、其餘公司淡化",
           s1["dim"] > 0 and s1["sel"] == 1 and (s1["on"] == ["foundry"] if wide else s1["segBox"] > 0), s1)
        # ② 點卡片本身（桌機：右欄那一節的標題；窄畫面：環節詳情的標題）→ 不收
        click(pg, "#relList .rlseg.on .rlsh b" if wide else "#segBox .segbox .t", 500)
        s2 = pg.evaluate(REL_ST)
        ok(f"{T} 點說明卡本身不會收掉",
           s2["dim"] == s1["dim"] and (s2["on"] == ["foundry"] if wide else s2["segBox"] > 0), s2)
        # ③ 點另一個環節標題＝換一格，不是點背景
        click(pg, "#chainMap .segtitle[data-seg='ic_design']", 700)
        s3 = pg.evaluate(REL_ST)
        ok(f"{T} 點另一個環節標題＝換成那一格（不是收掉）",
           s3["dim"] > 0 and s3["sel"] == 1 and (s3["on"] == ["ic_design"] if wide else s3["segBox"] > 0), s3)
        # ④ 點圖的空白背景 → 卡片消失、高亮全部取消
        pt = _rel_blank_click(pg)
        if ok(f"{T} 關聯圖上找得到空白背景可以點", bool(pt), pt):
            s4 = pg.evaluate(REL_ST)
            ok(f"{T} 點圖的空白背景：說明卡消失、高亮取消、下拉回到「全部」",
               not s4["hassel"] and not s4["on"] and s4["dim"] == 0 and s4["sel"] == 0 and s4["segBox"] == 0 and s4["dd"] == "全部", s4)
        # ⑤ 點個股標籤（2330）→ 公司資訊欄＋環節卡；再點另一家（2303）→ 換卡不收
        click(pg, "#chainMap .co[data-code='2330']", 900)
        s5 = pg.evaluate(REL_ST)
        ok(f"{T} 點台積電 2330：公司資訊欄出現、晶圓代工被選起來", s5["co"] and "2330" in s5["coTxt"] and s5["dim"] > 0, s5)
        click(pg, "#chainMap .co[data-code='2303']", 900)
        s6 = pg.evaluate(REL_ST)
        ok(f"{T} 點另一家聯電 2303＝換成它的資訊欄（不是收掉）", s6["co"] and "2303" in s6["coTxt"] and s6["dim"] > 0, s6)
        # ⑥ Esc → 全部收
        pg.keyboard.press("Escape"); pg.wait_for_timeout(600)
        s7 = pg.evaluate(REL_ST)
        ok(f"{T} 按 Esc：公司資訊欄與說明卡一起收、高亮取消",
           not s7["co"] and not s7["hassel"] and s7["dim"] == 0 and s7["sel"] == 0 and s7["segBox"] == 0, s7)
        # ⑦ 開公司資訊欄 → 點背景 → 全部收
        click(pg, "#chainMap .co[data-code='2330']", 900)
        pt = _rel_blank_click(pg)
        if not pt:
            # 窄畫面資訊欄會把圖往下推，可視範圍裡可能剛好沒有空白 —— 改點頁面最底下的空白處（同樣是「背景」）
            pg.mouse.click(width - 6, 940); pg.wait_for_timeout(600)
        s8 = pg.evaluate(REL_ST)
        ok(f"{T} 開著公司資訊欄時點背景：資訊欄與說明卡一起收、高亮取消",
           not s8["co"] and not s8["hassel"] and s8["dim"] == 0 and s8["segBox"] == 0, {**s8, "blank": pt})
        # ⑧ 從「環節 ▾」下拉選一格（桌機才有下拉）→ 卡片出現，不會被「點下拉」當成點外面收掉
        if wide:
            click(pg, "#segDDBtn", 400)
            click(pg, "#segChips .segchip[data-seg='foundry']", 700)
            s9 = pg.evaluate(REL_ST)
            ok(f"{T} 從下拉選「晶圓代工」：說明卡出現而且留著", s9["on"] == ["foundry"] and s9["dim"] > 0, s9)
            # 一層一層收：下拉開著時按 Esc 只收下拉，說明卡留著
            click(pg, "#segDDBtn", 400)
            pg.keyboard.press("Escape"); pg.wait_for_timeout(400)
            s9b = pg.evaluate(REL_ST)
            dd_open = pg.evaluate("() => document.getElementById('segDD').classList.contains('open')")
            ok(f"{T} 下拉開著時按 Esc：只收下拉，說明卡與高亮留著", not dd_open and s9b["on"] == ["foundry"] and s9b["dim"] > 0, {**s9b, "ddOpen": dd_open})
            pt = _rel_blank_click(pg)
            s10 = pg.evaluate(REL_ST)
            ok(f"{T} 下拉選的那一格，點背景一樣收", bool(pt) and not s10["on"] and s10["dim"] == 0, {**s10, "blank": pt})
    pg.evaluate("(v) => { try { ['tw.relOpen','tw.relView','tw.side'].forEach((k, i) => v[i] == null ? localStorage.removeItem(k) : localStorage.setItem(k, v[i])); } catch (e) {} }", keep)
    pg.set_viewport_size({"width": 1440, "height": 950})


# ===================================================================== 2026-09-26 晚：關聯圖切換鈕＋浮動說明卡
# Andy 原話：①「收合 展開合併」；②「幫我設計當點選族群（環節）時，不會動到關聯圖版面，
#   例如我點最右邊的族群，資訊會顯示在左側，同理顯示右側」。
# 改前：「全部收合」「全部展開」兩顆鈕並排；點環節 → 格線切成「圖｜右欄」兩欄，圖的容器縮窄、整張重排。
# 改後：一顆切換鈕（文字＝按下去會發生的事）；說明卡浮在圖上（position:absolute），圖的寬度與每一個節點的位置不動，
#   被點的環節在右半邊 → 卡片貼左、左半邊 → 貼右，卡片不蓋被點的那一格；點背景收起。
# 每一條都是真的點，再量畫面變了什麼（或該不變的真的沒變）。
OV_GEOM = """() => { const m = document.getElementById('chainMap'); if (!m) return null; const mr = m.getBoundingClientRect();
  const rel = (e) => { const r = e.getBoundingClientRect(); return [Math.round((r.left - mr.left) * 10) / 10, Math.round((r.top - mr.top) * 10) / 10]; };
  return { w: Math.round(mr.width * 10) / 10, h: Math.round(mr.height * 10) / 10, l: mr.left, r: mr.right, t: mr.top, b: mr.bottom,
    nodes: [...m.querySelectorAll('.segtitle, .co')].map(e => (e.dataset.seg || e.dataset.id) + '@' + rel(e).join(',')),
    docW: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth, sx: scrollX }; }"""
# 說明卡現在在哪、有沒有蓋到 sel 指的那一塊（被點的環節標題＋它底下的公司）
OV_CARD = """(seg) => { const c = document.querySelector('#relMain .relcol'), m = document.getElementById('chainMap');
  if (!c || !m) return null; const cr = c.getBoundingClientRect(), mr = m.getBoundingClientRect();
  const vis = cr.width > 1 && cr.height > 1 && getComputedStyle(c).display !== 'none';
  const hit = (a, b) => a.right > b.left + 1 && a.left < b.right - 1 && a.bottom > b.top + 1 && a.top < b.bottom - 1;
  const own = seg ? [...m.querySelectorAll(`.segtitle[data-seg="${seg}"], .co[data-segment="${seg}"]`)] : [];
  const t = seg ? m.querySelector(`.segtitle[data-seg="${seg}"]`) : null, tr = t ? t.getBoundingClientRect() : null;
  return { vis, pos: getComputedStyle(c).position, side: c.dataset.side || '', seg: c.dataset.seg || '',
    card: [cr.left, cr.top, cr.right, cr.bottom].map(Math.round), map: [mr.left, mr.top, mr.right, mr.bottom].map(Math.round),
    inFrameX: cr.left >= mr.left - 1 && cr.right <= mr.right + 1, overMap: hit(cr, mr),
    cardMid: (cr.left + cr.right) / 2, segMid: tr ? (tr.left + tr.right) / 2 : null, mapMid: (mr.left + mr.right) / 2,
    covers: own.filter(e => hit(cr, e.getBoundingClientRect())).length, own: own.length,
    onSec: [...document.querySelectorAll('#relList .rlseg.on')].filter(x => x.getClientRects().length).map(x => x.dataset.seg) }; }"""
FT_STATE = """() => { const m = document.getElementById('chainMap'); const bs = m ? [...m.querySelectorAll('.foldbar button')] : [];
  let ls = null; try { ls = localStorage.getItem('tw.chainFold'); } catch (e) {}
  return { n: bs.length, txt: bs.map(b => b.textContent.trim()), fold: bs.map(b => b.dataset.fold),
    cards: m ? m.querySelectorAll('.co:not(.chip)').length : 0, chips: m ? m.querySelectorAll('.co.chip').length : 0,
    folded: m ? [...m.querySelectorAll('.segfold')].filter(f => f.dataset.folded === '1').length : 0,
    folds: m ? m.querySelectorAll('.segfold').length : 0, ls }; }"""


def _ov_moved(a, b):
    """兩次 OV_GEOM 之間，節點（相對圖框）的最大位移（px）。節點集合不一樣就回 999。"""
    pa = dict(x.split("@") for x in a["nodes"])
    pb = dict(x.split("@") for x in b["nodes"])
    if set(pa) != set(pb):
        return 999
    mx = 0.0
    for k, v in pa.items():
        x1, y1 = map(float, v.split(","))
        x2, y2 = map(float, pb[k].split(","))
        mx = max(mx, abs(x1 - x2), abs(y1 - y2))
    return mx


def t_chainmap_overlay(pg, base):
    """① 收合／展開合併成一顆切換鈕；② 點環節／公司的說明卡浮在圖上、不動關聯圖版面（1440／1100／860）。"""
    pg.goto(f"{base}#overview", wait_until="domcontentloaded")
    keep = pg.evaluate("() => { try { return ['tw.chainFold','tw.relOpen','tw.side'].map(k => localStorage.getItem(k)); } catch (e) { return [null,null,null]; } }")
    # ---------------- ① 一顆切換鈕
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.evaluate("() => { try { localStorage.removeItem('tw.chainFold'); localStorage.setItem('tw.relOpen','1'); localStorage.setItem('tw.side','0'); } catch (e) {} }")
    pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor", wait_until="networkidle")
    pg.evaluate("() => { const r = document.getElementById('relSec'); if (r) r.scrollIntoView({ block: 'start', behavior: 'instant' }); }")
    if not wait_until(pg, "() => document.querySelectorAll('#chainMap .co').length > 10", 10000):
        ok("[切換鈕] 關聯圖畫得出來", False, "10 秒內沒有公司節點"); return
    pg.wait_for_timeout(400)
    f0 = pg.evaluate(FT_STATE)
    ok("[切換鈕] 改前兩顆（全部收合＋全部展開）→ 改後只剩一顆", f0["n"] == 1, f0)
    ok("[切換鈕] 預設全部收合時，鈕上寫「全部展開」（按下去會發生的事）", f0["txt"] == ["全部展開"] and f0["chips"] > 20 and f0["cards"] == 0, f0)
    click(pg, "#chainMap .foldbar button", 800)
    f1 = pg.evaluate(FT_STATE)
    ok("[切換鈕] 按一下 → 真的全部展開（標籤全變大卡、張數不變）", f1["chips"] == 0 and f1["cards"] == f0["chips"] and f1["folded"] == 0, {"前": f0, "後": f1})
    ok("[切換鈕] 全部展開之後，同一顆鈕的字換成「全部收合」、而且還是只有一顆", f1["n"] == 1 and f1["txt"] == ["全部收合"], f1)
    ok("[切換鈕] 狀態真的寫進 localStorage（tw.chainFold 的 def=false）", bool(f1["ls"]) and '"def":false' in f1["ls"], f1["ls"])
    # 只收一個環節 → 「有任何收合」＝鈕要寫「全部展開」
    seg = pg.evaluate("() => { const f = document.querySelector('#chainMap .segfold'); return f ? f.dataset.seg : null; }")
    if ok("[切換鈕] 找得到單一環節的 ▾", bool(seg), seg):
        click(pg, f'#chainMap .segfold[data-seg="{seg}"]', 800)
        f2 = pg.evaluate(FT_STATE)
        ok(f"[切換鈕] 只收合一個環節（{seg}）→ 鈕上改寫「全部展開」", f2["folded"] == 1 and f2["txt"] == ["全部展開"], f2)
        click(pg, "#chainMap .foldbar button", 800)
        f3 = pg.evaluate(FT_STATE)
        ok("[切換鈕] 這時按下去 → 全部展開（那一格也展開了），鈕又寫回「全部收合」",
           f3["folded"] == 0 and f3["chips"] == 0 and f3["txt"] == ["全部收合"], f3)
    click(pg, "#chainMap .foldbar button", 800)
    f4 = pg.evaluate(FT_STATE)
    ok("[切換鈕] 再按一下 → 真的全部收合（全是個股標籤），鈕寫「全部展開」",
       f4["cards"] == 0 and f4["chips"] == f0["chips"] and f4["folded"] == f4["folds"] and f4["txt"] == ["全部展開"], f4)
    ok("[切換鈕] 說明文字還在（收合＝只留個股標籤；▸／▾ 單獨切換）",
       pg.evaluate("() => { const s = document.querySelector('#chainMap .foldbar .sub'); return !!s && s.textContent.includes('個股標籤') && s.textContent.includes('▸'); }"))

    # ---------------- ② 浮動說明卡
    for w in (1440, 1100, 860):
        T = f"[浮動卡 {w}]"
        pg.set_viewport_size({"width": w, "height": 1000})
        pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor", wait_until="networkidle")
        pg.evaluate("() => { const s = document.getElementById('side'); if (s) s.classList.remove('open'); }")
        pg.evaluate("() => { const r = document.getElementById('relSec'); if (r) r.scrollIntoView({ block: 'start', behavior: 'instant' }); }")
        if not wait_until(pg, "() => document.querySelectorAll('#chainMap .segtitle').length > 3", 10000):
            ok(f"{T} 關聯圖畫得出來", False); continue
        pg.wait_for_timeout(500)
        g0 = pg.evaluate(OV_GEOM)
        # 挑最右邊與最左邊、而且有台股的環節（標題中心在圖框的右半／左半）
        segs = pg.evaluate("""() => { const m = document.getElementById('chainMap'), mr = m.getBoundingClientRect(), mid = (mr.left + mr.right) / 2;
            return [...m.querySelectorAll('.segtitle')].filter(t => m.querySelector(`.co[data-segment="${t.dataset.seg}"][data-code]:not([data-code=""])`))
              .map(t => { const r = t.getBoundingClientRect(); return { seg: t.dataset.seg, c: (r.left + r.right) / 2 - mid }; }); }""")
        rs = sorted([s for s in segs if s["c"] > 0], key=lambda s: -s["c"])
        ls_ = sorted([s for s in segs if s["c"] < 0], key=lambda s: s["c"])
        if not ok(f"{T} 圖的左右兩半都找得到有台股的環節", bool(rs) and bool(ls_), segs):
            continue
        for label, s, want in (("最右邊", rs[0]["seg"], "left"), ("最左邊", ls_[0]["seg"], "right")):
            click(pg, f"#chainMap .segtitle[data-seg='{s}']", 800)
            g1 = pg.evaluate(OV_GEOM)
            c1 = pg.evaluate(OV_CARD, s)
            if not ok(f"{T} 點{label}的環節（{s}）→ 說明卡出現、列的是這一格", bool(c1) and c1["vis"] and c1["onSec"] == [s], c1):
                continue
            ok(f"{T} 點{label}的環節 → 說明卡浮在圖上（absolute、在圖框的左右範圍內）",
               c1["pos"] == "absolute" and c1["overMap"] and c1["inFrameX"], c1)
            ok(f"{T} 點{label}的環節 → 卡片貼在圖框{'左' if want == 'left' else '右'}側",
               c1["side"] == want and ((c1["cardMid"] < c1["mapMid"]) if want == "left" else (c1["cardMid"] > c1["mapMid"])), c1)
            ok(f"{T} 點{label}的環節 → 卡片沒有蓋到被點的那一格（標題＋底下 {c1['own']} 個節點，蓋到 {c1['covers']} 個）",
               c1["covers"] == 0 and c1["own"] > 1, c1)
            ok(f"{T} 點{label}的環節 → 關聯圖寬度沒變（{g0['w']} → {g1['w']}）", abs(g1["w"] - g0["w"]) <= 1, {"前": g0["w"], "後": g1["w"]})
            mv = _ov_moved(g0, g1)
            ok(f"{T} 點{label}的環節 → 每一個環節與公司節點（相對圖框）的位置都沒動（最大位移 {mv}px ≤ 1）", mv <= 1, mv)
            ok(f"{T} 點{label}的環節 → 整頁沒有橫向捲軸、scrollX＝0", g1["docW"] <= g1["cw"] and g1["sx"] == 0, g1 and {k: g1[k] for k in ("docW", "cw", "sx")})
            # 點卡片本身不收（dismissable 的例外）；點背景收
            click(pg, "#relList .rlseg.on .rlsh b", 500)
            ok(f"{T} 點說明卡本身不會收掉", pg.evaluate(OV_CARD, s)["vis"])
            pt = _rel_blank_click(pg)
            c2 = pg.evaluate(OV_CARD, s)
            if ok(f"{T} 關聯圖上找得到空白背景可以點", bool(pt), pt):
                ok(f"{T} 點背景 → 說明卡收起來、高亮取消", not c2["vis"] and not c2["onSec"]
                   and pg.evaluate("() => document.querySelectorAll('#chainMap .co.dim').length") == 0, c2)
            g2 = pg.evaluate(OV_GEOM)
            ok(f"{T} 收起來之後圖的寬度與節點位置一樣沒動", abs(g2["w"] - g0["w"]) <= 1 and _ov_moved(g0, g2) <= 1, _ov_moved(g0, g2))
            pg.evaluate("() => { const r = document.getElementById('relSec'); if (r) r.scrollIntoView({ block: 'start', behavior: 'instant' }); }")
            pg.wait_for_timeout(300)
            g0 = pg.evaluate(OV_GEOM)          # 捲動過 → 以新的位置為基準（位置是相對圖框量的，捲動本來就不影響）
        # 點右半邊的一家公司 → 公司資訊欄也浮在圖上、貼左、不蓋那張公司卡
        code = pg.evaluate(f"""() => {{ const c = document.querySelector('#chainMap .co[data-segment="{rs[0]['seg']}"][data-code]:not([data-code=""])'); return c ? c.dataset.code : null; }}""")
        if code:
            pg.evaluate("() => { const b = document.getElementById('coBox'); if (b) b.remove(); }")
            click(pg, f"#chainMap .co[data-code='{code}']", 900)
            g3 = pg.evaluate(OV_GEOM)
            c3 = pg.evaluate(OV_CARD, rs[0]["seg"])
            box = pg.evaluate("() => { const b = document.getElementById('coBox'); return b ? { inStick: !!b.closest('.relstick'), h: Math.round(b.getBoundingClientRect().height) } : null; }")
            ok(f"{T} 點右半邊的公司（{code}）→ 資訊欄出現、住在浮動卡裡", bool(box) and box["inStick"] and box["h"] > 60, box)
            ok(f"{T} 點右半邊的公司 → 浮動卡貼左、不蓋到那一格（含那張公司卡）", c3["side"] == "left" and c3["covers"] == 0 and c3["overMap"], c3)
            ok(f"{T} 點公司 → 關聯圖寬度與節點位置沒動", abs(g3["w"] - g0["w"]) <= 1 and _ov_moved(g0, g3) <= 1, {"w": [g0["w"], g3["w"]], "mv": _ov_moved(g0, g3)})
            pg.keyboard.press("Escape"); pg.wait_for_timeout(500)
            ok(f"{T} 按 Esc → 資訊欄與浮動卡一起收", not pg.evaluate(OV_CARD, None)["vis"] and not pg.evaluate("() => !!document.getElementById('coBox')"))
    pg.evaluate("(v) => { try { ['tw.chainFold','tw.relOpen','tw.side'].forEach((k, i) => v[i] == null ? localStorage.removeItem(k) : localStorage.setItem(k, v[i])); } catch (e) {} }", keep)
    pg.set_viewport_size({"width": 1440, "height": 950})


# ===================================================================== 2026-09-26 晚：全市場族群下鑽不偏移
# Andy 原話：「點擊後出現位置跑掉，請處理」—— 產業地圖「全市場」分頁點「族群漲跌幅」長條進到某族群個股之後，
#   整頁往左偏、左邊被切掉（標題只剩半截、分頁「全市場」的「全」不見）。
# 驗：四種寬度點進去、再按「← 回到族群」，scrollX 必須是 0、documentElement.scrollWidth ≤ clientWidth、
#   標題與第一個分頁的左緣都在畫面內；另外甜甜圈的圓心要在容器正中（改前：5 檔時上半截被切掉）。
GP_POS = """() => { const d = document.documentElement, t = document.getElementById('gpTitle'), tab = document.querySelector('#chainSwitch button');
  const pe = document.getElementById('gpPie'), pi = window.echarts && pe && echarts.getInstanceByDom(pe);
  let cy = null; try { const o = pi.getOption(); cy = o.series[0].center[1]; } catch (e) {}
  return { sx: scrollX, sw: d.scrollWidth, cw: d.clientWidth, bsl: document.body.scrollLeft,
    titleL: t ? Math.round(t.getBoundingClientRect().left) : null, title: t ? t.innerText : '',
    tabL: tab ? Math.round(tab.getBoundingClientRect().left) : null,
    back: !!document.querySelector('#gpBack:not([hidden])'),
    pieH: pe ? pe.clientHeight : 0, instH: pi ? pi.getHeight() : 0, cy }; }"""


def t_gp_drill_pos(pg, base):
    for w in (1440, 1100, 800, 390):
        T = f"[族群下鑽 {w}]"
        pg.set_viewport_size({"width": w, "height": 900})
        pg.goto("about:blank"); pg.goto(f"{base}#industry", wait_until="networkidle")
        if not wait_until(pg, "() => { const e = document.getElementById('gpBar'); return !!(window.echarts && e && echarts.getInstanceByDom(e)); }", 8000):
            ok(f"{T} 族群漲跌幅長條畫得出來", False); continue
        pg.evaluate("() => { const s = document.getElementById('side'); if (s) s.classList.remove('open'); }")
        pg.evaluate("document.getElementById('gpBar').scrollIntoView({block:'center', behavior:'instant'})")
        pg.wait_for_timeout(600)
        p0 = pg.evaluate(GP_POS)
        ok(f"{T} 點之前：沒有橫向捲軸、scrollX＝0", p0["sx"] == 0 and p0["sw"] <= p0["cw"], p0)
        # 真的用滑鼠點一條長條（優先 HPC 與網通 IC，Andy 回報的就是它）
        pt = pg.evaluate("""() => { const el = document.getElementById('gpBar'), c = echarts.getInstanceByDom(el), o = c.getOption(), r = el.getBoundingClientRect();
            const d = o.series[0].data; let k = d.findIndex(x => (x && x.name) === 'HPC 與網通 IC'); if (k < 0) k = 0;
            const v = typeof d[k] === 'object' ? d[k].value : d[k];
            const e = c.convertToPixel({ seriesIndex: 0 }, [v, k]), z = c.convertToPixel({ seriesIndex: 0 }, [0, k]);
            return { x: r.left + (e[0] + z[0]) / 2, y: r.top + e[1], name: d[k].name }; }""")
        pg.mouse.move(pt["x"], pt["y"]); pg.wait_for_timeout(200)
        pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(1300)
        p1 = pg.evaluate(GP_POS)
        if not ok(f"{T} 點「{pt['name']}」長條 → 真的換成這個族群的個股（標題換了、出現「← 回到族群」）",
                  p1["back"] and "這個族群的個股" in p1["title"] and pt["name"] in p1["title"], p1):
            continue
        ok(f"{T} 點進去之後 scrollX＝0、body 沒被捲走、沒有橫向捲軸（scrollWidth {p1['sw']} ≤ clientWidth {p1['cw']}）",
           p1["sx"] == 0 and p1["bsl"] == 0 and p1["sw"] <= p1["cw"], p1)
        ok(f"{T} 點進去之後標題與「全市場」分頁的左緣都在畫面內（沒有被切掉）",
           p1["titleL"] is not None and p1["titleL"] >= 0 and (p1["tabL"] is None or p1["tabL"] >= 0), p1)
        ok(f"{T} 甜甜圈的圓心在容器正中（圓心 {p1['cy']}、容器高 {p1['pieH']}；改前 5 檔時圓心偏上、上半截被切掉）",
           p1["cy"] is not None and abs(float(p1["cy"]) - p1["pieH"] / 2) <= 2 and abs(p1["instH"] - p1["pieH"]) <= 1, p1)
        click(pg, "#gpBack", 1200)
        p2 = pg.evaluate(GP_POS)
        ok(f"{T} 按「← 回到族群」→ 回到族群層級", not p2["back"] and "族群漲幅與占比" in p2["title"], p2)
        ok(f"{T} 回到族群之後 scrollX＝0、沒有橫向捲軸、標題與分頁沒被切掉",
           p2["sx"] == 0 and p2["bsl"] == 0 and p2["sw"] <= p2["cw"] and p2["titleL"] >= 0 and (p2["tabL"] is None or p2["tabL"] >= 0), p2)
        ok(f"{T} 回到族群之後甜甜圈圓心也在正中", p2["cy"] is not None and abs(float(p2["cy"]) - p2["pieH"] / 2) <= 2, p2)
    pg.set_viewport_size({"width": 1440, "height": 950})


# ===================================================================== 2026-09-26：剖析圖 2D｜3D 分段鈕
DG_MODE = """() => { const s = document.getElementById('dg3d'); if (!s) return null;
  // ⚠ 不看 .hidden 屬性：.pill 的 display 會蓋掉 [hidden]（改前「拖曳／重設視角」設了 hidden 卻照樣看得到），要量真的有沒有框
  const vis = (e) => !!e && e.getClientRects().length > 0 && getComputedStyle(e).visibility !== 'hidden';
  return { shown: vis(s), mode: s.dataset.mode || '', on: [...s.querySelectorAll('button.on')].map(b => b.textContent.trim()),
    pressed: [...s.querySelectorAll('button[aria-pressed="true"]')].map(b => b.textContent.trim()),
    svg: vis(document.getElementById('prodDiagram')), canvas: document.querySelectorAll('#prod3d canvas').length,
    host3d: vis(document.getElementById('prod3d')),
    drag: vis(document.getElementById('dgDrag')), reset: vis(document.getElementById('dgReset')),
    ls: (() => { try { return localStorage.getItem('tw.dg3d'); } catch (e) { return 'ERR'; } })(),
    tab: location.hash.split('/').pop() }; }"""


def t_dg_2d3d(pg, base):
    """Andy 2026-09-26：「切回 2D 時，顯示 2D，不要都 3D」。
    以前那顆開關不管在哪個模式都寫「3D 立體」。現在是分段鈕「2D｜3D」，亮的那一格＝現在的模式。
    真的按：（上次選 3D 進來）3D 亮 → 按亮著的 3D 不動 → 切 2D：2D 亮、平面圖在、3D 收乾淨、拖曳／重設藏起來
    → 換分頁仍是 2D → 重新整理仍是 2D → 切 3D：3D 亮、畫布掛起來 → 換分頁仍是 3D → 收尾切回 2D。
    800px 也走一次，而且分段鈕不准撐出橫向捲軸。"""
    pg.goto(f"{base}#overview", wait_until="domcontentloaded")
    keep = pg.evaluate("() => { try { return ['tw.dg3d','tw.dgOpen','tw.side'].map(k => localStorage.getItem(k)); } catch (e) { return [null,null,null]; } }")
    for width in (1440, 800):
        T = f"[{width}]"
        pg.set_viewport_size({"width": width, "height": 950})
        pg.goto(f"{base}#overview", wait_until="domcontentloaded")
        # 故意從 3D 開始：「切回 2D」這一步本身就是要驗的事
        pg.evaluate("() => { try { localStorage.setItem('tw.dg3d','1'); localStorage.setItem('tw.dgOpen','1'); localStorage.setItem('tw.side','0'); } catch (e) {} }")
        pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor/dg/silicon_wafer", wait_until="networkidle")
        if not wait_until(pg, "() => { const s = document.getElementById('dg3d'); return !!s && !s.hidden; }", 8000):
            ok(f"{T} 矽晶圓分頁有 2D｜3D 分段鈕", False, pg.evaluate(DG_MODE)); continue
        if not pg.evaluate("() => !!(window.Rack3D && window.Rack3D.supported())"):
            notes.append(f"{T} 這個環境不支援 WebGL，2D｜3D 分段鈕沒有驗"); continue
        wait_until(pg, "() => document.querySelectorAll('#prod3d canvas').length === 1", 12000)
        m0 = pg.evaluate(DG_MODE)
        ok(f"{T} 上次選 3D → 一進來 3D 那一格亮（不是 2D）",
           m0["on"] == ["3D"] and m0["pressed"] == ["3D"] and m0["mode"] == "3d" and m0["host3d"], m0)
        ok(f"{T} 3D 時「拖曳」「重設視角」在", m0["drag"] and m0["reset"], m0)
        # 按一下已經亮著的「3D」＝什麼都不做（分段鈕不是開關）
        _dg3d_toolbar_click(pg, "#dg3d button[data-dm='3d']", 600)
        m1 = pg.evaluate(DG_MODE)
        ok(f"{T} 按已經亮著的「3D」不會切走", m1["mode"] == "3d" and m1["canvas"] == 1 and m1["host3d"], m1)
        # 切 2D
        _dg3d_toolbar_click(pg, "#dg3d button[data-dm='2d']", 900)
        m2 = pg.evaluate(DG_MODE)
        ok(f"{T} 按「2D」→ 2D 那一格亮、平面圖出現、3D 畫布收乾淨",
           m2["on"] == ["2D"] and m2["pressed"] == ["2D"] and m2["svg"] and m2["canvas"] == 0 and not m2["host3d"] and m2["ls"] == "0", m2)
        ok(f"{T} 2D 時「拖曳：轉動」「重設視角」藏起來", not m2["drag"] and not m2["reset"], m2)
        # 換分頁（真的點分頁列）→ 仍是 2D
        click(pg, "#dgPick .segchip[data-dgid='hbm']", 400)
        wait_until(pg, "() => location.hash.endsWith('/hbm') && (() => { const s = document.getElementById('dg3d'); return !!s && !s.hidden; })()", 6000)
        pg.wait_for_timeout(900)
        m3 = pg.evaluate(DG_MODE)
        ok(f"{T} 換到 HBM 分頁：仍然是 2D（2D 亮、沒有 3D 畫布）", m3["tab"] == "hbm" and m3["on"] == ["2D"] and m3["svg"] and m3["canvas"] == 0, m3)
        # ★ 2026-10-03 改前→改後（#307「重新整理＝圖表設定回預設」）：
        #   改前：（2D 時）重新整理 → 仍是 2D、tw.dg3d＝'0'。
        #   改後：先切 3D 再重新整理 → 回到預設 2D、tw.dg3d 被清掉（從 3D 開始才看得出「回預設」不是「記住」）。
        _dg3d_toolbar_click(pg, "#dg3d button[data-dm='3d']", 400)
        wait_until(pg, "() => document.querySelectorAll('#prod3d canvas').length === 1", 12000)
        m3b = pg.evaluate(DG_MODE)
        ok(f"{T} 先切到 3D（前提）：3D 亮、tw.dg3d＝'1'", m3b["on"] == ["3D"] and m3b["ls"] == "1", m3b)
        real_reload(pg)
        wait_until(pg, "() => { const s = document.getElementById('dg3d'); return !!s && !s.hidden; }", 8000)
        pg.wait_for_timeout(1200)
        m4 = pg.evaluate(DG_MODE)
        # 載入時 tw.dg3d 被清掉 → 讀不到＝預設 2D；setMode(false) 會照舊寫回 '0'（那是「現在是 2D」的紀錄，不是上次的選擇）
        ok(f"{T} 切 3D 後重新整理：回到預設 2D（#307）", m4["on"] == ["2D"] and m4["svg"] and m4["canvas"] == 0 and m4["ls"] in (None, "0"), m4)
        if width <= 820:
            ov = pg.evaluate("() => document.documentElement.scrollWidth - document.documentElement.clientWidth")
            ok(f"{T} 分段鈕沒有撐出整頁橫向捲軸", ov <= 1, ov)
        # 切 3D → 3D 亮、畫布掛起來
        _dg3d_toolbar_click(pg, "#dg3d button[data-dm='3d']", 400)
        wait_until(pg, "() => document.querySelectorAll('#prod3d canvas').length === 1", 12000)
        m5 = pg.evaluate(DG_MODE)
        ok(f"{T} 按「3D」→ 3D 那一格亮、平面圖收起來、3D 畫布掛起來",
           m5["on"] == ["3D"] and m5["mode"] == "3d" and not m5["svg"] and m5["canvas"] == 1 and m5["ls"] == "1", m5)
        # 換回矽晶圓分頁 → 仍是 3D（全頁一致）
        _dg3d_toolbar_click(pg, "#dgPick .segchip[data-dgid='silicon_wafer']", 400)
        wait_until(pg, "() => location.hash.endsWith('/silicon_wafer') && document.querySelectorAll('#prod3d canvas').length === 1", 12000)
        m6 = pg.evaluate(DG_MODE)
        ok(f"{T} 換到矽晶圓分頁：仍然是 3D", m6["tab"] == "silicon_wafer" and m6["on"] == ["3D"] and m6["canvas"] == 1, m6)
        # 收尾：切回 2D，不要汙染後面的段落
        _dg3d_toolbar_click(pg, "#dg3d button[data-dm='2d']", 900)
        m7 = pg.evaluate(DG_MODE)
        ok(f"{T} 收尾切回 2D", m7["on"] == ["2D"] and m7["canvas"] == 0, m7)
    pg.evaluate("(v) => { try { ['tw.dg3d','tw.dgOpen','tw.side'].forEach((k, i) => v[i] == null ? localStorage.removeItem(k) : localStorage.setItem(k, v[i])); } catch (e) {} }", keep)
    pg.set_viewport_size({"width": 1440, "height": 950})



# ===================================================================== 2026-09-26：3D 視角鈕搬進畫面框 ＋ 點兩下重設視角
DG3DCTL_M = """() => { const c = document.getElementById('dg3dCtl'), t = document.getElementById('dgTools');
  const cv = document.querySelector('#prod3d canvas');
  const vis = (e) => !!e && e.getClientRects().length > 0 && getComputedStyle(e).visibility !== 'hidden';
  const R = (e) => { const r = e.getBoundingClientRect(); return { l: r.left, t: r.top, r: r.right, b: r.bottom, w: r.width, h: r.height }; };
  const cr = vis(c) ? R(c) : null, vr = cv ? R(cv) : null, tr = t ? R(t) : null;
  // 看得到的卡片有沒有壓到這組鈕（窄畫面卡片在畫布底下，自然不會碰到）
  const hit = cr ? [...document.querySelectorAll('#prod3d .lbl3d')].filter(e => vis(e) && !e.classList.contains('hid')).filter(e => {
    const r = e.getBoundingClientRect(); return r.width > 0 && r.left < cr.r - 1 && r.right > cr.l + 1 && r.top < cr.b - 1 && r.bottom > cr.t + 1; })
    .map(e => (e.innerText || '').trim().slice(0, 10)) : [];
  const tools = t ? [...t.children].filter(vis).map(e => (e.innerText || '').replace(/\\s+/g, '').trim()) : [];
  return { exists: !!c, shown: vis(c), drag: vis(document.getElementById('dgDrag')), reset: vis(document.getElementById('dgReset')),
    inTools: !!(t && t.querySelector('#dgDrag, #dgReset, #dg3dCtl')), inHost: !!(c && c.closest('#prod3d')),
    ctl: cr, cv: vr, tools, toolsB: tr ? tr.b : null, hit,
    title: (document.getElementById('dgReset') || {}).title || '',
    // 單一環節的圖（晶圓代工整張都是 foundry）每張卡片本來就帶 .sel（環節層級的亮），要看的是「零件層級」的選取
    sel: document.querySelectorAll('#prod3d .lbl3d.sel-part').length, haspart: !!document.querySelector('#prod3d.haspart'),
    card: (() => { const b = document.getElementById('partCard'); return !!b && !b.hidden && b.getClientRects().length > 0; })(),
    canvas: document.querySelectorAll('#prod3d canvas').length,
    mode: (document.getElementById('dg3d') || { dataset: {} }).dataset.mode || '' }; }"""


def _cam_same(c0, c1):
    """重設之後相機跟一開始比：方向（單位向量內積）＋ 距離（±5%）。比法跟 check_3d 的「重設視角」同一套。"""
    def _u(v):
        m = sum(x * x for x in v) ** 0.5 or 1.0
        return [x / m for x in v], m
    u0, m0 = _u(c0); u1, m1 = _u(c1)
    return sum(a * b for a, b in zip(u0, u1)) > 0.999 and abs(m1 - m0) / m0 < 0.05


def _cam_moved(c0, c1):
    return max(abs(a - b) for a, b in zip(c0, c1)) > 3


def _dg3d_drag(pg, cv, dx=240, dy=50):
    """在畫布中間真的按住拖一段（起點避開右上角那組鈕）。"""
    cx, cy = cv["l"] + cv["w"] * 0.45, cv["t"] + cv["h"] * 0.55
    pg.mouse.move(cx, cy); pg.mouse.down()
    pg.mouse.move(cx + dx, cy + dy, steps=14)
    pg.mouse.up(); pg.wait_for_timeout(700)


def t_dg3d_ctl(pg, base):
    """Andy 2026-09-26：「拖曳、重設視角，移動到下面，另外新增 點兩下重設視角」。
    真的操作：2D 時兩顆看不到 → 切 3D → 兩顆在 3D 畫布框內右上角（量 bbox：在畫布裡、在設定列下方、沒壓到卡片）
    → 設定列只剩「怎麼看?｜2D 3D｜動畫｜收合圖」→ 游標移到鈕上爆炸圖不會收回 → 拖曳轉動相機真的變了
    → 在零件上點兩下：相機回預設、而且沒有留下選取／零件小卡 → 在背景點兩下也回預設
    → 按「重設視角」同樣回預設 → 「拖曳」鈕照樣切得到平移 → 切 2D 兩顆不見 → 再切 3D、換圖，兩顆都回到畫面框裡
    （換圖／切換會清空 #prod3d，鈕不能被一起清掉）。
    1440 與 800 各走一次（800 卡片搬到畫布底下，鈕照樣在畫布右上）。"""
    pg.goto(f"{base}#overview", wait_until="domcontentloaded")
    keep = pg.evaluate("() => { try { return ['tw.dg3d','tw.dgOpen','tw.side','tw.dganim'].map(k => localStorage.getItem(k)); } catch (e) { return [null,null,null,null]; } }")
    for width in (1440, 800):
        T = f"[3D視角鈕 {width}]"
        pg.set_viewport_size({"width": width, "height": 950})
        pg.goto(f"{base}#overview", wait_until="domcontentloaded")
        # 動畫關：場景不自轉，「相機回到預設」才比得準；從 2D 開始，先驗「2D 時看不到」
        pg.evaluate("() => { try { localStorage.setItem('tw.dg3d','0'); localStorage.setItem('tw.dgOpen','1'); localStorage.setItem('tw.side','0'); localStorage.setItem('tw.dganim','0'); } catch (e) {} }")
        pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor/dg/foundry", wait_until="networkidle")
        if not wait_until(pg, "() => { const s = document.getElementById('dg3d'); return !!s && !s.hidden; }", 8000):
            ok(f"{T} 晶圓代工分頁有 2D｜3D 分段鈕", False, pg.evaluate(DG3DCTL_M)); continue
        if not pg.evaluate("() => !!(window.Rack3D && window.Rack3D.supported())"):
            notes.append(f"{T} 這個環境不支援 WebGL，3D 視角鈕沒有驗"); continue
        m0 = pg.evaluate(DG3DCTL_M)
        ok(f"{T} 2D 時「拖曳」「重設視角」都看不到", m0["exists"] and not m0["shown"] and not m0["drag"] and not m0["reset"], m0)
        ok(f"{T} 設定列裡已經沒有「拖曳」「重設視角」", not m0["inTools"], m0["tools"])
        # 切 3D
        _dg3d_toolbar_click(pg, "#dg3d button[data-dm='3d']", 400)
        wait_until(pg, "() => document.querySelectorAll('#prod3d canvas').length === 1 && !!(window.Rack3D && window.Rack3D.current)", 12000)
        pg.mouse.move(4, 4); pg.wait_for_timeout(1500)
        m1 = pg.evaluate(DG3DCTL_M)
        if not m1["ctl"] or not m1["cv"]:
            ok(f"{T} 切 3D 之後兩顆出現", False, m1); continue
        c, v = m1["ctl"], m1["cv"]
        ok(f"{T} 切 3D：兩顆出現、住在 3D 畫面框裡（不在設定列）",
           m1["shown"] and m1["drag"] and m1["reset"] and m1["inHost"] and not m1["inTools"], m1)
        ok(f"{T} 那組鈕整個在 3D 畫布的範圍內",
           c["l"] >= v["l"] - 0.5 and c["r"] <= v["r"] + 0.5 and c["t"] >= v["t"] - 0.5 and c["b"] <= v["b"] + 0.5, {"ctl": c, "canvas": v})
        ok(f"{T} 那組鈕在畫布的右上角（離右緣、上緣都 ≤ 24px）",
           v["r"] - c["r"] <= 24 and c["t"] - v["t"] <= 24, {"右距": round(v["r"] - c["r"], 1), "上距": round(c["t"] - v["t"], 1)})
        ok(f"{T} 那組鈕在設定列下方（不跟設定列同一排）",
           m1["toolsB"] is not None and c["t"] >= m1["toolsB"] - 0.5, {"ctlTop": c["t"], "toolsBottom": m1["toolsB"]})
        ok(f"{T} 右欄卡片沒有壓到那組鈕", not m1["hit"], m1["hit"])
        # ★ 2026-09-26 改前→改後：改前設定列第一顆是「怎麼看 ?」（4 顆）→ 改後說明搬到圖名旁的「?」，設定列剩 3 顆
        ok(f"{T} 設定列剩「2D 3D｜動畫｜收合圖」（說明是圖名旁的「?」）",
           len(m1["tools"]) == 3 and "2D" in m1["tools"][0] and "3D" in m1["tools"][0]
           and "動畫" in m1["tools"][1] and "收合" in m1["tools"][2]
           and not any("怎麼看" in x for x in m1["tools"]), m1["tools"])
        ok(f"{T} 「重設視角」的提示寫了「也可以在 3D 畫面上點兩下」", "點兩下" in m1["title"], m1["title"])
        ok(f"{T} 3D 說明寫了「點兩下回到預設視角」", "點兩下" in text(pg, "#dg3dNote"), text(pg, "#dg3dNote")[-60:])
        # 游標從畫布移到鈕上：爆炸圖不可以收回去（鈕住在 #prod3d 裡，沒有「離開」3D 畫面）
        pg.mouse.move(v["l"] + v["w"] * 0.45, v["t"] + v["h"] * 0.55); pg.wait_for_timeout(300)
        _dg3d_settle(pg, 1, 4000)
        rb = pg.evaluate("() => { const r = document.getElementById('dgReset').getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; }")
        pg.mouse.move(rb["x"], rb["y"], steps=6); pg.wait_for_timeout(900)
        ex = pg.evaluate("() => window.Rack3D.current.explode()")
        ok(f"{T} 游標移到「重設視角」上，3D 爆炸圖不會收回去", ex > 0.99, ex)
        pg.mouse.move(4, 4); _dg3d_settle(pg, 0, 4000)
        cam0 = pg.evaluate("() => window.Rack3D.current.cam()")
        # ① 拖曳轉動
        _dg3d_drag(pg, v)
        cam1 = pg.evaluate("() => window.Rack3D.current.cam()")
        ok(f"{T} 在畫布上拖曳，相機真的轉了", _cam_moved(cam0, cam1), f"{cam0} → {cam1}")
        # ② 在零件上點兩下 → 回預設，而且不留選取（第一下會選起來，要被清掉）
        seg = pg.evaluate("() => window.Rack3D.current.segs().find(s => !!window.Rack3D.current.screen(s))")
        pt = pg.evaluate("(s) => window.Rack3D.current.screen(s)", seg) if seg else None
        if pt:
            tgt = pg.evaluate("(p) => { const e = document.elementFromPoint(p.x, p.y); return e ? e.tagName : ''; }", pt)
            pg.mouse.dblclick(pt["x"], pt["y"]); pg.wait_for_timeout(900)
            cam2 = pg.evaluate("() => window.Rack3D.current.cam()")
            m2 = pg.evaluate(DG3DCTL_M)
            ok(f"{T} 在零件上點兩下：相機回到預設", _cam_same(cam0, cam2), f"{cam0} → {cam1} → {cam2}（點的是 {tgt}）")
            ok(f"{T} 在零件上點兩下：不留下選取、零件小卡收掉", m2["sel"] == 0 and not m2["haspart"] and not m2["card"],
               {"sel": m2["sel"], "haspart": m2["haspart"], "card": m2["card"], "seg": seg})
            # 反證：同一個零件**單擊**一次要真的選得起來 —— 不然上面那條「沒有選取」可能只是點不到零件的假綠。
            # 相機剛回到預設，零件在螢幕上的位置變了，座標要重新問一次。
            pt = pg.evaluate("(s) => window.Rack3D.current.screen(s)", seg) or pt
            pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(900)
            m2b = pg.evaluate(DG3DCTL_M)
            ok(f"{T} 反證：同一個零件單擊一次會選起來", m2b["sel"] > 0 and m2b["haspart"], {"sel": m2b["sel"], "haspart": m2b["haspart"], "card": m2b["card"]})
            pg.mouse.dblclick(pt["x"], pt["y"]); pg.wait_for_timeout(900)
            m2c = pg.evaluate(DG3DCTL_M)
            ok(f"{T} 已經選著零件時再點兩下：選取清掉、小卡收掉", m2c["sel"] == 0 and not m2c["card"], {"sel": m2c["sel"], "card": m2c["card"]})
        else:
            ok(f"{T} 找得到一個點得到的零件（點兩下用）", False, seg)
        # ③ 再轉一次，在背景點兩下也回預設（找一個 elementFromPoint 是 canvas 的點）
        _dg3d_drag(pg, v, -200, -40)
        cam3 = pg.evaluate("() => window.Rack3D.current.cam()")
        ok(f"{T} 第二次拖曳相機又轉了", _cam_moved(cam0, cam3), f"{cam0} → {cam3}")
        bg = pg.evaluate("""(v) => { for (let fy = 0.92; fy > 0.1; fy -= 0.06) for (let fx = 0.5; fx < 0.9; fx += 0.08) {
            const x = v.l + v.w * fx, y = v.t + v.h * fy, e = document.elementFromPoint(x, y);
            if (e && e.tagName === 'CANVAS') return { x, y }; } return null; }""", v)
        ok(f"{T} 畫布上找得到背景點（點兩下用）", bool(bg), bg)
        if bg:
            pg.mouse.dblclick(bg["x"], bg["y"]); pg.wait_for_timeout(900)
            cam4 = pg.evaluate("() => window.Rack3D.current.cam()")
            ok(f"{T} 在畫布背景點兩下：相機回到預設", _cam_same(cam0, cam4), f"{cam3} → {cam4}")
        # ④ 按「重設視角」同樣回預設
        _dg3d_drag(pg, v, 180, 70)
        cam5 = pg.evaluate("() => window.Rack3D.current.cam()")
        _dg3d_toolbar_click(pg, "#dgReset", 900)
        cam6 = pg.evaluate("() => window.Rack3D.current.cam()")
        ok(f"{T} 按「重設視角」：相機回到預設（跟點兩下同一個結果）",
           _cam_moved(cam0, cam5) and _cam_same(cam0, cam6), f"{cam5} → {cam6}")
        # ⑤ 「拖曳：轉動」鈕搬家之後照樣能切平移
        _dg3d_toolbar_click(pg, "#dgDrag", 600)
        dm = pg.evaluate("() => window.Rack3D.current.dragMode()")
        ok(f"{T} 畫面框裡的「拖曳」鈕照樣能切到平移", dm == "pan" and "平移" in text(pg, "#dgDrag"), [dm, text(pg, "#dgDrag")])
        _dg3d_toolbar_click(pg, "#dgDrag", 600)
        # ⑥ 切 2D → 兩顆不見；再切 3D → 回到畫面框裡
        _dg3d_toolbar_click(pg, "#dg3d button[data-dm='2d']", 900)
        m7 = pg.evaluate(DG3DCTL_M)
        ok(f"{T} 切 2D：兩顆不見（元素還在、只是收起來）",
           m7["exists"] and not m7["shown"] and not m7["drag"] and not m7["reset"] and m7["canvas"] == 0, m7)
        _dg3d_toolbar_click(pg, "#dg3d button[data-dm='3d']", 400)
        wait_until(pg, "() => document.querySelectorAll('#prod3d canvas').length === 1 && !!(window.Rack3D && window.Rack3D.current)", 12000)
        pg.wait_for_timeout(600)
        m8 = pg.evaluate(DG3DCTL_M)
        ok(f"{T} 再切 3D：兩顆回到 3D 畫面框裡", m8["shown"] and m8["inHost"] and m8["reset"], m8)
        # 換一張圖（清空 #prod3d 的另一條路）→ 鈕仍然在
        _dg3d_toolbar_click(pg, "#dgPick .segchip[data-dgid='hbm']", 400)
        wait_until(pg, "() => location.hash.endsWith('/hbm') && document.querySelectorAll('#prod3d canvas').length === 1", 12000)
        pg.mouse.move(4, 4); pg.wait_for_timeout(1200)
        m9 = pg.evaluate(DG3DCTL_M)
        ok(f"{T} 換到 HBM 分頁（3D）：兩顆仍在畫面框裡、沒壓到卡片",
           m9["shown"] and m9["inHost"] and m9["reset"] and not m9["hit"], m9)
        _dg3d_toolbar_click(pg, "#dg3d button[data-dm='2d']", 900)
    pg.evaluate("(v) => { try { ['tw.dg3d','tw.dgOpen','tw.side','tw.dganim'].forEach((k, i) => v[i] == null ? localStorage.removeItem(k) : localStorage.setItem(k, v[i])); } catch (e) {} }", keep)
    pg.set_viewport_size({"width": 1440, "height": 950})


# ===================================================================== 2026-09-26 Andy 三件
# ① 「將我把這內容放進來，並且排版一下」：總覽頂端的 KPI 橫條（#hero）搬進大盤三張圖的工具列（#m3Kpis，「?」右邊）。
# ② 「放大功能取消」：資金流向頁足跡輪盤的「⤢ 放大」（#rotZoomBtn）與它開的放大視窗拿掉。
# ③ 「下面填滿版面 需要調整適當大小」：頁尾（#siteFoot）改成跟主內容同寬，八格 4／2／1 欄。
# 每一件都真的操作：量位置、真的點、真的讓即時更新走一輪、真的換寬度。
KPI0926_M = """() => { const h = document.getElementById('hero'), f = document.getElementById('m3Frame');
  if (!h || !f) return null;
  const bar = f.querySelector('.m3-bar'), q = bar && bar.querySelector('.howbtn[data-how="m3"]');
  const R = (e) => e.getBoundingClientRect();
  const hr = R(h), fr = R(f), qr = q ? R(q) : null;
  const ks = [...h.querySelectorAll('.kpi')];
  const fs = ks.flatMap(k => [...k.querySelectorAll('.l, .v, .d')]).map(e => parseFloat(getComputedStyle(e).fontSize));
  return { inBar: !!h.closest('#m3Frame .m3-bar #m3Kpis'), parent: h.parentElement.id,
    n: ks.length, labels: ks.map(k => ((k.querySelector('.l') || {}).textContent || '').replace('›', '').trim()),
    kh: ks.map(k => Math.round(R(k).height)),
    over: ks.filter(k => [...k.querySelectorAll('.l, .vv')].some(x => x.scrollWidth > x.clientWidth + 1)).map(k => k.textContent.trim().slice(0, 14)),
    inside: hr.left >= fr.left - 0.5 && hr.right <= fr.right + 0.5,
    afterQ: qr ? (hr.left >= qr.right - 0.5 || hr.top >= qr.bottom - 0.5) : false,
    sameRow: qr ? Math.abs((hr.top + hr.bottom) / 2 - (qr.top + qr.bottom) / 2) < 8 : false,
    minFs: fs.length ? Math.min(...fs) : 0,
    more: ks.filter(k => k.classList.contains('clickable')).map(k => !!k.querySelector('.more')),
    drills: ks.filter(k => k.classList.contains('clickable')).map(k => k.dataset.drill),
    sideways: document.documentElement.scrollWidth > innerWidth + 1 }; }"""

FOOT0926_M = """() => { const f = document.getElementById('siteFoot'), v = document.querySelector('main .view.on');
  if (!f || !v) return null;
  const R = (e) => e.getBoundingClientRect();
  const cards = [...v.querySelectorAll('.card')].map(R).filter(r => r.width > 40 && r.left >= -0.5 && r.right <= innerWidth + 0.5);
  const fr = R(f), vr = R(v), g = f.querySelector('.sf-grid');
  return { fl: Math.round(fr.left), fr: Math.round(fr.right), fw: Math.round(fr.width),
    vl: Math.round(vr.left), vr: Math.round(vr.right),
    cl: cards.length ? Math.round(Math.min(...cards.map(r => r.left))) : null,
    cr: cards.length ? Math.round(Math.max(...cards.map(r => r.right))) : null,
    cols: g ? getComputedStyle(g).gridTemplateColumns.split(' ').filter(Boolean).length : 0,
    shown: !!g && g.getBoundingClientRect().height > 0,
    sideways: document.documentElement.scrollWidth > innerWidth + 1 }; }"""


def t_kpi_footer_0926(pg, b, base):
    """2026-09-26：KPI 搬進大盤工具列、足跡輪盤放大取消、頁尾跟主內容同寬。"""
    # ★ 2026-09-28 改前→改後（Andy：「我想要以這種方式呈現數據在K線圖上方，並且將圖二紅框處拿掉」）：
    #   改前：這裡逐條驗工具列裡的四格 KPI（加權指數／成交值／漲跌家數／前五族群佔比；高 36～44px、同一列、live.js 改加權那格）。
    #   改後：那四格換成四張摘要卡（#hero 節點與位置不變）。四格專屬的斷言（標籤、42px、加權即時格、前五族群 → #flow）
    #   已無對象；寬度、點擊、手機位置改在「總覽摘要卡列」段驗。這裡只留 09-26 那件事本身：「放進大盤卡、重掛不會被丟掉」。
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(2400)
    wait_until(pg, "() => document.querySelectorAll('#hero .osc').length === 4", 8000)
    IN_BAR = "() => { const h = document.getElementById('hero'); return { inBar: !!(h && h.closest('#m3Frame .m3-bar #m3Kpis')), n: h ? h.querySelectorAll('.osc').length : 0 }; }"
    k = pg.evaluate(IN_BAR)
    ok("★ 摘要卡列在大盤三張圖的卡片裡（#m3Frame .m3-bar #m3Kpis）、四張都在", k["inBar"] and k["n"] == 4, k)
    ok("★ 頂端沒有另一條獨立的列（#v-overview 底下不直接掛 #hero）", pg.evaluate("() => !document.querySelector('#v-overview > #hero')"))
    pg.evaluate("() => window.Market3 && window.Market3.mount()"); pg.wait_for_timeout(1400)
    k2 = pg.evaluate(IN_BAR)
    ok("★ 大盤卡重掛之後摘要卡列還在、四張都在（沒有被 innerHTML 丟掉）", k2["inBar"] and k2["n"] == 4, k2)
    pg.evaluate("() => window.scrollTo(0, 0)"); pg.wait_for_timeout(250)
    click(pg, '#m3Kpis .osc[data-k="updown"]', 1600)
    ok("重掛之後點「漲跌家數」卡照樣打開市場明細", pg.evaluate("() => location.hash").startswith("#market/updown"),
       pg.evaluate("() => location.hash"))

    # ---------------------------------------------------------------- ② 足跡輪盤的放大鈕不存在；其他卡的放大／展開還在
    pg.set_viewport_size({"width": 1440, "height": 1000})
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(1800)
    ok("其他卡的放大沒動：總覽資金熱力圖的「放大 ⤢」還在", count(pg, "#heatZoom") == 1, count(pg, "#heatZoom"))
    ok("其他卡的展開沒動：大盤三張圖的「展開 ⤢」三顆還在", count(pg, "#m3Grid .m3-big") == 3, count(pg, "#m3Grid .m3-big"))
    pg.goto(f"{base}#flow", wait_until="networkidle"); pg.wait_for_timeout(2400)
    zb = pg.evaluate("""() => ({ btn: !!document.getElementById('rotZoomBtn'),
        txt: [...document.querySelectorAll('#flowRotCard button, #flowRotCard .btn')].filter(e => /放大/.test(e.textContent || '') && e.offsetParent !== null).map(e => e.textContent.trim()),
        head: ((document.querySelector('#flowRotCard .rotchead') || {}).innerText || '').trim() })""")
    ok("★ 資金輪動卡、足跡輪盤右上方的「⤢ 放大」不存在了", not zb["btn"] and not zb["txt"], zb)
    # ★ 2026-09-26 改前→改後：標題「足跡輪盤」→「資金輪盤」
    ok("資金輪盤標題列只剩標題與日期區間", zb["head"].startswith("資金輪盤") and "放大" not in zb["head"], zb["head"])
    # 真的在輪盤欄右上角那一帶點一下：不會打開任何放大罩
    pt = pg.evaluate("""() => { const h = document.querySelector('#flowRotCard .rotchead'); if (!h) return null;
        const r = h.getBoundingClientRect(); return { x: r.right - 20, y: r.top + r.height / 2 }; }""")
    if ok("量得到足跡輪盤的標題列", bool(pt), pt):
        scroll_to(pg, "rotClockWrap"); pg.wait_for_timeout(300)
        pt = pg.evaluate("""() => { const r = document.querySelector('#flowRotCard .rotchead').getBoundingClientRect();
            return { x: r.right - 20, y: r.top + r.height / 2 }; }""")
        pg.mouse.click(pt["x"], pt["y"]); pg.wait_for_timeout(900)
        ok("在原本放大鈕的位置點一下，不會打開放大罩", pg.evaluate(
            "() => { const o = document.getElementById('zoomOv'); return !o || o.hidden; }"))

    # ---------------------------------------------------------------- ③ 頁尾左右邊界＝主內容邊界
    pg.evaluate("() => { try { localStorage.setItem('tw.footDetail', '1'); } catch (e) {} }")
    for side in ("0", None):
        pg.evaluate("(s) => { try { if (s == null) localStorage.removeItem('tw.side'); else localStorage.setItem('tw.side', s); } catch (e) {} }", side)
        widths = (1600,) if side == "0" else (1440, 1024, 800, 390)
        for w in widths:
            pg.set_viewport_size({"width": w, "height": 1000})
            for path in ("#overview", "#flow", "#industry"):
                pg.goto("about:blank")      # 只換 hash 不會重新載入頁面 → tw.side／tw.footDetail 不會重讀；先離開再進來
                pg.goto(f"{base}{path}", wait_until="networkidle"); pg.wait_for_timeout(1400)
                f = pg.evaluate(FOOT0926_M)
                tag = f"[頁尾 {w}{'／側欄收起' if side == '0' else ''} {path}]"
                if not ok(tag + " 量得到頁尾與主內容", bool(f), f):
                    continue
                ok(f"★ {tag} 頁尾左右邊界＝主內容（.view）左右邊界（差 ≤ 1px）",
                   abs(f["fl"] - f["vl"]) <= 1 and abs(f["fr"] - f["vr"]) <= 1, f)
                if f["cl"] is not None:
                    ok(f"{tag} 也對齊最外側內容卡的左右邊（差 ≤ 1px）", abs(f["fl"] - f["cl"]) <= 1 and abs(f["fr"] - f["cr"]) <= 1, f)
                want = 4 if f["fw"] > 900 else (2 if f["fw"] > 560 else 1)
                ok(f"{tag} 八格依寬度 {want} 欄（頁尾寬 {f['fw']}px）", f["shown"] and f["cols"] == want, f)
                ok(f"{tag} 沒有橫向捲軸", not f["sideways"], f)
                if side == "0":
                    ok(f"{tag} 頁尾不再卡在 1200px（改前 max-width:1200 置中）", f["fw"] > 1200, f)
    pg.evaluate("() => { try { localStorage.removeItem('tw.footDetail'); localStorage.removeItem('tw.side'); } catch (e) {} }")
    pg.set_viewport_size({"width": 1500, "height": 1000})


# ===================================================================== 小數點普查（2026-09-26，claude/decimal-audit）
# Andy：「除了我抓到這邊數字異常，幫我檢查所有有這樣過多小數點的問題修正」。
# 他抓到的是資金集中度 tooltip「20 日均 34.951174999999985」—— 浮點數沒格式化、也沒有 %。
# 這段是**機器面的普查**，走遍每一頁、每張圖，四個面向一起掃：
#   ① ECharts 提示框：對每張看得見的圖、每個 series 抽樣（頭、尾、中間共 ≤8 點）dispatchAction showTip，
#      讀提示框 DOM 的字 —— 使用者把游標移上去看到的就是這些字。
#   ② ECharts 圖內文字：zrender 顯示清單裡每個文字元素（軸標籤、資料標籤、中心字）。
#   ③ 所有 canvas 的 fillText／strokeText（init script 攔截）：K 線（Lightweight Charts）、自畫 KChart、
#      流向拓撲這些**不是 ECharts** 的畫布；另外把游標在這些畫布上移幾格，讓十字線標籤也畫一次。
#   ④ 整頁看得見的文字（innerText）＋ SVG 文字＋ title 屬性（滑上去會跳出來的那段）。
# 抓三種字：小數點後 ≥ 4 位、科學記號（1e-7、2e+21）、NaN／undefined／Infinity。一個都不准有。
# ★ 門檻是 4 位不是 5 位：Andy 截圖裡的「前 5 族群佔比 30.5033」就是 4 位 —— 資料端存 4 位、前端原樣吐出，
#   5 位的門檻會把他親手抓到的那一半放掉。全站口徑最多 2 位（股價、指數、pp、比率），4 位一定是「沒格式化」。
# 另外 3 位的只記進備註（notes）給人逐條看：3 位有時是對的（例如成交量萬張 0.125），有時是漏網的原始值。
# 白名單：**目前一條都不需要**；真的需要放行時要在 _DEC_ALLOW 加一條並寫理由。
# 另外兩種「數字大到不合理」：連續 13 位以上的整數（JS 在 1e21 以下不會用科學記號，5.3e+18 會印成 5339467718210460000）、
# 千分位 5 組以上（≥ 1e15）—— 3504 的本益比就長這樣。全站的大數字都換成億／萬張，正常畫面不會出現。
_DEC_BAD = (r"\d\.\d{4,}|\d[eE][+-]\d|\bNaN\b|\bundefined\b|\bInfinity\b"
            r"|(?<![\w/.=-])\d{13,}(?![\w])|\d{1,3}(?:,\d{3}){5,}")
_DEC_SOFT = r"(?<![\d.])\d+\.\d{3}(?![\d])"
_DEC_ALLOW: list[str] = []   # 正規式；每一條都要寫為什麼需要放行

_DEC_HOOK = """(() => {
  const re = new RegExp(%s);
  const bad = []; window.__twDecCanvas = bad;
  const wrap = (P) => { if (!P) return; ['fillText', 'strokeText'].forEach(k => { const f = P[k]; if (!f) return;
    P[k] = function (t, ...a) { try { const s = String(t); if (re.test(s) && bad.length < 80) bad.push(location.hash + '｜' + s.slice(0, 80)); } catch (e) {}
      return f.call(this, t, ...a); }; }); };
  wrap(window.CanvasRenderingContext2D && CanvasRenderingContext2D.prototype);
  wrap(window.OffscreenCanvasRenderingContext2D && OffscreenCanvasRenderingContext2D.prototype);
})();""" % json.dumps(_DEC_BAD)

_DEC_SCAN = """async (bad) => {
  const re = new RegExp(bad[0]), soft = new RegExp(bad[1]);
  const hits = [], softs = [];
  const test = (s, where) => { if (s == null) return; s = String(s); const m = s.match(re);
    if (m) hits.push(where + '｜…' + s.slice(Math.max(0, m.index - 28), m.index + 28).replace(/\\s+/g, ' ') + '…');
    const m2 = s.match(soft);
    if (m2) softs.push(where + '｜…' + s.slice(Math.max(0, m2.index - 20), m2.index + 20).replace(/\\s+/g, ' ') + '…'); };
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const vis = (el) => { const r = el.getBoundingClientRect(); if (!(r.width > 0 && r.height > 0)) return false;
    const cs = getComputedStyle(el); return cs.visibility !== 'hidden' && cs.display !== 'none'; };
  const tipText = (dom) => [...dom.children, ...document.body.children]
    .filter(d => d.domBelongToZr && d.style.display !== 'none' && d.style.opacity !== '0').map(d => d.innerText || d.textContent || '').join(' ');
  let nChart = 0, nTip = 0;
  const doms = [...document.querySelectorAll('[_echarts_instance_]')].filter(vis);
  for (const dom of doms) {
    const c = window.echarts && echarts.getInstanceByDom(dom); if (!c || c.isDisposed()) continue;
    nChart++;
    const nm = '#' + (dom.id || (dom.parentElement && dom.parentElement.id) || dom.className || '?');
    try { c.getZr().storage.getDisplayList(true).forEach(e => {
      if (e.ignore || e.invisible) return;
      if (e.style && typeof e.style.text === 'string') test(e.style.text, '圖內文字' + nm);
      const tc = e.getTextContent && e.getTextContent(); if (tc && tc.style && !tc.ignore) test(tc.style.text, '圖內標籤' + nm); }); } catch (e) { /* 忽略 */ }
    let opt; try { opt = c.getOption(); } catch (e) { continue; }
    const tt = (opt.tooltip || [])[0];
    if (!tt || tt.show === false || tt.trigger === 'none') continue;
    const model = c.getModel();
    const q = []; let budget = 36;
    (opt.series || []).forEach((s, si) => {
      let n = 0; try { n = model.getSeriesByIndex(si).getData().count(); } catch (e) { n = 0; }
      if (!n) return;
      // treemap／sunburst 的 dataIndex 0 是看不見的根節點（使用者滑不到），從 1 開始抽
      const lo = /treemap|sunburst|tree/.test(s.type || '') && n > 1 ? 1 : 0;
      const k = Math.min(8, n - lo), idx = new Set();
      for (let j = 0; j < k; j++) idx.add(lo + Math.round(j * (n - 1 - lo) / Math.max(1, k - 1)));
      idx.forEach(i => { if (budget-- > 0) q.push([si, i]); });
    });
    for (const [si, i] of q) {
      try { c.dispatchAction({ type: 'showTip', seriesIndex: si, dataIndex: i }); } catch (e) { continue; }
      await sleep(25);
      const t = tipText(dom); if (t.trim()) { nTip++; test(t, '提示框' + nm + ' s' + si + '#' + i); }
    }
    try { c.dispatchAction({ type: 'hideTip' }); } catch (e) { /* 忽略 */ }
  }
  // 整頁看得見的字（display:none 的分頁 innerText 本來就不算）＋ SVG 字 ＋ title
  test(document.body.innerText, '頁面文字');
  document.querySelectorAll('svg text, svg tspan').forEach(t => { if (vis(t)) test(t.textContent, 'SVG 文字'); });
  document.querySelectorAll('[title]').forEach(t => { if (vis(t)) test(t.getAttribute('title'), 'title「' + (t.textContent || '').trim().slice(0, 10) + '」'); });
  return { hits: [...new Set(hits)], softs: [...new Set(softs)], nChart, nTip };
}"""


def _dec_page(pg, url: str, label: str, acts=(), settle: int = 2600, each: str = ""):
    """開一頁 → 捲到底（懶畫的圖捲到才畫）→ 掃 → 依序做 acts（點按鈕切狀態）每個狀態再掃一次。
    each：一個選擇器，符合的按鈕**每一顆都點一次再掃**（個股頁的營收／獲利／籌碼分頁、手機的分段列 .mpager）——
    這些分頁沒點開之前圖根本不存在，只掃預設那一段會漏掉大半張圖。回傳掃到的圖數。"""
    pg.goto(url, wait_until="networkidle")
    pg.wait_for_timeout(settle)
    total = 0

    def scan(tag):
        nonlocal total
        # 捲一遍整頁：IntersectionObserver 才會把還沒畫的圖畫出來
        pg.evaluate("""async () => { const H = document.documentElement.scrollHeight;
            for (let y = 0; y < H; y += Math.max(300, innerHeight * 0.8)) { scrollTo(0, y); await new Promise(r => setTimeout(r, 120)); }
            scrollTo(0, 0); }""")
        pg.wait_for_timeout(700)
        # 非 ECharts 的畫布（K 線、自畫 KChart、拓撲）：游標在上面走幾格，讓十字線／游標看板也畫一次
        boxes = pg.evaluate("""() => [...document.querySelectorAll('canvas')].filter(c => {
            if (c.closest('[_echarts_instance_]')) return false;
            const r = c.getBoundingClientRect(); return r.width > 80 && r.height > 60; }).slice(0, 12)
            .map(c => { c.scrollIntoView({block: 'center'}); const r = c.getBoundingClientRect(); return [r.x, r.y, r.width, r.height]; })""")
        for bx in boxes:
            for fx in (0.2, 0.5, 0.85):
                try:
                    pg.mouse.move(bx[0] + bx[2] * fx, bx[1] + bx[3] * 0.5); pg.wait_for_timeout(60)
                except Exception:  # noqa: BLE001
                    pass
        pg.mouse.move(2, 2)
        r = pg.evaluate(_DEC_SCAN, [_DEC_BAD, _DEC_SOFT])
        total += r["nChart"]
        notes.append(f"小數點普查／{label}{tag}：圖 {r['nChart']} 張、提示框 {r['nTip']} 次"
                     + (f"；3 位小數待看 {len(r['softs'])} 處：{r['softs'][:6]}" if r["softs"] else ""))
        hits = [h for h in r["hits"] if not any(re.search(a, h) for a in _DEC_ALLOW)]
        ok(f"小數點普查／{label}{tag}：提示框、圖內文字、頁面文字沒有長小數／科學記號／NaN（圖 {r['nChart']} 張、提示框 {r['nTip']} 次）",
           not hits, hits[:8])

    scan("")
    if each:
        labels = pg.evaluate(f"() => [...document.querySelectorAll({json.dumps(each)})].map(b => (b.textContent || '').trim())")
        for i, t in enumerate(labels):
            try:
                pg.evaluate(f"() => {{ const b = document.querySelectorAll({json.dumps(each)})[{i}]; if (b) b.click(); }}")
                pg.wait_for_timeout(1500)
                scan(f"（{t}）")
            except Exception as e:  # noqa: BLE001
                notes.append(f"小數點普查／{label}（{t}）：{type(e).__name__} {e}")
    for sel, tag in acts:
        try:
            if pg.evaluate(f"() => !!document.querySelector({json.dumps(sel)})"):
                pg.evaluate(f"() => document.querySelector({json.dumps(sel)}).click()")
                pg.wait_for_timeout(1600)
                scan(f"（{tag}）")
            else:
                notes.append(f"小數點普查／{label}：找不到 {sel}，那個狀態沒掃到")
        except Exception as e:  # noqa: BLE001
            notes.append(f"小數點普查／{label}（{tag}）：{type(e).__name__} {e}")
    return total


def t_decimal_audit(b, base, code):
    """全站小數點普查：桌機 1500 走十幾頁（含幾個切換狀態）＋ 手機 390 走主要頁。"""
    theme_id = ""
    try:
        theme_id = (json.loads((SITE / "data" / "themes.json").read_text(encoding="utf-8")).get("themes") or [{}])[0].get("id", "")
    except Exception:  # noqa: BLE001
        pass
    pg = b.new_page(viewport={"width": 1500, "height": 1000})
    pg.add_init_script(_DEC_HOOK)
    pg.on("pageerror", lambda e: fails.append(f"小數點普查 pageerror: {e}｜{pg.url}｜" + (getattr(e, "stack", "") or "").replace(chr(10), " / ")[:400]))
    pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    n = 0
    n += _dec_page(pg, f"{base}#overview", "總覽")
    n += _dec_page(pg, f"{base}#flow", "資金流向", acts=(("#concSeg button[data-v='10']", "集中度前 10 大"),))
    # 市場明細：每一個子頁都掃一次
    pg.goto(f"{base}#market", wait_until="networkidle"); pg.wait_for_timeout(1800)
    subs = pg.evaluate("() => [...document.querySelectorAll('#mktSeg2 button')].map(b => b.dataset.k).filter(Boolean)")
    ok("小數點普查：市場明細有子頁可以掃", len(subs) >= 2, subs)
    for k in subs:
        n += _dec_page(pg, f"{base}#market/{k}", f"市場明細/{k}", settle=1800)
    n += _dec_page(pg, f"{base}#industry", "產業地圖")
    for ch in ("semiconductor", "ai_server", "electronics"):
        n += _dec_page(pg, f"{base}#industry/{ch}", f"產業鏈/{ch}")
    n += _dec_page(pg, f"{base}#heatmap", "熱力圖")
    if theme_id:
        n += _dec_page(pg, f"{base}#heatmap/theme/{theme_id}", f"題材/{theme_id}")
    n += _dec_page(pg, f"{base}#season", "週期統計", acts=(("#seasonView button[data-v='line']", "曲線圖"),
                                                        ("#seasonMetric button[data-v='win_rate']", "勝率")))
    n += _dec_page(pg, f"{base}#delivery", "交付清單", settle=1500)
    n += _dec_page(pg, f"{base}#stock/{code}", f"個股/{code}", settle=3400, each="#stockTabs button")
    # 3504：資料湖裡有一季近四季 EPS 是浮點殘差（2.8e-17），舊版本益比印成 5.3e+18 —— 留著當「真的壞資料」的活體樣本
    n += _dec_page(pg, f"{base}#stock/3504", "個股/3504（本益比殘差樣本）", settle=3000, each="#stockTabs button[data-t='profit']")
    try:
        gid = (json.loads((SITE / "data" / "groups_today.json").read_text(encoding="utf-8")) or [{}])[0].get("group_id", "")
    except Exception:  # noqa: BLE001
        gid = ""
    if gid:
        n += _dec_page(pg, f"{base}#industry/group/{gid}", f"族群頁/{gid}")
    cv = pg.evaluate("() => window.__twDecCanvas || []")
    ok("小數點普查／桌機：所有畫布（含 K 線、自畫圖）fillText 沒有長小數／科學記號／NaN",
       not [x for x in cv if not any(re.search(a, x) for a in _DEC_ALLOW)], cv[:8])
    ok("小數點普查／桌機：真的掃到圖（不是空跑）", n >= 30, n)
    pg.close()

    m = b.new_page(viewport={"width": 390, "height": 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
    m.add_init_script(_DEC_HOOK)
    m.on("pageerror", lambda e: fails.append(f"小數點普查（手機）pageerror: {e}｜{m.url}｜" + (getattr(e, "stack", "") or "").replace(chr(10), " / ")[:400]))
    m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    mn = 0
    for h, name in (("overview", "總覽"), ("flow", "資金流向"), ("market", "市場明細"), ("heatmap", "熱力圖"),
                    ("season", "週期統計"), (f"stock/{code}", "個股")):
        mn += _dec_page(m, f"{base}#{h}", f"手機/{name}", settle=2400, each="main .view.on .mpager button")
    cv = m.evaluate("() => window.__twDecCanvas || []")
    ok("小數點普查／手機：所有畫布 fillText 沒有長小數／科學記號／NaN",
       not [x for x in cv if not any(re.search(a, x) for a in _DEC_ALLOW)], cv[:8])
    ok("小數點普查／手機：真的掃到圖", mn >= 6, mn)
    m.close()


# ★ 2026-09-27 手機按鈕普查（Andy：「手機版介面 幫我確實驗證所有按鈕功能，我發現有部分功能無法點選」）
#   量測本體在 scripts/_mobile_tap_audit.py。這一段做兩件事：
#   ① 量測本身有效：故意種三顆壞鈕（被透明層蓋住／點了沒反應／打開的浮層關不掉），三顆都要被抓到 ——
#      不然「0 個問題」可能只是量測壞掉。
#   ② 全站普查：390×844 與 360×780、is_mobile＋has_touch＋DPR2、觸控 tap，問題數必須是 0，
#      而且每種寬度真的點過足夠多顆、走過足夠多個畫面（防止「一顆都沒點到所以 0 個問題」）。
def t_mobile_tap_audit(b, base, code):
    sys.path.insert(0, str(ROOT))
    import importlib
    A = importlib.import_module("scripts._mobile_tap_audit")
    # ---- ① 種三顆壞鈕 ----
    au = A.Auditor(b, base, 390, log=lambda *a, **k: None)
    pg = au.new_page()
    try:
        st = {"name": "種壞鈕", "hash": "#overview"}
        au.load(st)
        pg.evaluate("""() => {
          const box = document.createElement('div'); box.id = 'taPlant';
          box.style.cssText = 'position:relative;margin:10px 16px;padding:8px;display:flex;gap:8px;flex-wrap:wrap';
          box.innerHTML = '<button id="taCover" style="min-width:90px;min-height:44px">被蓋住</button>'
            + '<button id="taDead" style="min-width:90px;min-height:44px">沒反應</button>'
            + '<button id="taPop" style="min-width:90px;min-height:44px">關不掉</button>'
            + '<div style="position:absolute;left:0;top:0;width:110px;height:64px;background:transparent"></div>';
          document.querySelector('main .view.on').prepend(box);
          document.getElementById('taCover').onclick = (e) => { e.currentTarget.textContent = '點到了'; };
          document.getElementById('taPop').onclick = () => {
            const p = document.createElement('div'); p.id = 'taPopPanel';
            p.style.cssText = 'position:fixed;left:40px;top:200px;width:240px;height:160px;background:#333;z-index:9999';
            p.textContent = '沒有關閉鈕、點外面也不關'; document.body.appendChild(p); };
        }""")
        pg.evaluate("() => window.scrollTo({top: 0, behavior: 'instant'})")
        au.baseline()
        au.audit_scope(st, "#taPlant", 0, lambda force=False: True, budget=10)
        rows = {r["txt"]: r for r in au.rows}
        c, d, p = rows.get("被蓋住", {}), rows.get("沒反應", {}), rows.get("關不掉", {})
        ok("手機按鈕普查：量測本身有效（被透明層蓋住的鈕被抓成「點不到」）", bool(c.get("blocked")), c)
        ok("手機按鈕普查：量測本身有效（點了沒反應的鈕被抓成「沒反應」）", bool(d.get("noreact")), d)
        ok("手機按鈕普查：量測本身有效（打開後關不掉的浮層被抓成「收不回來」）", bool(p.get("noclose")), p)
    finally:
        try:
            pg.close()
        except Exception:  # noqa: BLE001
            pass
    # ---- ①b 這一輪修掉的兩件，各自用觸控再驗一次「畫面真的變了」 ----
    for (W, H) in ((390, 844), (360, 780)):
        m = b.new_page(viewport={"width": W, "height": H}, device_scale_factor=2, is_mobile=True, has_touch=True)
        m.route("**/fonts.googleapis.com/**", lambda r: r.abort())
        m.on("pageerror", lambda e: fails.append(f"手機按鈕普查 pageerror: {e}"))
        try:
            m.goto(f"{base}#flow", wait_until="networkidle"); m.wait_for_timeout(2200)
            T = f"[手機按鈕普查 {W}px]"
            # (1) 搜尋列展開後點旁邊空白處 → 收回，左上品牌又點得到
            m.tap("#mSearchBtn"); m.wait_for_timeout(400)
            s0 = m.evaluate("() => document.querySelector('.topbar').classList.contains('msearch')")
            brand_hit0 = m.evaluate("""() => { const b = document.querySelector('.brand').getBoundingClientRect();
                const h = document.elementFromPoint(b.left + b.width / 2, b.top + b.height / 2); return !!h && !!h.closest('.brand'); }""")
            # 「外面」＝搜尋列與它的建議清單（#sugg 在 .search 裡，會往下蓋一大塊）以外、而且不是任何可點元素的空白處
            pt = m.evaluate("""() => { const INTER = 'button,a[href],summary,label,select,input,textarea,[role=button],[role=tab],[role=link],[onclick],svg,canvas';
                for (let y = innerHeight - 70; y > 60; y -= 23) for (let x = 6; x < innerWidth - 4; x += 23) {
                  const h = document.elementFromPoint(x, y); if (!h || h.closest('.topbar, .search, #tabs, nav') || h.closest(INTER)) continue;
                  let p = false; for (let n = h; n; n = n.parentElement) if (getComputedStyle(n).cursor === 'pointer') { p = true; break; }
                  if (!p) return { x, y, on: (h.id || '') + '.' + String(h.className).split(' ')[0] }; }
                return null; }""")
            if pt:
                m.touchscreen.tap(pt["x"], pt["y"]); m.wait_for_timeout(700)
            s1 = m.evaluate("() => document.querySelector('.topbar').classList.contains('msearch')")
            brand_hit1 = m.evaluate("""() => { const b = document.querySelector('.brand').getBoundingClientRect();
                const h = document.elementFromPoint(b.left + b.width / 2, b.top + b.height / 2); return !!h && !!h.closest('.brand'); }""")
            ok(f"{T} 搜尋列展開時蓋住品牌；點旁邊空白處 → 搜尋列收回、品牌又點得到",
               s0 and not brand_hit0 and bool(pt) and not s1 and brand_hit1,
               {"展開": s0, "展開時品牌點得到": brand_hit0, "空白點": pt, "點完還展開": s1, "點完品牌點得到": brand_hit1})
            if s1:
                m.keyboard.press("Escape"); m.wait_for_timeout(200)      # 上一條紅了也要能往下驗
            # 點搜尋框本身不算外面（打字到一半不會被收掉）
            m.tap("#mSearchBtn"); m.wait_for_timeout(300); m.tap("#q"); m.wait_for_timeout(400)
            ok(f"{T} 點搜尋框本身不會把搜尋列收掉",
               m.evaluate("() => document.querySelector('.topbar').classList.contains('msearch')"))
            m.tap("#mSearchX"); m.wait_for_timeout(300)
            # (2) 今日事件抽屜：事件列底下的個股連結換行，不再把抽屜撐寬（右邊的連結都在抽屜裡）
            m.goto(f"{base}#overview", wait_until="networkidle"); m.wait_for_timeout(2200)
            m.evaluate("() => { const b = document.getElementById('evToggle'); if (b) b.click(); }"); m.wait_for_timeout(900)
            ev = m.evaluate("""() => { const s = document.getElementById('side'); if (!s) return null; const sr = s.getBoundingClientRect();
                const lk = [...s.querySelectorAll('.ev .m a.lk')].filter(a => a.getClientRects().length);
                const out = lk.filter(a => a.getBoundingClientRect().right > sr.right + 1).length;
                return { sw: s.scrollWidth, cw: s.clientWidth, open: sr.left < innerWidth - 10, links: lk.length, outside: out }; }""")
            ok(f"{T} 今日事件抽屜打開後沒有被撐寬、個股連結全部在抽屜裡（可以直接點）",
               bool(ev) and ev["open"] and ev["links"] > 0 and ev["sw"] <= ev["cw"] + 2 and ev["outside"] == 0, ev)
            # (3) 普查白名單裡的「重設縮放」：先把 K 線縮到最後 10 根，再用觸控按它 → 可見範圍真的變回來
            m.goto(f"{base}#stock/{code}", wait_until="networkidle"); m.wait_for_timeout(2600)
            z = m.evaluate("""() => { const k = window.KChart && window.KChart.last; if (!k || !k.chart) return null;
                const ts = k.chart.timeScale(), r = ts.getVisibleLogicalRange(); if (!r) return null;
                ts.setVisibleLogicalRange({ from: r.to - 10, to: r.to });
                const r2 = ts.getVisibleLogicalRange(); return { before: r.to - r.from, zoomed: r2.to - r2.from }; }""")
            fit = m.evaluate("""() => { const b = [...document.querySelectorAll('.kfit')].find(x => x.getClientRects().length); if (!b) return null;
                b.scrollIntoView({ block: 'center', behavior: 'instant' }); const r = b.getBoundingClientRect();
                const h = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
                return { x: r.left + r.width / 2, y: r.top + r.height / 2, hit: !!h && (h === b || b.contains(h)) }; }""")
            if z and fit:
                m.touchscreen.tap(fit["x"], fit["y"]); m.wait_for_timeout(600)
                after = m.evaluate("() => { const r = window.KChart.last.chart.timeScale().getVisibleLogicalRange(); return r ? r.to - r.from : null; }")
                ok(f"{T} K 線縮到 10 根後用觸控按「重設縮放」→ 真的回到全覽（可見根數變多）",
                   fit["hit"] and after is not None and after > z["zoomed"] + 5, {"縮放前": z, "重設鈕": fit, "按完": after})
            else:
                ok(f"{T} 個股頁找得到 K 線與「重設縮放」鈕", False, {"z": z, "fit": fit})
        finally:
            m.close()
    # ---- ② 全站普查 ----
    # 兩種寬度各開一個子行程同時跑（一種一輪 30～60 分鐘）；子行程共用這一段已經持有的瀏覽器鎖與本機伺服器
    res = A.run_parallel(base, (390, 360), code=code, log=lambda *a, **k: print(*a, **k, flush=True))
    A.write_report(res)
    P = A.problems(res)
    for w in (390, 360):
        n = sum(1 for r in res["rows"] if r["w"] == w)
        ns = sum(1 for s in res["states"] if s["w"] == w)
        # 2026-09-27 實測一種寬度：點過約 720 顆、走過約 90 個畫面；門檻抓六～七成，少掉一大塊（整頁沒走到）就會紅
        ok(f"手機按鈕普查 {w}px：真的點過夠多顆（≥ 500）、走過夠多個畫面（≥ 60）", n >= 500 and ns >= 60, {"點過": n, "畫面": ns})
    ok("手機按鈕普查：點不到／沒反應／收不回來 0 顆", not P,
       [f"[{r['w']}] {r['page']}｜{r['txt']}｜{r['sel']}｜{r['blocked']}{'｜沒反應' if r['noreact'] else ''}{'｜' + r['noclose'] if r['noclose'] else ''}" for r in P[:30]])
    ok("手機按鈕普查：執行中沒有錯誤（pageerror、切不到分段、中途爆掉）", not res["errors"], res["errors"][:10])
    ndg = sum(1 for r in res["rows"] if A.is_dg_part(r) and (r["blocked"] or r["noreact"] or r["noclose"]))
    notes.append(f"手機按鈕普查：點過 {len(res['rows'])} 顆、觸控目標 < {A.MIN_TOUCH}px 的 {len(res['small'])} 顆、"
                 f"剖析圖零件圖形點不到或沒反應 {ndg} 列（手機以編號為入口，不算紅燈）—— 列表見 docs/_mobile_tap/report.md")


# ★ 2026-09-28 設計 v4 第二批 2D：手機 360／390 修正
#   ① 360 寬熱力圖圖例整條（.hmbar）撐出 382 寬 → 手機瀏覽器把版面視窗放大到 382、觸控座標對不上：
#      放大層按「關閉 ✕」關不掉、圖例 7 格有 6 格點了沒反應。這一段用觸控真的點：放大層打開 → 點 ✕ → 真的關掉；
#      圖例每一格點下去真的只亮那一級、再點一次還原；總覽每一段的文件寬 ＝ 視窗寬（版面視窗沒被撐大）。
#   ② 觸控目標放大到 40：剖析圖章節鈕列（點了圖真的展開）、週期統計排序抽屜（點了表頭排序月真的換、熱力圖列順序真的變）、
#      產業地圖圖例／頁尾連結／個股基本資料連結 ≥ 40 高、a.lk 點擊區 ≥ 40 而且中心點不會被隔壁的點擊區搶走。
#   ③ 桌機（1440）不插章節鈕列、不插排序鈕、圖裡的章節列照樣可以點。
_HITBOX_JS = r"""
(e) => { const r = e.getBoundingClientRect(); let x0 = r.left, y0 = r.top, x1 = r.right, y1 = r.bottom;
  if (getComputedStyle(e).position !== 'static') for (const ps of ['::before', '::after']) {
    const cs = getComputedStyle(e, ps); if (cs.content === 'none' || cs.content === 'normal' || cs.position !== 'absolute' || cs.display === 'none') continue;
    const t = parseFloat(cs.top), l = parseFloat(cs.left), rr = parseFloat(cs.right), b = parseFloat(cs.bottom);
    if (isFinite(t)) y0 = Math.min(y0, r.top + t); if (isFinite(b)) y1 = Math.max(y1, r.bottom - b);
    if (isFinite(l)) x0 = Math.min(x0, r.left + l); if (isFinite(rr)) x1 = Math.max(x1, r.right - rr); }
  return { w: Math.round(x1 - x0), h: Math.round(y1 - y0) }; }
"""


def t_mobile_v4_2d(b, base, code):
    sys.path.insert(0, str(ROOT))
    import importlib
    A = importlib.import_module("scripts._mobile_tap_audit")

    def tap(m, sel):
        c = m.evaluate("""(s) => { const e = document.querySelector(s); if (!e) return null;
            e.scrollIntoView({ block: 'center', behavior: 'instant' }); const r = e.getBoundingClientRect();
            const h = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
            return { x: r.left + r.width / 2, y: r.top + r.height / 2, hit: !!h && (h === e || e.contains(h)) }; }""", sel)
        if c:
            m.touchscreen.tap(c["x"], c["y"]); m.wait_for_timeout(650)
        return c

    for W in (390, 360):
        T = f"[手機v4二批 {W}px]"
        au = A.Auditor(b, base, W, log=lambda *a, **k: None)
        m = au.new_page()
        m.on("pageerror", lambda e: fails.append(f"手機v4二批 pageerror: {e}"))
        try:
            # ---- ① 總覽每一段：文件寬 ＝ 視窗寬（版面視窗沒有被撐大）
            au.load({"name": "總覽", "hash": "#overview"})
            bars = m.evaluate(A.SEG_JS)
            segs = [(f"{bar['sel']} > :nth-child({bt['nth']})", bt["label"]) for bar in bars if "mpager" in bar["sel"] for bt in bar["btns"]]
            heat_step = next((s for s, lb in segs if lb.startswith("熱力圖")), None)
            wide = []
            for s, lb in segs:
                au.load({"name": lb, "hash": "#overview", "steps": [s]})
                d = m.evaluate("() => [document.documentElement.scrollWidth, innerWidth, Math.round(visualViewport.width)]")
                if d[0] > W or d[1] != W:
                    wide.append((lb, d))
            ok(f"{T} 總覽每一段（{len(segs)} 段）文件寬 ≤ 視窗寬、版面視窗沒被撐大（360 圖例撐出 382 的根因）",
               len(segs) >= 3 and not wide, {"段": [lb for _, lb in segs], "撐寬": wide})
            if not heat_step:
                ok(f"{T} 總覽找得到「熱力圖」那一段", False, segs)
                continue
            au.load({"name": "總覽／熱力圖", "hash": "#overview", "steps": [heat_step]})
            # ---- 圖例每一格：觸控點下去 → 只亮那一級；再點一次 → 還原
            LG = """() => { const l = document.querySelector('#ovHeatCard .hmlegend'); if (!l) return null;
                const on = l.querySelector('.hmcell.on'); return { focus: l.classList.contains('focus'), on: on ? +on.dataset.bin : null,
                n: l.querySelectorAll('.hmcell').length, minH: Math.min(...[...l.querySelectorAll('.hmcell')].map(c => c.getBoundingClientRect().height)) }; }"""
            lg0 = m.evaluate(LG) or {}
            bad = []
            for i in range(lg0.get("n", 0)):
                c = tap(m, f'#ovHeatCard .hmcell[data-bin="{i}"]')
                s1 = m.evaluate(LG)
                if not (c and c["hit"] and s1 and s1["focus"] and s1["on"] == i):
                    bad.append({"格": i, "點": c, "點完": s1}); continue
                tap(m, f'#ovHeatCard .hmcell[data-bin="{i}"]')
                s2 = m.evaluate(LG)
                if not (s2 and not s2["focus"] and s2["on"] is None):
                    bad.append({"格": i, "再點": s2})
            ok(f"{T} 熱力圖圖例 7 格用觸控逐格點：每一格都真的只亮那一級、再點一次還原", lg0.get("n") == 7 and not bad, {"圖例": lg0, "失敗": bad[:4]})
            ok(f"{T} 熱力圖圖例每格高 ≥ 40", (lg0.get("minH") or 0) >= 40, lg0)
            # ---- 放大層：打開 → 標題列與關閉鈕都在視窗內 → 點 ✕ → 真的關掉
            c = tap(m, "#heatZoom"); m.wait_for_timeout(400)
            z = m.evaluate("""() => { const ov = document.getElementById('zoomOv'), zh = ov.querySelector('.zh'), x = document.getElementById('zoomClose');
                const r = x.getBoundingClientRect(), h = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
                return { open: !ov.hidden, zhRight: Math.round(zh.getBoundingClientRect().right), xRight: Math.round(r.right), xH: Math.round(r.height),
                         hit: !!h && (h === x || x.contains(h)), vw: innerWidth }; }""")
            ok(f"{T} 觸控點「放大 ⤢」→ 放大層真的打開，標題列與「關閉 ✕」都在 {W}px 視窗內、✕ 中心點得到、高 ≥ 40",
               bool(c) and z["open"] and z["zhRight"] <= W and z["xRight"] <= W and z["hit"] and z["xH"] >= 40 and z["vw"] == W, {"點": c, "放大層": z})
            if z["open"]:
                tap(m, "#zoomClose"); m.wait_for_timeout(300)
                z2 = m.evaluate("() => ({ hidden: document.getElementById('zoomOv').hidden, bodyOv: document.body.style.overflow })")
                ok(f"{T} 放大層按「關閉 ✕」（觸控）→ 真的關掉、頁面捲動還原", z2["hidden"] and z2["bodyOv"] == "", z2)
                if not z2["hidden"]:
                    m.keyboard.press("Escape")
            # ---- 頁尾連結與「詳細規範」≥ 40 高
            ft = m.evaluate("""() => [...document.querySelectorAll('.sitefoot .sf-links a, .sitefoot .sf-links button, #sfMore')]
                .filter(e => e.getClientRects().length).map(e => [e.textContent.trim().slice(0, 8), Math.round(e.getBoundingClientRect().height)])""")
            ok(f"{T} 頁尾連結、平台導覽、「顯示詳細規範」每顆高 ≥ 40", len(ft) >= 4 and all(h >= 40 for _, h in ft), ft)
            # ---- 產業地圖圖例 ≥ 40 高，點一列真的進族群
            au.load({"name": "產業地圖", "hash": "#industry"})
            gl = m.evaluate("""() => [...document.querySelectorAll('#gpLegend .lg')].filter(e => e.getClientRects().length)
                .map(e => [e.dataset.n, Math.round(e.getBoundingClientRect().height), e.classList.contains('other')])""")
            ok(f"{T} 產業地圖圖例每列高 ≥ 40", len(gl) >= 3 and all(h >= 40 for _, h, _o in gl), gl)
            first = next((n for n, _h, o in gl if not o), None)
            if first:
                # 點一列＝點那一塊扇形：同一頁往下鑽到那個族群的成分股（圖例整份換成個股）
                NM = "() => [...document.querySelectorAll('#gpLegend .lg')].map(e => e.dataset.n).join('|')"
                n0 = m.evaluate(NM)
                c = tap(m, f'#gpLegend .lg[data-n="{first}"]'); m.wait_for_timeout(700)
                n1 = m.evaluate(NM)
                ok(f"{T} 產業地圖圖例點一列（觸控）→ 真的鑽進那個族群（圖例換成成分股）", bool(c) and c["hit"] and n1 and n1 != n0,
                   {"點": first, "命中": c, "前": n0[:80], "後": n1[:80]})
            if W != 390:
                continue
            # ---- ② 剖析圖章節鈕列（390）
            au.load({"name": "半導體", "hash": "#industry/semiconductor"})
            m.wait_for_timeout(600)
            fd = m.evaluate("""() => { const bs = [...document.querySelectorAll('.mdgfolds button[data-fold]')], gs = [...document.querySelectorAll('#prodDiagram g.dgfold[data-fold]')];
                return { nb: bs.length, ng: gs.length, minH: bs.length ? Math.min(...bs.map(b => b.getBoundingClientRect().height)) : 0,
                         pe: gs.length ? getComputedStyle(gs[0]).pointerEvents : null, same: bs.map(b => b.dataset.fold).join() === gs.map(g => g.dataset.fold).join() }; }""")
            ok(f"{T} 半導體剖析圖：圖下方的章節鈕一條章節列一顆、順序相同、每顆高 ≥ 40；圖裡 15px 的章節列手機不接觸控",
               fd["nb"] >= 2 and fd["nb"] == fd["ng"] and fd["same"] and fd["minH"] >= 40 and fd["pe"] == "none", fd)
            if fd["nb"]:
                SV = "() => Math.round(document.querySelector('#prodDiagram svg').getBoundingClientRect().height)"
                h0 = m.evaluate(SV)
                tap(m, ".mdgfolds button[data-fold]:nth-child(2)")
                s1 = m.evaluate("""() => { const b = document.querySelector('.mdgfolds button[data-fold]:nth-child(2)'), g = document.querySelector(`#prodDiagram g.dgfold[data-fold="${b.dataset.fold}"]`);
                    const gr = g.getBoundingClientRect(); return { exp: b.getAttribute('aria-expanded'), sign: b.querySelector('.sg').textContent, open: g.classList.contains('open'),
                    gTop: Math.round(gr.top), vh: innerHeight }; }""")
                h1 = m.evaluate(SV)
                ok(f"{T} 點第二顆章節鈕（觸控）→ 圖裡那一段真的展開（圖變高、章節列 open、鈕變「－」），而且那一段捲進畫面",
                   s1["exp"] == "true" and s1["sign"] == "－" and s1["open"] and h1 > h0 + 20 and 40 <= s1["gTop"] <= s1["vh"] - 60,
                   {"圖高": [h0, h1], "狀態": s1})
                tap(m, ".mdgfolds button[data-fold]:nth-child(2)")
                s2 = m.evaluate("() => document.querySelector('.mdgfolds button[data-fold]:nth-child(2)').getAttribute('aria-expanded')")
                ok(f"{T} 再點一次 → 收回（圖高回到原本）", s2 == "false" and abs(m.evaluate(SV) - h0) <= 2, {"狀態": s2, "圖高": [h0, m.evaluate(SV)]})
            # ---- a.lk 點擊區 ≥ 40、中心點不被隔壁搶走（產業鏈頁的族群／產業鏈連結）
            lk = m.evaluate("""(HB) => { const hb = eval(HB); const as = [...document.querySelectorAll('main .view.on a.lk')].filter(a => a.getClientRects().length).slice(0, 60);
                const small = [], stolen = [];
                as.forEach(a => { a.scrollIntoView({ block: 'center', behavior: 'instant' }); const s = hb(a), r = a.getBoundingClientRect();
                  if (s.w < 40 || s.h < 40) small.push([a.textContent.trim().slice(0, 8), s]);
                  const h = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
                  if (h && !(h === a || a.contains(h)) && h.closest('a.lk')) stolen.push([a.textContent.trim().slice(0, 8), h.textContent.trim().slice(0, 8)]); });
                return { n: as.length, small, stolen }; }""", _HITBOX_JS)
            ok(f"{T} 產業鏈頁的族群／產業鏈連結點擊區 ≥ 40×40，而且中心點不會被隔壁連結的點擊區搶走",
               lk["n"] >= 5 and not lk["small"] and not lk["stolen"], lk)
            # ---- 市場明細「名單」：表格裡的個股／族群連結觸控範圍 ≥ 40（儲存格會裁掉 ::after，所以是連結本身 40 高）
            au.load({"name": "市場明細", "hash": "#market"})
            bars = m.evaluate(A.SEG_JS)
            st = next((f"{bar['sel']} > :nth-child({bt['nth']})" for bar in bars for bt in bar["btns"] if bt["label"].startswith("名單")), None)
            if st:
                au.load({"name": "市場明細／名單", "hash": "#market", "steps": [st]})
                ml = m.evaluate("""(HB) => { const hb = eval(HB); const as = [...document.querySelectorAll('main .view.on a.lk')].filter(a => a.getClientRects().length).slice(0, 40);
                    return { n: as.length, small: as.map(a => [a.textContent.trim().slice(0, 8), hb(a), Math.round(a.getBoundingClientRect().height)]).filter(x => x[2] < 40).slice(0, 6) }; }""", _HITBOX_JS)
                ok(f"{T} 市場明細名單：表格裡的個股／族群連結高 ≥ 40", ml["n"] >= 5 and not ml["small"], ml)
            else:
                ok(f"{T} 市場明細找得到「名單」分段", False, bars)
            # ---- 週期統計：排序抽屜
            au.load({"name": "週期統計", "hash": "#season"})
            m.wait_for_timeout(500)
            ROWS = "() => { const c = echarts.getInstanceByDom(document.getElementById('seasonHeat')); const y = c && c.getOption().yAxis; return y && y[0] ? (y[0].data || []).map(d => d && d.value !== undefined ? d.value : d).join('|') : ''; }"
            s0 = m.evaluate("""() => { const s = document.getElementById('mSeasonSort'), on = document.querySelector('#seasonHeatHead button.on');
                return { lab: s && s.textContent, h: s ? Math.round(s.getBoundingClientRect().height) : 0, on: on ? +on.dataset.m : null,
                         headPe: on ? getComputedStyle(on).pointerEvents : null }; }""")
            r0 = m.evaluate(ROWS)
            ok(f"{T} 週期統計有「排序：N 月 ›」鈕（高 ≥ 40、字跟表頭亮的那個月一致），表頭照樣可以點（次要入口，不准關成點不到）",
               s0["h"] >= 40 and s0["on"] and s0["lab"] == f"排序：{s0['on']} 月 ›" and s0["headPe"] != "none", s0)
            tgt = 3 if s0["on"] != 3 else 5
            tap(m, "#mSeasonSort")
            sh = m.evaluate("""() => { const s = document.getElementById('mSheet'); return { open: !!s && !s.hidden, kind: s && s.dataset.kind,
                n: s ? s.querySelectorAll('.mballgrid button[data-m]').length : 0,
                minH: s ? Math.min(...[...s.querySelectorAll('.mballgrid button[data-m]')].map(b => b.getBoundingClientRect().height)) : 0 }; }""")
            ok(f"{T} 點「排序」→ 底部抽屜打開、12 個月各一顆、每顆高 ≥ 40", sh["open"] and sh["kind"] == "seasonsort" and sh["n"] == 12 and sh["minH"] >= 40, sh)
            tap(m, f'#mSheet .mballgrid button[data-m="{tgt}"]'); m.wait_for_timeout(500)
            s1 = m.evaluate("""() => { const s = document.getElementById('mSeasonSort'), on = document.querySelector('#seasonHeatHead button.on');
                return { lab: s && s.textContent, on: on ? +on.dataset.m : null, sheet: (document.getElementById('mSheet') || { hidden: true }).hidden }; }""")
            r1 = m.evaluate(ROWS)
            ok(f"{T} 抽屜點「{tgt} 月」→ 抽屜收起、表頭改亮 {tgt} 月、鈕字跟著換、熱力圖的族群順序真的變了",
               s1["on"] == tgt and s1["lab"] == f"排序：{tgt} 月 ›" and s1["sheet"] and r1 and r1 != r0, {"前": s0, "後": s1, "列順序變了": r1 != r0})
            # ---- 個股頁「基本資料」的族群／題材連結 ≥ 40 高
            au.load({"name": "個股", "hash": f"#stock/{code}"})
            bars = m.evaluate(A.SEG_JS)
            st = next((f"{bar['sel']} > :nth-child({bt['nth']})" for bar in bars for bt in bar["btns"] if bt["label"].startswith("基本資料")), None)
            if st:
                au.load({"name": "個股基本資料", "hash": f"#stock/{code}", "steps": [st]})
                kv = m.evaluate("""() => [...document.querySelectorAll('.mbkv dd a')].filter(a => a.getClientRects().length)
                    .map(a => [a.textContent.trim().slice(0, 8), Math.round(a.getBoundingClientRect().height)])""")
                ok(f"{T} 個股頁「基本資料」的產業鏈／族群／題材／網站連結每顆高 ≥ 40", len(kv) >= 3 and all(h >= 40 for _, h in kv), kv)
                h0 = m.evaluate("() => location.hash")
                tap(m, '.mbkv dd a[href^="#industry/group/"]'); m.wait_for_timeout(500)
                ok(f"{T} 點族群連結（觸控）→ 真的換到族群頁", m.evaluate("() => location.hash").startswith("#industry/group/") and m.evaluate("() => location.hash") != h0,
                   m.evaluate("() => location.hash"))
            else:
                ok(f"{T} 個股頁找得到「基本資料」分段", False, bars)
        finally:
            m.close()
    # ---- ③ 桌機（1440）：不插章節鈕列與排序鈕，圖裡的章節列照樣可以點
    d = b.new_page(viewport={"width": 1440, "height": 950})
    d.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    try:
        d.goto(f"{base}#industry/semiconductor", wait_until="networkidle"); d.wait_for_timeout(2200)
        dk = d.evaluate("""() => { const g = document.querySelector('#prodDiagram g.dgfold'); return { lists: document.querySelectorAll('.mdgfolds').length,
            pe: g ? getComputedStyle(g).pointerEvents : null, foldon: document.querySelectorAll('.mfoldon').length }; }""")
        ok("[手機v4二批 1440px] 桌機不插章節鈕列、圖裡的章節列照樣接滑鼠", dk["lists"] == 0 and dk["foldon"] == 0 and dk["pe"] not in (None, "none"), dk)
        d.goto(f"{base}#season", wait_until="networkidle"); d.wait_for_timeout(1800)
        ok("[手機v4二批 1440px] 桌機週期統計沒有手機的排序鈕、表頭月份照樣可以點",
           d.evaluate("() => !document.getElementById('mSeasonSort') && getComputedStyle(document.querySelector('#seasonHeatHead button')).pointerEvents !== 'none'"))
    finally:
        d.close()


# ★ 2026-09-26 剖析圖覆蓋普查（Andy：「請檢查所有 2D 3D 圖說明有沒有覆蓋現象」）
#   量測本體在 scripts/_dg_overlap.py（單獨跑可以量 4 種寬度 × 2 種配色、附放大截圖），
#   這裡呼叫同一套 audit()：1440（抽屜開，預設）、1440c（抽屜關，三欄）、800 × 2D（收合＋全部段落展開）＋ 3D。
#   只看「元素存在」不算：① 先故意疊一行字在零件上，量測要抓得到（量測本身有效）
#   ② 真的點開每一個章節列（viewBox 變高＝畫面真的變了）③ 然後清單要是空的。
def t_dg_overlap(b, base):
    sys.path.insert(0, str(ROOT))
    import importlib
    ov = importlib.import_module("scripts._dg_overlap")
    pg = b.new_page(viewport={"width": 1440, "height": 950})
    pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
    try:
        # ① 量測本身有效：在第三代半導體主畫面的 SiC 剖面上疊一行字，要被抓成「文字被圖形蓋住／跨在邊緣」
        pg.goto(f"{base}#overview", wait_until="domcontentloaded")
        pg.evaluate("() => { try { localStorage.setItem('tw.dg3d', '0'); localStorage.setItem('tw.dgOpen', '1'); } catch (e) {} }")
        pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor/dg/wide_bandgap", wait_until="networkidle")
        wait_until(pg, "() => !!document.querySelector('#prodDiagram svg.dg')", 8000); pg.wait_for_timeout(800)
        r0 = pg.evaluate(ov.AUDIT2D_JS, {"host": "#prodDiagram", "tol": ov.TOL})
        planted = pg.evaluate("""() => { const svg = document.querySelector('#prodDiagram svg.dg'); const g = svg.querySelector('[data-part="wbg_sic_sub"]');
          if (!g) return false; const b = g.getBBox(); const t = document.createElementNS('http://www.w3.org/2000/svg', 'text');
          t.setAttribute('x', b.x - 30); t.setAttribute('y', b.y + b.height / 2); t.setAttribute('class', 'sub'); t.textContent = '故意疊上去的測試字串 PLANTED';
          g.parentNode.insertBefore(t, g); return true; }""")
        r1 = pg.evaluate(ov.AUDIT2D_JS, {"host": "#prodDiagram", "tol": ov.TOL})
        hit = [x for x in r1.get("issues", []) if "PLANTED" in x.get("a", "")]
        ok("覆蓋普查：量測本身有效（故意疊在 SiC 基板上的字被抓到）", planted and bool(hit),
           {"planted": planted, "before": len(r0.get("issues", [])), "after": len(r1.get("issues", [])), "hit": hit[:2]})
        # ② 章節列真的點得開：展開前後 viewBox 高度要變
        pg.goto("about:blank"); pg.goto(f"{base}#industry/semiconductor/dg/wide_bandgap", wait_until="networkidle")
        wait_until(pg, "() => !!document.querySelector('#prodDiagram svg.dg')", 8000); pg.wait_for_timeout(800)
        h0 = pg.evaluate("() => document.querySelector('#prodDiagram svg.dg').viewBox.baseVal.height")
        n = pg.evaluate(ov.EXPAND_FOLDS_JS, "#prodDiagram"); pg.wait_for_timeout(400)
        h1 = pg.evaluate("() => document.querySelector('#prodDiagram svg.dg').viewBox.baseVal.height")
        ok("覆蓋普查：全部段落展開＝章節列真的點開（viewBox 變高）", n >= 3 and h1 > h0 + 300, {"章節": n, "前": h0, "後": h1})
        # ③ 普查：清單要是空的
        logs: list[str] = []
        found = ov.audit(pg, base, widths=("1440", "1440c", "800"), modes=("2d", "3d"), pals=("tech",), shots=None, log=logs.append)
        measured = [x for x in logs if "問題" in x]
        ok("覆蓋普查：真的量到 40 張以上的圖 × 3 種版面", len(measured) >= 120, len(measured))
        broken = [f"{x['dg']}/{x['mode']}/{x['w']}：{x['kind']}" for x in found if x["kind"] in ("畫不出來", "3D 畫不出來", "量測失敗")]
        ok("覆蓋普查：每一張圖都畫得出來（2D 與 3D）", not broken, broken[:10])
        rest = [f"{x['dg']}/{x['mode']}/{x['w']}｜{x['sec']}｜{x['kind']}｜{x['a']} × {x['b']}｜{x['px']}px"
                for x in found if x["kind"] not in ("畫不出來", "3D 畫不出來", "量測失敗")]
        ok(f"覆蓋普查：文字被蓋／蓋圖／互疊／超出格子／卡片互蓋／3D 卡片蓋到零件 0 處（實際 {len(rest)} 處）", not rest, rest[:15])
    finally:
        pg.close()


# ===================================================================== 搜尋：近期搜尋／熱門股票／公司 Logo（2026-09-26）
# Andy 2026-09-26：「搜尋功能需要添『近期搜尋紀錄』、熱門股票，並且需要在名稱旁邊附上公司 Logo，包含查個個股也要附上 Logo」。
# 每一步都驗「畫面／localStorage 真的因此改變了」：
#   清空 → 聚焦看到熱門 10 筆與「還沒有搜尋紀錄」→ 搜尋 2330 進個股 → 回來聚焦近期第一筆是 2330
#   → × 刪單筆、「清除」全刪（localStorage 跟著變、下拉不收）→ 鍵盤上下 Enter 進得去、Esc 關
#   → 個股頁標題有 Logo → logos.json 回一筆圖時真的是 <img>、圖 404 時退回字母頭像、logos.json 404 也不報錯 → 390 不溢出。
SG_STATE = """() => { const s = document.getElementById('sugg'); const r = s.getBoundingClientRect();
    const rows = [...s.querySelectorAll('.sgrow[data-c]')];
    const hotHd = document.getElementById('sgHotHd');
    const hot = hotHd ? rows.filter(x => hotHd.compareDocumentPosition(x) & Node.DOCUMENT_POSITION_FOLLOWING) : [];
    const rec = rows.filter(x => !hot.includes(x));
    let ls = null; try { ls = localStorage.getItem('tw.search.recent'); } catch (e) {}
    return { open: s.style.display !== 'none' && r.height > 0, mode: s.dataset.mode || '',
      l: Math.round(r.left), r: Math.round(r.right), vw: innerWidth, sw: document.documentElement.scrollWidth,
      rec: rec.map(x => x.dataset.c), hot: hot.map(x => x.dataset.c),
      hotChg: hot.map(x => { const c = x.querySelector('.chg'); return c ? [c.textContent.trim(), c.className] : null; }),
      empty: !!document.getElementById('sgEmpty'), clr: !!document.getElementById('sgClr'),
      dels: s.querySelectorAll('.sgdel').length,
      logos: rows.filter(x => x.querySelector('.slogo')).length, n: rows.length,
      act: rows.findIndex(x => x.classList.contains('on')),
      aad: document.getElementById('q').getAttribute('aria-activedescendant') || '',
      minFs: Math.min(99, ...[...s.querySelectorAll('.sgrow span, .sghd span, .sghd small, .sgempty, .sgclr')]
        .filter(e => e.getClientRects().length).map(e => parseFloat(getComputedStyle(e).fontSize))),
      ls }; }"""
# 期望的熱門：全市場索引裡成交值前 10 的普通股（4 碼、不是 0 開頭）—— 跟產品同一個口徑，從頁面自己的資料算
SG_HOT_EXPECT = """() => (App.L.all || []).filter(s => /^[1-9]\\d{3}$/.test(String(s.code)) && +s.turnover > 0)
    .sort((a, b) => b.turnover - a.turnover).slice(0, 10).map(s => s.code)"""
SG_TITLE_LOGO = """() => { const h = document.querySelector('#stockPage h2'); if (!h) return null;
    const lg = h.querySelector('.slogo'); if (!lg) return { has: false, text: h.innerText };
    const img = lg.querySelector('img'); const r = lg.getBoundingClientRect();
    return { has: true, img: !!img, loaded: !!(img && img.complete && img.naturalWidth > 0),
      src: img ? img.getAttribute('src') : '', lazy: img ? img.getAttribute('loading') : '',
      letter: getComputedStyle(lg, '::before').content, w: Math.round(r.width), h: Math.round(r.height),
      edge: getComputedStyle(lg, '::after').boxShadow, text: h.innerText.trim(), cls: lg.className }; }"""
_PNG_1x1 = __import__("base64").b64decode(
    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==")


def _sg_focus(pg):
    """聚焦搜尋框（先點頁面別處讓它失焦，確保 focus 事件真的觸發）。"""
    pg.evaluate("() => { const q = document.getElementById('q'); q.blur(); q.value = ''; }")
    pg.click("#q"); pg.wait_for_timeout(350)
    return pg.evaluate(SG_STATE)


