# ===================================================================== 自選走勢與搜尋對齊（2026-10-01，DECISIONS #282）
# Andy 2026-10-01：搜尋下拉「熱門股票」的小走勢圖起點不齊（名稱長短不同就前後移、還壓到名稱）；
# 自選頁要用滿寬、每列加走勢圖、點走勢圖在下面展開（走勢／K 線＋週期）、再點收起、點名稱照舊進個股頁。
# 每一步都驗「畫面真的變了」：left 一致、展開那一列真的出現、換 K 線後 KChart 真的在、換週期後根數真的變。
WS_SG = """() => { const s = document.getElementById('sugg');
    const rows = [...s.querySelectorAll('.sgrow[data-c]')].filter(r => r.getClientRects().length);
    const L = (sel) => rows.map(r => { const e = r.querySelector(sel); return e ? Math.round(e.getBoundingClientRect().left * 2) / 2 : null; });
    const R = (sel) => rows.map(r => { const e = r.querySelector(sel); return e ? Math.round(e.getBoundingClientRect().right * 2) / 2 : null; });
    const ov = rows.filter(r => { const n = r.querySelector('.nm'), k = r.querySelector('.spkw'); return n && k && n.getBoundingClientRect().right > k.getBoundingClientRect().left + 0.5; }).map(r => r.dataset.c);
    const sr = s.getBoundingClientRect(), inR = sr.left + s.clientLeft + s.clientWidth;
    const clip = rows.filter(r => { const e = r.querySelector('.chg'); return e && e.getBoundingClientRect().right > inR + 0.5; }).map(r => r.dataset.c);
    return { n: rows.length, spk: L('.spkw'), tvR: R('.tv').filter(x => x != null), chgR: R('.chg').filter(x => x != null), ov, clip,
      nchg: rows.filter(r => r.querySelector('.chg')).length,
      sw: document.documentElement.scrollWidth, vw: innerWidth }; }"""
WS_ST = """() => { const t = document.getElementById('wpTbl'); const card = document.querySelector('#v-watch .wpcard');
    const main = document.querySelector('#v-watch');
    const rows = t ? [...t.querySelectorAll('tbody tr[data-go]')] : [];
    const x = document.querySelector('tr.wpexp'), c = document.getElementById('wpxC');
    return { rows: rows.length, spk: rows.filter(r => r.querySelector('.wpspk svg.spk')).length,
      spkBtn: rows.filter(r => r.querySelector('.wpspk')).length,
      cardW: card ? Math.round(card.getBoundingClientRect().width) : 0, mainW: main ? Math.round(main.getBoundingClientRect().width) : 0,
      exp: x ? x.dataset.expRow : null, nexp: document.querySelectorAll('tr.wpexp').length,
      prev: x ? (x.previousElementSibling || {}).dataset?.go : null,
      h: c ? Math.round(c.getBoundingClientRect().height) : 0, w: c ? Math.round(c.getBoundingClientRect().width) : 0,
      state: c ? c.dataset.state : null, mode: c ? c.dataset.mode : null, tf: c ? c.dataset.tf : null, n: c ? +(c.dataset.n || 0) : 0,
      seq: c ? c.dataset.seq : null,
      canvas: c ? c.querySelectorAll('canvas').length : 0, ec: c && window.echarts ? !!echarts.getInstanceByDom(c) : false,
      sw: document.documentElement.scrollWidth, vw: innerWidth, hash: location.hash }; }"""
# 2026-10-02（DECISIONS #290）小走勢精確化：每一張 svg.spk 的輔助繪製與數值口徑
#   fr＝外框、bl＝基準虛線（要真的有 dasharray）、ar＝面積、dot＝終點圓點、n＝點數、
#   Y 範圍（data-ymin／ymax）要包含基準、而且至少基準的 3%（小波動不准撐滿整格）、
#   圓點要在折線最後一點上、虛線的 y 要等於用基準價算出來的 y。
WS_SPK = """(sel) => [...document.querySelectorAll(sel)].map(s => {
    const W = +s.getAttribute('width'), H = +s.getAttribute('height');
    const fr = s.querySelector('rect.fr'), bl = s.querySelector('line.bl'), ar = s.querySelector('polygon.ar'),
          pl = s.querySelector('polyline'), dot = s.querySelector('circle.dot');
    const pts = pl ? pl.getAttribute('points').trim().split(' ').map(x => x.split(',').map(Number)) : [];
    const lastP = pts[pts.length - 1] || [NaN, NaN];
    const ymin = +s.dataset.ymin, ymax = +s.dataset.ymax, bse = +s.dataset.base;
    const ybCalc = H - 1.5 - (bse - ymin) / (ymax - ymin) * (H - 3);
    const cs = (e, k) => e ? getComputedStyle(e)[k] : '';
    const row = s.closest('tr[data-go]'), cell = row ? row.querySelector('[data-live="close"]') : null;
    return { code: (s.closest('[data-spk]') || {}).dataset?.spk || '', W, H, n: +s.dataset.n, k: s.dataset.k,
      fr: !!fr, frStroke: cs(fr, 'stroke'), frOp: +cs(fr, 'strokeOpacity'),
      bl: !!bl, dash: cs(bl, 'strokeDasharray'), blY: bl ? +bl.getAttribute('y1') : NaN, ybCalc,
      ar: !!ar, arOp: +cs(ar, 'fillOpacity'), dot: !!dot,
      dotOnLast: dot ? Math.abs(+dot.getAttribute('cx') - lastP[0]) < 0.2 && Math.abs(+dot.getAttribute('cy') - lastP[1]) < 0.2 : false,
      npl: pts.length, ymin, ymax, base: bse, last: +s.dataset.last, first: +s.dataset.first,
      stroke: cs(pl, 'stroke'), tip: s.dataset.tip || '',
      rowPx: cell ? parseFloat(cell.textContent.replace(/,/g, '')) : null }; })"""


def ws_spk_check(T, W, lst, where):
    """小走勢的共用斷言（搜尋下拉與自選列都用這一組）。"""
    ok(f"{T}{W} {where}小走勢都有外框與基準虛線", bool(lst) and all(x["fr"] and x["bl"] and x["dash"] not in ("", "none") for x in lst),
       [(x["code"], x["fr"], x["bl"], x["dash"]) for x in lst][:6])
    ok(f"{T}{W} {where}外框看得見（描邊不透明度 > 0.2）", all(x["frStroke"] not in ("", "none") and x["frOp"] > 0.2 for x in lst),
       [(x["code"], x["frStroke"], x["frOp"]) for x in lst][:4])
    ok(f"{T}{W} {where}小走勢點數 ≥ 30（不是只剩幾個轉折）", all(x["n"] >= 30 and x["npl"] == x["n"] for x in lst),
       [(x["code"], x["k"], x["n"], x["npl"]) for x in lst])
    ok(f"{T}{W} {where}Y 範圍包含基準線", all(x["ymin"] <= x["base"] <= x["ymax"] and 0 <= x["blY"] <= x["H"] for x in lst),
       [(x["code"], x["ymin"], x["base"], x["ymax"], x["blY"]) for x in lst][:6])
    ok(f"{T}{W} {where}基準虛線畫在基準價的位置", all(abs(x["blY"] - x["ybCalc"]) <= 0.15 for x in lst),
       [(x["code"], x["blY"], round(x["ybCalc"], 2)) for x in lst][:6])
    ok(f"{T}{W} {where}Y 範圍至少基準 ±1.5%（小波動不撐滿整格）", all(x["ymax"] - x["ymin"] >= x["base"] * 0.03 - 1e-6 for x in lst),
       [(x["code"], round((x["ymax"] - x["ymin"]) / x["base"] * 100, 2)) for x in lst][:6])
    ok(f"{T}{W} {where}有線下面積與終點圓點（圓點就在最後一點）", all(x["ar"] and 0 < x["arOp"] < 0.5 and x["dot"] and x["dotOnLast"] for x in lst),
       [(x["code"], x["ar"], x["arOp"], x["dotOnLast"]) for x in lst][:6])
    ok(f"{T}{W} {where}提示框文字寫了期間、起訖、漲跌幅", all("交易日" in x["tip"] and "起 " in x["tip"] and "訖 " in x["tip"] and "%" in x["tip"] for x in lst),
       [x["tip"] for x in lst][:2])


def t_watch_spark(b, base):
    T = "[自選走勢1001]"
    errs: list[str] = []
    # 2026-10-02：Andy 這次的截圖是 1440；800 保留（窄畫面）、390 手機
    for W in (1440, 800, 390):
        ctx = b.new_context(viewport={"width": W, "height": 1000})
        pg = ctx.new_page()
        pg.on("pageerror", lambda e: errs.append(f"{W}: {e}"))
        pg.route("**/fonts.googleapis.com/**", lambda r: r.abort())
        pg.goto(base + "#overview", wait_until="networkidle")
        wait_until(pg, "() => window.App && App.L && App.L.all && App.L.all.length > 0 && !!window.TwWatch", 8000)

        # ---- ① 搜尋下拉：熱門股票每一列的走勢圖起點一致、不壓名稱、成交值／漲跌幅右緣對齊
        # 手機的搜尋框收在頂列「⌕」鈕（#mSearchBtn）後面，打開的是同一個 #sugg —— 390 也要驗，不准跳過
        qvis = pg.evaluate("() => !!document.getElementById('q') && document.getElementById('q').getClientRects().length > 0")
        if True:
            try:
                pg.evaluate("() => { const q = document.getElementById('q'); q.blur(); q.value = ''; }")
                pg.click("#q" if qvis else "#mSearchBtn"); wait_until(pg, "() => document.querySelectorAll('#sugg .spkw svg').length >= 5", 5000)
                s = pg.evaluate(WS_SG)
                spk = [x for x in s["spk"] if x is not None]
                ok(f"{T}{W} 搜尋下拉各列走勢圖 left 一致", s["n"] >= 5 and len(spk) == s["n"] and max(spk) - min(spk) <= 0.5, s)
                ok(f"{T}{W} 名稱不壓到走勢圖", not s["ov"], s)
                # 欄寬固定後一列變長：以前桌機下拉 340px，漲跌幅整欄被擠到框外看不到 —— 驗它真的在框裡
                ok(f"{T}{W} 漲跌幅在下拉框裡看得到（沒被擠出去）", s["nchg"] >= 5 and not s["clip"], s)
                ok(f"{T}{W} 成交值、漲跌幅右緣對齊", len(s["tvR"]) >= 5 and max(s["tvR"]) - min(s["tvR"]) <= 0.5
                   and max(s["chgR"]) - min(s["chgR"]) <= 0.5, s)
                ok(f"{T}{W} 搜尋下拉不撐出橫向捲軸", s["sw"] <= s["vw"], s)
                # 2026-10-02（#290）：熱門股票的小走勢＝外框＋基準虛線＋面積＋終點圓點、≥30 點、Y 範圍含基準
                ws_spk_check(T, W, pg.evaluate(WS_SPK, "#sugg .sgrow[data-c] .spkw svg.spk"), "搜尋下拉")
                # 滑上去 → 提示框真的出現、寫的是那一張的期間與漲跌（390 是觸控寬度，桌機才驗）
                if W >= 800:
                    pg.hover("#sugg .sgrow[data-c] .spkw svg.spk"); pg.wait_for_timeout(150)
                    tip = pg.evaluate("""() => { const t = document.querySelector('.spktip'); const s = document.querySelector('#sugg .sgrow[data-c] .spkw svg.spk');
                        if (!t || t.hidden) return null; const r = t.getBoundingClientRect();
                        return { txt: t.textContent, want: s.dataset.tip.split('\\n')[0], vis: r.width > 40 && r.right <= innerWidth + 1 && r.bottom <= innerHeight + 1 }; }""")
                    ok(f"{T}{W} 滑到搜尋小走勢 → 提示框出現、寫那一張的期間與漲跌", bool(tip) and tip["vis"] and tip["want"] in tip["txt"] and "%" in tip["txt"], tip)
                    pg.mouse.move(2, 2); pg.wait_for_timeout(100)
                    ok(f"{T}{W} 滑開 → 提示框收起", pg.evaluate("() => { const t = document.querySelector('.spktip'); return !t || t.hidden; }"), "提示框沒收")
                pg.keyboard.press("Escape")
            except Exception as e:
                ok(f"{T}{W} 搜尋下拉打得開", False, str(e)[:200])

        # ---- ② 自選頁：放三檔（名稱長短不同），用滿寬、每列有走勢圖
        pg.evaluate("""() => { const T = TwWatch; T.curTab().codes.slice().forEach(c => T.remove(c));
            ['2330', '2454', '1303'].forEach(c => T.add(c)); }""")
        pg.goto(base + "#watch", wait_until="networkidle")
        wait_until(pg, "() => document.querySelectorAll('#wpTbl .wpspk svg.spk').length >= 3", 6000)
        st = pg.evaluate(WS_ST)
        ok(f"{T}{W} 自選列都有走勢圖", st["rows"] == 3 and st["spk"] == 3, st)
        ok(f"{T}{W} 自選卡片用滿內容寬（不再是置中窄卡）", st["cardW"] >= st["mainW"] - 40, st)
        ok(f"{T}{W} 自選頁沒有橫向捲軸", st["sw"] <= st["vw"], st)
        wl = pg.evaluate(WS_SPK, "#wpTbl .wpspk svg.spk")
        ws_spk_check(T, W, wl, "自選列")
        ok(f"{T}{W} 自選列小走勢最後一點跟列上現價差 < 1%",
           all(x["rowPx"] and abs(x["last"] / x["rowPx"] - 1) < 0.01 for x in wl), [(x["code"], x["last"], x["rowPx"]) for x in wl])
        ok(f"{T}{W} 自選列小走勢用實際像素畫（沒被 CSS 拉伸，圓點不會變橢圓）",
           all(abs(pg.evaluate("(c) => document.querySelector(`#wpTbl .wpspk[data-exp='${c}'] svg.spk`).getBoundingClientRect().width", x["code"]) - x["W"]) < 0.6 for x in wl),
           [(x["code"], x["W"]) for x in wl])

        # ---- ③ 點走勢圖 → 那一列下方展開一張圖（預設走勢）
        pg.click('#wpTbl .wpspk[data-exp="2330"]')
        wait_until(pg, "() => { const c = document.getElementById('wpxC'); return c && c.dataset.state === 'ok'; }", 8000)
        st = pg.evaluate(WS_ST)
        ok(f"{T}{W} 點走勢圖在那一列下方展開", st["exp"] == "2330" and st["prev"] == "2330" and st["nexp"] == 1, st)
        ok(f"{T}{W} 展開圖高 250～330、真的畫了線", 250 <= st["h"] <= 330 and st["mode"] == "line" and st["ec"] and st["n"] >= 2, st)
        ok(f"{T}{W} 展開不離開自選頁", st["hash"] == "#watch", st)
        # 2026-10-02（#290）：展開大圖跟列上小圖同一份資料、同一段期間 —— 點數、第一點、最後一點、基準逐一相同
        xs = pg.evaluate("""() => { const c = document.getElementById('wpxC'), s = document.querySelector('#wpTbl .wpspk[data-exp="2330"] svg.spk');
            const i = echarts.getInstanceByDom(c), o = i.getOption(), sr = o.series[0];
            const ml = ((sr.markLine || {}).data || []).find(d => d.yAxis != null);
            return { n: +c.dataset.n, first: +c.dataset.first, last: +c.dataset.last, base: +c.dataset.base, ymin: +c.dataset.ymin, ymax: +c.dataset.ymax,
              sn: +s.dataset.n, sfirst: +s.dataset.first, slast: +s.dataset.last, sbase: +s.dataset.base,
              ml: ml ? ml.yAxis : null, data: sr.data.length, note: document.getElementById('wpxNote').textContent }; }""")
        ok(f"{T}{W} 展開大圖與列上小圖同一份資料（點數／起／訖／基準相同）",
           xs["n"] == xs["sn"] == xs["data"] and xs["n"] >= 30 and abs(xs["first"] - xs["sfirst"]) < 1e-6
           and abs(xs["last"] - xs["slast"]) < 1e-6 and abs(xs["base"] - xs["sbase"]) < 1e-6, xs)
        ok(f"{T}{W} 展開大圖有昨收虛線、Y 軸包含它", xs["ml"] is not None and abs(xs["ml"] - xs["base"]) < 1e-6
           and xs["ymin"] <= xs["base"] <= xs["ymax"], xs)
        ok(f"{T}{W} 展開大圖小註寫出期間、起訖與漲跌幅", "交易日" in xs["note"] and "起 " in xs["note"] and "訖 " in xs["note"] and "%" in xs["note"], xs["note"])
        # Y 軸刻度標籤彼此不重疊（以前手算 min／max 會在 4,900 底下多冒一個 4,878 疊在一起）
        yov = pg.evaluate("""() => { const i = echarts.getInstanceByDom(document.getElementById('wpxC'));
            const ys = i.getModel().getComponent('yAxis').axis.getTicksCoords().map(t => t.coord).sort((a, b) => a - b);
            let m = 1e9; for (let k = 1; k < ys.length; k++) m = Math.min(m, ys[k] - ys[k - 1]); return Math.round(m); }""")
        ok(f"{T}{W} 展開走勢圖 Y 軸刻度間距夠（標籤不疊）", yov >= 14, yov)
        if W == 390:
            ok(f"{T}{W} 手機展開圖用滿寬（扣卡片內距）", st["w"] >= st["cardW"] - 50, st)
            ok(f"{T}{W} 手機自選表不超出卡片", pg.evaluate("() => document.getElementById('wpTbl').getBoundingClientRect().right <= document.querySelector('#v-watch .wpcard').getBoundingClientRect().right + 1"), "表格右緣超出卡片")

        # ---- ④ 切 K 線 → KChart（canvas）取代走勢線
        pg.click('tr.wpexp button[data-xm="k"]')
        wait_until(pg, "() => { const c = document.getElementById('wpxC'); return c && c.dataset.mode === 'k' && c.dataset.state === 'ok'; }", 8000)
        k1 = pg.evaluate(WS_ST)
        ok(f"{T}{W} 切 K 線後圖真的換了（canvas、不是 ECharts）", k1["mode"] == "k" and k1["tf"] == "1d" and k1["canvas"] > 0 and not k1["ec"] and k1["n"] > 20, k1)

        # ---- ⑤ 切週期 → 真的重畫（根數變了、序號變了）
        for tf in ("60m", "240m", "1w"):
            pg.click(f'tr.wpexp button[data-xtf="{tf}"]')
            wait_until(pg, f"() => {{ const c = document.getElementById('wpxC'); return c && c.dataset.tf === '{tf}' && c.dataset.state; }}", 8000)
            k2 = pg.evaluate(WS_ST)
            ok(f"{T}{W} 切到 {tf} 真的重畫", k2["tf"] == tf and k2["seq"] != k1["seq"]
               and (k2["n"] != k1["n"] or k2["state"] == "empty"), {"前": k1, "後": k2})
            k1 = k2

        # ---- ⑥ 只展開一列：點另一列 → 舊的收起、新的展開
        pg.click('#wpTbl .wpspk[data-exp="1303"]')
        wait_until(pg, "() => { const x = document.querySelector('tr.wpexp'); return x && x.dataset.expRow === '1303'; }", 6000)
        st = pg.evaluate(WS_ST)
        ok(f"{T}{W} 同時只展開一列", st["nexp"] == 1 and st["exp"] == "1303", st)

        # ---- ⑦ 再點同一格 → 收起
        pg.click('#wpTbl .wpspk[data-exp="1303"]'); pg.wait_for_timeout(250)
        st = pg.evaluate(WS_ST)
        ok(f"{T}{W} 再點一次收起", st["nexp"] == 0 and st["hash"] == "#watch", st)

        # ---- ⑧ 點名稱 → 照舊進個股頁
        pg.click('#wpTbl tr[data-go="2454"] .wpgo')
        wait_until(pg, "() => location.hash.startsWith('#stock/')", 4000)
        ok(f"{T}{W} 點名稱進個股頁", pg.evaluate("() => location.hash") == "#stock/2454", pg.evaluate("() => location.hash"))
        # ---- ⑨ 淺色主題：小走勢的線色跟著主題換（紅漲綠跌吃 --rise／--fall），外框照樣看得見
        if W == 1440:
            def _spk_cols():
                return pg.evaluate("""() => { const r = getComputedStyle(document.documentElement);
                    const tok = (k) => { const d = document.createElement('i'); d.style.color = r.getPropertyValue(k); document.body.appendChild(d); const c = getComputedStyle(d).color; d.remove(); return c; };
                    const s = [...document.querySelectorAll('#wpTbl svg.spk')];
                    return { theme: document.documentElement.getAttribute('data-theme') || 'dark', rise: tok('--rise'), fall: tok('--fall'),
                      lines: s.map(x => [x.classList.contains('up') ? 'up' : x.classList.contains('down') ? 'down' : 'flat', getComputedStyle(x.querySelector('polyline')).stroke]),
                      fr: s.map(x => { const f = x.querySelector('rect.fr'); return f ? +getComputedStyle(f).strokeOpacity : 0; }) }; }""")
            pg.goto(base + "#watch", wait_until="networkidle")
            wait_until(pg, "() => document.querySelectorAll('#wpTbl .wpspk svg.spk').length >= 3", 6000)
            c1 = _spk_cols()
            dg_set_theme(pg, "light" if c1["theme"] != "light" else "dark", 600)
            wait_until(pg, "() => document.querySelectorAll('#wpTbl .wpspk svg.spk').length >= 3", 6000)
            c2 = _spk_cols()
            for c in (c1, c2):
                ok(f"{T}{W} {c['theme']} 主題小走勢紅漲綠跌、外框看得見",
                   all((k != "up" or st_ == c["rise"]) and (k != "down" or st_ == c["fall"]) for k, st_ in c["lines"]) and all(o > 0.2 for o in c["fr"]), c)
            changed(f"{T}{W} 切主題後小走勢線色真的換了", [x[1] for x in c1["lines"]], [x[1] for x in c2["lines"]])
            dg_set_theme(pg, c1["theme"], 300)
        ctx.close()
    ok(f"{T} 沒有 pageerror", not errs, errs[:5])


# ===================================================================== 版面 v2 結構（2026-10-02，DECISIONS #291）
L4_NAV = """() => { const t = document.querySelector('.topbar'), m = document.querySelector('main');
    const r = t.getBoundingClientRect(), cs = getComputedStyle(t);
    return { mini: document.documentElement.classList.contains('l4-mini'), l4: document.documentElement.classList.contains('l4'),
      navW: Math.round(r.width), barH: Math.round(r.height), pos: cs.position, left: Math.round(r.left),
      // 左欄看得到的範圍：底色畫在 .topbar::before（從上到下）。2026-10-03 第三批最底下是「淺色｜深色」（#l4Mode）；
      // 第四批（DECISIONS #312）登入／明暗搬到右上角，左欄最底下就是頁面清單本身（#tabsWrap）
      bgH: (() => { const b = getComputedStyle(t, '::before'); return b.position === 'fixed' && b.top === '0px' && b.bottom === '0px' ? innerHeight : 0; })(),
      footB: (() => { const f = document.getElementById('tabsWrap'); return f ? Math.round(f.getBoundingClientRect().bottom) : -1; })(), vh: innerHeight,
      mainL: Math.round(m.getBoundingClientRect().left), mainW: Math.round(m.getBoundingClientRect().width),
      pref: (() => { try { return localStorage.getItem('tw.layout4.nav'); } catch (e) { return 'x'; } })(),
      sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth, hash: location.hash }; }"""
L4_JUMP = """() => { const j = document.getElementById('l4Jump'); if (!j) return null;
    const bs = [...j.querySelectorAll('.chips button')];
    return { shown: !j.hidden && j.getClientRects().length > 0, n: bs.length, labels: bs.map(b => b.textContent),
      on: bs.findIndex(b => b.classList.contains('on')), bottom: Math.round(j.getBoundingClientRect().bottom),
      top: Math.round(j.getBoundingClientRect().top), sy: Math.round(scrollY) }; }"""


L4_MHEAD = """() => { const h = document.getElementById('l4Head'); if (!h || !h.getClientRects().length) return null;
    const p = h.querySelector('p'), r = h.getBoundingClientRect();
    const fs = [...h.querySelectorAll('.eyebrow, h1, p')].map(e => parseFloat(getComputedStyle(e).fontSize));
    const tops = [...h.querySelectorAll('.eyebrow, h1, p')].map(e => Math.round(e.getBoundingClientRect().top));
    return { eb: (h.querySelector('.eyebrow') || {}).textContent, h1: (h.querySelector('h1') || {}).textContent, p: p ? p.textContent : '',
      h: Math.round(r.height), oneLine: Math.max(...tops) - Math.min(...tops) <= 6, ell: !!p && p.scrollWidth > p.clientWidth && getComputedStyle(p).textOverflow === 'ellipsis',
      minFs: Math.min(...fs), sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth }; }"""
L4_MPAGER = """() => { const v = document.querySelector('.view.on'), mp = v && v.querySelector(':scope > .mpager'), sp = v && v.querySelector(':scope > .mspine');
    const vis = e => !!e && !e.hidden && e.getClientRects().length > 0; const j = document.getElementById('l4Jump');
    const on = mp ? mp.querySelector('button.on') : null, cs = on ? getComputedStyle(on) : null;
    return { pager: vis(mp), spine: vis(sp), jump: vis(j), spineH: sp && vis(sp) ? Math.round(sp.getBoundingClientRect().height) : 0,
      pos: mp ? getComputedStyle(mp).position : '', stTop: mp ? parseFloat(getComputedStyle(mp).top) : null,
      top: mp ? Math.round(mp.getBoundingClientRect().top) : null, on: on ? on.textContent.trim() : null,
      onUnified: !!cs && cs.color === cs.borderTopColor && cs.color !== getComputedStyle(document.body).backgroundColor,
      sy: Math.round(scrollY) }; }"""
L4_SIDE = """() => { const s = document.getElementById('side'), k = document.getElementById('sideBack'), r = s.getBoundingClientRect();
    return { open: s.classList.contains('open'), top: Math.round(r.top), bottom: Math.round(r.bottom), left: Math.round(r.left), right: Math.round(r.right),
      vw: innerWidth, vh: innerHeight, back: k.classList.contains('on') }; }"""


def t_layout4(b, base, code):
    """V2 分支的版面結構搬到設計 v4（Andy 2026-10-02：「只做排版，不改配色、不改功能」）。

    每一項都用真的滑鼠／觸控操作，驗「畫面真的因此改變了」：
      ① 桌機 1440：左側導覽固定在左邊、主內容讓出導覽寬；分組順序＝今日市場／資金流水／族群與個股／歷史規律／專案
         （2026-10-03 Andy：「錢往哪裡跑」改名「資金流水」）
      ② 點分組裡的頁面 → 路由真的換了（hash、.tab.on、.view.on、頁首的頁名與分組小標都跟著換）
      ③ 收合 → 導覽寬度真的變窄、主內容真的變寬、localStorage 記住；重新整理後還是收合；展開再重新整理也記得
      ④ 「本頁功能」膠囊：點了捲到對應卡片（卡片頂端落在跳轉列下面）、那顆亮起；用滾輪捲回去，亮起的膠囊跟著變
      ⑤ 事件抽屜：打開（從視窗頂端起、遮罩不蓋左欄）、點遮罩關、Esc 關、× 關
      ⑥ 左欄底部的「外觀」面板與搜尋下拉都完整在視窗內
      ⑦ 1100（沒按過收合）預設收成圖示列；圖示列的頁面有滑鼠提示
      ⑧ ≤820（手機版暫停，Andy 2026-10-03）：390（總覽／資金流向／個股）與 768（總覽／個股）沒有任何 l4 痕跡 ——
         html 沒有 l4 class、沒有 #l4 開頭的節點、底部列高度＝停用 layout4.css 時當場量的高度；手機底部仍是文字符號、分段列不是 sticky；
         768 → 拉寬 1440 整套掛回來、再縮到 800 撤乾淨。（第二批手機斷言的量測字串 L4_MHEAD／L4_MPAGER／L4_SIDE 留著，手機版接回來時用）
    """
    T = "[版面v2結構]"
    errs: list[str] = []

    # ---------------- 桌機 1440 ----------------
    ctx = b.new_context(viewport={"width": 1440, "height": 900})
    pg = ctx.new_page()
    pg.on("pageerror", lambda e: errs.append(f"1440: {e}"))
    try:
        pg.goto(f"{base}#overview", wait_until="networkidle")
        pg.evaluate("() => { try { localStorage.removeItem('tw.layout4.nav'); } catch (e) {} }")
        pg.reload(wait_until="networkidle")
        wait_until(pg, "() => !!document.getElementById('l4NavBtn') && !!document.querySelector('#l4Head h1')", 8000)
        n0 = pg.evaluate(L4_NAV)
        ok(f"{T}1440 掛上新版面、沒按過收合時是展開的", n0["l4"] and not n0["mini"], n0)
        ok(f"{T}1440 導覽固定在左邊、底色從上到下整個視窗高、頁面清單撐到視窗底部", n0["pos"] == "fixed" and n0["left"] == 0
           and 200 <= n0["navW"] <= 240 and n0["bgH"] == n0["vh"] and n0["vh"] - 40 <= n0["footB"] <= n0["vh"], n0)
        # .topbar 的盒子只能是「頂端被蓋住的那一條」（＝跳轉列高）：industry.js 的指標面板拿它的下緣判斷按鈕有沒有被蓋住
        ok(f"{T}1440 .topbar 盒子高＝頂端那一條（≤ 60px，不是整個視窗高）", n0["barH"] <= 60, n0)
        ok(f"{T}1440 主內容讓出導覽寬（不被蓋住）", abs(n0["mainL"] - n0["navW"]) <= 2, n0)
        ok(f"{T}1440 沒有橫向捲軸", n0["sw"] <= n0["cw"] + 1, n0)
        grp = pg.evaluate("""() => { const tabs = [...document.querySelectorAll('#tabs .tab')].filter(t => t.getClientRects().length);
            tabs.sort((a, b) => a.getBoundingClientRect().top - b.getBoundingClientRect().top);
            return { order: tabs.map(t => t.dataset.view),
              labels: tabs.map(t => getComputedStyle(t, '::before').content).filter(c => c && c !== 'none' && c !== 'normal').map(c => c.replace(/"/g, '')),
              icons: tabs.filter(t => /svg/.test(getComputedStyle(t, '::after').maskImage || getComputedStyle(t, '::after').webkitMaskImage || '')).length,
              n: tabs.length }; }""")
        ok(f"{T}1440 頁面依分組排：總覽｜資金流向、熱力圖｜產業地圖、市場明細｜週期統計｜自選",
           grp["order"] == ["overview", "flow", "heatmap", "industry", "market", "season", "watch"], grp)
        ok(f"{T}1440 分組標題依序是 今日市場／資金流水／族群與個股／歷史規律／專案",
           grp["labels"] == ["今日市場", "資金流水", "族群與個股", "歷史規律", "專案"], grp)
        ok(f"{T}1440 每一頁都有線條圖示", grp["icons"] == grp["n"], grp)

        # ② 點分組裡的頁面 → 切路由
        for view, name, g in (("flow", "資金流向", "資金流水"), ("heatmap", "熱力圖", "資金流水"),
                              ("season", "週期統計", "歷史規律"), ("overview", "總覽", "今日市場")):
            pg.locator(f"#tabs .tab[data-view='{view}']").click(timeout=6000)
            got = wait_until(pg, f"""() => location.hash.startsWith('#{view}') && document.querySelector('#v-{view}.on')
                && ((document.querySelector('#l4Head h1') || {{}}).firstChild || {{}}).textContent === '{name}' ? 1 : 0""", 6000)
            st = pg.evaluate("""() => ({ hash: location.hash, on: (document.querySelector('#tabs .tab.on') || {}).dataset?.view,
                view: (document.querySelector('.view.on') || {}).id, h1: (document.querySelector('#l4Head h1') || {}).textContent,
                kids: [...document.querySelectorAll('#l4Head > *')].map(e => e.tagName.toLowerCase() + (e.className ? '.' + e.className : '')),
                clock: (document.querySelector('#l4Head .l4clock') || { dataset: {} }).dataset.t || '' })""")
            # 2026-10-03 第三批（Andy：「紅框處 只留下 總覽 及當下日期時間（所有分頁都是）」）：
            # 改前驗「分組小標＝{g}、說明句 ≥ 10 字」→ 改後驗頁首只剩 h1＋時間兩樣
            # 第四批（DECISIONS #312）：右邊多一塊工具列（☀、外觀、登入 —— Andy：「都放在右上」）
            ok(f"{T}1440 點導覽「{name}」→ 路由真的換到 #{view}（分頁亮、頁面換、頁首換）、頁首只剩頁名＋時間＋右上角工具",
               bool(got) and st["on"] == view and st["kids"] == ["h1", "time.l4clock", "div.l4tools"] and len(st["clock"]) >= 19, st)

        # ③ 收合／展開，寬度真的變、重新整理後還在
        pg.locator("#l4NavBtn").click(timeout=6000)
        wait_until(pg, "() => document.documentElement.classList.contains('l4-mini')", 3000)
        pg.wait_for_timeout(250)
        n1 = pg.evaluate(L4_NAV)
        ok(f"{T}1440 按「收合導覽」→ 導覽真的變窄（只剩圖示）", n1["mini"] and n1["navW"] <= 80 and n1["navW"] < n0["navW"] - 100, {"前": n0, "後": n1})
        ok(f"{T}1440 收合後頁面清單仍撐到視窗底部（中間清單高度重算過）", n1["vh"] - 60 <= n1["footB"] <= n1["vh"], n1)
        ok(f"{T}1440 收合後主內容真的變寬", n1["mainW"] >= n0["mainW"] + 100 and abs(n1["mainL"] - n1["navW"]) <= 2, {"前": n0["mainW"], "後": n1["mainW"]})
        ok(f"{T}1440 收合狀態寫進 localStorage", n1["pref"] == "mini", n1)
        tip = pg.evaluate("() => [...document.querySelectorAll('#tabs .tab')].filter(t => t.getClientRects().length).map(t => t.title)")
        ok(f"{T}1440 圖示列的每一頁都有滑鼠提示（字收掉了，靠 title 認）", all(tip) and len(tip) >= 7, tip)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(600)
        n2 = pg.evaluate(L4_NAV)
        ok(f"{T}1440 重新整理後還是收合", n2["mini"] and n2["navW"] <= 80, n2)
        pg.locator("#l4NavBtn").click(timeout=6000); pg.wait_for_timeout(300)
        n3 = pg.evaluate(L4_NAV)
        ok(f"{T}1440 再按一次 → 展開、寬度回來", not n3["mini"] and abs(n3["navW"] - n0["navW"]) <= 2 and n3["pref"] == "full", n3)
        pg.reload(wait_until="networkidle"); pg.wait_for_timeout(600)
        n4 = pg.evaluate(L4_NAV)
        ok(f"{T}1440 重新整理後還是展開（記得的是使用者按的，不是視窗寬）", not n4["mini"] and abs(n4["navW"] - n0["navW"]) <= 2, n4)

        # ④ 2026-10-03 第三批（Andy：「紅框處 只留下 總覽 及當下日期時間」）：
        #   改前：「本頁功能」膠囊點了捲過去、捲動時亮起的跟著變 → 改後：那一排拿掉（DOM 留著、看不到），
        #   頁首（頁名＋時間）頂替它黏在視窗最上面 —— 捲下去之後頁首還在頂端、而且 .topbar 盒子高＝頁首高（trackPop 的前提）
        # 總覽夠長（資金流向拆子分頁後單一子分頁不一定捲得到 900px）
        pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(1200)
        jh = pg.evaluate("""() => { const j = document.getElementById('l4Jump'); return { dom: !!j, seen: !!j && j.getClientRects().length > 0 }; }""")
        ok(f"{T}#overview 「本頁功能」那一排看不到（只藏不刪：DOM 還在）", jh["dom"] and not jh["seen"], jh)
        pg.mouse.move(700, 20)
        pg.evaluate("() => window.scrollTo({ top: 900, behavior: 'instant' })"); pg.wait_for_timeout(500)
        hs = pg.evaluate("""() => { const h = document.getElementById('l4Head').getBoundingClientRect();
            return { top: Math.round(h.top), h: Math.round(h.height), sy: Math.round(scrollY),
              bar: Math.round(document.querySelector('.topbar').getBoundingClientRect().height),
              stuck: document.getElementById('l4Head').classList.contains('stuck') }; }""")
        ok(f"{T}#overview 捲下去之後頁首（頁名＋時間）黏在視窗頂端、畫出下框線", hs["sy"] > 300 and hs["top"] == 0 and hs["stuck"], hs)
        ok(f"{T}#overview 頁首高＝.topbar 盒子高（≤ 60，指標面板 trackPop 的前提沒變）", abs(hs["h"] - hs["bar"]) <= 1 and hs["h"] <= 60, hs)
        pg.evaluate("() => window.scrollTo({ top: 0, behavior: 'instant' })"); pg.wait_for_timeout(300)

        # ⑤ 事件抽屜
        SD = """() => { const s = document.getElementById('side'), k = document.getElementById('sideBack'), r = s.getBoundingClientRect();
            return { open: s.classList.contains('open'), top: Math.round(r.top), right: Math.round(r.right), vw: innerWidth,
              seen: getComputedStyle(s).visibility !== 'hidden' && r.left < innerWidth - 2,
              back: k.classList.contains('on'), backL: Math.round(k.getBoundingClientRect().left),
              navW: Math.round(document.querySelector('.topbar').getBoundingClientRect().width) }; }"""
        pg.locator("#evToggle").click(timeout=6000)
        # 等滑進來的動畫（0.25s）真的跑完：機器忙的時候固定睡 600ms 會量到還在畫面外的抽屜（right＝1860）
        wait_until(pg, "() => { const r = document.getElementById('side').getBoundingClientRect(); return Math.round(r.right) === innerWidth; }", 4000)
        d1 = pg.evaluate(SD)
        ok(f"{T}1440 按左欄「事件」→ 抽屜滑出、遮罩出現", d1["open"] and d1["seen"] and d1["back"], d1)
        ok(f"{T}1440 抽屜從視窗頂端開始（上面已經沒有頂欄）、貼右", d1["top"] == 0 and d1["right"] == d1["vw"], d1)
        ok(f"{T}1440 遮罩從左欄右緣開始蓋（左欄的鈕照樣按得到）", abs(d1["backL"] - d1["navW"]) <= 1, d1)
        pg.mouse.click(d1["navW"] + 200, 450); pg.wait_for_timeout(600)
        ok(f"{T}1440 點遮罩 → 抽屜關掉", not pg.evaluate(SD)["open"], pg.evaluate(SD))
        pg.locator("#evToggle").click(timeout=6000); pg.wait_for_timeout(500)
        pg.keyboard.press("Escape"); pg.wait_for_timeout(500)
        ok(f"{T}1440 按 Esc → 抽屜關掉", not pg.evaluate(SD)["open"], pg.evaluate(SD))
        pg.locator("#evToggle").click(timeout=6000); pg.wait_for_timeout(500)
        ok(f"{T}1440 第三次打開（× 驗收前提）", pg.evaluate(SD)["open"])
        pg.locator("#evClose").click(timeout=6000); pg.wait_for_timeout(500)
        ok(f"{T}1440 點 × → 抽屜關掉", not pg.evaluate(SD)["open"], pg.evaluate(SD))

        # ⑥ 外觀面板、搜尋下拉在視窗內
        pg.locator("#t4Btn").click(timeout=6000); pg.wait_for_timeout(400)
        tp = pg.evaluate("""() => { const p = document.getElementById('t4Pop'); if (!p || p.hidden) return null; const r = p.getBoundingClientRect();
            return { top: Math.round(r.top), bottom: Math.round(r.bottom), left: Math.round(r.left), right: Math.round(r.right), vh: innerHeight, vw: innerWidth,
              navW: Math.round(document.querySelector('.topbar').getBoundingClientRect().width) }; }""")
        # 第四批（DECISIONS #312）：調色盤搬到右上角 → 面板在按鈕正下方、整塊在視窗內、不蓋到左欄
        ok(f"{T}1440 右上角「外觀」（調色盤小鈕）→ 面板打開而且整塊在視窗內、在按鈕下面",
           bool(tp) and tp["top"] >= 40 and tp["bottom"] <= tp["vh"] and tp["left"] >= tp["navW"] and tp["right"] <= tp["vw"], tp)
        pg.keyboard.press("Escape"); pg.wait_for_timeout(300)
        pg.locator("#q").click(timeout=6000)
        wait_until(pg, "() => document.querySelectorAll('#sugg .sgrow').length >= 3", 5000)
        sg = pg.evaluate("""() => { const s = document.getElementById('sugg'), r = s.getBoundingClientRect();
            return { n: s.querySelectorAll('.sgrow').length, left: Math.round(r.left), right: Math.round(r.right), vw: innerWidth,
              sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth }; }""")
        ok(f"{T}1440 左欄搜尋框 → 下拉往右長、整塊在視窗內", sg["n"] >= 3 and sg["left"] >= 0 and sg["right"] <= sg["vw"] and sg["sw"] <= sg["cw"] + 1, sg)
        pg.keyboard.press("Escape")

        # ⑨ 回歸：個股頁「指標 ▾」面板打開後要留著（左欄第一版把 .topbar 撐滿視窗高，面板 320ms 後就被 trackPop 當成「按鈕被蓋住」關掉）
        pg.goto(f"{base}#stock/{code}", wait_until="networkidle")
        wait_until(pg, "() => !!document.getElementById('indBtn')", 8000); pg.wait_for_timeout(800)
        pg.locator("#indBtn").click(timeout=6000); pg.wait_for_timeout(900)
        cp = pg.evaluate("""() => { const p = document.getElementById('cfgPop'); if (!p || p.hidden) return { open: false };
            const r = p.getBoundingClientRect(); return { open: true, top: Math.round(r.top), bottom: Math.round(r.bottom), vh: innerHeight }; }""")
        ok(f"{T}1440 個股頁按「指標 ▾」→ 面板打開、過了 0.9 秒還在", cp["open"] and cp["top"] >= 0 and cp["top"] < cp["vh"], cp)
        pg.keyboard.press("Escape")
        t_layout4_batch3(pg, base, code, T)
    finally:
        ctx.close()

    # ---------------- 1100：沒按過收合 → 預設圖示列 ----------------
    ctx = b.new_context(viewport={"width": 1100, "height": 900})
    pg = ctx.new_page()
    pg.on("pageerror", lambda e: errs.append(f"1100: {e}"))
    try:
        pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(800)
        n = pg.evaluate(L4_NAV)
        ok(f"{T}1100 沒按過收合 → 預設收成圖示列（讓內容有地方放）", n["mini"] and n["navW"] <= 80 and n["pref"] is None, n)
        ok(f"{T}1100 沒有橫向捲軸", n["sw"] <= n["cw"] + 1, n)
        pg.locator("#tabs .tab[data-view='market']").click(timeout=6000)
        ok(f"{T}1100 圖示列點「市場明細」→ 路由換到 #market", bool(wait_until(pg, "() => location.hash.startsWith('#market') && !!document.querySelector('#v-market.on')", 5000)),
           pg.evaluate("() => location.hash"))
    finally:
        ctx.close()

    t_layout4_login(b, base, T, errs)

    # ---------------- ≤820：手機版暫停（Andy 2026-10-03「手機版先停擺，等電腦版 OK 之後再做」）----------------
    # 驗「沒有任何 l4 痕跡」：html 沒有 l4／l4m／l4-mini、沒有 #l4 開頭的節點、沒有 .l4pt／.l4foot、html 沒被寫 inline style、
    # 分頁沒被補 title／aria-label；底部列高度＝把 layout4.css 整張停用之後當場量的高度（＝main 的樣子，不是寫死的數字）。
    NOL4 = """() => { const h = document.documentElement, t = document.getElementById('tabs');
        const sheet = [...document.styleSheets].find(x => (x.href || '').indexOf('layout4.css') >= 0);
        const tabsH = Math.round(t.getBoundingClientRect().height);
        let rawH = null; if (sheet) { sheet.disabled = true; rawH = Math.round(t.getBoundingClientRect().height); sheet.disabled = false; }
        return { cls: [...h.classList].filter(c => /^l4/.test(c)), ids: [...document.querySelectorAll('[id^="l4"]')].map(e => e.id),
          extra: document.querySelectorAll('.l4pt, .l4foot').length, style: h.getAttribute('style'),
          tabAttr: [...document.querySelectorAll('#tabs .tab')].filter(x => x.hasAttribute('title') || x.hasAttribute('aria-label')).length,
          tabsH, rawH, sheet: !!sheet, sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth }; }"""
    def no_l4(tag, st):
        ok(f"{T}{tag} 沒有任何 l4 痕跡（class／#l4 節點／.l4pt／.l4foot／inline style／分頁 title）",
           not st["cls"] and not st["ids"] and st["extra"] == 0 and not st["style"] and st["tabAttr"] == 0, st)
        ok(f"{T}{tag} 底部分頁列高度＝停用 layout4.css 時的高度（跟 main 一樣）", st["sheet"] and st["tabsH"] == st["rawH"], st)
        ok(f"{T}{tag} 沒有橫向捲軸", st["sw"] <= st["cw"] + 1, st)

    ctx = b.new_context(viewport={"width": 390, "height": 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
    pg = ctx.new_page()
    pg.on("pageerror", lambda e: errs.append(f"390: {e}"))
    try:
        for h in ("overview", "flow", f"stock/{code}"):
            pg.goto(f"{base}#{h}", wait_until="networkidle")
            wait_until(pg, "() => document.body.classList.contains('m3on') && !!document.getElementById('mTabMore')", 8000)
            pg.wait_for_timeout(1200)
            no_l4(f"390 #{h}", pg.evaluate(NOL4))
        # 手機原本的長相：底部圖示仍是文字符號（不是 layout4 的遮罩圖）、分段列不是 sticky、頂欄仍寫站名
        mo = pg.evaluate("""() => { const t = document.querySelector('#tabs .tab[data-view=overview]');
            location.hash = '#flow'; return { before: getComputedStyle(t, '::before').content,
              mask: getComputedStyle(t, '::before').maskImage || getComputedStyle(t, '::before').webkitMaskImage || 'none',
              site: !!document.querySelector('.brand b') && document.querySelector('.brand b').getClientRects().length > 0 }; }""")
        ok(f"{T}390 底部圖示是 main 的文字符號、頂欄寫站名", mo["before"] not in ("none", '""', "normal") and "svg" not in mo["mask"] and mo["site"], mo)
        wait_until(pg, "() => !!document.querySelector('#v-flow.on > .mpager')", 6000); pg.wait_for_timeout(600)
        mp = pg.evaluate("() => getComputedStyle(document.querySelector('#v-flow.on > .mpager')).position")
        ok(f"{T}390 資金流向分段列是 main 的樣子（沒有被改成 sticky）", mp == "static", mp)
    finally:
        ctx.close()

    # 768：一進來就沒有痕跡；1440 → 縮到 768 要撤乾淨、再拉回 1440 要整套回來
    ctx = b.new_context(viewport={"width": 768, "height": 900})
    pg = ctx.new_page()
    pg.on("pageerror", lambda e: errs.append(f"768: {e}"))
    try:
        for h in ("overview", f"stock/{code}"):
            pg.goto(f"{base}#{h}", wait_until="networkidle"); pg.wait_for_timeout(1500)
            no_l4(f"768 #{h}", pg.evaluate(NOL4))
        pg.locator("#tabs .tab[data-view='market']").click(timeout=6000)
        ok(f"{T}768 底部分頁列照樣能換頁", bool(wait_until(pg, "() => location.hash.startsWith('#market') && !!document.querySelector('#v-market.on')", 5000)),
           pg.evaluate("() => location.hash"))
        pg.set_viewport_size({"width": 1440, "height": 900}); pg.wait_for_timeout(900)
        up = pg.evaluate("""() => ({ l4: document.documentElement.classList.contains('l4'), head: !!document.getElementById('l4Head'),
            nav: !!document.getElementById('l4NavBtn'), pos: getComputedStyle(document.querySelector('.topbar')).position,
            h1: (document.querySelector('#l4Head h1') || {}).textContent })""")
        ok(f"{T}768 → 拉寬到 1440：左側導覽、頁首整套掛回來（頁名＝市場明細）", up["l4"] and up["head"] and up["nav"] and up["pos"] == "fixed" and up["h1"] == "市場明細", up)
        pg.set_viewport_size({"width": 800, "height": 900}); pg.wait_for_timeout(900)
        no_l4("1440 → 縮到 800", pg.evaluate(NOL4))
        # 第四批：右上角那幾顆是別支檔的按鈕本人 —— 縮回 ≤820 要放回原位（☀ 在「⋯」前面、外觀在 ☀ 前面，跟 main 的頂欄同一個順序）
        hm = pg.evaluate("""() => { const tb = document.getElementById('themeBtn'), t4 = document.getElementById('t4Btn');
            return { tb: !!tb && tb.parentElement.classList.contains('topbar') && !!tb.nextElementSibling && tb.nextElementSibling.id === 'moreBtn',
              t4: !t4 || (t4.parentElement.classList.contains('topbar') && t4.nextElementSibling === tb),
              tip: !document.getElementById('l4LoginTip') && !document.getElementById('l4Login') }; }""")
        ok(f"{T}1440 → 縮到 800：☀／外觀放回頂欄原位、#l4Login 撤掉", hm["tb"] and hm["t4"] and hm["tip"], hm)
    finally:
        ctx.close()
    ok(f"{T} 沒有 pageerror", not errs, errs[:5])



def t_layout4_login(b, base, T, errs):
    """第四批（Andy 看正式站：「這個登入功能不見了」，DECISIONS #312）：有會員設定檔時，右上角的登入鈕真的會開登入流程。

    用 TW_ACCOUNT_OVERRIDE 注入一個假的會員伺服器網址（https，account.js 只收 https 或本機），所有打到那台的請求由
    Playwright 攔下來回假資料 —— 不連任何外部服務、不真的登入。驗：
      · #acctBtn 在頁首右上角（跟頁名同一列、最右邊），寫「登入」；1440／1100（收合）／900 都看得到
      · 有呼叫會員 API（心跳 /v1/beat）
      · 按「登入」→ 先跳出告知（account.js 原本那個 #acctDlg）→ 按「用 Google 登入」→ 開出小視窗，網址是 <api>/auth/start?n=…&mode=popup
      · 右上角沒有 #l4Login（會員功能開著就不放那顆「沒開」的說明鈕）；縮到 800 → #acctBtn 回到 .acctbar
    真的 Google 登入、合併清單、登出那一整條在「會員雲端路徑」（本機 devserver）。"""
    API = "https://acct-uitest.example.workers.dev"
    hits: list[str] = []

    def fake(route):
        u = route.request.url
        hits.append(u)
        if "/auth/start" in u:
            route.fulfill(status=200, content_type="text/html; charset=utf-8", body="<!doctype html><title>假的 Google 登入</title><p>uitest</p>")
        else:
            route.fulfill(status=200, content_type="application/json", body='{"n": 2}')
    for W in (1440, 1100, 900):
        ctx = b.new_context(viewport={"width": W, "height": 900})
        ctx.add_init_script("window.TW_ACCOUNT_OVERRIDE = " + json.dumps({"api": API}) + ";")
        ctx.route(API + "/**", fake)
        pg = ctx.new_page()
        pg.on("pageerror", lambda e, W=W: errs.append(f"登入 {W}: {e}"))
        try:
            pg.goto(f"{base}#overview", wait_until="networkidle")
            wait_until(pg, "() => !!document.querySelector('#l4Head .l4tools #acctBtn') ? 1 : 0", 8000)
            st = pg.evaluate("""() => { const b = document.getElementById('acctBtn'), h1 = document.querySelector('#l4Head h1');
                const r = b.getBoundingClientRect(), hr = h1.getBoundingClientRect(), tools = document.querySelector('#l4Head .l4tools');
                const last = [...tools.children].filter(e => e.getClientRects().length).pop();
                return { inHead: !!b.closest('#l4Head .l4tools'), txt: b.textContent.trim(), seen: r.width > 0 && r.right <= innerWidth && r.top >= 0 && r.bottom <= 60,
                  row: Math.abs((r.top + r.height / 2) - (hr.top + hr.height / 2)) <= 8, last: last === b, right: Math.round(innerWidth - r.right),
                  fake: !!document.getElementById('l4Login'), on: TwAccount.on() }; }""")
            ok(f"{T}{W} 有會員設定檔：頁首右上角（跟頁名同一列、最右邊）有「登入」鈕、沒有「沒開啟」那顆",
               st["inHead"] and st["txt"] == "登入" and st["seen"] and st["row"] and st["last"] and st["right"] <= 40 and not st["fake"] and st["on"], st)
            if W != 1440:
                continue
            wait_until(pg, "() => performance.getEntriesByType('resource').some(e => e.name.indexOf('/v1/beat') >= 0) ? 1 : 0", 6000)
            ok(f"{T}1440 有會員設定檔：頁面真的呼叫了會員 API（心跳 /v1/beat）", any("/v1/beat" in u for u in hits), hits[:4])
            pg.locator("#l4Head #acctBtn").click(timeout=6000)
            dlg = wait_until(pg, "() => { const d = document.getElementById('acctDlg'); return d && !d.hidden && /Google/.test(d.textContent) ? 1 : 0; }", 4000)
            ok(f"{T}1440 按右上角「登入」→ 跳出登入前告知（account.js 原本那個對話框）", bool(dlg))
            with pg.expect_popup(timeout=8000) as pi:
                pg.locator("#acctGo").click(timeout=6000)
            pop = pi.value
            pop.wait_for_load_state("domcontentloaded")
            ok(f"{T}1440 按「用 Google 登入」→ 開出登入小視窗，網址是會員伺服器的 /auth/start（n＝一次性代碼、mode＝popup）",
               pop.url.startswith(API + "/auth/start?") and "mode=popup" in pop.url and re.search(r"[?&]n=[\w-]{16,}", pop.url) is not None, pop.url)
            pop.close()
            wd = wait_until(pg, "() => { const d = document.getElementById('acctDlg'); return d && !d.hidden && /等待 Google 登入/.test(d.textContent) ? 1 : 0; }", 4000)
            ok(f"{T}1440 開出小視窗之後原頁面顯示「等待 Google 登入完成」（換權杖的輪詢開始了）", bool(wd))
            pg.locator("#acctDlg [data-close]").click(timeout=4000); pg.wait_for_timeout(200)
            pg.set_viewport_size({"width": 800, "height": 900}); pg.wait_for_timeout(900)
            back = pg.evaluate("() => { const b = document.getElementById('acctBtn'); return !!b && !!b.closest('#acctBar') && !document.getElementById('l4Head'); }")
            ok(f"{T}1440 → 縮到 800：#acctBtn 回到頂欄的 .acctbar（≤820 跟 main 一樣）", back)
        finally:
            ctx.close()


def t_layout4_batch3(pg, base, code, T):
    """版面 V2 第三批（Andy 2026-10-03 對預覽 preview/layout-v2 的四條）——真的點、驗畫面真的變：
      ① 頁首只剩「頁名＋台北現在時間」，七個分頁都一樣；時間每秒真的在走、而且是台北時間（不是容器的 UTC）
      ② 收合鈕在 logo 右側（同一列）；按了左欄真的變窄、再按真的變回來；左欄底部沒有「‹ 收合導覽」文字列
      ③ 「事件」是導覽最上面一格（在所有頁面上面），保留數字徽章；按了抽屜真的打開
      ④ 帳號卡：圓形頭像＋「訪客」＋一行小字；沒有設定檔時不放登入鈕；原「★ 自選」「☀」兩顆在電腦版看不到
         「淺色｜深色」：按淺色 → data-theme、整頁底色、localStorage 真的換；再按淺色不會翻回去；按深色換回來
      ⑤ 收合時帳號卡只剩頭像、淺色深色剩兩顆圖示，左欄沒有東西溢出 72px
    ★ 同日第四批（Andy 看正式站：「這個登入功能不見了」「明暗用原來的圖示即可，並且都放在右上」「圖案換個圖案，畫在線上」，DECISIONS #312）：
      ② 改驗：收合鈕是騎在側欄分隔線上的圓鈕（中心 x 在左欄右緣 ±4px、垂直在 logo 那一列），展開 «、收合 »；按了左欄真的收合、鈕仍在新的邊線上
      ④ 改驗：帳號卡與「淺色｜深色」不存在；頁首右上角（跟頁名＋時間同一列）有 ☀ 鈕、外觀調色盤、登入；
         按 ☀ → 主題真的換（data-theme、底色、localStorage、圖表重建、圖示變 🌙），再按換回來（☀）；
         沒有會員設定檔時右上角是 #l4Login，按了跳出「沒有開啟」的說明（不是 #acctBtn、不連任何外部服務），Esc 關
      ⑤ 改驗：收合時事件、子分頁都在 72px 左欄裡，右上角三顆照樣在
      有會員設定檔的登入流程在 t_layout4_login（另開一個帶設定檔的分頁）
    """
    import datetime as _dt
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(900)
    pg.evaluate("() => { try { localStorage.setItem('tw.layout4.nav', 'full'); localStorage.removeItem('tw.theme'); } catch (e) {} }")
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(900)

    # ① 七個分頁的頁首
    HEAD = """() => { const h = document.getElementById('l4Head'), c = h && h.querySelector('.l4clock');
        return { kids: h ? [...h.children].map(e => e.tagName.toLowerCase()) : null, h1: ((h && h.querySelector('h1') || {}).firstChild || {}).textContent,
          t: c ? c.dataset.t : '', shown: !!c && getComputedStyle(c, '::before').content.replace(/"/g, '') === c.dataset.t,
          // 第四批：頁首右邊多了工具列（☀、外觀、登入），「頁首寫了什麼」只看頁名＋時間兩格
          txt: h ? [...h.children].filter(e => !e.classList.contains('l4tools')).map(e => e.innerText).join('').trim() : '' }; }"""
    bad = []
    for view, name in (("overview", "總覽"), ("flow", "資金流向"), ("heatmap", "熱力圖"), ("industry", "產業地圖"),
                       ("market", "市場明細"), ("season", "週期統計"), ("watch", "自選")):
        pg.locator(f"#tabs .tab[data-view='{view}']").click(timeout=6000)
        wait_until(pg, f"() => ((document.querySelector('#l4Head h1') || {{}}).firstChild || {{}}).textContent === '{name}' ? 1 : 0", 6000)
        hd = pg.evaluate(HEAD)
        # 資金流向／熱力圖的頁名後面接子分頁名（例：資金流向 資金輪動）—— 那也是頁名的一部分，不是說明句
        sub_ok = hd["txt"] == name or (view in ("flow", "heatmap") and hd["txt"].startswith(name) and len(hd["txt"]) <= len(name) + 12)
        if not (hd["kids"] == ["h1", "time", "div"] and hd["h1"] == name and hd["shown"] and sub_ok):
            bad.append({view: hd})
    ok(f"{T}第三批① 七個分頁的頁首都只剩頁名＋時間＋右上角工具（沒有分組小標、說明句、本頁功能）", not bad, bad[:3])
    t1 = pg.evaluate(HEAD)["t"]
    pg.wait_for_timeout(1300)
    t2 = pg.evaluate(HEAD)["t"]
    ok(f"{T}第三批① 頁首時間每秒真的在走（1.3 秒後字不一樣）", bool(t1) and t1 != t2, (t1, t2))
    now = _dt.datetime.now(_dt.timezone(_dt.timedelta(hours=8)))
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})（(.)）(\d{2}):(\d{2}):(\d{2})$", t2 or "")
    wk = "一二三四五六日"[now.weekday()]
    if m:
        shown = _dt.datetime(*[int(m.group(i)) for i in (1, 2, 3, 5, 6, 7)], tzinfo=now.tzinfo)
        drift = abs((shown - now).total_seconds())
    else:
        drift = None
    ok(f"{T}第三批① 時間是台北時間（格式 YYYY-MM-DD（週）HH:MM:SS、跟台北現在差 ≤ 5 秒、星期對）",
       bool(m) and drift is not None and drift <= 5 and m.group(4) == wk, {"畫面": t2, "台北現在": now.strftime("%Y-%m-%d %H:%M:%S"), "差秒": drift, "星期": wk})

    # ② 收合鈕騎在側欄分隔線上（第四批）
    NB = """() => { const b = document.getElementById('l4NavBtn'), lg = document.querySelector('.brand .logo'), ic = b.querySelector('.ic');
        const r = b.getBoundingClientRect(), l = lg.getBoundingClientRect(), t = document.querySelector('.topbar').getBoundingClientRect();
        // 分隔線＝左欄底色（.topbar::before）的右框線：x ＝ 左欄寬 − 0.5
        return { cx: r.left + r.width / 2, cy: r.top + r.height / 2, line: t.width - 0.5, bw: Math.round(r.width), bh: Math.round(r.height),
          round: getComputedStyle(b).borderRadius === '50%', lcy: l.top + l.height / 2, navW: Math.round(t.width),
          mini: document.documentElement.classList.contains('l4-mini'), label: b.getAttribute('aria-label'),
          rot: getComputedStyle(ic).transform, mask: getComputedStyle(ic).maskImage || getComputedStyle(ic).webkitMaskImage || '',
          top: document.elementFromPoint(Math.round(r.left + r.width / 2), Math.round(r.top + r.height / 2)) === b
            || b.contains(document.elementFromPoint(Math.round(r.left + r.width / 2), Math.round(r.top + r.height / 2))),
          foot: document.querySelectorAll('.l4foot').length,
          oldTxt: [...document.querySelectorAll('.topbar *')].some(e => e.children.length === 0 && /收合導覽/.test(e.textContent)) }; }"""
    a0 = pg.evaluate(NB)
    ok(f"{T}第四批② 收合鈕是騎在側欄分隔線上的圓鈕（中心 x 在左欄右緣 ±4px、垂直在 logo 那一列 ±12px、≤ 28px、最上層點得到）",
       abs(a0["cx"] - a0["line"]) <= 4 and abs(a0["cy"] - a0["lcy"]) <= 12 and a0["round"] and a0["bw"] <= 28 and abs(a0["bw"] - a0["bh"]) <= 1 and a0["top"], a0)
    ok(f"{T}第四批② 圖示換成雙箭頭、展開時沒有旋轉（« 指向左）", "svg" in a0["mask"] and "m11" in a0["mask"].lower() and a0["rot"] in ("none", ""), a0)
    ok(f"{T}第三批② 左欄底部的「‹ 收合導覽」文字列拿掉了", a0["foot"] == 0 and not a0["oldTxt"], a0)
    pg.locator("#l4NavBtn").click(timeout=6000); pg.wait_for_timeout(450)
    a1 = pg.evaluate(NB)
    ok(f"{T}第四批② 按收合鈕 → 左欄真的變窄（≤ 80）、鈕仍騎在新的邊線上（±4px）、箭頭轉成 »",
       a1["mini"] and a1["navW"] <= 80 and abs(a1["cx"] - a1["line"]) <= 4 and a1["label"] == "展開導覽" and a1["rot"] not in ("none", "") and a1["top"], a1)
    over = pg.evaluate("""() => { const w = document.querySelector('.topbar').getBoundingClientRect().width;
        return ['#evToggle', '.l4subtab'].flatMap(s => [...document.querySelectorAll(s)]).map(e => { const r = e.getBoundingClientRect();
          return { s: e.id || e.dataset.l4sub, l: Math.round(r.left), r: Math.round(r.right), ok: r.left >= 0 && r.right <= w + 0.5 && r.width > 0 }; }).filter(x => !x.ok); }""")
    ok(f"{T}第四批⑤ 收合時事件、子分頁都在 72px 左欄裡（沒有溢出）", not over, over)
    tr = pg.evaluate("""() => ['themeBtn', 't4Btn'].map(id => { const e = document.getElementById(id); return !!e && !!e.closest('#l4Head') && e.getClientRects().length > 0; })""")
    ok(f"{T}第四批⑤ 收合時右上角的 ☀ 與外觀照樣在", all(tr), tr)
    pg.locator("#l4NavBtn").click(timeout=6000); pg.wait_for_timeout(450)
    a2 = pg.evaluate(NB)
    ok(f"{T}第四批② 再按 → 左欄展開回來、鈕回到展開後的邊線上、箭頭轉回 «",
       not a2["mini"] and a2["navW"] >= 200 and abs(a2["cx"] - a2["line"]) <= 4 and a2["label"] == "收合導覽" and a2["rot"] in ("none", ""), a2)

    # ③ 事件在導覽最上面
    ev = pg.evaluate("""() => { const e = document.getElementById('evToggle'), r = e.getBoundingClientRect();
        const tabs = [...document.querySelectorAll('#tabs .tab')].filter(t => t.getClientRects().length).map(t => t.getBoundingClientRect().top);
        const n = document.getElementById('evCount');
        return { top: Math.round(r.top), bottom: Math.round(r.bottom), firstTab: Math.round(Math.min(...tabs)),
          search: Math.round(document.querySelector('.topbar .search').getBoundingClientRect().bottom),
          badge: !!n && n.getClientRects().length > 0 && /^\\d+$/.test(n.textContent.trim()), n: n ? n.textContent : null }; }""")
    ok(f"{T}第三批③ 「事件」是導覽最上面一格（在搜尋下面、所有頁面上面）、保留數字徽章",
       ev["top"] >= ev["search"] and ev["bottom"] <= ev["firstTab"] and ev["badge"], ev)
    pg.locator("#evToggle").click(timeout=6000)
    opened = wait_until(pg, "() => document.getElementById('side').classList.contains('open') ? 1 : 0", 3000)
    ok(f"{T}第三批③ 按最上面的「事件」→ 抽屜真的打開", bool(opened))
    pg.keyboard.press("Escape"); pg.wait_for_timeout(500)

    # ④ 第四批：右上角 ☀／外觀／登入（帳號卡與「淺色｜深色」拿掉）
    TR = """() => { const h = document.getElementById('l4Head'), h1 = h.querySelector('h1'), hr = h1.getBoundingClientRect();
        const box = (id) => { const e = document.getElementById(id); if (!e) return null; const r = e.getBoundingClientRect();
          return { inHead: !!e.closest('#l4Head .l4tools'), seen: e.getClientRects().length > 0 && r.width > 0, l: Math.round(r.left), r: Math.round(r.right),
                   cy: Math.round(r.top + r.height / 2), b: Math.round(r.bottom) }; };
        const vis = (s) => { const e = document.querySelector(s); return !!e && e.getClientRects().length > 0; };
        return { vw: innerWidth, h1cy: Math.round(hr.top + hr.height / 2), headB: Math.round(h.getBoundingClientRect().bottom),
          theme: box('themeBtn'), t4: box('t4Btn'), login: box('l4Login'), acct: !!document.getElementById('acctBtn'),
          card: !!document.getElementById('l4Acct'), mode: !!document.getElementById('l4Mode'),
          wl: vis('#wlBtn'), bar: vis('#acctBar'), ic: (document.getElementById('themeBtn') || {}).textContent }; }"""
    tr0 = pg.evaluate(TR)
    row = lambda x: bool(x) and x["inHead"] and x["seen"] and abs(x["cy"] - tr0["h1cy"]) <= 8 and x["r"] <= tr0["vw"] and x["l"] >= tr0["vw"] - 360
    ok(f"{T}第四批④ 頁首右上角（跟頁名同一列、靠右 360px 內）有 ☀ 鈕、外觀調色盤、登入",
       row(tr0["theme"]) and row(tr0["t4"]) and row(tr0["login"]) and tr0["theme"]["r"] <= tr0["t4"]["l"] and tr0["t4"]["r"] <= tr0["login"]["l"], tr0)
    ok(f"{T}第四批④ 左欄底部的帳號卡、「淺色｜深色」都拿掉了；原「★ 自選」列仍藏著", not tr0["card"] and not tr0["mode"] and not tr0["wl"] and not tr0["bar"], tr0)
    ok(f"{T}第四批④ 明暗鈕是原本那顆的圖示（深色時 ☀）", tr0["ic"] == "☀", tr0)
    # 沒有會員設定檔：#l4Login，按了講原因
    pg.locator("#l4Login").click(timeout=6000); pg.wait_for_timeout(300)
    tip = pg.evaluate("""() => { const t = document.getElementById('l4LoginTip'); if (!t || t.hidden) return null; const r = t.getBoundingClientRect();
        return { txt: t.innerText, top: Math.round(r.top), right: Math.round(r.right), vw: innerWidth, acct: !!document.getElementById('acctBtn'),
          exp: document.getElementById('l4Login').getAttribute('aria-expanded') }; }""")
    ok(f"{T}第四批④ 沒有會員設定檔時按右上角「登入」→ 跳出「會員登入目前沒有開啟」的說明（在按鈕下面、在視窗內、沒有冒出 #acctBtn）",
       bool(tip) and "沒有開啟" in tip["txt"] and "這台瀏覽器" in tip["txt"] and tip["top"] >= tr0["headB"] - 2 and tip["right"] <= tip["vw"] and not tip["acct"] and tip["exp"] == "true", tip)
    pg.keyboard.press("Escape"); pg.wait_for_timeout(200)
    ok(f"{T}第四批④ 按 Esc → 說明收起來", pg.evaluate("() => { const t = document.getElementById('l4LoginTip'); return !t || t.hidden; }"))
    MS = """() => ({ th: document.documentElement.getAttribute('data-theme') || 'dark', bg: getComputedStyle(document.body).backgroundColor,
        ls: (() => { try { return localStorage.getItem('tw.theme'); } catch (e) { return 'x'; } })(),
        ic: (document.getElementById('themeBtn') || {}).textContent,
        heat: (() => { const i = window.echarts && echarts.getInstanceByDom(document.getElementById('heat')); return i ? i.id : ''; })() })"""
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(1500)
    m0 = pg.evaluate(MS)
    ok(f"{T}第四批④ 一開始是深色、右上角是 ☀", m0["th"] == "dark" and m0["ic"] == "☀", m0)
    pg.locator("#l4Head #themeBtn").click(timeout=15000); pg.wait_for_timeout(1800)
    m1 = pg.evaluate(MS)
    ok(f"{T}第四批④ 按右上角 ☀ → 主題真的換（data-theme、整頁底色、localStorage、圖表重建）、圖示變 🌙",
       m1["th"] == "light" and m1["bg"] != m0["bg"] and m1["ls"] == "light" and m1["ic"] == "🌙" and m1["heat"] and m1["heat"] != m0["heat"], {"前": m0, "後": m1})
    pg.locator("#l4Head #themeBtn").click(timeout=15000); pg.wait_for_timeout(1800)
    m3 = pg.evaluate(MS)
    ok(f"{T}第四批④ 再按一次 → 換回深色、底色回來、localStorage 寫 dark、圖示回 ☀", m3["th"] == "dark" and m3["bg"] == m0["bg"] and m3["ls"] == "dark" and m3["ic"] == "☀", m3)
    # 外觀面板切明暗 → 右上角 ☀ 鈕的圖示跟著換（app.js applyTheme 寫的，不管是誰切的）
    pg.locator("#l4Head #t4Btn").click(timeout=6000); pg.wait_for_timeout(300)
    pg.locator("#t4Pop .t4m[data-t4m='light']").click(timeout=6000); pg.wait_for_timeout(1600)
    ok(f"{T}第四批④ 從右上角外觀面板切淺色 → ☀ 鈕跟著變 🌙", pg.evaluate(MS)["ic"] == "🌙", pg.evaluate(MS))
    pg.keyboard.press("Escape"); pg.wait_for_timeout(200)
    pg.locator("#l4Head #themeBtn").click(timeout=15000); pg.wait_for_timeout(1200)
    pg.evaluate("() => { try { localStorage.removeItem('tw.theme'); localStorage.removeItem('tw.layout4.nav'); } catch (e) {} }")
    t_layout4_subs(pg, base, T)


# 子分頁量測：哪幾張卡看得到、哪幾張圖真的畫了（有 ECharts 實例＝畫過；沒有＝根本沒畫，不是只是藏起來）
L4_SUBST = """() => { const vis = (id) => { const e = document.getElementById(id); return !!e && e.getClientRects().length > 0 && e.getBoundingClientRect().height > 20; };
    const inst = (id) => { const e = document.getElementById(id); return !!(e && window.echarts && echarts.getInstanceByDom(e)); };
    const on = [...document.querySelectorAll('.l4subtab.on')].map(b => b.dataset.l4sub);
    const h1 = document.querySelector('#l4Head h1');
    return { hash: location.hash, sub: document.documentElement.getAttribute('data-l4sub'), on,
      tabOn: (document.querySelector('#tabs .tab.on') || { dataset: {} }).dataset.view,
      cards: { rot: vis('flowRotCard'), sankey: vis('flowSankeyCard'), inst: vis('flowInstCard'), conc: vis('flowConcCard'),
               ind: vis('indHeat'), theme: vis('themeMapCard') },
      drawn: { rot: inst('rotClock'), rank: inst('rankFlow'), sankey: !!document.querySelector('#sankey .ftstage')   /* 資金去向是 flowtopo.js 畫的（不是 ECharts） */, inst: inst('instGroups'), conc: inst('conc'), theme: inst('themeMap') },
      head: h1 ? h1.textContent : '', sy: Math.round(scrollY) }; }"""


def t_layout4_subs(pg, base, T):
    """版面 V2 子分頁（Andy 2026-10-03）：「資金流向」拆成 ①資金輪動 ②資金去向 ③族群×法人＋資金集中度、「熱力圖」拆成 產業／題材。
    真的點側欄子項，驗：hash 真的換、側欄那格亮、畫面只出現那個子分頁的卡、**其他子分頁的圖根本沒畫**（沒有 ECharts 實例）、
    舊網址 #flow／#heatmap 導到第一個子分頁、分組名「資金流水」、收合時子項是兩個字的短名而且點得到。"""
    pg.goto(f"{base}#overview", wait_until="networkidle"); pg.wait_for_timeout(600)
    pg.evaluate("() => { try { localStorage.setItem('tw.layout4.nav', 'full'); } catch (e) {} }")
    # 從別頁點父頁「資金流向」：一進資金流向就是全新的一輪（重新整理，確保別的子分頁的圖真的還沒畫過）
    pg.reload(wait_until="networkidle"); pg.wait_for_timeout(800)
    lbl = pg.evaluate("() => getComputedStyle(document.querySelector('#tabs .tab[data-view=flow]'), '::before').content.replace(/\"/g, '')")
